	public void RobotCalculate(List<Pnt3D> ImagePoints, Pnt6D Offset, double XYOffset, double ZPosition, double APosition, bool Spline, double DevideLen, ref List<Pnt6D> calculatedPoints)
	{
		List<Pnt3D> OffsetedPoints = new List<Pnt3D>();
		List<Pnt3D> CalculatedPoints = new List<Pnt3D>();
		calculatedPoints.Clear();
		if (IsClosed(ImagePoints))
		{
			OffsetContour(ImagePoints, XYOffset, OffsetCornerType.Line, CamOpenContourType2.Center, new WorkPlane(), 0.0, ref OffsetedPoints);
		}
		if (Spline)
		{
			BSplineCubicUniform(OffsetedPoints, 0.1, Closed: true, ref CalculatedPoints);
			OffsetedPoints = new List<Pnt3D>();
			for (int i = 0; i <= CalculatedPoints.Count - 1; i++)
			{
				OffsetedPoints.Add(new Pnt3D(CalculatedPoints[i]));
			}
		}
		if (DevideLen > 0.0)
		{
			PointFilterByLength(DevideLen, 0, ref OffsetedPoints);
		}
		double num = 0.0;
		for (int j = 0; j <= OffsetedPoints.Count - 1; j++)
		{
			double num2 = 0.0;
			num2 = ((j == 0) ? PointAngle(OffsetedPoints[j + 1], OffsetedPoints[j]) : PointAngle(OffsetedPoints[j], OffsetedPoints[j - 1]));
			if (j > 0)
			{
				if (num2 - num > 180.0)
				{
					num2 -= 360.0;
				}
				if (num2 - num < -180.0)
				{
					num2 += 360.0;
				}
			}
			Pnt6D item = new Pnt6D(OffsetedPoints[j].X + Offset.X, OffsetedPoints[j].Y + Offset.Y, ZPosition + Offset.Z, APosition + Offset.A, Offset.B, num2 + Offset.C);
			calculatedPoints.Add(item);
			num = num2;
		}
	}

	public double Length2D(double X1, double Y1, double X2, double Y2)
	{
		try
		{
			return Math.Sqrt((X1 - X2) * (X1 - X2) + (Y1 - Y2) * (Y1 - Y2));
		}
		catch (Exception mSException)
		{
			string text = "X1: " + X1 + " - X2: " + X2 + " - Y1: " + Y1 + " - Y2: " + Y2;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

