	public double Length3D(Pnt3D StartPoint, Pnt3D EndPoint, WorkPlane Plane)
	{
		try
		{
			if (!WorkPlane.isPlaneXY(Plane))
			{
				if (!WorkPlane.isPlaneXZ(Plane))
				{
					if (!WorkPlane.isPlaneYZ(Plane))
					{
						return Length3D(StartPoint, EndPoint);
					}
					return Math.Sqrt((StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z));
				}
				return Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Z - EndPoint.Z) * (StartPoint.Z - EndPoint.Z));
			}
			return Math.Sqrt((StartPoint.X - EndPoint.X) * (StartPoint.X - EndPoint.X) + (StartPoint.Y - EndPoint.Y) * (StartPoint.Y - EndPoint.Y));
		}
		catch (Exception mSException)
		{
			string text = "StartPnt : " + StartPoint.ToString() + " - EndPnt : " + EndPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

