	public void StepLengthCalculation(HeightStepCalculationType StepType, double Step, double StartZ, double EndZ, ref List<double> CalculatedHeight)
	{
		try
		{
			double num = StartZ - EndZ;
			int num2 = 1;
			CalculatedHeight.Clear();
			if (StepType == HeightStepCalculationType.ChangeBaseStepMakeEqualAllStep)
			{
				num2 = Convert.ToInt32(Math.Ceiling(num / Step));
				double num3 = num / (double)num2;
				for (int i = 1; i <= num2; i++)
				{
					CalculatedHeight.Add(StartZ - (double)i * num3);
				}
			}
			if (StepType == HeightStepCalculationType.DontChangeBaseStepMakeExtraStep)
			{
				num2 = Convert.ToInt32(Math.Floor(num / Step));
				double num4 = StartZ;
				for (int j = 1; j <= num2; j++)
				{
					CalculatedHeight.Add(StartZ - (double)j * Step);
					num4 = StartZ - (double)j * Step;
				}
				if (num4 - EndZ > 0.001)
				{
					CalculatedHeight.Add(EndZ);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "StepType: " + StepType.ToString() + " - Step: " + Step + " - StepStartZ: " + StartZ + " - EndZ: " + EndZ;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void MinMaxLengthInPoints(List<Pnt3D> RefPoints, ref double MinLength, ref double MaxLength)
	{
		string callMethod = "MinMaxLengthInPoints";
		try
		{
			if (RefPoints.Count >= 1)
			{
				MinLength = double.MaxValue;
				MaxLength = double.MinValue;
				for (int i = 1; i <= RefPoints.Count - 1; i++)
				{
					double num = Length3D(RefPoints[i - 1], RefPoints[i]);
					if (num < MinLength)
					{
						MinLength = num;
					}
					if (num > MaxLength)
					{
						MaxLength = num;
					}
				}
			}
			else
			{
				MinLength = 0.0;
				MaxLength = 0.0;
			}
		}
		catch (Exception mSException)
		{
			string text = "RefPoints: " + RefPoints.Count;
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: false, text);
		}
	}

	public void RectangleEdgeDistanceByAngle(double Width, double Height, double Angle, ref double CalcLength)
	{
		string callMethod = "RectangleEdgeDistanceByAngle";
		try
		{
			double num = Math.Abs(Math.Cos(buConversion.DegreeToRadian(Angle)));
			double num2 = Math.Abs(Math.Sin(buConversion.DegreeToRadian(Angle)));
			if (!(Width / 2.0 * num2 <= Height / 2.0 * num))
			{
				CalcLength = Height / 2.0 / num2;
			}
			else
			{
				CalcLength = Width / 2.0 / num;
			}
		}
		catch (Exception mSException)
		{
			string text = "Width: " + Width + "- Height: " + Height + "- Angle: " + Angle;
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: false, text);
		}
	}

	public void SawDistance(double Diameter, double Thickness, double TargetZ, ref double CalcDistance)
	{
		string callMethod = "SawDistance";
		try
		{
			double num = Math.Pow(Diameter / 2.0 - (Thickness - TargetZ), 2.0);
			CalcDistance = Math.Sqrt(Math.Pow(Diameter / 2.0, 2.0) - num);
		}
		catch (Exception mSException)
		{
			string text = "Diameter: " + Diameter + "- Thickness: " + Thickness + "- TargetZ: " + TargetZ;
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: false, text);
			CalcDistance = 0.0;
		}
	}

	public void AreaUnitRatioFromMM(LengthUnit Unit, ref double UnitRatio)
	{
		switch (Unit)
		{
		case LengthUnit.mm:
			UnitRatio = 1.0;
			break;
		case LengthUnit.cm:
			UnitRatio = 100.0;
			break;
		case LengthUnit.dm:
			UnitRatio = 10000.0;
			break;
		case LengthUnit.m:
			UnitRatio = 1000000.0;
			break;
		case LengthUnit.dam:
			UnitRatio = 100000000.0;
			break;
		case LengthUnit.hm:
			UnitRatio = 10000000000.0;
			break;
		case LengthUnit.km:
			UnitRatio = 1000000000000.0;
			break;
		}
	}

	public double PointAngle(Pnt6D PntEnd, Pnt6D PntCenter, ref double XY, ref double XZ, ref double YZ)
	{
		try
		{
			double num = DeltaY(PntEnd.Y, PntCenter.Y);
			double num2 = DeltaX(PntEnd.X, PntCenter.X);
			double d = num / num2;
			Math.Atan(d);
			double num3 = buConversion.RadianToDegree(Math.Atan(DeltaY(PntEnd.Y, PntCenter.Y) / DeltaX(PntEnd.X, PntCenter.X)));
			if (PntEnd.X == PntCenter.X)
			{
				num3 = 90.0;
			}
			if (PntEnd.Y > PntCenter.Y && num3 < 0.0)
			{
				num3 = 180.0 + num3;
			}
			if (PntEnd.Y < PntCenter.Y)
			{
				num3 = ((num3 < 0.0) ? (360.0 + num3) : (180.0 + num3));
			}
			if ((PntCenter.Y == PntEnd.Y) & (PntCenter.X > PntEnd.X))
			{
				num3 = 180.0;
			}
			if ((PntCenter.X == PntEnd.X) & (PntCenter.Y == PntEnd.Y))
			{
				num3 = -1.0;
			}
			XY = num3;
			num3 = buConversion.RadianToDegree(Math.Atan(DeltaZ(PntEnd.Z, PntCenter.Z) / DeltaX(PntEnd.X, PntCenter.X)));
			if (PntEnd.X == PntCenter.X)
			{
				num3 = 90.0;
			}
			if (PntEnd.Z > PntCenter.Z && num3 < 0.0)
			{
				num3 = 180.0 + num3;
			}
			if (PntEnd.Z < PntCenter.Z)
			{
				num3 = ((num3 < 0.0) ? (360.0 + num3) : (180.0 + num3));
			}
			if ((PntCenter.Z == PntEnd.Z) & (PntCenter.X > PntEnd.X))
			{
				num3 = 180.0;
			}
			if ((PntCenter.X == PntEnd.X) & (PntCenter.Z == PntEnd.Z))
			{
				num3 = -1.0;
			}
			XZ = num3;
			num3 = buConversion.RadianToDegree(Math.Atan(DeltaZ(PntEnd.Z, PntCenter.Z) / DeltaY(PntEnd.Y, PntCenter.Y)));
			if (PntEnd.Y == PntCenter.Y)
			{
				num3 = 90.0;
			}
			if (PntEnd.Z > PntCenter.Z && num3 < 0.0)
			{
				num3 = 180.0 + num3;
			}
			if (PntEnd.Z < PntCenter.Z)
			{
				num3 = ((num3 < 0.0) ? (360.0 + num3) : (180.0 + num3));
			}
			if ((PntCenter.Z == PntEnd.Z) & (PntCenter.Y > PntEnd.Y))
			{
				num3 = 180.0;
			}
			if ((PntCenter.Y == PntEnd.Y) & (PntCenter.Z == PntEnd.Z))
			{
				num3 = -1.0;
			}
			YZ = num3;
			return XY;
		}
		catch (Exception mSException)
		{
			string text = "PntEnd: " + PntEnd.ToString() + " - PntCenter: " + PntCenter.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double PointAngle(Pnt3D PntEnd, Pnt3D PntCenter, ref double XY, ref double XZ, ref double YZ)
	{
		try
		{
			double num = DeltaY(PntEnd.Y, PntCenter.Y);
			double num2 = DeltaX(PntEnd.X, PntCenter.X);
			double d = num / num2;
			Math.Atan(d);
			double num3 = buConversion.RadianToDegree(Math.Atan(DeltaY(PntEnd.Y, PntCenter.Y) / DeltaX(PntEnd.X, PntCenter.X)));
			if (PntEnd.X == PntCenter.X)
			{
				num3 = 90.0;
			}
			if (PntEnd.Y > PntCenter.Y && num3 < 0.0)
			{
				num3 = 180.0 + num3;
			}
			if (PntEnd.Y < PntCenter.Y)
			{
				num3 = ((num3 < 0.0) ? (360.0 + num3) : (180.0 + num3));
			}
			if ((PntCenter.Y == PntEnd.Y) & (PntCenter.X > PntEnd.X))
			{
				num3 = 180.0;
			}
			if ((PntCenter.X == PntEnd.X) & (PntCenter.Y == PntEnd.Y))
			{
				num3 = -1.0;
			}
			XY = num3;
			num3 = buConversion.RadianToDegree(Math.Atan(DeltaZ(PntEnd.Z, PntCenter.Z) / DeltaX(PntEnd.X, PntCenter.X)));
			if (PntEnd.X == PntCenter.X)
			{
				num3 = 90.0;
			}
			if (PntEnd.Z > PntCenter.Z && num3 < 0.0)
			{
				num3 = 180.0 + num3;
			}
			if (PntEnd.Z < PntCenter.Z)
			{
				num3 = ((num3 < 0.0) ? (360.0 + num3) : (180.0 + num3));
			}
			if ((PntCenter.Z == PntEnd.Z) & (PntCenter.X > PntEnd.X))
			{
				num3 = 180.0;
			}
			if ((PntCenter.X == PntEnd.X) & (PntCenter.Z == PntEnd.Z))
			{
				num3 = -1.0;
			}
			XZ = num3;
			num3 = buConversion.RadianToDegree(Math.Atan(DeltaZ(PntEnd.Z, PntCenter.Z) / DeltaY(PntEnd.Y, PntCenter.Y)));
			if (PntEnd.Y == PntCenter.Y)
			{
				num3 = 90.0;
			}
			if (PntEnd.Z > PntCenter.Z && num3 < 0.0)
			{
				num3 = 180.0 + num3;
			}
			if (PntEnd.Z < PntCenter.Z)
			{
				num3 = ((num3 < 0.0) ? (360.0 + num3) : (180.0 + num3));
			}
			if ((PntCenter.Z == PntEnd.Z) & (PntCenter.Y > PntEnd.Y))
			{
				num3 = 180.0;
			}
			if ((PntCenter.Y == PntEnd.Y) & (PntCenter.Z == PntEnd.Z))
			{
				num3 = -1.0;
			}
			YZ = num3;
			return XY;
		}
		catch (Exception mSException)
		{
			string text = "PntEnd: " + PntEnd.ToString() + " - PntCenter: " + PntCenter.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

