	public double AngleOfTwoLines(Pnt3D FirstLineStart, Pnt3D FirstLineEnd, Pnt3D SecondLineStart, Pnt3D SecondLineEnd, WorkPlane Plane)
	{
		try
		{
			double num = 0.0;
			Pnt3D IntersectionPoint = new Pnt3D();
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			bool IsLineIntersect = false;
			LineLineIntersection(FirstLineStart, FirstLineEnd, SecondLineStart, SecondLineEnd, Plane, ref IntersectionPoint, ref IsLineIntersect);
			if (IsLineIntersect)
			{
				double num2 = Length3D(FirstLineStart, IntersectionPoint);
				double num3 = Length3D(FirstLineEnd, IntersectionPoint);
				double num4 = Length3D(SecondLineStart, IntersectionPoint);
				double num5 = Length3D(SecondLineEnd, IntersectionPoint);
				pnt3D = ((num2 > num3) ? new Pnt3D(FirstLineStart) : new Pnt3D(FirstLineEnd));
				pnt3D2 = ((num4 > num5) ? new Pnt3D(SecondLineStart) : new Pnt3D(SecondLineEnd));
				double num6 = PointAngle(pnt3D, IntersectionPoint, Plane);
				double num7 = PointAngle(pnt3D2, IntersectionPoint, Plane);
				num = Math.Abs(num6 - num7);
				if (num > 180.0)
				{
					num = 360.0 - num;
				}
				return num;
			}
			return 180.0;
		}
		catch (Exception mSException)
		{
			string text = "FirstLineStart: " + FirstLineStart.ToString() + " - FirstLineEnd: " + FirstLineEnd.ToString() + " - SecondLineStart: " + SecondLineStart.ToString() + " - SecondLineEnd: " + SecondLineEnd.ToString() + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public OrientationAngle Vector3dToOrientationAngle(Vec3D d)
	{
		double num = 0.0;
		double num2 = 0.0;
		double num3 = 0.0;
		new Vec3D();
		Vec3D.Normalise(d);
		Vec3D vec3D = new Vec3D(d.X, d.Y, 0.0);
		Vec3D vec3D2 = new Vec3D();
		vec3D2 = Vec3D.Normalise(vec3D);
		if ((d.X > 0.0) & (d.Y > 0.0))
		{
			num3 = ((vec3D.X >= 0.0) ? ((vec3D.Y > 0.0) ? buConversion.RadianToDegree(Math.Acos(vec3D2.X)) : (360.0 - buConversion.RadianToDegree(Math.Acos(vec3D2.X)))) : ((vec3D.Y > 0.0) ? buConversion.RadianToDegree(Math.Acos(vec3D2.X)) : (360.0 - buConversion.RadianToDegree(Math.Acos(vec3D2.X)))));
		}
		Vec3D vec3D3 = new Vec3D(d.X, 0.0, d.Z);
		Vec3D vec3D4 = new Vec3D();
		vec3D4 = Vec3D.Normalise(vec3D3);
		if ((d.X > 0.0) & (d.Z > 0.0))
		{
			num2 = ((vec3D3.X >= 0.0) ? ((vec3D3.Z > 0.0) ? buConversion.RadianToDegree(Math.Acos(vec3D4.X)) : (360.0 - buConversion.RadianToDegree(Math.Acos(vec3D4.X)))) : ((vec3D3.Z > 0.0) ? buConversion.RadianToDegree(Math.Acos(vec3D4.X)) : (360.0 - buConversion.RadianToDegree(Math.Acos(vec3D4.X)))));
		}
		Vec3D vec3D5 = new Vec3D(0.0, d.Y, d.Z);
		Vec3D vec3D6 = new Vec3D();
		vec3D6 = Vec3D.Normalise(vec3D5);
		if ((d.Y > 0.0) & (d.Z > 0.0))
		{
			num = ((vec3D5.Y >= 0.0) ? ((vec3D5.Z >= 0.0) ? buConversion.RadianToDegree(Math.Acos(vec3D6.Y)) : (360.0 - buConversion.RadianToDegree(Math.Acos(vec3D6.Y)))) : ((vec3D5.Z >= 0.0) ? buConversion.RadianToDegree(Math.Acos(vec3D6.Y)) : (360.0 - buConversion.RadianToDegree(Math.Acos(vec3D6.Y)))));
		}
		if (num >= 360.0)
		{
			num -= 360.0;
		}
		if (num2 >= 360.0)
		{
			num2 -= 360.0;
		}
		if (num3 >= 360.0)
		{
			num3 -= 360.0;
		}
		return new OrientationAngle(num, num2, num3);
	}

	public void CalculateCAngleFromPointList(List<Pnt3D> RefPoints, ref List<Pnt6D> calcPoints)
	{
		string callMethod = "CalculateCAngleFromPointList";
		try
		{
			if (RefPoints.Count > 1)
			{
				double c = PointAngle(RefPoints[1], RefPoints[0], new WorkPlane());
				calcPoints.Add(new Pnt6D(RefPoints[0].X, RefPoints[0].Y, RefPoints[0].Z, 0.0, 0.0, c));
				for (int i = 1; i <= RefPoints.Count - 1; i++)
				{
					c = PointAngle(RefPoints[i], RefPoints[i - 1], new WorkPlane());
					calcPoints.Add(new Pnt6D(RefPoints[i].X, RefPoints[i].Y, RefPoints[i].Z, 0.0, 0.0, c));
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "RefPoints: " + RefPoints.Count;
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: false, text);
		}
	}

	public void BoxSizeCalculate(List<ContourPoints> Points, ref Pnt3D MinPoint, ref Pnt3D MaxPoint)
	{
		try
		{
			MinPoint = new Pnt3D(double.MaxValue, double.MaxValue, double.MaxValue);
			MaxPoint = new Pnt3D(double.MinValue, double.MinValue, double.MinValue);
			for (int i = 0; i <= Points.Count - 1; i++)
			{
				for (int j = 0; j <= Points[i].Outter.Count - 1; j++)
				{
					if (Points[i].Outter[j].X > MaxPoint.X)
					{
						MaxPoint.X = Points[i].Outter[j].X;
					}
					if (Points[i].Outter[j].Y > MaxPoint.Y)
					{
						MaxPoint.Y = Points[i].Outter[j].Y;
					}
					if (Points[i].Outter[j].Z > MaxPoint.Z)
					{
						MaxPoint.Z = Points[i].Outter[j].Z;
					}
					if (Points[i].Outter[j].X < MinPoint.X)
					{
						MinPoint.X = Points[i].Outter[j].X;
					}
					if (Points[i].Outter[j].Y < MinPoint.Y)
					{
						MinPoint.Y = Points[i].Outter[j].Y;
					}
					if (Points[i].Outter[j].Z < MinPoint.Z)
					{
						MinPoint.Z = Points[i].Outter[j].Z;
					}
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Count: " + Points.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

