			for (int i = 0; i <= Triangles.Count - 1; i++)
			{
				if (Triangles[i].FirstPoint.X > MaxPoint.X)
				{
					MaxPoint.X = Triangles[i].FirstPoint.X;
				}
				if (Triangles[i].FirstPoint.Y > MaxPoint.Y)
				{
					MaxPoint.Y = Triangles[i].FirstPoint.Y;
				}
				if (Triangles[i].FirstPoint.Z > MaxPoint.Z)
				{
					MaxPoint.Z = Triangles[i].FirstPoint.Z;
				}
				if (Triangles[i].FirstPoint.X < MinPoint.X)
				{
					MinPoint.X = Triangles[i].FirstPoint.X;
				}
				if (Triangles[i].FirstPoint.Y < MinPoint.Y)
				{
					MinPoint.Y = Triangles[i].FirstPoint.Y;
				}
				if (Triangles[i].FirstPoint.Z < MinPoint.Z)
				{
					MinPoint.Z = Triangles[i].FirstPoint.Z;
				}
				if (Triangles[i].SecondPoint.X > MaxPoint.X)
				{
					MaxPoint.X = Triangles[i].SecondPoint.X;
				}
				if (Triangles[i].SecondPoint.Y > MaxPoint.Y)
				{
					MaxPoint.Y = Triangles[i].SecondPoint.Y;
				}
				if (Triangles[i].SecondPoint.Z > MaxPoint.Z)
				{
					MaxPoint.Z = Triangles[i].SecondPoint.Z;
				}
				if (Triangles[i].SecondPoint.X < MinPoint.X)
				{
					MinPoint.X = Triangles[i].SecondPoint.X;
				}
				if (Triangles[i].SecondPoint.Y < MinPoint.Y)
				{
					MinPoint.Y = Triangles[i].SecondPoint.Y;
				}
				if (Triangles[i].SecondPoint.Z < MinPoint.Z)
				{
					MinPoint.Z = Triangles[i].SecondPoint.Z;
				}
				if (Triangles[i].ThirdPoint.X > MaxPoint.X)
				{
					MaxPoint.X = Triangles[i].ThirdPoint.X;
				}
				if (Triangles[i].ThirdPoint.Y > MaxPoint.Y)
				{
					MaxPoint.Y = Triangles[i].ThirdPoint.Y;
				}
				if (Triangles[i].ThirdPoint.Z > MaxPoint.Z)
				{
					MaxPoint.Z = Triangles[i].ThirdPoint.Z;
				}
				if (Triangles[i].ThirdPoint.X < MinPoint.X)
				{
					MinPoint.X = Triangles[i].ThirdPoint.X;
				}
				if (Triangles[i].ThirdPoint.Y < MinPoint.Y)
				{
					MinPoint.Y = Triangles[i].ThirdPoint.Y;
				}
				if (Triangles[i].ThirdPoint.Z < MinPoint.Z)
				{
					MinPoint.Z = Triangles[i].ThirdPoint.Z;
				}
			}
			MiddlePointOfLine(MinPoint, MaxPoint, ref MidPoint);
		}
		catch (Exception mSException)
		{
			string text = "Count: " + Triangles.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

