	public void CircularZHeightRampByLengthAndHeight(double Length, double ZUp, double ZDown, double ArcRatio, int Count, ref List<double> Heights, ref List<Pnt3D> Points)
	{
		List<Pnt3D> Vertices = new List<Pnt3D>();
		Pnt3D ArcCenter = new Pnt3D();
		double ArcSA = 0.0;
		double ArcEA = 0.0;
		double num = 0.0;
		Pnt3D pnt3D = new Pnt3D(0.0, ZUp, 0.0);
		Pnt3D pnt3D2 = new Pnt3D(Length, ZDown, 0.0);
		if (ZDown > ZUp)
		{
			pnt3D = new Pnt3D(0.0, ZDown, 0.0);
			pnt3D2 = new Pnt3D(Length, ZUp, 0.0);
		}
		num = Length / ArcRatio;
		double radius = num;
		for (double num2 = 1.0; num2 <= 1000.0; num2 += 0.5)
		{
			Pnt3D startPoint = new Pnt3D(pnt3D2.X, pnt3D2.Y + num2);
			double num3 = Length3D(startPoint, pnt3D);
			Math.Abs(num3 - num2);
			if (buCompare.EQ(num3, num2, 1.0))
			{
				radius = num3;
				num2 = 1000.0;
			}
		}
		ArcWithTwoPointAndRadius(pnt3D, pnt3D2, radius, CW: false, new WorkPlane(), ref ArcCenter, ref ArcSA, ref ArcEA);
		ArcWithCenter(ArcCenter, radius, ArcSA, ArcEA, new WorkPlane(), new EntityResolution(1.0, Count - 1, 10.0, EntityResolutionType.ByNumber), ref Vertices);
		RotateByMatrix(new Pnt3D(), 90.0, VectorType.XVector, ref Vertices);
		if (!(ZUp > ZDown))
		{
			if (Vertices[0].Z > Vertices[Vertices.Count - 1].Z)
			{
				Vertices.Reverse();
			}
		}
		else if (Vertices[0].Z < Vertices[Vertices.Count - 1].Z)
		{
			Vertices.Reverse();
		}
		for (int i = 0; i <= Vertices.Count - 1; i++)
		{
			Heights.Add(Vertices[i].Z);
		}
		Points.Clear();
		Pnt3D.Copy(Vertices, ref Points);
	}

	public void Pnt3DToPnt6DByTangentAngle(List<Pnt3D> P3List, ref List<Pnt6D> P6List)
	{
		try
		{
			if (P3List.Count == 0)
			{
				return;
			}
			if (P3List.Count != 1)
			{
				P6List.Clear();
				P6List = new List<Pnt6D>();
				for (int i = 0; i <= P3List.Count - 1; i++)
				{
					if (i != 0)
					{
						double c = PointAngle(P3List[i], P3List[i - 1]);
						Pnt6D item = new Pnt6D(P3List[i].X, P3List[i].Y, P3List[i].Z, 0.0, 0.0, c);
						P6List.Add(item);
					}
					else
					{
						double c2 = PointAngle(P3List[i + 1], P3List[i]);
						Pnt6D item2 = new Pnt6D(P3List[i].X, P3List[i].Y, P3List[i].Z, 0.0, 0.0, c2);
						P6List.Add(item2);
					}
				}
			}
			else
			{
