	public void XLengthFromYLengthAndAngle(double YLength, double Angle, ref double XLength)
	{
		try
		{
			if (Angle % 90.0 != 0.0)
			{
				XLength = YLength * Math.Tan(buConversion.DegreeToRadian(Angle));
			}
			else
			{
				XLength = 0.0;
			}
		}
		catch (Exception mSException)
		{
			string text = "YLength: " + YLength + " - Angle: " + Angle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

