	public double XFromXYZ(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D RefPoint)
	{
		try
		{
			double num = 0.0;
			double result = 0.0;
			if (buCompare.EQ(FirstPoint.Y, SecondPoint.Y))
			{
				if (buCompare.EQ(FirstPoint.Z, SecondPoint.Z))
				{
					if (buCompare.EQ(FirstPoint.Y, SecondPoint.Y) & buCompare.EQ(FirstPoint.Z, SecondPoint.Z))
					{
						result = FirstPoint.X;
					}
				}
				else
				{
					num = (SecondPoint.X - FirstPoint.X) / (SecondPoint.Z - FirstPoint.Z);
					result = num * (RefPoint.Z - FirstPoint.Z) + FirstPoint.X;
				}
			}
			else
			{
				num = (SecondPoint.X - FirstPoint.X) / (SecondPoint.Y - FirstPoint.Y);
				result = num * (RefPoint.Y - FirstPoint.Y) + FirstPoint.X;
			}
			return result;
		}
		catch (Exception mSException)
		{
			string text = "FirstPoint: " + FirstPoint.ToString() + " - SecondPoint: " + SecondPoint.ToString() + " - RefPoint: " + RefPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

