	public double ZFromXYZ(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D RefPoint)
	{
		try
		{
			double num = 0.0;
			double result = 0.0;
			if (buCompare.EQ(FirstPoint.X, SecondPoint.X))
			{
				if (buCompare.EQ(FirstPoint.Y, SecondPoint.Y))
				{
					if (buCompare.EQ(FirstPoint.X, SecondPoint.X) & buCompare.EQ(FirstPoint.Y, SecondPoint.Y))
					{
						result = FirstPoint.Z;
					}
				}
				else
				{
					num = (SecondPoint.Z - FirstPoint.Z) / (SecondPoint.Y - FirstPoint.Y);
					result = num * (RefPoint.Y - FirstPoint.Y) + FirstPoint.Z;
				}
			}
			else
			{
				num = (SecondPoint.Z - FirstPoint.Z) / (SecondPoint.X - FirstPoint.X);
				result = num * (RefPoint.X - FirstPoint.X) + FirstPoint.Z;
			}
			return result;
		}
		catch (Exception mSException)
		{
			string text = "FirstPoint: " + FirstPoint.ToString() + " - SecondPoint: " + SecondPoint.ToString() + " - RefPoint: " + RefPoint.ToString();
