	public void XYFromZ(Pnt3D StartPoint, Pnt3D EndPoint, double ZValue, ref Pnt3D CalcPoint)
	{
		try
		{
			double num = StartPoint.X - EndPoint.X;
			double num2 = StartPoint.Y - EndPoint.Y;
			double num3 = StartPoint.Z - EndPoint.Z;
			double num4 = StartPoint.Z - ZValue;
			if (num3 == 0.0)
			{
				CalcPoint = new Pnt3D(StartPoint);
				return;
			}
			double num5 = num4 / num3;
			CalcPoint = new Pnt3D(StartPoint.X - num * num5, StartPoint.Y - num2 * num5, ZValue);
		}
		catch (Exception mSException)
		{
			string text = "StartPoint: " + StartPoint.ToString() + " - EndPoint: " + EndPoint.ToString() + " - ZValue: " + ZValue;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

