	public void XYValueToPointByPlane(double X, double Y, WorkPlane Plane, ref Pnt3D RefPoint)
	{
		try
		{
			if (WorkPlane.isPlaneXY(Plane) | (Plane.PlaneType == planeType.YX))
			{
				RefPoint.X = X;
				RefPoint.Y = Y;
			}
			if (WorkPlane.isPlaneXZ(Plane) | (Plane.PlaneType == planeType.ZX))
			{
				RefPoint.X = X;
				RefPoint.Z = Y;
			}
			if (WorkPlane.isPlaneYZ(Plane) | (Plane.PlaneType == planeType.ZY))
			{
				RefPoint.Y = X;
				RefPoint.Z = Y;
			}
		}
		catch (Exception mSException)
		{
			string text = "X: " + X + " - Y: " + Y + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
