	public void AlingementContentPointByPlane(Pnt3D MinPoint, Pnt3D MaxPoint, ContentAlignment Alingement, WorkPlane Plane, ref Pnt3D CalcPoint, ref Vec3D Size, ref AxesEnableXYZ IsCatchMiddle)
	{
		try
		{
			IsCatchMiddle = new AxesEnableXYZ(x: false, y: false, z: false);
			if (WorkPlane.isPlaneXY(Plane))
			{
				if (Alingement == ContentAlignment.TopLeft)
				{
					CalcPoint.X = MinPoint.X;
					CalcPoint.Y = MaxPoint.Y;
					CalcPoint.Z = 0.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
				if (Alingement == ContentAlignment.TopCenter)
				{
					CalcPoint.X = (MinPoint.X + MaxPoint.X) / 2.0;
					CalcPoint.Y = MaxPoint.Y;
					CalcPoint.Z = 0.0;
					Size.X = MaxPoint.X - CalcPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: true, y: false, z: false);
				}
				if (Alingement == ContentAlignment.TopRight)
				{
					CalcPoint.X = MaxPoint.X;
					CalcPoint.Y = MaxPoint.Y;
					CalcPoint.Z = 0.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
				if (Alingement == ContentAlignment.MiddleLeft)
				{
					CalcPoint.X = MinPoint.X;
					CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
					CalcPoint.Z = 0.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - CalcPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: false, y: true, z: false);
				}
				if (Alingement == ContentAlignment.MiddleCenter)
				{
					CalcPoint.X = (MinPoint.X + MaxPoint.X) / 2.0;
					CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
					CalcPoint.Z = 0.0;
					Size.X = MaxPoint.X - CalcPoint.X;
					Size.Y = MaxPoint.Y - CalcPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: true, y: true, z: false);
				}
				if (Alingement == ContentAlignment.MiddleRight)
				{
					CalcPoint.X = MaxPoint.X;
					CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
					CalcPoint.Z = 0.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - CalcPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: false, y: true, z: false);
				}
				if (Alingement == ContentAlignment.BottomLeft)
				{
					CalcPoint.X = MinPoint.X;
					CalcPoint.Y = MinPoint.Y;
					CalcPoint.Z = 0.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
				if (Alingement == ContentAlignment.BottomCenter)
				{
					CalcPoint.X = (MinPoint.X + MaxPoint.X) / 2.0;
					CalcPoint.Y = MinPoint.Y;
					CalcPoint.Z = 0.0;
					Size.X = MaxPoint.X - CalcPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: true, y: false, z: false);
				}
				if (Alingement == ContentAlignment.BottomRight)
				{
					CalcPoint.X = MaxPoint.X;
					CalcPoint.Y = MinPoint.Y;
					CalcPoint.Z = 0.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				if (Alingement == ContentAlignment.TopLeft)
				{
					CalcPoint.X = MinPoint.X;
					CalcPoint.Y = 0.0;
					CalcPoint.Z = MaxPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
				if (Alingement == ContentAlignment.TopCenter)
				{
					CalcPoint.X = (MinPoint.X + MaxPoint.X) / 2.0;
					CalcPoint.Y = 0.0;
					CalcPoint.Z = MaxPoint.Z;
					Size.X = MaxPoint.X - CalcPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: true, y: false, z: false);
				}
				if (Alingement == ContentAlignment.TopRight)
				{
					CalcPoint.X = MaxPoint.X;
					CalcPoint.Y = 0.0;
					CalcPoint.Z = MaxPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
				if (Alingement == ContentAlignment.MiddleLeft)
				{
					CalcPoint.X = MinPoint.X;
					CalcPoint.Y = 0.0;
					CalcPoint.Z = (MinPoint.Z + MaxPoint.Z) / 2.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - CalcPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: false, y: false, z: true);
				}
				if (Alingement == ContentAlignment.MiddleCenter)
				{
					CalcPoint.X = (MinPoint.X + MaxPoint.X) / 2.0;
					CalcPoint.Y = 0.0;
					CalcPoint.Z = (MinPoint.Z + MaxPoint.Z) / 2.0;
					Size.X = MaxPoint.X - CalcPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - CalcPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: true, y: false, z: true);
				}
				if (Alingement == ContentAlignment.MiddleRight)
				{
					CalcPoint.X = MaxPoint.X;
					CalcPoint.Y = 0.0;
					CalcPoint.Z = (MinPoint.Z + MaxPoint.Z) / 2.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - CalcPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: false, y: false, z: true);
				}
				if (Alingement == ContentAlignment.BottomLeft)
				{
					CalcPoint.X = MinPoint.X;
					CalcPoint.Y = 0.0;
					CalcPoint.Z = MinPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
				if (Alingement == ContentAlignment.BottomCenter)
				{
					CalcPoint.X = (MinPoint.X + MaxPoint.X) / 2.0;
					CalcPoint.Y = 0.0;
					CalcPoint.Z = MinPoint.Z;
					Size.X = MaxPoint.X - CalcPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: true, y: false, z: false);
				}
				if (Alingement == ContentAlignment.BottomRight)
				{
					CalcPoint.X = MaxPoint.X;
					CalcPoint.Y = 0.0;
					CalcPoint.Z = MinPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				if (Alingement == ContentAlignment.TopLeft)
				{
					CalcPoint.X = 0.0;
					CalcPoint.Y = MinPoint.Y;
					CalcPoint.Z = MaxPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
				if (Alingement == ContentAlignment.TopCenter)
				{
					CalcPoint.X = 0.0;
					CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
					CalcPoint.Z = MaxPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - CalcPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: false, y: true, z: false);
				}
				if (Alingement == ContentAlignment.TopRight)
				{
					CalcPoint.X = 0.0;
					CalcPoint.Y = MaxPoint.Y;
					CalcPoint.Z = MaxPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
				if (Alingement == ContentAlignment.MiddleLeft)
				{
					CalcPoint.X = 0.0;
					CalcPoint.Y = MinPoint.Y;
					CalcPoint.Z = (MinPoint.Z + MaxPoint.Z) / 2.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - CalcPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: false, y: false, z: true);
				}
				if (Alingement == ContentAlignment.MiddleCenter)
				{
					CalcPoint.X = 0.0;
					CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
					CalcPoint.Z = (MinPoint.Z + MaxPoint.Z) / 2.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - CalcPoint.Y;
					Size.Z = MaxPoint.Z - CalcPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: false, y: true, z: true);
				}
				if (Alingement == ContentAlignment.MiddleRight)
				{
					CalcPoint.X = 0.0;
					CalcPoint.Y = MaxPoint.Y;
					CalcPoint.Z = (MinPoint.Z + MaxPoint.Z) / 2.0;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - CalcPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: false, y: false, z: true);
				}
				if (Alingement == ContentAlignment.BottomLeft)
				{
					CalcPoint.X = 0.0;
					CalcPoint.Y = MinPoint.Y;
					CalcPoint.Z = MinPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
				if (Alingement == ContentAlignment.BottomCenter)
				{
					CalcPoint.X = 0.0;
					CalcPoint.Y = (MinPoint.Y + MaxPoint.Y) / 2.0;
					CalcPoint.Z = MinPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - CalcPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
					IsCatchMiddle = new AxesEnableXYZ(x: false, y: true, z: false);
				}
				if (Alingement == ContentAlignment.BottomRight)
				{
					CalcPoint.X = 0.0;
					CalcPoint.Y = MaxPoint.Y;
					CalcPoint.Z = MinPoint.Z;
					Size.X = MaxPoint.X - MinPoint.X;
					Size.Y = MaxPoint.Y - MinPoint.Y;
					Size.Z = MaxPoint.Z - MinPoint.Z;
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "MinPoint: " + MinPoint.ToString() + " - MaxPoint: " + MaxPoint.ToString() + " - Alingement: " + Alingement.ToString() + " - Plane: " + Plane.ToString();
