	public void FindClosestPointOfLine(Pnt3D StartPoint, Pnt3D EndPoint, Pnt3D RefPoint, ref ClosestPointType ClosestPoint)
	{
		try
		{
			double num = Length3D(StartPoint, RefPoint);
			double num2 = Length3D(EndPoint, RefPoint);
			if (!(num <= num2))
			{
				ClosestPoint = ClosestPointType.End;
			}
			else
			{
				ClosestPoint = ClosestPointType.Start;
			}
		}
		catch (Exception mSException)
		{
			string text = "StartPoint: " + StartPoint.ToString() + " - EndPoint: " + EndPoint.ToString() + " - RefPoint: " + RefPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
