	public void FindRefPointBtSortNextRule(ref Pnt3D RefPoint, List<eEntities> Entities, SortingNextGroupFindRulesType SortNextType)
	{
		Pnt3D MinPoint = new Pnt3D();
		Pnt3D MaxPoint = new Pnt3D();
		BoxSizeCalculate(Entities, ref MinPoint, ref MaxPoint);
		if (SortNextType == SortingNextGroupFindRulesType.MaxXMaxY || SortNextType == SortingNextGroupFindRulesType.MaxYMaxX)
		{
			RefPoint = new Pnt3D(MaxPoint.X, MaxPoint.Y);
		}
		if (SortNextType == SortingNextGroupFindRulesType.MaxXMinY || SortNextType == SortingNextGroupFindRulesType.MinYMaxX)
		{
			RefPoint = new Pnt3D(MaxPoint.X, MinPoint.Y);
		}
		if (SortNextType == SortingNextGroupFindRulesType.MinXMaxY || SortNextType == SortingNextGroupFindRulesType.MaxYMinX)
		{
			RefPoint = new Pnt3D(MinPoint.X, MaxPoint.Y);
		}
		if (SortNextType == SortingNextGroupFindRulesType.MinXMinY || SortNextType == SortingNextGroupFindRulesType.MinYMinX)
		{
			RefPoint = new Pnt3D(MinPoint.X, MinPoint.Y);
		}
	}

	public void PointFilterByLength(double FilterLength, int CountLimit, ref List<Pnt3D> Vertice)
	{
		try
		{
			List<Pnt3D> list = new List<Pnt3D>();
			List<Pnt3D> list2 = new List<Pnt3D>();
			double num = 0.0;
			if (Vertice.Count <= 0)
			{
				return;
			}
			for (int i = 0; i <= Vertice.Count - 1; i++)
			{
				list.Add(new Pnt3D(Vertice[i]));
			}
			list2.Add(new Pnt3D(list[0]));
			for (int j = 1; j <= list.Count - 1; j++)
			{
				num = Length3D(list2[list2.Count - 1], list[j]);
				if (num > FilterLength)
				{
					list2.Add(new Pnt3D(list[j]));
				}
			}
			if ((list.Count >= 2) & (list2.Count == 1))
			{
				list2.Add(new Pnt3D(list[list.Count - 1]));
			}
			if (!buCompare.EQ(list2[list2.Count - 1], list[list.Count - 1]))
			{
				list2.Add(new Pnt3D(list[list.Count - 1]));
			}
			if (CountLimit > 0)
			{
				if (list2.Count >= CountLimit)
				{
					Vertice.Clear();
					Pnt3D.Copy(list2, ref Vertice);
				}
			}
			else
			{
				Vertice.Clear();
				Pnt3D.Copy(list2, ref Vertice);
			}
		}
		catch (Exception mSException)
		{
			string text = "FilterLength: " + FilterLength;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PointFilterByLengthAndAngle(double FilterLength, double AngleLimit, ref List<Pnt3D> Vertice)
	{
		try
		{
			List<Pnt3D> list = new List<Pnt3D>();
			double num = 0.0;
			if (Vertice.Count <= 0)
			{
				return;
			}
			for (int i = 0; i <= Vertice.Count - 1; i++)
			{
				list.Add(new Pnt3D(Vertice[i]));
			}
			Vertice.Clear();
			Vertice.Add(new Pnt3D(list[0]));
			for (int j = 1; j <= list.Count - 2; j++)
			{
				double num2 = AngleOfTwoLines(list[j - 1], list[j], list[j], list[j + 1], new WorkPlane());
				if (!(num2 > AngleLimit))
				{
					Vertice.Add(new Pnt3D(list[j]));
					continue;
				}
				num = Length3D(Vertice[Vertice.Count - 1], list[j]);
				if (num > FilterLength)
				{
					Vertice.Add(new Pnt3D(list[j]));
				}
			}
			Vertice.Add(new Pnt3D(list[list.Count - 1]));
		}
		catch (Exception mSException)
		{
			string text = "FilterLength: " + FilterLength;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

