	public Pnt3D AddOffsetToPoint(Pnt3D RefPoint, Vec3D OffsetVector, double Value)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			pnt3D = new Pnt3D(RefPoint);
			if (OffsetVector.X > 0.0)
			{
				pnt3D.X += Value;
			}
			if (OffsetVector.X < 0.0)
			{
				pnt3D.X -= Value;
			}
			if (OffsetVector.Y > 0.0)
			{
				pnt3D.Y += Value;
			}
			if (OffsetVector.Y < 0.0)
			{
				pnt3D.Y -= Value;
			}
			if (OffsetVector.Z > 0.0)
			{
				pnt3D.Z += Value;
			}
			if (OffsetVector.Z < 0.0)
			{
				pnt3D.Z -= Value;
			}
			return pnt3D;
		}
		catch (Exception mSException)
		{
			string text = "RefPoint: " + RefPoint.ToString() + " - OffsetVector: " + OffsetVector.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return new Pnt3D();
		}
	}

