	public Pnt3D MostClosestPoint(Pnt3D RefPoint, MostClosestPointType Type, WorkPlane Plane, List<eEntities> RefVertices, ref int Sequence)
	{
		try
		{
			int num = 0;
			bool flag = false;
			double num2 = 10000000000.0;
			double num3 = 0.0;
			Pnt3D result = new Pnt3D();
			if (Type == MostClosestPointType.AllEntities)
			{
				flag = true;
			}
			for (int i = 0; i <= RefVertices.Count - 1; i++)
			{
				if ((RefVertices[i].GetType() != typeof(eLine)) & (RefVertices[i].GetType() != typeof(ePolyline)) & (RefVertices[i].GetType() != typeof(eCam)))
				{
					num = RefVertices[i].Vertice.Count;
					if (num > 0)
					{
						num3 = Length3D(RefVertices[i].Vertice[0], RefPoint, Plane);
						if ((num3 < num2) & (!RefVertices[i].bCamSelected || flag))
						{
							Sequence = i;
							num2 = num3;
							result = new Pnt3D(RefVertices[i].Vertice[0]);
						}
						num3 = Length3D(RefVertices[i].Vertice[num - 1], RefPoint, Plane);
						if ((num3 < num2) & (!RefVertices[i].bCamSelected || flag))
						{
							Sequence = i;
							num2 = num3;
							result = new Pnt3D(RefVertices[i].Vertice[num - 1]);
						}
					}
				}
				if (!((RefVertices[i].GetType() == typeof(eLine)) | (RefVertices[i].GetType() == typeof(ePolyline))))
				{
					continue;
				}
				num = RefVertices[i].Vertice.Count;
				if (num > 0)
				{
					num3 = Length3D(RefVertices[i].Vertice[0], RefPoint, Plane);
					if ((num3 < num2) & (!RefVertices[i].bCamSelected || flag))
					{
						Sequence = i;
						num2 = num3;
						result = new Pnt3D(RefVertices[i].Vertice[0]);
					}
					num3 = Length3D(RefVertices[i].Vertice[num - 1], RefPoint, Plane);
					if ((num3 < num2) & (!RefVertices[i].bCamSelected || flag))
					{
						Sequence = i;
						num2 = num3;
						result = new Pnt3D(RefVertices[i].Vertice[num - 1]);
					}
				}
			}
			return result;
		}
		catch (Exception mSException)
		{
			string text = "RefPoint: " + RefPoint.ToString() + " - Type: " + Type.ToString() + " - Plane: " + Plane.ToString() + " - RefVertices.Count: " + RefVertices.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return new Pnt3D();
		}
	}

