	public void PointConversionByPlane(WorkPlane FromPlane, WorkPlane ToPlane, Pnt3D RefPoint, ref Pnt3D CalcPoint)
	{
		try
		{
			if (WorkPlane.isPlaneXY(FromPlane))
			{
				if (WorkPlane.isPlaneXY(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Y = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
				if (WorkPlane.isPlaneXZ(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Z = RefPoint.Y;
					CalcPoint.Y = RefPoint.Z;
				}
				if (WorkPlane.isPlaneYZ(ToPlane))
				{
					CalcPoint.Y = RefPoint.X;
					CalcPoint.Z = RefPoint.Y;
					CalcPoint.X = RefPoint.Z;
				}
			}
			if (WorkPlane.isPlaneXZ(FromPlane))
			{
				if (WorkPlane.isPlaneXY(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Z = RefPoint.Y;
					CalcPoint.Y = RefPoint.Z;
				}
				if (WorkPlane.isPlaneXZ(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Y = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
				if (WorkPlane.isPlaneYZ(ToPlane))
				{
					CalcPoint.Y = RefPoint.X;
					CalcPoint.X = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
			}
			if (WorkPlane.isPlaneYZ(FromPlane))
			{
				if (WorkPlane.isPlaneYZ(ToPlane))
				{
					CalcPoint.X = RefPoint.X;
					CalcPoint.Y = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
				if (WorkPlane.isPlaneXY(ToPlane))
				{
					CalcPoint.Z = RefPoint.X;
					CalcPoint.X = RefPoint.Y;
					CalcPoint.Y = RefPoint.Z;
				}
				if (WorkPlane.isPlaneXZ(ToPlane))
				{
					CalcPoint.Y = RefPoint.X;
					CalcPoint.X = RefPoint.Y;
					CalcPoint.Z = RefPoint.Z;
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "FromPlane: " + FromPlane.ToString() + " - ToPlane: " + ToPlane.ToString() + " - RefPoint: " + RefPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

