	public void ShiftList(ref List<Pnt3D> List, int ShiftValue)
	{
		if (ShiftValue == 0 || ShiftValue >= List.Count)
		{
			return;
		}
		if (ShiftValue < 0)
		{
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			Pnt3D.Copy(List, ref CopiedPnt);
			List.Clear();
			for (int i = Math.Abs(ShiftValue); i <= CopiedPnt.Count - 1; i++)
			{
				List.Add(new Pnt3D(CopiedPnt[i]));
			}
			for (int j = 0; j < Math.Abs(ShiftValue); j++)
			{
				List.Add(new Pnt3D(CopiedPnt[j]));
			}
		}
		if (ShiftValue > 0)
		{
			List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
			Pnt3D.Copy(List, ref CopiedPnt2);
			List.Clear();
			for (int k = CopiedPnt2.Count - Math.Abs(ShiftValue) - 1; k <= CopiedPnt2.Count - 1; k++)
			{
				List.Add(new Pnt3D(CopiedPnt2[k]));
			}
			for (int l = 0; l < CopiedPnt2.Count - Math.Abs(ShiftValue) - 1; l++)
			{
				List.Add(new Pnt3D(CopiedPnt2[l]));
			}
		}
	}

	public void ShiftPointsByLength(Pnt3D FirstRefPoints, Pnt3D SecondRefPoints, ref List<Pnt3D> Points)
	{
		ShiftPointsByLength(FirstRefPoints, SecondRefPoints, OnlyXYPlane: false, ref Points);
	}

	public void ShiftPointsByLength(Pnt3D FirstRefPoints, Pnt3D SecondRefPoints, bool OnlyXYPlane, ref List<Pnt3D> Points)
	{
		double num = double.MaxValue;
		int num2 = 0;
		for (int i = 0; i <= Points.Count - 1; i++)
		{
			double num3 = Length3D(FirstRefPoints, Points[i]);
			if (OnlyXYPlane)
			{
				num3 = Length3D(FirstRefPoints, Points[i], new WorkPlane());
			}
			if (num3 < num)
			{
				num2 = i;
				num = num3;
			}
		}
		for (int j = 0; j <= Points.Count - 1; j++)
		{
			double num4 = Length3D(SecondRefPoints, Points[j]);
			if (OnlyXYPlane)
			{
				num4 = Length3D(SecondRefPoints, Points[j], new WorkPlane());
			}
			if (num4 < num)
			{
				num = num4;
			}
		}
		if (num2 <= 0)
		{
			return;
		}
		List<Pnt3D> CopiedPnt = new List<Pnt3D>();
		Pnt3D.Copy(Points, ref CopiedPnt);
		Points.Clear();
		for (int k = num2; k <= CopiedPnt.Count - 1; k++)
		{
			Points.Add(new Pnt3D(CopiedPnt[k]));
		}
		for (int l = 0; l < num2; l++)
		{
			if (l != 0)
			{
				Points.Add(new Pnt3D(CopiedPnt[l]));
			}
			else if (!buCompare.EQ(Points[Points.Count - 1], CopiedPnt[l]))
			{
				Points.Add(new Pnt3D(CopiedPnt[l]));
			}
		}
	}

	public void ShiftPointsByLength(Pnt3D RefPoints, ref List<Pnt3D> Points)
	{
		double num = double.MaxValue;
		int num2 = 0;
		bool flag = IsClosed(Points);
		for (int i = 0; i <= Points.Count - 1; i++)
		{
			double num3 = Length3D(RefPoints, Points[i]);
			if (num3 < num)
			{
				num2 = i;
				num = num3;
			}
		}
		if (num2 > 0)
		{
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			Pnt3D.Copy(Points, ref CopiedPnt);
			Points.Clear();
			for (int j = num2; j <= CopiedPnt.Count - 1; j++)
			{
				Points.Add(new Pnt3D(CopiedPnt[j]));
			}
			for (int k = 0; k < num2; k++)
			{
				if (k != 0)
				{
					Points.Add(new Pnt3D(CopiedPnt[k]));
				}
				else if (!buCompare.EQ(Points[Points.Count - 1], CopiedPnt[k]))
				{
					Points.Add(new Pnt3D(CopiedPnt[k]));
				}
			}
		}
		if ((flag & (Points.Count > 2)) && Points[0] != Points[Points.Count - 1])
		{
			Points.Add(new Pnt3D(Points[0]));
		}
	}

	public void CheckDuplicatedPointsWithPrevious(ref List<double> Points)
	{
		try
		{
			List<double> list = new List<double>();
			if (Points.Count <= 0)
			{
				return;
			}
			for (int i = 0; i <= Points.Count - 1; i++)
			{
				list.Add(Points[i]);
			}
			Points.Clear();
			Points.Add(list[0]);
			for (int j = 1; j <= list.Count - 1; j++)
			{
				if (!buCompare.EQ(Points[Points.Count - 1], list[j]))
				{
					Points.Add(list[j]);
				}
			}
			if (Points.Count > 0 && !buCompare.EQ(Points[Points.Count - 1], list[list.Count - 1]))
			{
				Points.RemoveAt(Points.Count - 1);
				Points.Add(list[list.Count - 1]);
			}
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

