	public void ReCreatsLinearPointsByCount(ref List<Pnt3D> Points, int NewCount)
	{
		double dt = 1.0 / (double)NewCount;
		List<Pnt3D> CalculatedPoints = new List<Pnt3D>();
		LineerInterpolation(Points[0], Points[Points.Count - 1], dt, ref CalculatedPoints);
		for (int i = 0; i <= CalculatedPoints.Count - 1; i++)
		{
			for (int j = 1; j <= Points.Count - 1; j++)
			{
				if (IsPointOverAndInsideLine(Points[j - 1], Points[j], CalculatedPoints[i], new WorkPlane(), buSystem.resolutionCompare))
				{
					Pnt3D pnt3D = new Pnt3D(CalculatedPoints[i]);
					double z = ZFromXYZ(Points[j - 1], Points[j], CalculatedPoints[i]);
					pnt3D.Z = z;
					CalculatedPoints[i] = pnt3D;
				}
			}
		}
		Points.Clear();
		Pnt3D.Copy(CalculatedPoints, ref Points);
	}

