	public void GetPlanePointFromLenght(WorkPlane refPlane, double Length, ref Pnt3D calcPoint)
	{
		if ((refPlane.PlaneType == planeType.YZ) | (refPlane.PlaneType == planeType.ZY))
		{
			double num = refPlane.Angles.A;
			if (refPlane.isReverse)
			{
				num += 180.0;
			}
			if (refPlane.UseCenterPoint)
			{
				LineWithLengthAndAngle(refPlane.MiddlePoint, Length, num, refPlane, ref calcPoint);
				return;
			}
			calcPoint = new Pnt3D();
			LineWithLengthAndAngle(refPlane.BasePoint, Length, num, refPlane, ref calcPoint);
		}
	}

	public void PlaneCalculationFromSurfaceQuad(Quad3D Quad, double Angle, double DirectionLenght, planeType PerpendicularType, ref WorkPlane calcPlane)
