		Pnt3D MinPoint = new Pnt3D();
		Pnt3D MidPoint = new Pnt3D();
		Pnt3D MaxPoint = new Pnt3D();
		BoxSizeCalculate(Quad, ref MinPoint, ref MidPoint, ref MaxPoint);
		if (!(Angle < 0.0 && Angle > -90.0))
		{
			if (!(Angle <= -90.0))
			{
				if (!(Angle >= 0.0))
				{
					pnt3D2 = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
