					{
						calcPlane.Angles = new OrientationAngle(num, 0.0, 0.0);
						calcPlane.BaseAngle = num;
						calcPlane.Lenght = Length3D(pnt3D2, pnt3D);
						calcPlane.BasePoint = new Pnt3D(pnt3D2);
						calcPlane.TipPoint = new Pnt3D(pnt3D);
						calcPlane.Quad = new Quad3D(Quad);
						calcPlane.PlaneType = planeType.YZ;
						QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
						flag = true;
					}
					if (!flag)
					{
						pnt3D2 = new Pnt3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
						pnt3D = new Pnt3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
						num = PointAngle(pnt3D, pnt3D2, new WorkPlane(planeType.YZ, 1));
						if (buCompare.EQ(num, Angle, 0.1))
						{
							calcPlane.Angles = new OrientationAngle(num, 0.0, 0.0);
							calcPlane.BaseAngle = num;
							calcPlane.Lenght = Length3D(pnt3D2, pnt3D);
							calcPlane.BasePoint = new Pnt3D(pnt3D2);
							calcPlane.TipPoint = new Pnt3D(pnt3D);
							calcPlane.Quad = new Quad3D(Quad);
							calcPlane.PlaneType = planeType.YZ;
							QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
							flag = true;
						}
					}
				}
				else
				{
					pnt3D2 = new Pnt3D(MinPoint.X, MinPoint.Y, MinPoint.Z);
					pnt3D = new Pnt3D(MinPoint.X, MaxPoint.Y, MaxPoint.Z);
					calcPlane.Angles = new OrientationAngle(Angle, 0.0, 0.0);
					calcPlane.BaseAngle = Angle;
					calcPlane.Lenght = Length3D(pnt3D2, pnt3D);
					calcPlane.BasePoint = new Pnt3D(pnt3D2);
					calcPlane.TipPoint = new Pnt3D(pnt3D);
					calcPlane.Quad = new Quad3D(Quad);
					calcPlane.PlaneType = planeType.YZ;
					QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
				}
			}
			else
			{
				pnt3D2 = new Pnt3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
				pnt3D = new Pnt3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
				calcPlane.Angles = new OrientationAngle(Angle, 0.0, 0.0);
				calcPlane.BaseAngle = Angle;
				calcPlane.Lenght = Length3D(pnt3D2, pnt3D);
				calcPlane.BasePoint = new Pnt3D(pnt3D2);
				calcPlane.TipPoint = new Pnt3D(pnt3D);
				calcPlane.Quad = new Quad3D(Quad);
				calcPlane.PlaneType = planeType.YZ;
				calcPlane.isReverse = true;
				QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
			}
		}
		else
		{
			pnt3D2 = new Pnt3D(MinPoint.X, MaxPoint.Y, MinPoint.Z);
			pnt3D = new Pnt3D(MinPoint.X, MinPoint.Y, MaxPoint.Z);
			calcPlane.Angles = new OrientationAngle(Angle, 0.0, 0.0);
			calcPlane.BaseAngle = Angle;
