	public void PlaneCalculationFromDistancesForProfile(double Width, double Height, double Length, double DistanceWidth, double DistanceHeight, planeType Type, LeftRightLocationType Direction, ProfileYAxisDirection YDirection, ref WorkPlane calcPlane)
	{
		Pnt3D EndPnt = new Pnt3D();
		if (!(Type == planeType.YZ || Type == planeType.ZY))
		{
			return;
		}
		if (Direction == LeftRightLocationType.Right)
		{
			double d = (Height - DistanceHeight) / (Width - DistanceWidth);
			double a = 180.0 - buConversion.RadianToDegree(Math.Atan(d));
			calcPlane.Angles = new OrientationAngle(a, 0.0, 0.0);
			calcPlane.Lenght = Math.Sqrt(Math.Pow(Height - DistanceHeight, 2.0) + Math.Pow(Width - DistanceWidth, 2.0));
			LineWithLengthAndAngle(new Pnt3D(), calcPlane.Lenght, calcPlane.Angles.A, new WorkPlane(planeType.YZ, 1), ref EndPnt);
			calcPlane.BasePoint = new Pnt3D(0.0, Width, DistanceHeight);
			calcPlane.TipPoint = new Pnt3D(0.0, DistanceWidth, Height);
			calcPlane.Quad = new Quad3D(calcPlane.BasePoint, calcPlane.TipPoint, new Pnt3D(Length, calcPlane.TipPoint.Y, calcPlane.TipPoint.Z), new Pnt3D(Length, calcPlane.BasePoint.Y, calcPlane.BasePoint.Z));
			if (YDirection == ProfileYAxisDirection.NegativeDirection)
			{
				Move(new Pnt3D(), new Pnt3D(0.0, 0.0 - Width, 0.0), ref calcPlane.Quad);
				Move(new Pnt3D(), new Pnt3D(0.0, 0.0 - Width, 0.0), ref calcPlane.BasePoint);
				Move(new Pnt3D(), new Pnt3D(0.0, 0.0 - Width, 0.0), ref calcPlane.TipPoint);
			}
			calcPlane.PlaneType = planeType.YZ;
			QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
		}
		if (Direction == LeftRightLocationType.Left)
		{
			double d2 = (Height - DistanceHeight) / (Width - DistanceWidth);
			double a2 = buConversion.RadianToDegree(Math.Atan(d2));
			calcPlane.Angles = new OrientationAngle(a2, 0.0, 0.0);
			calcPlane.Lenght = Math.Sqrt(Math.Pow(Height - DistanceHeight, 2.0) + Math.Pow(Width - DistanceWidth, 2.0));
			LineWithLengthAndAngle(new Pnt3D(), calcPlane.Lenght, calcPlane.Angles.A, new WorkPlane(planeType.YZ, 1), ref EndPnt);
			calcPlane.BasePoint = new Pnt3D(0.0, 0.0, DistanceHeight);
			calcPlane.TipPoint = new Pnt3D(0.0, Width - DistanceWidth, Height);
			calcPlane.Quad = new Quad3D(calcPlane.BasePoint, calcPlane.TipPoint, new Pnt3D(Length, calcPlane.TipPoint.Y, calcPlane.TipPoint.Z), new Pnt3D(Length, calcPlane.BasePoint.Y, calcPlane.BasePoint.Z));
			calcPlane.PlaneType = planeType.YZ;
			if (YDirection == ProfileYAxisDirection.NegativeDirection)
			{
				Move(new Pnt3D(), new Pnt3D(0.0, 0.0 - Width, 0.0), ref calcPlane.Quad);
				Move(new Pnt3D(), new Pnt3D(0.0, 0.0 - Width, 0.0), ref calcPlane.BasePoint);
				Move(new Pnt3D(), new Pnt3D(0.0, 0.0 - Width, 0.0), ref calcPlane.TipPoint);
			}
			QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
		}
	}

	public void PlaneCalculationFromAngleLenghtForProfile(double PlaneLenght, double PlaneAngle, Pnt3D BasePoint, bool UseCenterPoint, double ProfileLength, ref WorkPlane calcPlane)
	{
		Pnt3D EndPnt = new Pnt3D();
		double num = 0.0;
		double num2 = 180.0;
		if (PlaneAngle < 0.0)
		{
			num = 180.0;
			num2 = 0.0;
			calcPlane.isReverse = true;
		}
		calcPlane.Angles = new OrientationAngle(PlaneAngle, 0.0, 0.0);
		calcPlane.BaseAngle = PlaneAngle;
		calcPlane.Lenght = PlaneLenght;
		if (!UseCenterPoint)
		{
			calcPlane.BasePoint = new Pnt3D(BasePoint);
			LineWithLengthAndAngle(calcPlane.BasePoint, calcPlane.Lenght, calcPlane.Angles.A + num, new WorkPlane(planeType.YZ, 1), ref EndPnt);
			calcPlane.TipPoint = new Pnt3D(EndPnt);
		}
		else
		{
			LineWithLengthAndAngle(BasePoint, calcPlane.Lenght / 2.0, calcPlane.Angles.A - num2, new WorkPlane(planeType.YZ, 1), ref calcPlane.BasePoint);
			LineWithLengthAndAngle(calcPlane.BasePoint, calcPlane.Lenght, calcPlane.Angles.A + num, new WorkPlane(planeType.YZ, 1), ref calcPlane.TipPoint);
			calcPlane.MiddlePoint = new Pnt3D(BasePoint);
		}
		calcPlane.Quad = new Quad3D(calcPlane.BasePoint, calcPlane.TipPoint, new Pnt3D(ProfileLength, calcPlane.TipPoint.Y, calcPlane.TipPoint.Z), new Pnt3D(ProfileLength, calcPlane.BasePoint.Y, calcPlane.BasePoint.Z));
		calcPlane.PlaneType = planeType.YZ;
		QuadToPoints(calcPlane.Quad, ref calcPlane.BoxPoints);
	}

	public int AddPocketToLine(Pnt3D Start, Pnt3D End, List<Pnt3D> Location, List<double> Width, List<double> Height, VectorType Direction, UpCenterDownLocationType VerDir, LeftMiddleRightLocationType PocketDirection, ref List<Pnt3D> Calculated)
	{
		try
		{
			double num = 1.0;
			List<double> RefList = new List<double>();
			if (Location.Count <= 0)
			{
				Calculated.Clear();
				Calculated.Add(new Pnt3D(Start));
				Calculated.Add(new Pnt3D(End));
			}
			if (Direction == VectorType.XVector)
			{
				for (int i = 0; i <= Location.Count - 1; i++)
				{
					RefList.Add(Location[i].X);
				}
			}
			if (Direction == VectorType.YVector)
			{
				for (int j = 0; j <= Location.Count - 1; j++)
				{
					RefList.Add(Location[j].Y);
				}
			}
			num = -1.0;
			if (VerDir == UpCenterDownLocationType.Up)
			{
				num = 1.0;
			}
			Calculated.Clear();
			Calculated.Add(new Pnt3D(Start));
			SortList(SortDirectionType.Lower, ref RefList);
			for (int k = 0; k <= RefList.Count - 1; k++)
			{
				if (PocketDirection == LeftMiddleRightLocationType.Middle)
				{
					Calculated.Add(new Pnt3D(Start.X + RefList[k] - Width[k] / 2.0, Start.Y));
					Calculated.Add(new Pnt3D(Start.X + RefList[k] - Width[k] / 2.0, Start.Y + num * Height[k]));
					Calculated.Add(new Pnt3D(Start.X + RefList[k] + Width[k] / 2.0, Start.Y + num * Height[k]));
					Calculated.Add(new Pnt3D(Start.X + RefList[k] + Width[k] / 2.0, Start.Y));
				}
				if (PocketDirection == LeftMiddleRightLocationType.Left)
				{
					Calculated.Add(new Pnt3D(Start.X + RefList[k], Start.Y));
					Calculated.Add(new Pnt3D(Start.X + RefList[k], Start.Y + num * Height[k]));
					Calculated.Add(new Pnt3D(Start.X + RefList[k] + Width[k], Start.Y + num * Height[k]));
					Calculated.Add(new Pnt3D(Start.X + RefList[k] + Width[k], Start.Y));
				}
				if (PocketDirection == LeftMiddleRightLocationType.Right)
				{
					Calculated.Add(new Pnt3D(Start.X + RefList[k] - Width[k], Start.Y));
					Calculated.Add(new Pnt3D(Start.X + RefList[k] - Width[k], Start.Y + num * Height[k]));
					Calculated.Add(new Pnt3D(Start.X + RefList[k], Start.Y + num * Height[k]));
					Calculated.Add(new Pnt3D(Start.X + RefList[k], Start.Y));
				}
			}
			Calculated.Add(new Pnt3D(End));
			return 1;
		}
		catch (Exception mSException)
		{
			string text = "Start: " + Start.ToString() + " - End: " + End.ToString() + " - Location: " + Location.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

