	public void PerfoMaleMale(double StartPoint, double EndPoint, double StartOffset, double EndOffset, double MaleWidth, double FamaleWidth, double TotalHeight, double MaleHeight, ref List<Pnt3D> CalcPoints, ref List<PerfoPoint> PerfoPoints)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			double num6 = 0.0;
			int num7 = 0;
			Pnt3D pnt3D = new Pnt3D();
			PerfoPoint perfoPoint = new PerfoPoint();
			double num8 = EndPoint - StartPoint;
			num6 = TotalHeight - MaleHeight;
			CalcPoints.Clear();
			PerfoPoints.Clear();
			num = num8 - FamaleWidth - StartOffset - EndOffset;
			num2 = FamaleWidth + MaleWidth;
			num7 = (int)Math.Floor(num / num2);
			num4 = (double)num7 * num2 + FamaleWidth;
			num5 = num8 - num4 - StartOffset - EndOffset;
			pnt3D = new Pnt3D(StartPoint, TotalHeight);
			CalcPoints.Add(pnt3D);
			pnt3D = new Pnt3D(num5 / 2.0 + StartPoint + StartOffset, TotalHeight);
			CalcPoints.Add(pnt3D);
			pnt3D = new Pnt3D(num5 / 2.0 + StartPoint + StartOffset, num6);
			CalcPoints.Add(pnt3D);
			num3 = num5 / 2.0 + StartOffset;
			for (int i = 0; i < num7; i++)
			{
				perfoPoint = new PerfoPoint();
				perfoPoint.X = StartPoint + num3 + FamaleWidth / 2.0;
				perfoPoint.Width = FamaleWidth;
				perfoPoint.Height = MaleHeight;
				PerfoPoints.Add(perfoPoint);
				num3 += FamaleWidth;
				pnt3D = new Pnt3D(num3 + StartPoint, num6);
				CalcPoints.Add(pnt3D);
				pnt3D = new Pnt3D(num3 + StartPoint, TotalHeight);
				CalcPoints.Add(pnt3D);
				num3 += MaleWidth;
				pnt3D = new Pnt3D(num3 + StartPoint, TotalHeight);
				CalcPoints.Add(pnt3D);
				pnt3D = new Pnt3D(num3 + StartPoint, num6);
				CalcPoints.Add(pnt3D);
			}
			perfoPoint = new PerfoPoint();
			perfoPoint.X = StartPoint + num3 + FamaleWidth / 2.0;
			perfoPoint.Width = FamaleWidth;
			perfoPoint.Height = MaleHeight;
			PerfoPoints.Add(perfoPoint);
			num3 += FamaleWidth;
			pnt3D = new Pnt3D(num3 + StartPoint, num6);
			CalcPoints.Add(pnt3D);
			pnt3D = new Pnt3D(num3 + StartPoint, TotalHeight);
			CalcPoints.Add(pnt3D);
			num3 = num3 + num5 / 2.0 + EndOffset;
			pnt3D = new Pnt3D(num3 + StartPoint, TotalHeight);
			CalcPoints.Add(pnt3D);
		}
		catch (Exception mSException)
		{
