	public void PerfoEmptyPocket(double StartPoint, double EndPoint, double StartOffset, double EndOffset, double TotalHeight, double MaleHeight, ref List<Pnt3D> CalcPoints, ref List<PerfoPoint> PerfoPoints)
	{
		try
		{
			double num = 0.0;
			PerfoPoint perfoPoint = new PerfoPoint();
			Pnt3D pnt3D = new Pnt3D();
			num = TotalHeight - MaleHeight;
			CalcPoints.Clear();
			PerfoPoints.Clear();
			pnt3D = new Pnt3D(StartPoint + StartOffset, TotalHeight);
			CalcPoints.Add(pnt3D);
			pnt3D = new Pnt3D(StartPoint + StartOffset, num);
			CalcPoints.Add(pnt3D);
			pnt3D = new Pnt3D(EndPoint - EndOffset, num);
			CalcPoints.Add(pnt3D);
			pnt3D = new Pnt3D(EndPoint - EndOffset, TotalHeight);
