	public void ReCalculateEntitiesSawDepth(List<eEntities> RefEntities, bool InsideCalculation, ToolBase Tool, double MaterialThickness, double TargetZ, double InnerCutSafeDistance, bool IfEntitiesOpenTrimFromStartPoint, bool IfEntitiesOpenTrimFromEndPoint, double CutSawDistanceOverlap, ref List<List<eEntities>> calcEntities)
	{
		List<eEntities> CopiedEnt = new List<eEntities>();
		eEntities.CopyEntities(RefEntities, ref CopiedEnt);
		bool reverseThetaCalculation = InsideCalculation;
		List<List<eEntities>> list = new List<List<eEntities>>();
		new List<List<eEntities>>();
		new List<eEntities>();
		eEntities copiedEnt = new eEntities();
		eEntities copiedEnt2 = new eEntities();
		List<eEntities> list2 = new List<eEntities>();
		eEntities ModifiedFirstEntity = new eEntities();
		eEntities ModifiedLastEntity = new eEntities();
		eEntities.CopyEntity(CopiedEnt[0], ref copiedEnt);
		eEntities.CopyEntity(CopiedEnt[CopiedEnt.Count - 1], ref copiedEnt2);
		bool flag = IsClosed(CopiedEnt);
		ClockDirectionType clockDir = EntitiesClockDirection(CopiedEnt, new WorkPlane());
		double num = Math.Sqrt(Math.Pow(Tool.Geometry.Diameter / 2.0, 2.0) - Math.Pow(Tool.Geometry.Diameter / 2.0 - (MaterialThickness - TargetZ), 2.0));
		if (Tool.Purpose == ToolPurpose.Saw && flag)
		{
			EntityCornerModifyByConvexConcave(copiedEnt2, copiedEnt, clockDir, reverseThetaCalculation, num + InnerCutSafeDistance, ref ModifiedFirstEntity, ref ModifiedLastEntity);
			CopiedEnt[0] = ModifiedLastEntity;
			CopiedEnt[CopiedEnt.Count - 1] = ModifiedFirstEntity;
		}
		for (int i = 0; i <= CopiedEnt.Count - 1; i++)
		{
			ModifiedFirstEntity = new eEntities();
			ModifiedLastEntity = new eEntities();
			if (i < CopiedEnt.Count - 1)
			{
				if (Tool.Purpose != ToolPurpose.Saw)
				{
					list2.Add(eEntities.CopyEntity(CopiedEnt[i]));
					list2[list2.Count - 1].bCamSelected = false;
					list2[list2.Count - 1].bSelected = false;
				}
				else
				{
					EntityCornerModifyByConvexConcave(CopiedEnt[i], CopiedEnt[i + 1], clockDir, reverseThetaCalculation, num + InnerCutSafeDistance, ref ModifiedFirstEntity, ref ModifiedLastEntity);
					CopiedEnt[i] = ModifiedFirstEntity;
					CopiedEnt[i + 1] = ModifiedLastEntity;
					list2.Add(ModifiedFirstEntity);
				}
			}
			if (i == CopiedEnt.Count - 1)
			{
				list2.Add(eEntities.CopyEntity(CopiedEnt[i]));
				list2[list2.Count - 1].bCamSelected = false;
				list2[list2.Count - 1].bSelected = false;
			}
		}
		if (!flag && list2.Count >= 1)
		{
			if (IfEntitiesOpenTrimFromStartPoint)
			{
				eEntities ModifiedEntity = new eEntities();
				EntityLengthModify(list2[0], StartPointType.Start, num + CutSawDistanceOverlap, ref ModifiedEntity);
				list2[0] = ModifiedEntity;
			}
			if (IfEntitiesOpenTrimFromEndPoint)
			{
				eEntities ModifiedEntity2 = new eEntities();
				EntityLengthModify(list2[list2.Count - 1], StartPointType.End, num + CutSawDistanceOverlap, ref ModifiedEntity2);
				list2[list2.Count - 1] = ModifiedEntity2;
			}
		}
		List<eEntities> CopiedEnt2 = new List<eEntities>();
		List<eEntities> list3 = new List<eEntities>();
		eEntities copiedEnt3 = new eEntities();
		eEntities.CopyEntity(list2[0], ref copiedEnt3);
		eEntities.CopyEntities(list2, ref CopiedEnt2);
		list3.Add(copiedEnt3);
		for (int j = 1; j <= CopiedEnt2.Count - 1; j++)
		{
			copiedEnt3 = new eEntities();
			eEntities.CopyEntity(CopiedEnt2[j], ref copiedEnt3);
			if (!(CopiedEnt2[j].GetType() != typeof(eUpperLine)))
			{
				if (list3.Count > 0)
				{
					list.Add(list3);
					list3 = new List<eEntities>();
				}
				continue;
			}
			if (list3.Count <= 0)
			{
				list3.Add(copiedEnt3);
				continue;
			}
			if (!(CopiedEnt2[j].Orientation == list3[list3.Count - 1].Orientation))
			{
				list.Add(list3);
				list3 = new List<eEntities>();
				list3.Add(copiedEnt3);
				continue;
			}
			Pnt3D pntStart = new Pnt3D();
			Pnt3D pntEnd = new Pnt3D();
			GetStartPointOfEntityByCamDirection(CopiedEnt2[j], ref pntStart);
			GetEndPointOfEntityByCamDirection(list3[list3.Count - 1], ref pntEnd);
			if (!buCompare.EQ(pntEnd, pntStart))
			{
				list.Add(list3);
				list3 = new List<eEntities>();
				list3.Add(copiedEnt3);
			}
			else
			{
				list3.Add(copiedEnt3);
			}
		}
		if (list3.Count > 0)
		{
			list.Add(list3);
		}
		calcEntities = new List<List<eEntities>>();
		for (int k = 0; k <= list.Count - 1; k++)
		{
			list3 = new List<eEntities>();
			eEntities.CopyEntities(list[k], ref list3);
			ChangeEntityByCamDirection(ref list3);
			calcEntities.Add(eEntities.CopyEntities(list3));
		}
	}

	public void DimensionFromEntity(eEntities RefEntity, int VerticeIndex, Pnt3D pntActive, WorkPlane Plane, bool ForceVertical, bool ForceHorizontal, ref Pnt3D StartPoint, ref Pnt3D EndPoint, ref int CatchIndex, ref DimensionType DimType)
	{
		Pnt3D CalculatedPoint = new Pnt3D();
		DimType = DimensionType.None;
		if (RefEntity.Vertice.Count <= 0)
		{
			return;
		}
		if (RefEntity.GetType() == typeof(eLine))
		{
			double num = 0.0;
			double num2 = 0.0;
			num = Length3D(pntActive, RefEntity.Vertice[0]);
			num2 = Length3D(pntActive, RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
			if (!(num < num2))
			{
				CatchIndex = RefEntity.Vertice.Count - 1;
			}
			else
			{
				CatchIndex = 0;
			}
			double Distance = 0.0;
			if (!(IsPointOverEntity(RefEntity, pntActive, Plane, 0.1, ref CalculatedPoint, ref Distance) && !ForceHorizontal && !ForceVertical))
			{
				if (((RefEntity.geoMinPoint.X < pntActive.X) & (pntActive.X <= RefEntity.geoMaxPoint.X)) && !ForceVertical)
				{
					StartPoint = new Pnt3D(pntActive);
					EndPoint = new Pnt3D(pntActive);
					StartPoint.X = RefEntity.geoMinPoint.X;
					EndPoint.X = RefEntity.geoMaxPoint.X;
					DimType = DimensionType.Horizontal;
				}
				if (((RefEntity.geoMinPoint.Y < pntActive.Y) & (pntActive.Y <= RefEntity.geoMaxPoint.Y)) && !ForceHorizontal)
				{
					StartPoint = new Pnt3D(pntActive);
					EndPoint = new Pnt3D(pntActive);
					StartPoint.Y = RefEntity.geoMinPoint.Y;
					EndPoint.Y = RefEntity.geoMaxPoint.Y;
					DimType = DimensionType.Vertical;
				}
			}
			else
			{
				eEntities CalcEnt = new eEntities();
				Move(CalculatedPoint, pntActive, RefEntity, ref CalcEnt);
				StartPoint = new Pnt3D(CalcEnt.Vertice[0]);
				EndPoint = new Pnt3D(CalcEnt.Vertice[CalcEnt.Vertice.Count - 1]);
				DimType = DimensionType.Length;
			}
		}
		if (RefEntity.GetType() == typeof(ePolyline) && ((VerticeIndex >= 0) & (VerticeIndex <= RefEntity.Vertice.Count - 2)))
		{
			eEntities eEntities2 = new eLine(RefEntity.Vertice[VerticeIndex], RefEntity.Vertice[VerticeIndex + 1]);
			double num3 = 0.0;
			double num4 = 0.0;
			num3 = Length3D(pntActive, eEntities2.Vertice[0]);
			num4 = Length3D(pntActive, eEntities2.Vertice[1]);
			if (!(num3 < num4))
			{
				CatchIndex = 1;
			}
			else
			{
				CatchIndex = 0;
			}
			double Distance2 = 0.0;
			if (!IsPointOverEntity(eEntities2, pntActive, Plane, 0.1, ref CalculatedPoint, ref Distance2))
			{
				if ((eEntities2.geoMinPoint.X < pntActive.X) & (pntActive.X <= eEntities2.geoMaxPoint.X))
				{
					StartPoint = new Pnt3D(pntActive);
					EndPoint = new Pnt3D(pntActive);
					StartPoint.X = eEntities2.geoMinPoint.X;
					EndPoint.X = eEntities2.geoMaxPoint.X;
					DimType = DimensionType.Horizontal;
				}
				if ((eEntities2.geoMinPoint.Y < pntActive.Y) & (pntActive.Y <= eEntities2.geoMaxPoint.Y))
				{
					StartPoint = new Pnt3D(pntActive);
					EndPoint = new Pnt3D(pntActive);
					StartPoint.Y = eEntities2.geoMinPoint.Y;
					EndPoint.Y = eEntities2.geoMaxPoint.Y;
					DimType = DimensionType.Vertical;
				}
			}
			else
			{
				eEntities CalcEnt2 = new eEntities();
				Move(CalculatedPoint, pntActive, eEntities2, ref CalcEnt2);
				StartPoint = new Pnt3D(CalcEnt2.Vertice[0]);
				EndPoint = new Pnt3D(CalcEnt2.Vertice[CalcEnt2.Vertice.Count - 1]);
				DimType = DimensionType.Length;
			}
		}
		if (RefEntity.GetType() == typeof(eArc))
		{
			double num5 = Length3D(pntActive, ((eArc)RefEntity).CenterPoint);
			if (!(num5 > ((eArc)RefEntity).Radius))
			{
				StartPoint = new Pnt3D(((eArc)RefEntity).StartPoint);
				EndPoint = new Pnt3D(((eArc)RefEntity).EndPoint);
				DimType = DimensionType.Length;
			}
			else
			{
				double angle = PointAngle(pntActive, ((eArc)RefEntity).CenterPoint);
				Pnt3D BasePnt = new Pnt3D();
				Pnt3D EndPnt = new Pnt3D();
				LineWithLengthAndAngle(((eArc)RefEntity).CenterPoint, ((eArc)RefEntity).Radius, angle, new WorkPlane(), ref BasePnt, ref EndPnt);
				StartPoint = new Pnt3D(((eArc)RefEntity).CenterPoint);
				EndPoint = new Pnt3D(EndPnt);
				DimType = DimensionType.Radius;
			}
		}
		if (RefEntity.GetType() == typeof(eCircle))
		{
			double num6 = Length3D(pntActive, ((eCircle)RefEntity).CenterPoint);
			if (!(num6 > ((eCircle)RefEntity).Radius))
			{
				CircleDiameterLine(((eCircle)RefEntity).CenterPoint, ((eCircle)RefEntity).Radius, pntActive, ref StartPoint, ref EndPoint);
				DimType = DimensionType.Diameter;
			}
			else
			{
				double angle2 = PointAngle(pntActive, ((eCircle)RefEntity).CenterPoint);
				Pnt3D BasePnt2 = new Pnt3D();
				Pnt3D EndPnt2 = new Pnt3D();
				LineWithLengthAndAngle(((eCircle)RefEntity).CenterPoint, ((eCircle)RefEntity).Radius, angle2, new WorkPlane(), ref BasePnt2, ref EndPnt2);
				StartPoint = new Pnt3D(((eCircle)RefEntity).CenterPoint);
				EndPoint = new Pnt3D(EndPnt2);
				DimType = DimensionType.Radius;
			}
		}
		if (RefEntity.GetType() == typeof(eEllipse))
		{
			if (!IsPointInsidePolygon(RefEntity.Vertice, pntActive))
			{
				EllipseMajorDiameterLine(((eEllipse)RefEntity).CenterPoint, ((eEllipse)RefEntity).MajorRadius, ((eEllipse)RefEntity).Angle, pntActive, ref StartPoint, ref EndPoint);
			}
			else
			{
				EllipseMinorDiameterLine(((eEllipse)RefEntity).CenterPoint, ((eEllipse)RefEntity).MinorRadius, ((eEllipse)RefEntity).Angle, pntActive, ref StartPoint, ref EndPoint);
			}
			DimType = DimensionType.Diameter;
		}
		if ((RefEntity.GetType() == typeof(eBSpline)) | (RefEntity.GetType() == typeof(eBezeir)))
		{
			if ((RefEntity.geoMinPoint.X < pntActive.X) & (pntActive.X <= RefEntity.geoMaxPoint.X))
			{
				StartPoint = new Pnt3D(pntActive);
				EndPoint = new Pnt3D(pntActive);
				StartPoint.X = RefEntity.geoMinPoint.X;
				EndPoint.X = RefEntity.geoMaxPoint.X;
				DimType = DimensionType.Horizontal;
			}
			if ((RefEntity.geoMinPoint.Y < pntActive.Y) & (pntActive.Y <= RefEntity.geoMaxPoint.Y))
			{
				StartPoint = new Pnt3D(pntActive);
				EndPoint = new Pnt3D(pntActive);
				StartPoint.Y = RefEntity.geoMinPoint.Y;
				EndPoint.Y = RefEntity.geoMaxPoint.Y;
				DimType = DimensionType.Vertical;
			}
		}
	}

	public void DimensionLinear(Pnt3D StartPoint, Pnt3D EndPoint, Pnt3D SetPoint, double dimTextHeight, ref eEntities StartPointExtension, ref eEntities EndPointExtension, ref eEntities DimLine)
	{
		bool flag = (!(SetPoint.X <= StartPoint.X) && !(SetPoint.X <= EndPoint.X)) || (!(SetPoint.X >= StartPoint.X) && SetPoint.X < EndPoint.X);
		Pnt3D pnt3D = new Pnt3D();
		Pnt3D pnt3D2 = new Pnt3D();
		if (!flag)
		{
			pnt3D = new Pnt3D(StartPoint.X, SetPoint.Y);
			pnt3D2 = new Pnt3D(EndPoint.X, SetPoint.Y);
			if (SetPoint.Y <= StartPoint.Y || !(SetPoint.Y > EndPoint.Y))
			{
				pnt3D.Y -= dimTextHeight / 2.0;
				pnt3D2.Y -= dimTextHeight / 2.0;
			}
			else
			{
				pnt3D.Y += dimTextHeight / 2.0;
				pnt3D2.Y += dimTextHeight / 2.0;
			}
		}
		else
		{
			pnt3D = new Pnt3D(SetPoint.X, StartPoint.Y);
			pnt3D2 = new Pnt3D(SetPoint.X, EndPoint.Y);
			if (SetPoint.X <= StartPoint.X || !(SetPoint.X > EndPoint.X))
			{
				pnt3D.X -= dimTextHeight / 2.0;
				pnt3D2.X -= dimTextHeight / 2.0;
			}
			else
			{
				pnt3D.X += dimTextHeight / 2.0;
				pnt3D2.X += dimTextHeight / 2.0;
			}
		}
		StartPointExtension = new eLine(StartPoint, pnt3D);
		EndPointExtension = new eLine(EndPoint, pnt3D2);
		DimLine = new eLine(pnt3D, pnt3D2);
	}

	public void DimensionHorizontal(Pnt3D StartPoint, Pnt3D EndPoint, Pnt3D SetPoint, double dimTextHeight, ref eEntities StartPointExtension, ref eEntities EndPointExtension, ref eEntities DimLine)
	{
		if (!(SetPoint.X <= StartPoint.X) && !(SetPoint.X <= EndPoint.X))
		{
			_ = 1;
		}
		else if (!(SetPoint.X >= StartPoint.X))
		{
			_ = SetPoint.X < EndPoint.X;
		}
		else
			_ = 0;
		Pnt3D pnt3D = new Pnt3D();
		Pnt3D pnt3D2 = new Pnt3D();
		pnt3D = new Pnt3D(StartPoint.X, SetPoint.Y);
		pnt3D2 = new Pnt3D(EndPoint.X, SetPoint.Y);
		if (SetPoint.Y <= StartPoint.Y || !(SetPoint.Y > EndPoint.Y))
		{
			pnt3D.Y -= dimTextHeight / 2.0;
			pnt3D2.Y -= dimTextHeight / 2.0;
		}
		else
		{
			pnt3D.Y += dimTextHeight / 2.0;
			pnt3D2.Y += dimTextHeight / 2.0;
		}
		StartPointExtension = new eLine(StartPoint, pnt3D);
		EndPointExtension = new eLine(EndPoint, pnt3D2);
		DimLine = new eLine(pnt3D, pnt3D2);
	}

