	public void DiagonalLengthByAnglePerpendicularDistance(Pnt3D BasePoint, double Angle, double PerpendicularDistance, WorkPlane Plane, ref Pnt3D CalcPoint)
	{
		try
		{
			if ((Math.Abs(Angle) >= -90.0) & (Math.Abs(Angle) <= 180.0))
			{
				double value = PerpendicularDistance / Math.Cos(buConversion.DegreeToRadian(Angle));
				if (WorkPlane.isPlaneXY(Plane))
				{
					Pnt3D BasePnt = new Pnt3D(BasePoint);
					BasePnt.Y += PerpendicularDistance;
					double num = PointAngle(BasePnt, BasePoint, Plane);
					CalcPoint = new Pnt3D(BasePoint);
					LineWithLengthAndAngle(BasePoint, Math.Abs(value), num + Angle, Plane, ref BasePnt, ref CalcPoint);
				}
				if (WorkPlane.isPlaneXZ(Plane))
				{
					Pnt3D BasePnt2 = new Pnt3D(BasePoint);
					BasePnt2.Z += PerpendicularDistance;
					double num2 = PointAngle(BasePnt2, BasePoint, Plane);
					CalcPoint = new Pnt3D(BasePoint);
					LineWithLengthAndAngle(BasePoint, Math.Abs(value), num2 + Angle, Plane, ref BasePnt2, ref CalcPoint);
				}
				if (WorkPlane.isPlaneYZ(Plane))
				{
					Pnt3D BasePnt3 = new Pnt3D(BasePoint);
					BasePnt3.Z += PerpendicularDistance;
					double num3 = PointAngle(BasePnt3, BasePoint, Plane);
					CalcPoint = new Pnt3D(BasePoint);
					LineWithLengthAndAngle(BasePoint, Math.Abs(value), num3 + Angle, Plane, ref BasePnt3, ref CalcPoint);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - Angle: " + Angle + " - PerpendicularDistance: " + PerpendicularDistance + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void LineWithOrientationAngle(Pnt3D BasePoint, OrientationAngle Angles, double Length, ref Pnt3D calcPoint)
	{
		try
		{
			calcPoint.X = BasePoint.X + Length * Math.Sin(buConversion.DegreeToRadian(Angles.A)) * Math.Cos(buConversion.DegreeToRadian(Angles.C + 90.0));
			calcPoint.Y = BasePoint.Y + Length * Math.Sin(buConversion.DegreeToRadian(Angles.A)) * Math.Sin(buConversion.DegreeToRadian(Angles.C + 90.0));
			calcPoint.Z = BasePoint.Z + Length * Math.Cos(buConversion.DegreeToRadian(Angles.A));
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - Angles: " + Angles.ToString() + " - Length: " + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void LineWithLengthAndAngle(Pnt3D CenterPnt, double Length, double Angle, WorkPlane Plane, ref Pnt3D EndPnt)
	{
		try
		{
			Pnt3D BasePnt = new Pnt3D();
			LineWithLengthAndAngle(CenterPnt, Length, Angle, Plane, ref BasePnt, ref EndPnt);
		}
		catch (Exception mSException)
		{
			string text = "Center: " + CenterPnt.ToString() + " - Len: " + Length + " - Angle: " + Angle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void LineWithLengthAndAngle(Pnt3D CenterPnt, double Length, double Angle, WorkPlane Plane, ref Pnt3D BasePnt, ref Pnt3D EndPnt)
	{
		try
		{
			BasePnt = new Pnt3D();
			EndPnt = new Pnt3D();
			if (WorkPlane.isPlaneXY(Plane) | (Plane.PlaneType == planeType.YX))
			{
				BasePnt.X = CenterPnt.X;
				BasePnt.Y = CenterPnt.Y;
				BasePnt.Z = CenterPnt.Z;
				EndPnt.X = CenterPnt.X + Length * Math.Cos(buConversion.DegreeToRadian(Angle));
				EndPnt.Y = CenterPnt.Y + Length * Math.Sin(buConversion.DegreeToRadian(Angle));
				EndPnt.Z = CenterPnt.Z;
			}
			if ((Plane.PlaneType == planeType.XZ) | (Plane.PlaneType == planeType.ZX))
			{
				BasePnt.X = CenterPnt.X;
				BasePnt.Y = CenterPnt.Y;
				BasePnt.Z = CenterPnt.Z;
				EndPnt.X = CenterPnt.X + Length * Math.Cos(buConversion.DegreeToRadian(Angle));
				EndPnt.Y = CenterPnt.Y;
				EndPnt.Z = CenterPnt.Z + Length * Math.Sin(buConversion.DegreeToRadian(Angle));
			}
			if ((Plane.PlaneType == planeType.YZ) | (Plane.PlaneType == planeType.ZY))
			{
				BasePnt.X = CenterPnt.X;
				BasePnt.Y = CenterPnt.Y;
				BasePnt.Z = CenterPnt.Z;
				EndPnt.X = CenterPnt.X;
				EndPnt.Y = CenterPnt.Y + Length * Math.Cos(buConversion.DegreeToRadian(Angle));
				EndPnt.Z = CenterPnt.Z + Length * Math.Sin(buConversion.DegreeToRadian(Angle));
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + CenterPnt.ToString() + " - Len: " + Length + " - Angle: " + Angle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void LinePerpendicular(double LX1, double LY1, double LX2, double LY2, double BaseX, double BaseY, double Length, ref double CalcX1, ref double CalcY1, ref double CalcX2, ref double CalcY2)
	{
		double num = 0.0;
		double num2 = 0.0;
		double num3 = 0.0;
		double num4 = 0.0;
		double num5 = 0.0;
		double num6 = 0.0;
		num5 = Length;
		if (!buCompare.EQ(LX1, LX2))
		{
			num6 = (LY2 - LY1) / (LX2 - LX1);
			num = -0.5 * num6 / (Math.Pow(num6, 2.0) + 1.0) * (2.0 * Math.Pow(num6, 2.0) * BaseY + 2.0 * BaseY + 2.0 * Math.Pow(Math.Pow(num6, 2.0) * Math.Pow(num5, 2.0) + Math.Pow(num5, 2.0), 0.5)) + num6 * BaseY + BaseX;
			num3 = -0.5 * num6 / (Math.Pow(num6, 2.0) + 1.0) * (2.0 * Math.Pow(num6, 2.0) * BaseY + 2.0 * BaseY - 2.0 * Math.Pow(Math.Pow(num6, 2.0) * Math.Pow(num5, 2.0) + Math.Pow(num5, 2.0), 0.5)) + num6 * BaseY + BaseX;
			num2 = 0.5 / (Math.Pow(num6, 2.0) + 1.0) * (2.0 * Math.Pow(num6, 2.0) * BaseY + 2.0 * BaseY + 2.0 * Math.Pow(Math.Pow(num6, 2.0) * Math.Pow(num5, 2.0) + Math.Pow(num5, 2.0), 0.5));
			num4 = 0.5 / (Math.Pow(num6, 2.0) + 1.0) * (2.0 * Math.Pow(num6, 2.0) * BaseY + 2.0 * BaseY - 2.0 * Math.Pow(Math.Pow(num6, 2.0) * Math.Pow(num5, 2.0) + Math.Pow(num5, 2.0), 0.5));
		}
		if (buCompare.EQ(LX1, LX2))
		{
			num = LX1 + num5;
			num3 = LX1 - num5;
			num2 = BaseY;
			num4 = BaseY;
		}
		CalcX1 = num;
		CalcY1 = num2;
		CalcX2 = num3;
		CalcY2 = num4;
	}

	public void LinePerpendicular(Pnt3D RefStartPoint, Pnt3D RefEndPoint, Pnt3D BasePoint, double Length, WorkPlane Plane, ref Pnt3D CalcStartPoint, ref Pnt3D CalcEndPoint)
	{
		double CalcX = 0.0;
		double CalcY = 0.0;
		double CalcX2 = 0.0;
		double CalcY2 = 0.0;
		CalcStartPoint = new Pnt3D();
		CalcEndPoint = new Pnt3D();
		if (WorkPlane.isPlaneXY(Plane))
		{
			LinePerpendicular(RefStartPoint.X, RefStartPoint.Y, RefEndPoint.X, RefEndPoint.Y, BasePoint.X, BasePoint.Y, Length, ref CalcX, ref CalcY, ref CalcX2, ref CalcY2);
			CalcStartPoint.X = CalcX;
			CalcStartPoint.Y = CalcY;
			CalcStartPoint.Z = BasePoint.Z;
			CalcEndPoint.X = CalcX2;
			CalcEndPoint.Y = CalcY2;
			CalcEndPoint.Z = BasePoint.Z;
		}
		if (WorkPlane.isPlaneXZ(Plane))
		{
			LinePerpendicular(RefStartPoint.X, RefStartPoint.Z, RefEndPoint.X, RefEndPoint.Z, BasePoint.X, BasePoint.Z, Length, ref CalcX, ref CalcY, ref CalcX2, ref CalcY2);
			CalcStartPoint.X = CalcX;
			CalcStartPoint.Y = BasePoint.Y;
			CalcStartPoint.Z = CalcY;
			CalcEndPoint.X = CalcX2;
			CalcEndPoint.Y = BasePoint.Y;
			CalcEndPoint.Z = CalcY2;
		}
		if (WorkPlane.isPlaneYZ(Plane))
		{
			LinePerpendicular(RefStartPoint.Y, RefStartPoint.Z, RefEndPoint.Y, RefEndPoint.Z, BasePoint.Y, BasePoint.Z, Length, ref CalcX, ref CalcY, ref CalcX2, ref CalcY2);
			CalcStartPoint.X = BasePoint.X;
			CalcStartPoint.Y = CalcX;
			CalcStartPoint.Z = CalcY;
			CalcEndPoint.X = BasePoint.X;
			CalcEndPoint.Y = CalcX2;
			CalcEndPoint.Z = CalcY2;
		}
	}

	public void LineParalelToLine(double LX1, double LY1, double LX2, double LY2, double Length, ref double CalcLX1_1, ref double CalcLY1_1, ref double CalcLX2_1, ref double CalcLY2_1, ref double CalcLX1_2, ref double CalcLY1_2, ref double CalcLX2_2, ref double CalcLY2_2)
	{
		double CalcX = 0.0;
		double CalcY = 0.0;
		double CalcX2 = 0.0;
		double CalcY2 = 0.0;
		double CalcX3 = 0.0;
		double CalcY3 = 0.0;
		double CalcX4 = 0.0;
		double CalcY4 = 0.0;
		LinePerpendicular(LX1, LY1, LX2, LY2, LX1, LY1, Length, ref CalcX, ref CalcY, ref CalcX2, ref CalcY2);
		LinePerpendicular(LX1, LY1, LX2, LY2, LX2, LY2, Length, ref CalcX3, ref CalcY3, ref CalcX4, ref CalcY4);
		CalcLX1_1 = CalcX;
		CalcLY1_1 = CalcY;
		CalcLX2_1 = CalcX3;
		CalcLY2_1 = CalcY3;
		CalcLX1_2 = CalcX2;
		CalcLY1_2 = CalcY2;
		CalcLX2_2 = CalcX4;
		CalcLY2_2 = CalcY4;
	}

	public void LineParalelToLine(Line3D RefLine, double Distance, ref Line3D CalculatedLine1, ref Line3D CalculatedLine2)
	{
		double CalcLX1_ = 0.0;
		double CalcLY1_ = 0.0;
		double num = 0.0;
		double CalcLX2_ = 0.0;
		double CalcLY2_ = 0.0;
		double num2 = 0.0;
		double CalcLX1_2 = 0.0;
		double CalcLY1_2 = 0.0;
		double num3 = 0.0;
		double CalcLX2_2 = 0.0;
		double CalcLY2_2 = 0.0;
		double num4 = 0.0;
		Pnt3D pnt3D = new Pnt3D();
		num = RefLine.Start.Z;
		num2 = RefLine.End.Z;
		num3 = RefLine.Start.Z;
		num4 = RefLine.End.Z;
		LineParalelToLine(RefLine.Start.X, RefLine.Start.Y, RefLine.End.X, RefLine.End.Y, Distance, ref CalcLX1_, ref CalcLY1_, ref CalcLX2_, ref CalcLY2_, ref CalcLX1_2, ref CalcLY1_2, ref CalcLX2_2, ref CalcLY2_2);
		pnt3D.X = CalcLX1_;
		pnt3D.Y = CalcLY1_;
		pnt3D.Z = num;
		CalculatedLine1.Start = new Pnt3D(pnt3D);
		pnt3D.X = CalcLX2_;
		pnt3D.Y = CalcLY2_;
		pnt3D.Z = num2;
		CalculatedLine1.End = new Pnt3D(pnt3D);
		pnt3D.X = CalcLX1_2;
		pnt3D.Y = CalcLY1_2;
		pnt3D.Z = num3;
		CalculatedLine2.Start = new Pnt3D(pnt3D);
		pnt3D.X = CalcLX2_2;
		pnt3D.Y = CalcLY2_2;
		pnt3D.Z = num4;
		CalculatedLine2.End = new Pnt3D(pnt3D);
	}

	public void LineParalelToLine(Line3D RefLine, double Distance, WorkPlane Plane, ref Line3D CalculatedLine1, ref Line3D CalculatedLine2)
	{
		Line3D line3D = new Line3D();
		Line3D CalculatedLine3 = new Line3D();
		Line3D CalculatedLine4 = new Line3D();
		Pnt3D pnt3D = new Pnt3D();
		if (WorkPlane.isPlaneXY(Plane))
		{
			line3D = RefLine;
			LineParalelToLine(line3D, Distance, ref CalculatedLine3, ref CalculatedLine4);
			CalculatedLine1 = CalculatedLine3;
			CalculatedLine2 = CalculatedLine4;
		}
		if (WorkPlane.isPlaneXZ(Plane))
		{
			pnt3D = new Pnt3D();
			pnt3D.X = RefLine.Start.X;
			pnt3D.Y = RefLine.Start.Z;
			pnt3D.Z = RefLine.Start.Y;
			line3D.Start = new Pnt3D(pnt3D);
			pnt3D = new Pnt3D();
			pnt3D.X = RefLine.End.X;
			pnt3D.Y = RefLine.End.Z;
			pnt3D.Z = RefLine.End.Y;
			line3D.End = new Pnt3D(pnt3D);
			LineParalelToLine(line3D, Distance, ref CalculatedLine3, ref CalculatedLine4);
			pnt3D = new Pnt3D();
			pnt3D.X = CalculatedLine3.Start.X;
			pnt3D.Y = RefLine.Start.Y;
			pnt3D.Z = CalculatedLine3.Start.Y;
			CalculatedLine1.Start = new Pnt3D(pnt3D);
			pnt3D = new Pnt3D();
			pnt3D.X = CalculatedLine3.End.X;
			pnt3D.Y = RefLine.End.Y;
			pnt3D.Z = CalculatedLine3.End.Y;
			CalculatedLine1.End = new Pnt3D(pnt3D);
			pnt3D = new Pnt3D();
			pnt3D.X = CalculatedLine4.Start.X;
			pnt3D.Y = RefLine.Start.Y;
			pnt3D.Z = CalculatedLine4.Start.Y;
			CalculatedLine2.Start = new Pnt3D(pnt3D);
			pnt3D = new Pnt3D();
			pnt3D.X = CalculatedLine4.End.X;
			pnt3D.Y = RefLine.End.Y;
			pnt3D.Z = CalculatedLine4.End.Y;
			CalculatedLine2.End = new Pnt3D(pnt3D);
		}
		if (WorkPlane.isPlaneYZ(Plane))
		{
			pnt3D = new Pnt3D();
			pnt3D.X = RefLine.Start.Y;
			pnt3D.Y = RefLine.Start.Z;
			pnt3D.Z = RefLine.Start.X;
			line3D.Start = new Pnt3D(pnt3D);
			pnt3D = new Pnt3D();
			pnt3D.X = RefLine.End.Y;
			pnt3D.Y = RefLine.End.Z;
			pnt3D.Z = RefLine.End.X;
			line3D.End = new Pnt3D(pnt3D);
			LineParalelToLine(line3D, Distance, ref CalculatedLine3, ref CalculatedLine4);
			pnt3D = new Pnt3D();
			pnt3D.X = CalculatedLine3.Start.Z;
			pnt3D.Y = CalculatedLine3.Start.X;
			pnt3D.Z = CalculatedLine3.Start.Y;
			CalculatedLine1.Start = new Pnt3D(pnt3D);
			pnt3D = new Pnt3D();
			pnt3D.X = CalculatedLine3.End.Z;
			pnt3D.Y = CalculatedLine3.End.X;
			pnt3D.Z = CalculatedLine3.End.Y;
			CalculatedLine1.End = new Pnt3D(pnt3D);
			pnt3D = new Pnt3D();
			pnt3D.X = CalculatedLine4.Start.Z;
			pnt3D.Y = CalculatedLine4.Start.X;
			pnt3D.Z = CalculatedLine4.Start.Y;
			CalculatedLine2.Start = new Pnt3D(pnt3D);
			pnt3D = new Pnt3D();
			pnt3D.X = CalculatedLine4.End.Z;
			pnt3D.Y = CalculatedLine4.End.X;
			pnt3D.Z = CalculatedLine4.End.Y;
			CalculatedLine2.End = new Pnt3D(pnt3D);
		}
	}

	public bool LineSplitByRefPoint(eEntities LineEntity, Pnt3D RefPoint, ref eEntities FirstEntity, ref eEntities SecondEntity)
	{
		try
		{
			if (!(LineEntity.GetType() == typeof(eLine)))
			{
				FirstEntity = new eEntities();
				SecondEntity = new eEntities();
				eEntities.CopyEntity(LineEntity, ref FirstEntity);
				eEntities.CopyEntity(LineEntity, ref SecondEntity);
				return false;
			}
			Line3D FirstLine = new Line3D();
			Line3D SecondLine = new Line3D();
			bool result;
			if (!(result = LineSplitByRefPoint(LineEntity.Vertice[0], LineEntity.Vertice[1], RefPoint, ref FirstLine, ref SecondLine)))
			{
				FirstEntity = new eEntities();
				SecondEntity = new eEntities();
				eEntities.CopyEntity(LineEntity, ref FirstEntity);
				eEntities.CopyEntity(LineEntity, ref SecondEntity);
			}
			else
			{
				FirstEntity = new eLine(FirstLine.Start, FirstLine.End);
				eEntities.CopyCommonPorperties(LineEntity, ref FirstEntity);
				SecondEntity = new eLine(SecondLine.Start, SecondLine.End);
				eEntities.CopyCommonPorperties(LineEntity, ref SecondEntity);
			}
			return result;
		}
		catch (Exception mSException)
		{
			string text = "LineEntity: " + LineEntity.ToString() + " - RefPoint: " + RefPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public bool LineSplitByRefPoint(Pnt3D StartPoint, Pnt3D EndPoint, Pnt3D RefPoint, ref Line3D FirstLine, ref Line3D SecondLine)
	{
		try
		{
			bool flag = false;
			Pnt3D CalculatedPoint = new Pnt3D();
			if (!IsPointOverAndInsideLine(StartPoint, EndPoint, RefPoint, new WorkPlane(), buSystem.resolutionCompare, ref CalculatedPoint))
			{
				FirstLine = new Line3D(StartPoint, EndPoint);
				SecondLine = new Line3D(StartPoint, EndPoint);
				flag = false;
			}
			else
			{
				FirstLine = new Line3D(StartPoint, CalculatedPoint);
				SecondLine = new Line3D(CalculatedPoint, EndPoint);
				flag = true;
			}
			return flag;
		}
		catch (Exception mSException)
		{
			string text = "StartPoint: " + StartPoint.ToString() + " - EndPoint: " + EndPoint.ToString() + " - RefPoint: " + RefPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public void LineWithCenterPointByLengthAndAngle(Pnt3D CenterPoint, double Lenght, double Angle, WorkPlane Plane, ref Pnt3D StartPoint, ref Pnt3D EndPoint)
	{
		try
		{
			Pnt3D BasePnt = new Pnt3D();
			Pnt3D EndPnt = new Pnt3D();
			LineWithLengthAndAngle(CenterPoint, Lenght, Angle, Plane, ref BasePnt, ref EndPnt);
			LineWithLengthAndAngle(EndPnt, Lenght * 2.0, Angle + 180.0, Plane, ref StartPoint, ref EndPoint);
		}
		catch (Exception mSException)
		{
			string text = "CenterPoint: " + CenterPoint.ToString() + " - Lenght: " + Lenght + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public bool AddPointToPolylineIfOnPath(ref eEntities PolylineEnt, Pnt3D AddingPoint, double Resolution)
	{
		try
		{
			bool result = false;
			if (PolylineEnt.GetType() == typeof(ePolyline))
			{
				for (int i = 1; i <= PolylineEnt.Vertice.Count - 1; i++)
				{
					if (IsPointOverAndInsideLine(PolylineEnt.Vertice[i - 1], PolylineEnt.Vertice[i], AddingPoint, new WorkPlane(), Resolution) && ((PolylineEnt.Vertice[i - 1] != AddingPoint) & (PolylineEnt.Vertice[i] != AddingPoint)))
					{
						PolylineEnt.Vertice.Insert(i, new Pnt3D(AddingPoint));
						((ePolyline)PolylineEnt).Update();
						result = true;
					}
				}
			}
			return result;
		}
		catch (Exception mSException)
		{
			string text = "PolylineEnt: " + PolylineEnt.ToString() + " - AddingPoint: " + AddingPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public void CircleWithCenter(Pnt3D Center, double Radius, WorkPlane Plane, EntityResolution EntResolution, ref List<Pnt3D> Vertices)
	{
		try
		{
			int num = 0;
			Pnt3D pnt3D = new Pnt3D();
			Vertices.Clear();
			num = CircleVerticeCountByResolution(Radius, EntResolution);
			for (int i = 0; i <= num; i++)
			{
				pnt3D = new Pnt3D();
				if (WorkPlane.isPlaneXY(Plane))
				{
					pnt3D.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((float)i * 360f / (float)num));
					pnt3D.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((float)i * 360f / (float)num));
					pnt3D.Z = Center.Z;
					Vertices.Add(pnt3D);
				}
				if (Plane.PlaneType == planeType.XZ)
				{
					pnt3D.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((float)i * 360f / (float)num));
					pnt3D.Y = Center.Y;
					pnt3D.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((float)i * 360f / (float)num));
					Vertices.Add(pnt3D);
				}
				if (Plane.PlaneType == planeType.YZ)
				{
					pnt3D.X = Center.X;
					pnt3D.Y = Center.Y + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((float)i * 360f / (float)num));
					pnt3D.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((float)i * 360f / (float)num));
					Vertices.Add(pnt3D);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Rad: " + Radius + " - Plane: " + Plane.ToString() + " - EntResolution: " + EntResolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

