	public void Circle2Point(Pnt3D FirstPoint, Pnt3D SecondPoint, WorkPlane Plane, EntityResolution EntResolution, ref Pnt3D CenterPoint, ref double Radius, ref List<Pnt3D> Vertices)
	{
		try
		{
			int num = 1;
			Vertices.Clear();
			if (WorkPlane.isPlaneXY(Plane))
			{
				Radius = Math.Sqrt(Math.Pow(FirstPoint.X - SecondPoint.X, 2.0) + Math.Pow(FirstPoint.Y - SecondPoint.Y, 2.0)) / 2.0;
				if (Radius <= 0.0)
				{
					return;
				}
				CenterPoint.X = FirstPoint.X + (SecondPoint.X - FirstPoint.X) / 2.0;
				CenterPoint.Y = FirstPoint.Y + (SecondPoint.Y - FirstPoint.Y) / 2.0;
				CenterPoint.Z = FirstPoint.Z;
				num = CircleVerticeCountByResolution(Radius, EntResolution);
				if (num < 10)
				{
					num = 10;
				}
				for (int i = 0; i <= num; i++)
				{
					if (WorkPlane.isPlaneXY(Plane))
					{
						Pnt3D pnt3D = new Pnt3D();
						pnt3D.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((float)i * 360f / (float)num));
						pnt3D.Y = CenterPoint.Y + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((float)i * 360f / (float)num));
						pnt3D.Z = CenterPoint.Z;
						Vertices.Add(pnt3D);
					}
				}
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				Radius = Math.Sqrt(Math.Pow(FirstPoint.X - SecondPoint.X, 2.0) + Math.Pow(FirstPoint.Z - SecondPoint.Z, 2.0)) / 2.0;
				if (Radius <= 0.0)
				{
					return;
				}
				CenterPoint.X = FirstPoint.X + (SecondPoint.X - FirstPoint.X) / 2.0;
				CenterPoint.Y = FirstPoint.Y;
				CenterPoint.Z = FirstPoint.Z + (SecondPoint.Z - FirstPoint.Z) / 2.0;
				num = CircleVerticeCountByResolution(Radius, EntResolution);
				if (num < 10)
				{
					num = 10;
				}
				for (int j = 0; j <= num; j++)
				{
					if (WorkPlane.isPlaneXZ(Plane))
					{
						Pnt3D pnt3D2 = new Pnt3D();
						pnt3D2.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((float)j * 360f / (float)num));
						pnt3D2.Y = CenterPoint.Y;
						pnt3D2.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((float)j * 360f / (float)num));
						Vertices.Add(pnt3D2);
					}
				}
			}
			if (!WorkPlane.isPlaneYZ(Plane))
			{
				return;
			}
			Radius = Math.Sqrt(Math.Pow(FirstPoint.Y - SecondPoint.Y, 2.0) + Math.Pow(FirstPoint.Z - SecondPoint.Z, 2.0)) / 2.0;
			if (Radius <= 0.0)
			{
				return;
			}
			CenterPoint.X = FirstPoint.X;
			CenterPoint.Y = FirstPoint.Y + (SecondPoint.Y - FirstPoint.Y) / 2.0;
			CenterPoint.Z = FirstPoint.Z + (SecondPoint.Z - FirstPoint.Z) / 2.0;
			num = CircleVerticeCountByResolution(Radius, EntResolution);
			if (num < 10)
			{
				num = 10;
			}
			for (int k = 0; k <= num; k++)
			{
				if (WorkPlane.isPlaneYZ(Plane))
				{
					Pnt3D pnt3D3 = new Pnt3D();
					pnt3D3.X = CenterPoint.X;
					pnt3D3.Y = CenterPoint.Y + Radius * Math.Cos(buConversion.DegreeToRadianGreat360((float)k * 360f / (float)num));
					pnt3D3.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360((float)k * 360f / (float)num));
					Vertices.Add(pnt3D3);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "FirstPoint: " + FirstPoint.ToString() + " - SecondPoint: " + SecondPoint.ToString() + " - Plane: " + Plane.ToString() + " - EntResolution: " + EntResolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Circle2Point(Pnt3D FirstPoint, Pnt3D SecondPoint, WorkPlane Plane, ref Pnt3D CenterPoint, ref double Radius)
	{
		List<Pnt3D> Vertices = new List<Pnt3D>();
		Circle2Point(FirstPoint, SecondPoint, Plane, new EntityResolution(), ref CenterPoint, ref Radius, ref Vertices);
		Vertices.Clear();
	}

