	public int Circle3Point(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D ThirdPoint, WorkPlane Plane, EntityResolution EntResolution, ref List<Pnt3D> Vertices)
	{
		Pnt3D CenterPoint = new Pnt3D();
		double Radius = 0.0;
		Circle3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, EntResolution, ref CenterPoint, ref Radius, ref Vertices);
		return 1;
	}

	public int Circle3Point(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D ThirdPoint, WorkPlane Plane, ref Pnt3D CenterPoint, ref double Radius)
	{
		List<Pnt3D> Vertices = new List<Pnt3D>();
		Circle3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, new EntityResolution(), ref CenterPoint, ref Radius, ref Vertices);
		Vertices.Clear();
		return 1;
	}

	public int CircleVerticeCountByResolution(double Radius, EntityResolution EntResolution)
	{
		try
		{
			int num = 10;
			double num2 = 0.0;
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByNumber)
			{
				num = EntResolution.GeometricCount;
			}
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByLength && buNumeric.IsNumeric(Radius.ToString()))
			{
				num2 = Math.PI * 2.0 * Radius;
				num = Convert.ToInt32(num2 / EntResolution.GeometricLength);
			}
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByLnRadius && buNumeric.IsNumeric(Radius.ToString()) && Radius > 0.0)
			{
				num = Convert.ToInt32(Math.Log(Radius, Math.E) * EntResolution.LnRatio);
			}
			if (num < EntResolution.MinPointCount)
			{
				num = EntResolution.MinPointCount;
			}
			return num;
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - Entitiy Res: " + EntResolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

	public double CircleArea(double Radius, double StartAngle, double EndAngle)
	{
		try
		{
			return Math.PI * Radius * Radius;
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - SA: " + StartAngle + " - EA: " + EndAngle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double CircleCircumference(double Radius, double StartAngle, double EndAngle)
	{
		try
		{
			return Radius * Math.PI * 2.0;
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - SA: " + StartAngle + " - EA: " + EndAngle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public void CircleDiameterLine(Pnt3D Center, double Radius, Pnt3D ActivePoint, ref Pnt3D FirstPoint, ref Pnt3D SecondPoint)
	{
		try
		{
			if (Radius > 0.0)
			{
				double num = PointAngle(ActivePoint, Center);
				Pnt3D BasePnt = new Pnt3D();
				Pnt3D EndPnt = new Pnt3D();
				LineWithLengthAndAngle(Center, Radius, num, new WorkPlane(), ref BasePnt, ref EndPnt);
				LineWithLengthAndAngle(EndPnt, Radius * 2.0, num + 180.0, new WorkPlane(), ref FirstPoint, ref SecondPoint);
			}
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - Center: " + Center.ToString() + " - ActivePoint: " + ActivePoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void CircleRadiusLine(Pnt3D Center, double Radius, Pnt3D ActivePoint, ref Pnt3D FirstPoint, ref Pnt3D SecondPoint)
	{
		try
		{
			if (Radius > 0.0)
			{
				double angle = PointAngle(ActivePoint, Center);
				LineWithLengthAndAngle(Center, Radius, angle, new WorkPlane(), ref FirstPoint, ref SecondPoint);
			}
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - Center: " + Center.ToString() + " - ActivePoint: " + ActivePoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void CircleQuadrantPoints(Pnt3D Center, double Radius, ref Pnt3D Point0, ref Pnt3D Point90, ref Pnt3D Point180, ref Pnt3D Point270)
	{
		try
		{
			Point0.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(0.0));
			Point0.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(0.0));
			Point90.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(90.0));
			Point90.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(90.0));
			Point180.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(180.0));
			Point180.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(180.0));
			Point270.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(270.0));
			Point270.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(270.0));
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - Center: " + Center.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public double CircleSegmentLengthByDepth(double Radius, double RemoveLength)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			num2 = Radius - RemoveLength;
			num = Math.Sqrt(Math.Pow(Radius, 2.0) - Math.Pow(num2, 2.0));
			return num * 2.0;
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - RemoveLength: " + RemoveLength;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public void CirclePointAngleByLenght(double Radius, double RefLenght, ref double calcAngle)
	{
		double num = CircleCircumference(Radius, 0.0, 360.0);
		calcAngle = RefLenght / num * 360.0;
	}

	public void ArcWithCenter(Pnt3D Center, double Radius, double StartAngle, double EndAngle, WorkPlane Plane, EntityResolution EntResolution, ref List<Pnt3D> Vertices)
	{
		try
		{
			int num = 0;
			Pnt3D pnt3D = new Pnt3D();
			Vertices.Clear();
			num = ArcVerticeCountByResolution(Radius, StartAngle, EndAngle, EntResolution);
			for (int i = 0; i <= num; i++)
			{
				pnt3D = new Pnt3D();
				if (WorkPlane.isPlaneXY(Plane))
				{
					pnt3D.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					pnt3D.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					pnt3D.Z = Center.Z;
					Vertices.Add(pnt3D);
				}
				if (Plane.PlaneType == planeType.XZ)
				{
					pnt3D.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					pnt3D.Y = Center.Y;
					pnt3D.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					Vertices.Add(pnt3D);
				}
				if (Plane.PlaneType == planeType.YZ)
				{
					pnt3D.X = Center.X;
					pnt3D.Y = Center.Y + Radius * Math.Cos(buConversion.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					pnt3D.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadianGreat360(StartAngle + (double)i * (EndAngle - StartAngle) / (double)num));
					Vertices.Add(pnt3D);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Rad: " + Radius + " - SA: " + StartAngle + " - EA: " + EndAngle + " - Plane: " + Plane.ToString() + " - EntResolution: " + EntResolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void ArcWithTwoPointAndRadius(Pnt3D ArcStartPoint, Pnt3D ArcEndPoint, double Radius, bool CW, WorkPlane Plane, ref Pnt3D ArcCenter, ref double ArcSA, ref double ArcEA)
	{
		try
		{
			double num = 1.0;
			Pnt3D MiddlePoint = new Pnt3D();
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			bool flag = false;
			if (Radius < 0.0)
			{
				flag = true;
			}
			MiddlePointOfLine(ArcStartPoint, ArcEndPoint, ref MiddlePoint);
			Radius = Math.Abs(Radius);
			if (buCompare.EQ(ArcStartPoint.Y, ArcEndPoint.Y))
			{
				double x = Math.Sqrt(Math.Pow(ArcEndPoint.Y - MiddlePoint.Y, 2.0) + Math.Pow(ArcEndPoint.X - MiddlePoint.X, 2.0));
				double num6 = Math.Pow(Radius, 2.0) - Math.Pow(x, 2.0);
				if (num6 < 0.0)
				{
					num6 = 0.0;
				}
				double num7 = Math.Sqrt(num6);
				double num8 = num7;
				pnt3D.Y = MiddlePoint.Y + num8;
				pnt3D2.Y = MiddlePoint.Y - num8;
				pnt3D.X = MiddlePoint.X;
				pnt3D2.X = MiddlePoint.X;
			}
