	public void ArcWithIJK(Pnt3D PreviousPoint, Pnt3D NextPoint, double I, double J, double K, int ArcDir, ref Pnt3D ArcCenter, ref double Radius, ref double StartAngle, ref double EndAngle)
	{
		ArcCenter = new Pnt3D();
		double num = 0.0;
		double num2 = 0.0;
		bool flag = false;
		ArcCenter.X = PreviousPoint.X + I;
		ArcCenter.Y = PreviousPoint.Y + J;
		ArcCenter.Z = PreviousPoint.Z + K;
		if (ArcDir == 2)
		{
			num = PointAngle(PreviousPoint, ArcCenter);
			num2 = PointAngle(NextPoint, ArcCenter);
			if (!flag)
			{
				if ((num2 > 180.0) & buCompare.EQ(num, 0.0, 0.01))
				{
					num = 360.0;
				}
				if ((num < 180.0) & buCompare.EQ(num2, 0.0, 0.01))
				{
					num2 = 0.0;
				}
			}
			if (num2 > num)
			{
				num = 360.0 + num;
			}
		}
		if (ArcDir == 3)
		{
			num = PointAngle(PreviousPoint, ArcCenter);
			num2 = PointAngle(NextPoint, ArcCenter);
			if (!flag)
			{
				if ((num > 180.0) & buCompare.EQ(num2, 0.0, 0.01))
				{
					num2 = 360.0;
				}
				if ((num2 < 180.0) & buCompare.EQ(num, 0.0, 0.01))
				{
					num = 0.0;
				}
			}
			if (num > num2)
			{
				num2 = 360.0 + num2;
			}
		}
		if (!(num > num2))
		{
			StartAngle = num;
			EndAngle = num2;
		}
		else
		{
			StartAngle = num2;
			EndAngle = num;
		}
		if (StartAngle > EndAngle)
		{
			EndAngle = 360.0 + EndAngle;
		}
		Radius = Length3D(PreviousPoint, ArcCenter);
	}

