	public void Arc3Point(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D ThirdPoint, WorkPlane Plane, EntityResolution EntResolution, ref List<Pnt3D> Vertices)
	{
		Pnt3D Center = new Pnt3D();
		double Radius = 0.0;
		double StartAngle = 0.0;
		double EndAngle = 0.0;
		Vertices.Clear();
		Arc3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, EntResolution, ref Center, ref Radius, ref StartAngle, ref EndAngle, ref Vertices);
	}

	public void Arc3Point(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D ThirdPoint, WorkPlane Plane, ref Pnt3D Center, ref double Radius, ref double StartAngle, ref double EndAngle)
	{
		List<Pnt3D> Vertices = new List<Pnt3D>();
		Arc3Point(FirstPoint, SecondPoint, ThirdPoint, Plane, new EntityResolution(), ref Center, ref Radius, ref StartAngle, ref EndAngle, ref Vertices);
	}

