	public void ArcStartMiddleEndPoint(Pnt3D CenterPoint, double Radius, double StartAngle, double EndAngle, WorkPlane Plane, ref Pnt3D MiddlePoint)
	{
		Pnt3D StartPoint = new Pnt3D();
		Pnt3D EndPoint = new Pnt3D();
		ArcStartMiddleEndPoint(CenterPoint, Radius, StartAngle, EndAngle, Plane, ref StartPoint, ref MiddlePoint, ref EndPoint);
	}

	public void ArcStartMiddleEndPoint(Pnt3D CenterPoint, double Radius, double StartAngle, double EndAngle, WorkPlane Plane, ref Pnt3D StartPoint, ref Pnt3D MiddlePoint, ref Pnt3D EndPoint)
	{
		try
		{
			if (WorkPlane.isPlaneXY(Plane))
			{
				StartPoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian(StartAngle));
				StartPoint.Y = CenterPoint.Y + Radius * Math.Sin(buConversion.DegreeToRadian(StartAngle));
				StartPoint.Z = CenterPoint.Z;
				MiddlePoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
				MiddlePoint.Y = CenterPoint.Y + Radius * Math.Sin(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
				MiddlePoint.Z = CenterPoint.Z;
				EndPoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian(EndAngle));
				EndPoint.Y = CenterPoint.Y + Radius * Math.Sin(buConversion.DegreeToRadian(EndAngle));
				EndPoint.Z = CenterPoint.Z;
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				StartPoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian(StartAngle));
				StartPoint.Y = CenterPoint.Y;
				StartPoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian(StartAngle));
				MiddlePoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
				MiddlePoint.Y = CenterPoint.Y;
				MiddlePoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
				EndPoint.X = CenterPoint.X + Radius * Math.Cos(buConversion.DegreeToRadian(EndAngle));
				EndPoint.Y = CenterPoint.Y;
				EndPoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian(EndAngle));
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				StartPoint.X = CenterPoint.X;
				StartPoint.Y = CenterPoint.Y + Radius * Math.Cos(buConversion.DegreeToRadian(StartAngle));
				StartPoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian(StartAngle));
				MiddlePoint.X = CenterPoint.X;
				MiddlePoint.Y = CenterPoint.Y + Radius * Math.Cos(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
				MiddlePoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian((StartAngle + EndAngle) / 2.0));
				EndPoint.X = CenterPoint.X;
				EndPoint.Y = CenterPoint.Y + Radius * Math.Cos(buConversion.DegreeToRadian(EndAngle));
				EndPoint.Z = CenterPoint.Z + Radius * Math.Sin(buConversion.DegreeToRadian(EndAngle));
			}
		}
		catch (Exception mSException)
		{
			string text = "CenterPoint: " + CenterPoint.ToString() + " - Radius: " + Radius + " - StartAngle: " + StartAngle + " - EndAngle: " + EndAngle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void ArcOutsidePoints(Pnt3D CenterPoint, double Radius, double StartAngle, double EndAngle, WorkPlane Plane, ref List<Pnt3D> OutsidePoints)
	{
		try
		{
			OutsidePoints.Clear();
			Pnt3D pnt3D = new Pnt3D(CenterPoint);
			pnt3D.X += Radius;
			if (IsPointInsideArc(CenterPoint, Radius, StartAngle, EndAngle, pnt3D, Plane))
			{
				OutsidePoints.Add(new Pnt3D(pnt3D));
			}
			pnt3D = new Pnt3D(CenterPoint);
			pnt3D.X -= Radius;
			if (IsPointInsideArc(CenterPoint, Radius, StartAngle, EndAngle, pnt3D, Plane))
			{
				OutsidePoints.Add(new Pnt3D(pnt3D));
			}
			pnt3D = new Pnt3D(CenterPoint);
			pnt3D.Y += Radius;
			if (IsPointInsideArc(CenterPoint, Radius, StartAngle, EndAngle, pnt3D, Plane))
			{
				OutsidePoints.Add(new Pnt3D(pnt3D));
			}
			pnt3D = new Pnt3D(CenterPoint);
			pnt3D.Y -= Radius;
			if (IsPointInsideArc(CenterPoint, Radius, StartAngle, EndAngle, pnt3D, Plane))
			{
				OutsidePoints.Add(new Pnt3D(pnt3D));
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + CenterPoint.ToString() + " - Radius: " + Radius + " - StartAngle: " + StartAngle + " - EndAngle: " + EndAngle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

