				}
			}
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByLength)
			{
				if (buNumeric.IsNumeric(Radius.ToString()))
				{
					num2 = Math.PI * 2.0 * Radius;
					num = Convert.ToInt32(num2 * ((EndAngle - StartAngle) / 360.0) / EntResolution.GeometricLength);
				}
				if (num < EntResolution.MinPointCount)
				{
					num = EntResolution.MinPointCount;
				}
			}
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByLnRadius)
			{
				if (buNumeric.IsNumeric(Radius.ToString()) && Radius > 0.0)
				{
					num = Convert.ToInt32(Math.Log(Radius, Math.E) * EntResolution.LnRatio);
				}
				if (num < EntResolution.MinPointCount)
				{
					num = EntResolution.MinPointCount;
				}
			}
			return num;
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - SA: " + StartAngle + " - EA: " + EndAngle + " - Ent Res:" + EntResolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

	public double ArcArea(double Radius, double StartAngle, double EndAngle)
	{
		try
		{
			return Math.PI * Radius * Radius * (EndAngle - StartAngle) / 360.0;
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - SA: " + StartAngle + " - EA: " + EndAngle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double ArcCircumference(double Radius, double StartAngle, double EndAngle)
	{
		try
		{
			return Radius * Math.PI * 2.0 * (EndAngle - StartAngle) / 360.0;
		}
		catch (Exception mSException)
		{
			string text = "R: " + Radius + " - SA: " + StartAngle + " - EA: " + EndAngle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public void ArcByLength(Pnt3D Center, double Radius, double SA, double EA, double Length, ArcDirectionType Direction, ref double CalcSA, ref double CalcEA)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 1.0;
			num2 = Math.Abs(EA - SA);
			num = Math.PI * Radius * 2.0 * num2 / 360.0;
			num3 = Length / num;
			if (Direction == ArcDirectionType.FromStart)
			{
				CalcEA = SA + num2 * num3;
				CalcSA = SA;
			}
			if (Direction == ArcDirectionType.FromEnd)
			{
				CalcSA = EA - num2 * num3;
				CalcEA = EA;
			}
			if (Direction == ArcDirectionType.FromMiddle)
			{
				CalcEA = (SA + EA) / 2.0 + num2 * num3;
				CalcSA = (SA + EA) / 2.0;
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Radius: " + Radius + " - SA: " + SA + " - EA: " + EA + " - Length: " + Length + " - Direction: " + Direction;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

