	public void RectangleCenter(Pnt3D Center, Pnt3D RefPoint, WorkPlane Plane, ref List<Pnt3D> Vertices)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			Vertices.Clear();
			if (WorkPlane.isPlaneXY(Plane))
			{
				num = Math.Abs(Center.X - RefPoint.X);
				num2 = Math.Abs(Center.Y - RefPoint.Y);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X - num;
				pnt3D.Y = Center.Y - num2;
				pnt3D.Z = Center.Z;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X + num;
				pnt3D.Y = Center.Y - num2;
				pnt3D.Z = Center.Z;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X + num;
				pnt3D.Y = Center.Y + num2;
				pnt3D.Z = Center.Z;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X - num;
				pnt3D.Y = Center.Y + num2;
				pnt3D.Z = Center.Z;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X - num;
				pnt3D.Y = Center.Y - num2;
				pnt3D.Z = Center.Z;
				Vertices.Add(pnt3D);
			}
			if (Plane.PlaneType == planeType.XZ)
			{
				num = Math.Abs(Center.X - RefPoint.X);
				num2 = Math.Abs(Center.Z - RefPoint.Z);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X - num;
				pnt3D.Y = Center.Y;
				pnt3D.Z = Center.Z - num2;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X + num;
				pnt3D.Y = Center.Y;
				pnt3D.Z = Center.Z - num2;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X + num;
				pnt3D.Y = Center.Y;
				pnt3D.Z = Center.Z + num2;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X - num;
				pnt3D.Y = Center.Y;
				pnt3D.Z = Center.Z + num2;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X - num;
				pnt3D.Y = Center.Y;
				pnt3D.Z = Center.Z - num2;
				Vertices.Add(pnt3D);
			}
			if (Plane.PlaneType == planeType.YZ)
			{
				num = Math.Abs(Center.Y - RefPoint.Y);
				num2 = Math.Abs(Center.Z - RefPoint.Z);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X;
				pnt3D.Y = Center.Y - num;
				pnt3D.Z = Center.Z - num2;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X;
				pnt3D.Y = Center.Y + num;
				pnt3D.Z = Center.Z - num2;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X;
				pnt3D.Y = Center.Y + num;
				pnt3D.Z = Center.Z + num2;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X;
				pnt3D.Y = Center.Y - num;
				pnt3D.Z = Center.Z + num2;
				Vertices.Add(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X;
				pnt3D.Y = Center.Y - num;
				pnt3D.Z = Center.Z - num2;
				Vertices.Add(pnt3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - RefPoint: " + RefPoint.ToString() + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void RectangleAngleWithCenter(Pnt3D Center, double Width, double Height, double Angle, WorkPlane Plane, ref List<Pnt3D> Vertices)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			List<Pnt3D> list = new List<Pnt3D>();
			if (Plane.PlaneType == planeType.XY)
			{
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X - Width / 2.0;
				pnt3D.Y = Center.Y - Height / 2.0;
				pnt3D.Z = Center.Z;
				RectangleCorner(pnt3D, Width, Height, Plane, ref Vertices);
				for (int i = 0; i <= Vertices.Count - 1; i++)
				{
					pnt3D = new Pnt3D();
					num = Length3D(Vertices[i], Center, Plane);
					num2 = PointAngle(Vertices[i].X, Vertices[i].Y, Center.X, Center.Y) + Angle;
					pnt3D.X = Center.X + num * Math.Cos(buConversion.DegreeToRadian(num2));
					pnt3D.Y = Center.Y + num * Math.Sin(buConversion.DegreeToRadian(num2));
					pnt3D.Z = Center.Z;
					list.Add(pnt3D);
				}
			}
			if (Plane.PlaneType == planeType.XZ)
			{
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X - Width / 2.0;
				pnt3D.Y = Center.Y;
				pnt3D.Z = Center.Z - Height / 2.0;
				RectangleCorner(pnt3D, Width, Height, Plane, ref Vertices);
				for (int j = 0; j <= Vertices.Count - 1; j++)
				{
					pnt3D = new Pnt3D();
					num = Length3D(Vertices[j], Center, Plane);
					num2 = PointAngle(Vertices[j].X, Vertices[j].Z, Center.X, Center.Z) + Angle;
					pnt3D.X = Center.X + num * Math.Cos(buConversion.DegreeToRadian(num2));
					pnt3D.Y = Center.Y;
					pnt3D.Z = Center.Z + num * Math.Sin(buConversion.DegreeToRadian(num2));
					list.Add(pnt3D);
				}
			}
			if (Plane.PlaneType == planeType.YZ)
			{
				pnt3D = new Pnt3D();
				pnt3D.X = Center.X;
				pnt3D.Y = Center.Y - Width / 2.0;
				pnt3D.Z = Center.Z - Height / 2.0;
				RectangleCorner(pnt3D, Width, Height, Plane, ref Vertices);
				for (int k = 0; k <= Vertices.Count - 1; k++)
				{
					pnt3D = new Pnt3D();
					num = Length3D(Vertices[k], Center, Plane);
					num2 = PointAngle(Vertices[k].Y, Vertices[k].Z, Center.Y, Center.Z) + Angle;
					pnt3D.X = Center.X;
					pnt3D.Y = Center.Y + num * Math.Cos(buConversion.DegreeToRadian(num2));
					pnt3D.Z = Center.Z + num * Math.Sin(buConversion.DegreeToRadian(num2));
					list.Add(pnt3D);
				}
			}
			Vertices.Clear();
			buGeneral.CopyLists(list, ref Vertices);
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Width: " + Width + " - Height: " + Height + " - Angle: " + Angle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void RectangleChamfer(Pnt3D CornerPnt1, double Width, double Height, double Chamfer, WorkPlane Plane, ref List<Pnt3D> Points)
	{
		Pnt3D cornerPnt = new Pnt3D();
		if (WorkPlane.isPlaneXY(Plane))
		{
			cornerPnt = new Pnt3D(CornerPnt1.X + Width, CornerPnt1.Y + Height, CornerPnt1.Z);
		}
		if (WorkPlane.isPlaneXZ(Plane))
		{
			cornerPnt = new Pnt3D(CornerPnt1.X + Width, CornerPnt1.Y, CornerPnt1.Z + Height);
		}
		if (WorkPlane.isPlaneYZ(Plane))
		{
			cornerPnt = new Pnt3D(CornerPnt1.X, CornerPnt1.Y + Width, CornerPnt1.Z + Height);
		}
		RectangleChamfer(CornerPnt1, cornerPnt, Chamfer, Plane, ref Points);
	}

	public void RectangleChamfer(Pnt3D CornerPnt1, Pnt3D CornerPnt2, double Chamfer, WorkPlane Plane, ref List<Pnt3D> Points)
	{
		try
		{
			Points.Clear();
			if (WorkPlane.isPlaneXY(Plane))
			{
				double num = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				double num2 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				if (CornerPnt2.X <= CornerPnt1.X)
				{
					if (CornerPnt2.Y <= CornerPnt1.Y)
					{
						num *= -1.0;
						num2 *= -1.0;
					}
					else
					{
						num *= -1.0;
						num2 *= 1.0;
					}
				}
				else if (CornerPnt2.Y <= CornerPnt1.Y)
				{
					num *= 1.0;
					num2 *= -1.0;
				}
				else
				{
					num *= 1.0;
					num2 *= 1.0;
				}
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num2, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y - num2, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt1.X + num, CornerPnt2.Y, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt2.X - num, CornerPnt2.Y, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt2.Y - num2, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt1.Y + num2, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt2.X - num, CornerPnt1.Y, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt1.X + num, CornerPnt1.Y, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num2, CornerPnt1.Z));
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				double num3 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				double num4 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				if (CornerPnt2.X <= CornerPnt1.X)
				{
					if (CornerPnt2.Z <= CornerPnt1.Z)
					{
						num3 *= -1.0;
						num4 *= -1.0;
					}
					else
					{
						num3 *= -1.0;
						num4 *= 1.0;
					}
				}
				else if (CornerPnt2.Z <= CornerPnt1.Z)
				{
					num3 *= 1.0;
					num4 *= -1.0;
				}
				else
				{
					num3 *= 1.0;
					num4 *= 1.0;
				}
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num4));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt2.Z - num4));
				Points.Add(new Pnt3D(CornerPnt1.X + num3, CornerPnt1.Y, CornerPnt2.Z));
				Points.Add(new Pnt3D(CornerPnt2.X - num3, CornerPnt1.Y, CornerPnt2.Z));
				Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt1.Y, CornerPnt2.Z - num4));
				Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt1.Y, CornerPnt1.Z + num4));
				Points.Add(new Pnt3D(CornerPnt2.X - num3, CornerPnt1.Y, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt1.X + num3, CornerPnt1.Y, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num4));
				Points.Add(new Pnt3D());
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				double num5 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				double num6 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
				if (CornerPnt2.Y <= CornerPnt1.Y)
				{
					if (CornerPnt2.Z <= CornerPnt1.Z)
					{
						num5 *= -1.0;
						num6 *= -1.0;
					}
					else
					{
						num5 *= -1.0;
						num6 *= 1.0;
					}
				}
				else if (CornerPnt2.Z <= CornerPnt1.Z)
				{
					num5 *= 1.0;
					num6 *= -1.0;
				}
				else
				{
					num5 *= 1.0;
					num6 *= 1.0;
				}
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num6));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt2.Z - num6));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num5, CornerPnt2.Z));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y - num5, CornerPnt2.Z));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt2.Z - num6));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt1.Z + num6));
				Points.Add(new Pnt3D(CornerPnt2.X, CornerPnt2.Y - num5, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num5, CornerPnt1.Z));
				Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num6));
			}
			if (!WorkPlane.isPlaneYZ(Plane))
			{
				return;
			}
			double num7 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
			double num8 = Math.Sqrt(Math.Pow(Chamfer, 2.0) / 2.0);
			double num9;
			double num10;
			if (CornerPnt2.Y > CornerPnt1.Y)
			{
				if (CornerPnt2.Z > CornerPnt1.Z)
				{
					num9 = num7;
					num10 = num8;
				}
				else
				{
					num9 = num7;
					num10 = num8 * -1.0;
				}
			}
			else if (CornerPnt2.Z > CornerPnt1.Z)
			{
				num9 = num7 * -1.0;
				num10 = num8;
			}
			else
			{
				num9 = num7 * -1.0;
				num10 = num8 * -1.0;
			}
			Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num10));
			Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt2.Z - num10));
			Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num9, CornerPnt2.Z));
			Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y - num9, CornerPnt2.Z));
			Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt2.Z - num10));
			Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y, CornerPnt1.Z + num10));
			Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt2.Y - num9, CornerPnt1.Z));
			Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y + num9, CornerPnt1.Z));
			Points.Add(new Pnt3D(CornerPnt1.X, CornerPnt1.Y, CornerPnt1.Z + num10));
		}
		catch (Exception mSException)
		{
			string text = "CornerPnt1: " + CornerPnt1.ToString() + " - CornerPnt2: " + CornerPnt2.ToString() + " - Plane: " + Plane.ToString() + " - Chamfer: " + Chamfer;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void RectangleFillet(Pnt3D Center, double Width, double Height, double Radius, WorkPlane Plane, ref List<Pnt3D> Vertices)
	{
		RectangleFillet(Center, Width, Height, Radius, 0.0, Plane, ref Vertices);
	}

	public void RectangleFillet(Pnt3D Center, double Width, double Height, double Radius, double Angle, WorkPlane Plane, ref List<Pnt3D> Vertices)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			if (WorkPlane.isPlaneXY(Plane))
			{
				pnt3D = new Pnt3D(Center);
				pnt3D.X = Center.X - Width / 2.0;
				pnt3D.Y = Center.Y - Height / 2.0;
				pnt3D2 = new Pnt3D(Center);
				pnt3D2.X = Center.X + Width / 2.0;
				pnt3D2.Y = Center.Y + Height / 2.0;
				RectangleFillet(pnt3D, pnt3D2, Radius, Plane, ref Vertices);
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				pnt3D = new Pnt3D(Center);
				pnt3D.X = Center.X - Width / 2.0;
				pnt3D.Z = Center.Z - Height / 2.0;
				pnt3D2 = new Pnt3D(Center);
				pnt3D2.X = Center.X + Width / 2.0;
				pnt3D2.Z = Center.Z + Height / 2.0;
				RectangleFillet(pnt3D, pnt3D2, Radius, Plane, ref Vertices);
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				pnt3D = new Pnt3D(Center);
				pnt3D.Y = Center.Y - Width / 2.0;
				pnt3D.Z = Center.Z - Height / 2.0;
				pnt3D2 = new Pnt3D(Center);
				pnt3D2.Y = Center.Y + Width / 2.0;
				pnt3D2.Z = Center.Z + Height / 2.0;
				RectangleFillet(pnt3D, pnt3D2, Radius, Plane, ref Vertices);
			}
			if (Angle != 0.0)
			{
				Rotate(Center, Angle, Plane, ref Vertices);
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Width: " + Width + " - Height: " + Height + " - Plane: " + Plane.ToString() + " - Radius: " + Radius;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void RectangleFillet(Pnt3D CornerPnt1, Pnt3D CornerPnt2, double Radius, WorkPlane Plane, ref List<eEntities> Entities)
	{
		try
		{
			eLine eLine2 = new eLine();
			eArc eArc2 = new eArc();
			Entities.Clear();
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			if (WorkPlane.isPlaneXY(Plane))
			{
				pnt3D.Z = CornerPnt1.Z;
				pnt3D2.Z = CornerPnt1.Z;
				if (!(CornerPnt2.X > CornerPnt1.X))
				{
					pnt3D2.X = CornerPnt1.X;
					pnt3D.X = CornerPnt2.X;
					if (!(CornerPnt2.Y > CornerPnt1.Y))
					{
						pnt3D2.Y = CornerPnt1.Y;
						pnt3D.Y = CornerPnt2.Y;
					}
					else
					{
						pnt3D2.Y = CornerPnt2.Y;
						pnt3D.Y = CornerPnt1.Y;
					}
				}
				else
				{
					pnt3D2.X = CornerPnt2.X;
					pnt3D.X = CornerPnt1.X;
					if (!(CornerPnt2.Y > CornerPnt1.Y))
					{
						pnt3D2.Y = CornerPnt1.Y;
						pnt3D.Y = CornerPnt2.Y;
					}
					else
					{
						pnt3D2.Y = CornerPnt2.Y;
						pnt3D.Y = CornerPnt1.Y;
					}
				}
				eLine2 = new eLine(new Pnt3D(pnt3D.X + Radius, pnt3D.Y, pnt3D.Z), new Pnt3D(pnt3D2.X - Radius, pnt3D.Y, pnt3D.Z));
				Entities.Add(eLine2);
				eArc2 = new eArc(new Pnt3D(pnt3D2.X - Radius, pnt3D.Y + Radius, pnt3D.Z), Radius, 270.0, 360.0, Plane);
				Entities.Add(eArc2);
				eLine2 = new eLine(new Pnt3D(pnt3D2.X, pnt3D.Y + Radius, pnt3D.Z), new Pnt3D(pnt3D2.X, pnt3D2.Y - Radius, pnt3D.Z));
				Entities.Add(eLine2);
				eArc2 = new eArc(new Pnt3D(pnt3D2.X - Radius, pnt3D2.Y - Radius, pnt3D.Z), Radius, 0.0, 90.0, Plane);
				Entities.Add(eArc2);
				eLine2 = new eLine(new Pnt3D(pnt3D2.X - Radius, pnt3D2.Y, pnt3D.Z), new Pnt3D(pnt3D.X + Radius, pnt3D2.Y, pnt3D.Z));
				Entities.Add(eLine2);
				eArc2 = new eArc(new Pnt3D(pnt3D.X + Radius, pnt3D2.Y - Radius, pnt3D.Z), Radius, 90.0, 180.0, Plane);
				Entities.Add(eArc2);
				eLine2 = new eLine(new Pnt3D(pnt3D.X, pnt3D2.Y - Radius, pnt3D.Z), new Pnt3D(pnt3D.X, pnt3D.Y + Radius, pnt3D.Z));
				Entities.Add(eLine2);
				eArc2 = new eArc(new Pnt3D(pnt3D.X + Radius, pnt3D.Y + Radius, pnt3D.Z), Radius, 180.0, 270.0, Plane);
				Entities.Add(eArc2);
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				pnt3D.Y = CornerPnt1.Y;
				pnt3D2.Y = CornerPnt1.Y;
				if (!(CornerPnt2.X > CornerPnt1.X))
				{
					pnt3D2.X = CornerPnt1.X;
					pnt3D.X = CornerPnt2.X;
					if (!(CornerPnt2.Z > CornerPnt1.Z))
					{
						pnt3D2.Z = CornerPnt1.Z;
						pnt3D.Z = CornerPnt2.Z;
					}
					else
					{
						pnt3D2.Z = CornerPnt2.Z;
						pnt3D.Z = CornerPnt1.Z;
					}
				}
				else
				{
					pnt3D2.X = CornerPnt2.X;
					pnt3D.X = CornerPnt1.X;
					if (!(CornerPnt2.Z > CornerPnt1.Z))
					{
						pnt3D2.Z = CornerPnt1.Z;
						pnt3D.Z = CornerPnt2.Z;
					}
					else
					{
						pnt3D2.Z = CornerPnt2.Z;
						pnt3D.Z = CornerPnt1.Z;
					}
				}
				eLine2 = new eLine(new Pnt3D(pnt3D.X + Radius, pnt3D.Y, pnt3D.Z), new Pnt3D(pnt3D2.X - Radius, pnt3D.Y, pnt3D.Z));
				Entities.Add(eLine2);
				eArc2 = new eArc(new Pnt3D(pnt3D2.X - Radius, pnt3D.Y, pnt3D.Z + Radius), Radius, 270.0, 360.0, Plane);
				Entities.Add(eArc2);
				eLine2 = new eLine(new Pnt3D(pnt3D2.X, pnt3D.Y, pnt3D.Z + Radius), new Pnt3D(pnt3D2.X, pnt3D.Y, pnt3D2.Z - Radius));
				Entities.Add(eLine2);
				eArc2 = new eArc(new Pnt3D(pnt3D2.X - Radius, pnt3D.Y, pnt3D2.Z - Radius), Radius, 0.0, 90.0, Plane);
				Entities.Add(eArc2);
				eLine2 = new eLine(new Pnt3D(pnt3D2.X - Radius, pnt3D.Y, pnt3D2.Z), new Pnt3D(pnt3D.X + Radius, pnt3D.Y, pnt3D2.Z));
				Entities.Add(eLine2);
				eArc2 = new eArc(new Pnt3D(pnt3D.X + Radius, pnt3D.Y, pnt3D2.Z - Radius), Radius, 90.0, 180.0, Plane);
				Entities.Add(eArc2);
				eLine2 = new eLine(new Pnt3D(pnt3D.X, pnt3D.Y, pnt3D2.Z - Radius), new Pnt3D(pnt3D.X, pnt3D.Y, pnt3D.Z + Radius));
				Entities.Add(eLine2);
				eArc2 = new eArc(new Pnt3D(pnt3D.X + Radius, pnt3D.Y, pnt3D.Z + Radius), Radius, 180.0, 270.0, Plane);
				Entities.Add(eArc2);
			}
			if (!WorkPlane.isPlaneYZ(Plane))
			{
				return;
			}
			pnt3D.X = CornerPnt1.X;
			pnt3D2.X = CornerPnt1.X;
			if (!(CornerPnt2.Y > CornerPnt1.Y))
			{
				pnt3D2.Y = CornerPnt1.Y;
				pnt3D.Y = CornerPnt2.Y;
				if (!(CornerPnt2.Z > CornerPnt1.Z))
				{
					pnt3D2.Z = CornerPnt1.Z;
					pnt3D.Z = CornerPnt2.Z;
				}
				else
				{
					pnt3D2.Z = CornerPnt2.Z;
					pnt3D.Z = CornerPnt1.Z;
				}
			}
			else
			{
				pnt3D2.Y = CornerPnt2.Y;
				pnt3D.Y = CornerPnt1.Y;
				if (!(CornerPnt2.Z > CornerPnt1.Z))
				{
					pnt3D2.Z = CornerPnt1.Z;
					pnt3D.Z = CornerPnt2.Z;
				}
				else
				{
					pnt3D2.Z = CornerPnt2.Z;
					pnt3D.Z = CornerPnt1.Z;
				}
			}
			eLine2 = new eLine(new Pnt3D(pnt3D.X, pnt3D.Y + Radius, pnt3D.Z), new Pnt3D(pnt3D.X, pnt3D2.Y - Radius, pnt3D.Z));
			Entities.Add(eLine2);
			eArc2 = new eArc(new Pnt3D(pnt3D.X, pnt3D2.Y - Radius, pnt3D.Z + Radius), Radius, 270.0, 360.0, Plane);
			Entities.Add(eArc2);
			eLine2 = new eLine(new Pnt3D(pnt3D.X, pnt3D2.Y, pnt3D.Z + Radius), new Pnt3D(pnt3D.X, pnt3D2.Y, pnt3D2.Z - Radius));
			Entities.Add(eLine2);
			eArc2 = new eArc(new Pnt3D(pnt3D2.X, pnt3D2.Y - Radius, pnt3D2.Z - Radius), Radius, 0.0, 90.0, Plane);
			Entities.Add(eArc2);
			eLine2 = new eLine(new Pnt3D(pnt3D.X, pnt3D2.Y - Radius, pnt3D2.Z), new Pnt3D(pnt3D.X, pnt3D.Y + Radius, pnt3D2.Z));
			Entities.Add(eLine2);
			eArc2 = new eArc(new Pnt3D(pnt3D.X, pnt3D.Y + Radius, pnt3D2.Z - Radius), Radius, 90.0, 180.0, Plane);
			Entities.Add(eArc2);
			eLine2 = new eLine(new Pnt3D(pnt3D.X, pnt3D.Y, pnt3D2.Z - Radius), new Pnt3D(pnt3D.X, pnt3D.Y, pnt3D.Z + Radius));
			Entities.Add(eLine2);
			eArc2 = new eArc(new Pnt3D(pnt3D.X, pnt3D.Y + Radius, pnt3D.Z + Radius), Radius, 180.0, 270.0, Plane);
			Entities.Add(eArc2);
		}
		catch (Exception mSException)
		{
			string text = "CornerPnt1: " + CornerPnt1.ToString() + " - CornerPnt2: " + CornerPnt2.ToString() + " - Plane: " + Plane.ToString() + " - Radius: " + Radius;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

