	public void Rectangle3Point(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D ThirdPoint, WorkPlane Plane, ref List<Pnt3D> Vertices, ref Pnt3D ConnectPoint)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			int num6 = 0;
			Pnt3D CalculatedPoint = new Pnt3D();
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			Pnt3D pnt3D3 = new Pnt3D();
			double Distance = 0.0;
			Vertices.Clear();
			if (IsPointOverAndInsideLine(FirstPoint, SecondPoint, ThirdPoint, Plane, buSystem.resolutionCompare))
			{
				Vertices.Add(new Pnt3D(FirstPoint));
				Vertices.Add(new Pnt3D(SecondPoint));
			}
			if (!IsPointOverLine(FirstPoint, SecondPoint, ThirdPoint, Plane, ref CalculatedPoint, ref Distance))
			{
				num = Length3D(FirstPoint, ThirdPoint);
				num2 = Length3D(SecondPoint, ThirdPoint);
				pnt3D = ((num < num2) ? new Pnt3D(FirstPoint) : new Pnt3D(SecondPoint));
			}
			else
			{
				pnt3D = CalculatedPoint;
			}
			ConnectPoint = new Pnt3D(pnt3D);
			num = Length3D(pnt3D, ThirdPoint);
			num2 = Length3D(FirstPoint, SecondPoint);
			num5 = PointAngle(FirstPoint, SecondPoint, Plane);
			Vertices.Add(new Pnt3D(FirstPoint));
			Vertices.Add(new Pnt3D(SecondPoint));
			Pnt3D BasePnt = new Pnt3D();
			Pnt3D BasePnt2 = new Pnt3D();
			Pnt3D EndPnt = new Pnt3D();
			Pnt3D EndPnt2 = new Pnt3D();
			LineWithLengthAndAngle(SecondPoint, num, num5 - 90.0, Plane, ref BasePnt, ref EndPnt);
			LineWithLengthAndAngle(SecondPoint, num, num5 + 90.0, Plane, ref BasePnt2, ref EndPnt2);
			num3 = Length3D(EndPnt, ThirdPoint);
			num4 = Length3D(EndPnt2, ThirdPoint);
			if (!(num3 < num4))
			{
				Vertices.Add(new Pnt3D(EndPnt2));
				pnt3D2 = new Pnt3D(BasePnt2);
				pnt3D3 = new Pnt3D(EndPnt2);
				num6 = 1;
			}
			else
			{
				Vertices.Add(new Pnt3D(EndPnt));
				pnt3D2 = new Pnt3D(BasePnt);
				pnt3D3 = new Pnt3D(EndPnt);
				num6 = -1;
			}
			num5 = PointAngle(pnt3D2, pnt3D3, Plane);
			LineWithLengthAndAngle(pnt3D3, num2, num5 + (double)(90 * num6), Plane, ref BasePnt, ref EndPnt);
			Vertices.Add(new Pnt3D(EndPnt));
			pnt3D2 = new Pnt3D(BasePnt);
			pnt3D3 = new Pnt3D(EndPnt);
			num5 = PointAngle(pnt3D2, pnt3D3, Plane);
			LineWithLengthAndAngle(pnt3D3, num, num5 + (double)(90 * num6), Plane, ref BasePnt, ref EndPnt);
			Vertices.Add(new Pnt3D(EndPnt));
			pnt3D2 = new Pnt3D(BasePnt);
			pnt3D3 = new Pnt3D(EndPnt);
		}
		catch (Exception mSException)
		{
			string text = "FirstPoint: " + FirstPoint.ToString() + " - SecondPoint: " + SecondPoint.ToString() + " - ThirdPoint: " + ThirdPoint.ToString() + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Slot(Pnt3D BasePoint, double Width, double Height, double Angle, WorkPlane Plane, EntityResolution EntitiesResolution, ref List<Pnt3D> Vertices, ref List<eEntities> Entities)
	{
		try
		{
			Entities.Clear();
			Entities = new List<eEntities>();
			if (WorkPlane.isPlaneXY(Plane))
			{
				eArc item = new eArc(new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y, BasePoint.Z), Height / 2.0, 90.0, 270.0, Plane);
				eArc item2 = new eArc(new Pnt3D(BasePoint.X + Width - Height / 2.0, BasePoint.Y, BasePoint.Z), Height / 2.0, 270.0, 450.0, Plane);
				eLine item3 = new eLine(new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y - Height / 2.0, BasePoint.Z), new Pnt3D(BasePoint.X + Width - Height / 2.0, BasePoint.Y - Height / 2.0, BasePoint.Z));
				eLine item4 = new eLine(new Pnt3D(BasePoint.X + Width - Height / 2.0, BasePoint.Y + Height / 2.0, BasePoint.Z), new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y + Height / 2.0, BasePoint.Z));
				Entities.Add(item3);
				Entities.Add(item2);
				Entities.Add(item4);
				Entities.Add(item);
				Rotate(BasePoint, Angle, ClockDirectionType.CCW, Plane, ref Entities);
				EntityToPoint(Entities, EntitiesResolution, ref Vertices);
				CheckDuplicatedPointsWithPrevious(ref Vertices);
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				eArc item5 = new eArc(new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y, BasePoint.Z), Height / 2.0, 90.0, 270.0, Plane);
				eArc item6 = new eArc(new Pnt3D(Width - Height / 2.0, BasePoint.Y, BasePoint.Z), Height / 2.0, 270.0, 450.0, Plane);
				eLine item7 = new eLine(new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y, BasePoint.Z - Height / 2.0), new Pnt3D(Width - Height / 2.0, BasePoint.Y, BasePoint.Z - Height / 2.0));
				eLine item8 = new eLine(new Pnt3D(Width - Height / 2.0, BasePoint.Y, BasePoint.Z + Height / 2.0), new Pnt3D(BasePoint.X + Height / 2.0, BasePoint.Y, BasePoint.Z + Height / 2.0));
				Entities.Add(item7);
				Entities.Add(item6);
				Entities.Add(item8);
				Entities.Add(item5);
				Rotate(BasePoint, Angle, ClockDirectionType.CCW, Plane, ref Entities);
				EntityToPoint(Entities, EntitiesResolution, ref Vertices);
				CheckDuplicatedPointsWithPrevious(ref Vertices);
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				eArc item9 = new eArc(new Pnt3D(BasePoint.X, BasePoint.Y + Height / 2.0, BasePoint.Z), Height / 2.0, 90.0, 270.0, Plane);
				eArc item10 = new eArc(new Pnt3D(Width, BasePoint.Y - Height / 2.0, BasePoint.Z), Height / 2.0, 270.0, 450.0, Plane);
				eLine item11 = new eLine(new Pnt3D(BasePoint.X, BasePoint.Y + Height / 2.0, BasePoint.Z - Height / 2.0), new Pnt3D(Width, BasePoint.Y - Height / 2.0, BasePoint.Z - Height / 2.0));
				eLine item12 = new eLine(new Pnt3D(Width, BasePoint.Y - Height / 2.0, BasePoint.Z + Height / 2.0), new Pnt3D(BasePoint.X, BasePoint.Y + Height / 2.0, BasePoint.Z + Height / 2.0));
				Entities.Add(item11);
				Entities.Add(item10);
				Entities.Add(item12);
				Entities.Add(item9);
				Rotate(BasePoint, Angle, ClockDirectionType.CCW, Plane, ref Entities);
				EntityToPoint(Entities, EntitiesResolution, ref Vertices);
				CheckDuplicatedPointsWithPrevious(ref Vertices);
			}
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - Width: " + Width + " - Height: " + Height + " - Angle: " + Angle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Slot(Pnt3D BasePoint, double Width, double Height, double Rotate, WorkPlane Plane, EntityResolution EntitiesResolution, ref List<Pnt3D> Vertices)
	{
		try
		{
			List<eEntities> Entities = new List<eEntities>();
			Slot(BasePoint, Width, Height, Rotate, Plane, EntitiesResolution, ref Vertices, ref Entities);
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - Width: " + Width + " - Height: " + Height + " - Rotate: " + Rotate + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PolygonCenter(double BaseX, double BaseY, double BaseZ, double PointX, double PointY, double PointZ, int Side, WorkPlane Plane, ref List<double> VerticeX, ref List<double> VerticeY, ref List<double> VerticeZ)
	{
		try
		{
			if (Side <= 2)
			{
				return;
			}
			VerticeX.Clear();
			VerticeY.Clear();
			VerticeZ.Clear();
			if (WorkPlane.isPlaneXY(Plane))
			{
				double num = Math.Sqrt(Math.Pow(PointX - BaseX, 2.0) + Math.Pow(PointY - BaseY, 2.0));
				double num2 = 360f / (float)Side;
				double num3 = PointAngle(PointX, PointY, BaseX, BaseY);
				VerticeX.Add(BaseX + num * Math.Cos(buConversion.DegreeToRadian(num3 + 0.0 * num2)));
				VerticeY.Add(BaseY + num * Math.Sin(buConversion.DegreeToRadian(num3 + 0.0 * num2)));
				VerticeZ.Add(BaseZ);
				for (int i = 0; i <= Side - 1; i++)
				{
					VerticeX.Add(BaseX + num * Math.Cos(buConversion.DegreeToRadian(num3 + (double)(i + 1) * num2)));
					VerticeY.Add(BaseY + num * Math.Sin(buConversion.DegreeToRadian(num3 + (double)(i + 1) * num2)));
					VerticeZ.Add(BaseZ);
				}
			}
			if (Plane.PlaneType == planeType.XZ)
			{
				double num = Math.Sqrt(Math.Pow(PointX - BaseX, 2.0) + Math.Pow(PointZ - BaseZ, 2.0));
				double num2 = 360f / (float)Side;
				double num3 = PointAngle(PointX, PointZ, BaseX, BaseZ);
				VerticeX.Add(BaseX + num * Math.Cos(buConversion.DegreeToRadian(num3 + 0.0 * num2)));
				VerticeY.Add(BaseY);
				VerticeZ.Add(BaseZ + num * Math.Sin(buConversion.DegreeToRadian(num3 + 0.0 * num2)));
				for (int j = 0; j <= Side - 1; j++)
				{
					VerticeX.Add(BaseX + num * Math.Cos(buConversion.DegreeToRadian(num3 + (double)(j + 1) * num2)));
					VerticeY.Add(BaseY);
					VerticeZ.Add(BaseZ + num * Math.Sin(buConversion.DegreeToRadian(num3 + (double)(j + 1) * num2)));
				}
			}
			if (Plane.PlaneType == planeType.YZ)
			{
				double num = Math.Sqrt(Math.Pow(PointY - BaseY, 2.0) + Math.Pow(PointZ - BaseZ, 2.0));
				double num2 = 360f / (float)Side;
				double num3 = PointAngle(PointY, PointZ, BaseY, BaseZ);
				VerticeX.Add(BaseX);
				VerticeY.Add(BaseY + num * Math.Cos(buConversion.DegreeToRadian(num3 + 0.0 * num2)));
				VerticeZ.Add(BaseZ + num * Math.Sin(buConversion.DegreeToRadian(num3 + 0.0 * num2)));
				for (int k = 0; k <= Side - 1; k++)
				{
					VerticeX.Add(BaseX);
					VerticeY.Add(BaseY + num * Math.Cos(buConversion.DegreeToRadian(num3 + (double)(k + 1) * num2)));
					VerticeZ.Add(BaseZ + num * Math.Sin(buConversion.DegreeToRadian(num3 + (double)(k + 1) * num2)));
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "BaseX: " + BaseX + " - BaseY: " + BaseY + " - BaseZ: " + BaseZ + " - PointX: " + PointX + " - PointZ: " + PointY + " - PointZ: " + PointZ + " - Side: " + Side + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PolygonCenter(Pnt3D Center, Pnt3D RefPoint, int Side, WorkPlane Plane, ref List<Pnt3D> Vertices)
	{
		try
