			List<double> VerticeZ = new List<double>();
			PolygonCenter(Center.X, Center.Y, Center.Z, RefPoint.X, RefPoint.Y, RefPoint.Z, Side, Plane, ref VerticeX, ref VerticeY, ref VerticeZ);
			Vertices.Clear();
			for (int i = 0; i <= VerticeX.Count - 1; i++)
			{
				pnt3D = new Pnt3D();
				pnt3D.X = VerticeX[i];
				pnt3D.Y = VerticeY[i];
				pnt3D.Z = VerticeZ[i];
				Vertices.Add(pnt3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - RefPoint: " + RefPoint.ToString() + " - Side: " + Side + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PolygonCenter(Pnt3D Center, double Radius, int Side, WorkPlane Plane, ref List<Pnt3D> Vertices)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			List<double> VerticeX = new List<double>();
			List<double> VerticeY = new List<double>();
			List<double> VerticeZ = new List<double>();
			if (WorkPlane.isPlaneXY(Plane))
			{
				pnt3D2 = new Pnt3D(Center);
				pnt3D2.X += Radius;
			}
			if (Plane.PlaneType == planeType.XZ)
			{
				pnt3D2 = new Pnt3D(Center);
				pnt3D2.X += Radius;
			}
			if (Plane.PlaneType == planeType.YZ)
			{
				pnt3D2 = new Pnt3D(Center);
				pnt3D2.Y += Radius;
			}
			PolygonCenter(Center.X, Center.Y, Center.Z, pnt3D2.X, pnt3D2.Y, pnt3D2.Z, Side, Plane, ref VerticeX, ref VerticeY, ref VerticeZ);
			Vertices.Clear();
			for (int i = 0; i <= VerticeX.Count - 1; i++)
			{
				pnt3D = new Pnt3D();
				pnt3D.X = VerticeX[i];
				pnt3D.Y = VerticeY[i];
				pnt3D.Z = VerticeZ[i];
				Vertices.Add(pnt3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Radius: " + Radius + " - Side: " + Side + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PolygonSide(double BaseX, double BaseY, double BaseZ, double PointX, double PointY, double PointZ, int Side, WorkPlane Plane, ref List<double> VerticeX, ref List<double> VerticeY, ref List<double> VerticeZ)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			double num6 = 0.0;
			double num7 = 0.0;
			double num8 = 0.0;
			double num9 = 0.0;
			double num10 = 0.0;
			double num11 = 0.0;
			double num12 = 0.0;
			if (Side <= 2)
			{
				return;
			}
			VerticeX.Clear();
			VerticeY.Clear();
			VerticeZ.Clear();
			double num13;
			if (WorkPlane.isPlaneXY(Plane))
			{
				num8 = BaseX;
				num11 = PointX;
				num9 = BaseY;
				num12 = PointY;
				num10 = BaseZ;
				num13 = 360f / (float)Side;
				num = Length2D(num8, num9, num11, num12);
				num2 = num / 2.0 / Math.Sin(buConversion.DegreeToRadian(num13 / 2.0));
				if (num8 == num11)
				{
					num5 = (num9 + num12) / 2.0;
					num6 = (num9 + num12) / 2.0;
					num3 = num8 + Math.Sqrt(2.0 * num5 * num9 - Math.Pow(num9, 2.0) - Math.Pow(num5, 2.0) + Math.Pow(num2, 2.0));
					num4 = num8 - Math.Sqrt(2.0 * num5 * num9 - Math.Pow(num9, 2.0) - Math.Pow(num5, 2.0) + Math.Pow(num2, 2.0));
					num7 = PointAngle(num11, num12, num8, num9);
					if (!(num7 >= 90.0 && num7 < 270.0))
					{
						double num14 = PointAngle(num8, num9, num4, num6);
						double num15 = num2;
						VerticeX.Add(num4 + num15 * Math.Cos(buConversion.DegreeToRadianGreat360(num14 + 0.0 * num13)));
						VerticeY.Add(num6 + num15 * Math.Sin(buConversion.DegreeToRadianGreat360(num14 + 0.0 * num13)));
						VerticeZ.Add(num10);
						for (int i = 0; i <= Side - 1; i++)
						{
							VerticeX.Add(num4 + num15 * Math.Cos(buConversion.DegreeToRadianGreat360(num14 + (double)(i + 1) * num13)));
							VerticeY.Add(num6 + num15 * Math.Sin(buConversion.DegreeToRadianGreat360(num14 + (double)(i + 1) * num13)));
							VerticeZ.Add(num10);
						}
					}
					else
					{
						double num14 = PointAngle(num8, num9, num3, num5);
						double num15 = num2;
						VerticeX.Add(num3 + num15 * Math.Cos(buConversion.DegreeToRadianGreat360(num14 + 0.0 * num13)));
						VerticeY.Add(num5 + num15 * Math.Sin(buConversion.DegreeToRadianGreat360(num14 + 0.0 * num13)));
						VerticeZ.Add(num10);
