	public void PolygonStar(double BaseX, double BaseY, double BaseZ, double FirstX, double FirstY, double FirstZ, double SecondX, double SecondY, double SecondZ, WorkPlane Plane, int Slice, ref List<double> VerticeX, ref List<double> VerticeY, ref List<double> VerticeZ)
	{
		try
		{
			VerticeX.Clear();
			VerticeY.Clear();
			VerticeZ.Clear();
			if (Slice < 3)
			{
				Slice = 3;
			}
			if (WorkPlane.isPlaneXY(Plane))
			{
				double num = Math.Sqrt(Math.Pow(FirstX - BaseX, 2.0) + Math.Pow(FirstY - BaseY, 2.0));
				double num2 = Math.Sqrt(Math.Pow(SecondX - BaseX, 2.0) + Math.Pow(SecondY - BaseY, 2.0));
				double num3 = 360f / (float)Slice;
				double num4 = PointAngle(FirstX, FirstY, BaseX, BaseY);
				VerticeX.Add(BaseX + num * Math.Cos(buConversion.DegreeToRadian(num4 + 0.0 * num3)));
				VerticeY.Add(BaseY + num * Math.Sin(buConversion.DegreeToRadian(num4 + 0.0 * num3)));
				VerticeZ.Add(BaseZ);
				for (int i = 0; i <= Slice - 1; i++)
				{
					VerticeX.Add(BaseX + num2 * Math.Cos(buConversion.DegreeToRadian(num4 + num3 / 2.0 + (double)i * num3)));
					VerticeY.Add(BaseY + num2 * Math.Sin(buConversion.DegreeToRadian(num4 + num3 / 2.0 + (double)i * num3)));
					VerticeZ.Add(BaseZ);
					VerticeX.Add(BaseX + num * Math.Cos(buConversion.DegreeToRadian(num4 + (double)(i + 1) * num3)));
					VerticeY.Add(BaseY + num * Math.Sin(buConversion.DegreeToRadian(num4 + (double)(i + 1) * num3)));
					VerticeZ.Add(BaseZ);
				}
			}
			if (Plane.PlaneType == planeType.XZ)
			{
				double num = Math.Sqrt(Math.Pow(FirstX - BaseX, 2.0) + Math.Pow(FirstZ - BaseZ, 2.0));
				double num2 = Math.Sqrt(Math.Pow(SecondX - BaseX, 2.0) + Math.Pow(SecondZ - BaseZ, 2.0));
				double num3 = 360f / (float)Slice;
				double num4 = PointAngle(FirstX, FirstZ, BaseX, BaseZ);
				VerticeX.Add(BaseX + num * Math.Cos(buConversion.DegreeToRadian(num4 + 0.0 * num3)));
				VerticeY.Add(BaseY);
				VerticeZ.Add(BaseZ + num * Math.Sin(buConversion.DegreeToRadian(num4 + 0.0 * num3)));
				for (int j = 0; j <= Slice - 1; j++)
				{
					VerticeX.Add(BaseX + num2 * Math.Cos(buConversion.DegreeToRadian(num4 + num3 / 2.0 + (double)j * num3)));
					VerticeY.Add(BaseY);
					VerticeZ.Add(BaseZ + num2 * Math.Sin(buConversion.DegreeToRadian(num4 + num3 / 2.0 + (double)j * num3)));
					VerticeX.Add(BaseX + num * Math.Cos(buConversion.DegreeToRadian(num4 + (double)(j + 1) * num3)));
					VerticeY.Add(BaseY);
					VerticeZ.Add(BaseZ + num * Math.Sin(buConversion.DegreeToRadian(num4 + (double)(j + 1) * num3)));
				}
			}
			if (Plane.PlaneType == planeType.YZ)
			{
				double num = Math.Sqrt(Math.Pow(FirstY - BaseY, 2.0) + Math.Pow(FirstZ - BaseZ, 2.0));
				double num2 = Math.Sqrt(Math.Pow(SecondY - BaseY, 2.0) + Math.Pow(SecondZ - BaseZ, 2.0));
				double num3 = 360f / (float)Slice;
				double num4 = PointAngle(FirstY, FirstZ, BaseY, BaseZ);
				VerticeX.Add(BaseX);
				VerticeY.Add(BaseY + num * Math.Cos(buConversion.DegreeToRadian(num4 + 0.0 * num3)));
				VerticeZ.Add(BaseZ + num * Math.Sin(buConversion.DegreeToRadian(num4 + 0.0 * num3)));
				for (int k = 0; k <= Slice - 1; k++)
				{
					VerticeX.Add(BaseX);
					VerticeY.Add(BaseY + num2 * Math.Cos(buConversion.DegreeToRadian(num4 + num3 / 2.0 + (double)k * num3)));
					VerticeZ.Add(BaseZ + num2 * Math.Sin(buConversion.DegreeToRadian(num4 + num3 / 2.0 + (double)k * num3)));
					VerticeX.Add(BaseX);
					VerticeY.Add(BaseY + num * Math.Cos(buConversion.DegreeToRadian(num4 + (double)(k + 1) * num3)));
					VerticeZ.Add(BaseZ + num * Math.Sin(buConversion.DegreeToRadian(num4 + (double)(k + 1) * num3)));
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "BaseX: " + BaseX + " - BaseY: " + BaseY + " - BaseZ: " + BaseZ + " - FirstX: " + FirstX + " - FirstY: " + FirstY + " - FirstZ: " + FirstZ + " - SecondX: " + SecondX + " - SecondY: " + SecondY + " - SecondZ: " + SecondZ + " - Slice: " + Slice + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

