	public void Trapezoid(Pnt3D StartPoint, double Length, double Width, double FirstAngle, double SecondAngle, WorkPlane Plane, ref List<Pnt3D> Vertices)
	{
		try
		{
			double length = Width;
			double num = Width;
			double num2 = Width;
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			if (FirstAngle < 90.0)
			{
				_ = Width / Math.Cos(buConversion.DegreeToRadian(FirstAngle));
				num = Math.Tan(buConversion.DegreeToRadian(FirstAngle)) * Width;
			}
			if (SecondAngle < 90.0)
			{
				length = Width / Math.Cos(buConversion.DegreeToRadian(SecondAngle));
				num2 = Math.Tan(buConversion.DegreeToRadian(SecondAngle)) * Width;
			}
			if (FirstAngle == 90.0)
			{
				num = 0.0;
			}
			if (SecondAngle == 90.0)
			{
				num2 = 0.0;
			}
			Vertices.Clear();
			Pnt3D pnt = new Pnt3D(StartPoint);
			Vertices.Add(new Pnt3D(pnt));
			pnt = new Pnt3D(new Pnt3D(StartPoint));
			pnt.X += Length;
			Vertices.Add(new Pnt3D(pnt));
			pnt3D = new Pnt3D();
			pnt3D2 = new Pnt3D();
			LineWithLengthAndAngle(pnt, length, 180.0 + SecondAngle, Plane, ref pnt3D, ref pnt3D2);
			Vertices.Add(new Pnt3D(pnt3D2));
			pnt = new Pnt3D(new Pnt3D(pnt3D2));
			pnt3D = new Pnt3D();
			pnt3D2 = new Pnt3D();
			LineWithLengthAndAngle(pnt, Length - num - num2, 180.0, Plane, ref pnt3D, ref pnt3D2);
			Vertices.Add(new Pnt3D(pnt3D2));
			Vertices.Add(new Pnt3D(StartPoint));
		}
		catch (Exception mSException)
		{
			string text = "StartPoint: " + StartPoint.ToString() + " - Length: " + Length + " - Width: " + Width + " - FirstAngle: " + FirstAngle + " - SecondAngle: " + SecondAngle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

