	public ClockDirectionType PolygonDirection(List<Pnt3D> Vertices, WorkPlane Plane, ref double TotalArea)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			Pnt3D.Copy(Vertices, ref CopiedPnt);
			if (!IsClosed(CopiedPnt))
			{
				CopiedPnt.Add(new Pnt3D(Vertices[0]));
			}
			if (WorkPlane.isPlaneXY(Plane))
			{
				for (int i = 1; i <= CopiedPnt.Count - 1; i++)
				{
					_ = CopiedPnt[i].X - CopiedPnt[i - 1].X;
					_ = CopiedPnt[i].Y + CopiedPnt[i - 1].Y;
					num += (CopiedPnt[i].X - CopiedPnt[i - 1].X) * (CopiedPnt[i].Y + CopiedPnt[i - 1].Y) / 2.0;
					num2 += (CopiedPnt[i - 1].X * CopiedPnt[i].Y - CopiedPnt[i].X * CopiedPnt[i - 1].Y) / 2.0;
				}
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				for (int j = 1; j <= CopiedPnt.Count - 1; j++)
				{
					num += (CopiedPnt[j].X - CopiedPnt[j - 1].X) * (CopiedPnt[j].Z + CopiedPnt[j - 1].Z) / 2.0;
				}
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				for (int k = 1; k <= CopiedPnt.Count - 1; k++)
				{
					num += (CopiedPnt[k].Y - CopiedPnt[k - 1].Y) * (CopiedPnt[k].Z + CopiedPnt[k - 1].Z) / 2.0;
				}
			}
			TotalArea = num;
			if (!(num > 0.0))
			{
				return ClockDirectionType.CCW;
			}
			return ClockDirectionType.CW;
		}
		catch (Exception mSException)
		{
			string text = "Vertices: " + Vertices.Count + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return ClockDirectionType.CW;
		}
	}

	public double PolygonArea(List<Pnt3D> Vertices, WorkPlane Plane)
	{
		try
		{
			double num = 0.0;
			if (WorkPlane.isPlaneXY(Plane))
			{
				for (int i = 1; i <= Vertices.Count - 1; i++)
				{
					num += (Vertices[i].X - Vertices[i - 1].X) * (Vertices[i].Y + Vertices[i - 1].Y) / 2.0;
				}
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				for (int j = 1; j <= Vertices.Count - 1; j++)
				{
					num += (Vertices[j].X - Vertices[j - 1].X) * (Vertices[j].Z + Vertices[j - 1].Z) / 2.0;
				}
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				for (int k = 1; k <= Vertices.Count - 1; k++)
				{
					num += (Vertices[k].Y - Vertices[k - 1].Y) * (Vertices[k].Z + Vertices[k - 1].Z) / 2.0;
				}
			}
			return Math.Abs(num);
		}
		catch (Exception mSException)
		{
			string text = "Vertices: " + Vertices.Count + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public bool PolygonIsConvex(List<Pnt3D> Vertices)
	{
		bool flag = false;
		bool flag2 = false;
		for (int i = 0; i < Vertices.Count - 1; i++)
		{
			int num = (i + 1) % Vertices.Count;
			int index = (num + 1) % Vertices.Count;
			double num2 = CrossProductLength(Vertices[i].X, Vertices[i].Y, Vertices[num].X, Vertices[num].Y, Vertices[index].X, Vertices[index].Y);
			if (!(num2 < 0.0))
			{
				if (num2 > 0.0)
				{
					flag2 = true;
				}
			}
			else
			{
				flag = true;
			}
			if (flag && flag2)
			{
				return false;
			}
		}
		return true;
	}

	public double CrossProductLength(Pnt3D PA, Pnt3D PB, Pnt3D PC)
	{
		return CrossProductLength(PA.X, PA.Y, PB.X, PB.Y, PC.X, PC.Y);
	}

	public double CrossProductLength(double Ax, double Ay, double Bx, double By, double Cx, double Cy)
	{
		double num = Ax - Bx;
		double num2 = Ay - By;
		double num3 = Cx - Bx;
		double num4 = Cy - By;
		return num * num4 - num2 * num3;
	}

