	public void EllipseArcWithCenter(Pnt3D Center, double MajorRadius, double MinorRadius, double StartAngle, double EndAngle, double Angle, WorkPlane Plane, EntityResolution EntResolution, ref List<Pnt3D> Vertices)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			double num6 = 0.0;
			double num7 = StartAngle;
			double num8 = EndAngle;
			double num9 = 0.0;
			double num10 = 0.1;
			int num11 = 10;
			num11 = EllipseVerticeCountByResolution(MajorRadius, MinorRadius, EntResolution);
			if (num11 < 10)
			{
				num11 = 10;
			}
			num10 = (num8 - num7) / (double)num11;
			num10 = buConversion.DegreeToRadianGreat360(num10);
			Vertices.Clear();
			if (WorkPlane.isPlaneXY(Plane))
			{
				num9 = (360.0 - Angle) * Math.PI / 180.0;
				num = Math.Sin(num9);
