	public int EllipseArcVerticeCountByResolution(double MajorRadius, double MinorRadius, double StartAngle, double EndAngle, EntityResolution EntResolution)
	{
		try
		{
			int num = 10;
			double num2 = 0.0;
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByNumber)
			{
				num = EntResolution.GeometricCount;
				if (num < EntResolution.MinPointCount)
				{
					num = EntResolution.MinPointCount;
				}
			}
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByLength)
			{
				num2 = EllipseCircumference(MajorRadius, MinorRadius);
				num = Convert.ToInt32(num2 / EntResolution.GeometricLength * ((EndAngle - StartAngle) / 360.0));
				if (num < EntResolution.MinPointCount)
				{
					num = EntResolution.MinPointCount;
				}
			}
			if (EntResolution.ResolutionTypes == EntityResolutionType.ByLnRadius)
			{
				double num3 = MajorRadius;
				if (MinorRadius < MajorRadius)
				{
					num3 = MinorRadius;
				}
				if (num3 > 0.0)
				{
					num = Convert.ToInt32(Math.Log(Math.Abs(num3), Math.E) * EntResolution.LnRatio * ((EndAngle - StartAngle) / 360.0));
				}
				if (num < EntResolution.MinPointCount)
				{
					num = EntResolution.MinPointCount;
				}
			}
			return num;
		}
		catch (Exception mSException)
		{
			string text = "Major R: " + MajorRadius + " - Minor R: " + MinorRadius + " - Entitiy Res: " + EntResolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

