	public void EllipseMajorDiameterLine(Pnt3D Center, double MajorRadius, double Angle, Pnt3D ActivePoint, ref Pnt3D FirstPoint, ref Pnt3D SecondPoint)
	{
		try
		{
			if (MajorRadius > 0.0)
			{
				double num = Angle;
				Pnt3D BasePnt = new Pnt3D();
				Pnt3D EndPnt = new Pnt3D();
				LineWithLengthAndAngle(Center, MajorRadius, num, new WorkPlane(), ref BasePnt, ref EndPnt);
				LineWithLengthAndAngle(EndPnt, MajorRadius * 2.0, num + 180.0, new WorkPlane(), ref FirstPoint, ref SecondPoint);
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - MajorRadius: " + MajorRadius + " - Angle: " + Angle + " - ActivePoint: " + ActivePoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void EllipseMinorDiameterLine(Pnt3D Center, double MinorRadius, double Angle, Pnt3D ActivePoint, ref Pnt3D FirstPoint, ref Pnt3D SecondPoint)
	{
		try
		{
			if (MinorRadius > 0.0)
			{
				double num = Angle + 90.0;
				Pnt3D BasePnt = new Pnt3D();
				Pnt3D EndPnt = new Pnt3D();
				LineWithLengthAndAngle(Center, MinorRadius, num, new WorkPlane(), ref BasePnt, ref EndPnt);
				LineWithLengthAndAngle(EndPnt, MinorRadius * 2.0, num + 180.0, new WorkPlane(), ref FirstPoint, ref SecondPoint);
			}
