		}
	}

	public double EllipseAngle(Pnt3D CenterPoint, double MajorRadius, double MinorRadius, Pnt3D RefPoint, WorkPlane Plane)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			double num6 = 0.0;
			double num7 = 0.0;
			int ClosestPoint = 0;
			if (!WorkPlane.isPlaneXY(Plane))
			{
				if (WorkPlane.isPlaneXZ(Plane))
				{
					MessageBox.Show("Not Ready");
				}
				if (WorkPlane.isPlaneYZ(Plane))
				{
					MessageBox.Show("Not Ready");
				}
				return 0.0;
			}
			if (CenterPoint.X != RefPoint.X)
