	}

	public double EllipseArea(double MajorRadius, double MinorRadius)
	{
		try
		{
			return Math.PI * MajorRadius * MinorRadius;
		}
		catch (Exception mSException)
		{
			string text = "Major R: " + MajorRadius + " - Minor R: " + MinorRadius;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double EllipseCircumference(double MajorRadius, double MinorRadius)
	{
		try
		{
			return Math.Sqrt((MajorRadius * MajorRadius + MinorRadius * MinorRadius) * 0.5) * Math.PI * 2.0;
		}
		catch (Exception mSException)
		{
			string text = "Major R: " + MajorRadius + " - Minor R: " + MinorRadius;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double ArcEllipseArea(double MajorRadius, double MinorRadius, double StartAngle, double EndAngle)
	{
		try
		{
			return Math.PI * MajorRadius * MinorRadius * (EndAngle - StartAngle) / 360.0;
		}
		catch (Exception mSException)
		{
			string text = "Major R: " + MajorRadius + " - Minor R: " + MinorRadius + "- SA: " + StartAngle + " - EA: " + EndAngle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public double ArcEllipseCircumference(double MajorRadius, double MinorRadius, double StartAngle, double EndAngle)
	{
		try
		{
			return Math.Sqrt((MajorRadius * MajorRadius + MinorRadius * MinorRadius) * 0.5) * Math.PI * 2.0 * (EndAngle - StartAngle) / 360.0;
		}
		catch (Exception mSException)
		{
			string text = "Major R: " + MajorRadius + " - Minor R: " + MinorRadius + "- SA: " + StartAngle + " - EA: " + EndAngle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public void EllipseRadiusByAngle(double MajorRadius, double MinorRadius, double Angle, ref double CalcRadius)
	{
		string callMethod = "EllipseRadiusByAngle";
		try
		{
			CalcRadius = MajorRadius * MinorRadius / Math.Sqrt(Math.Pow(MajorRadius * Math.Sin(buConversion.DegreeToRadian(Angle)), 2.0) + Math.Pow(MinorRadius * Math.Cos(buConversion.DegreeToRadian(Angle)), 2.0));
		}
		catch (Exception mSException)
		{
			string text = "MajorRadius: " + MajorRadius + "- MinorRadius: " + MinorRadius + "- Angle: " + Angle;
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: false, text);
		}
	}

