	public bool Barrel(Pnt3D HeadPosition, double HeadRadius, double TaleRadius, double Length, double Angle, bool Reverse, WorkPlane Plane, EntityResolution EntResolution, ref eArc HeadArc, ref eArc TaleArc)
	{
		try
		{
			double num = 0.0;
			if (Reverse)
			{
				num = 180.0;
			}
			Pnt3D pnt3D = new Pnt3D();
			if (!WorkPlane.isPlaneXY(Plane))
			{
				if (!WorkPlane.isPlaneXZ(Plane))
				{
					if (!WorkPlane.isPlaneYZ(Plane))
					{
						return true;
					}
					double num2 = HeadPosition.Z + TaleRadius;
					double num3 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Z - num2, 2.0));
					double num4 = HeadPosition.Y + num3;
					double num5 = buConversion.RadianToDegree(Math.Atan((num2 - HeadPosition.Z) / (num4 - HeadPosition.Y)));
					double num6 = 360.0 - num5;
					double num7 = num5 + Angle + num;
					double num8 = num6 + Angle + num;
					if (num7 > 360.0 && num8 > 360.0)
					{
						num7 -= 360.0;
						num8 -= 360.0;
					}
					HeadArc = new eArc(new Pnt3D(HeadPosition), HeadRadius, num7, num8, Plane);
					pnt3D = new Pnt3D();
					Pnt3D BasePnt = new Pnt3D();
					LineWithLengthAndAngle(HeadPosition, Length + num, Angle, Plane, ref BasePnt, ref pnt3D);
					num7 = 270.0 + Angle + num;
					num8 = 450.0 + Angle + num;
					if (num7 > 360.0 && num8 > 360.0)
					{
						num7 -= 360.0;
						num8 -= 360.0;
					}
					TaleArc = new eArc(new Pnt3D(pnt3D), TaleRadius, num7, num8, Plane);
					return true;
				}
				double num9 = HeadPosition.Z + TaleRadius;
				double num10 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Z - num9, 2.0));
				double num11 = HeadPosition.X + num10;
				double num12 = buConversion.RadianToDegree(Math.Atan((num9 - HeadPosition.Z) / (num11 - HeadPosition.X)));
				double num13 = 360.0 - num12;
				double num14 = num12 + Angle + num;
				double num15 = num13 + Angle + num;
				if (num14 > 360.0 && num15 > 360.0)
				{
					num14 -= 360.0;
					num15 -= 360.0;
				}
				HeadArc = new eArc(new Pnt3D(HeadPosition), HeadRadius, num14, num15, Plane);
				pnt3D = new Pnt3D();
				Pnt3D BasePnt2 = new Pnt3D();
				LineWithLengthAndAngle(HeadPosition, Length, Angle + num, Plane, ref BasePnt2, ref pnt3D);
				num14 = 270.0 + Angle + num;
				num15 = 450.0 + Angle + num;
				if (num14 > 360.0 && num15 > 360.0)
				{
					num14 -= 360.0;
					num15 -= 360.0;
				}
				TaleArc = new eArc(new Pnt3D(pnt3D), TaleRadius, num14, num15, Plane);
				return true;
			}
			double num16 = HeadPosition.Y + TaleRadius;
			double num17 = Math.Sqrt(Math.Pow(HeadRadius, 2.0) - Math.Pow(HeadPosition.Y - num16, 2.0));
			double num18 = HeadPosition.X + num17;
			double num19 = buConversion.RadianToDegree(Math.Atan((num16 - HeadPosition.Y) / (num18 - HeadPosition.X)));
			double num20 = 360.0 - num19;
			if (buNumeric.IsNumeric(num19.ToString()))
			{
				double num21 = num19 + Angle + num;
				double num22 = num20 + Angle + num;
				if (num21 > 360.0 && num22 > 360.0)
				{
					num21 -= 360.0;
					num22 -= 360.0;
				}
				HeadArc = new eArc(new Pnt3D(HeadPosition), HeadRadius, num21, num22, Plane);
				pnt3D = new Pnt3D();
				Pnt3D BasePnt3 = new Pnt3D();
				LineWithLengthAndAngle(HeadPosition, Length, Angle + num, Plane, ref BasePnt3, ref pnt3D);
				num21 = 270.0 + Angle + num;
				num22 = 450.0 + Angle + num;
				if (num21 > 360.0 && num22 > 360.0)
				{
					num21 -= 360.0;
					num22 -= 360.0;
				}
				TaleArc = new eArc(new Pnt3D(pnt3D), TaleRadius, num21, num22, Plane);
				return true;
			}
			return false;
		}
		catch (Exception mSException)
		{
			string text = "HeadPosition: " + HeadPosition.ToString() + " - HeadRadius: " + HeadRadius + " - TaleRadius: " + TaleRadius + " - Length: " + Length + " - Angle: " + Angle + " - Plane: " + Plane.ToString() + " - EntResolution: " + EntResolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public bool Barrel(Pnt3D HeadPosition, double HeadRadius, double TaleRadius, double Length, double Angle, bool Reverse, WorkPlane Plane, EntityResolution EntResolution, ref List<Pnt3D> CalculatedPoints)
	{
		try
		{
			eArc HeadArc = new eArc();
			eArc TaleArc = new eArc();
			Barrel(HeadPosition, HeadRadius, TaleRadius, Length, Angle, Reverse, Plane, EntResolution, ref HeadArc, ref TaleArc);
			CalculatedPoints.Clear();
			Pnt3D.Copy(HeadArc.Vertice, ref CalculatedPoints);
			Pnt3D.Add(TaleArc.Vertice, ref CalculatedPoints);
			CalculatedPoints.Add(new Pnt3D(CalculatedPoints[0]));
			return false;
		}
		catch (Exception)
		{
			return false;
		}
	}

	public bool Barrel(Pnt3D HeadPosition, double HeadRadius, double TaleRadius, double Length, double Angle, bool Reverse, WorkPlane Plane, EntityResolution EntResolution, ref eArc HeadArc, ref eArc TaleArc, ref eLine FirstLine, ref eLine SecondLine)
	{
		try
		{
			bool flag = false;
			new eArc();
			new eArc();
			flag = Barrel(HeadPosition, HeadRadius, TaleRadius, Length, Angle, Reverse, Plane, EntResolution, ref HeadArc, ref TaleArc);
			FirstLine = new eLine(new Pnt3D(HeadArc.Vertice[HeadArc.Vertice.Count - 1]), new Pnt3D(TaleArc.Vertice[0]));
			SecondLine = new eLine(new Pnt3D(TaleArc.Vertice[TaleArc.Vertice.Count - 1]), new Pnt3D(HeadArc.Vertice[0]));
			return flag;
		}
		catch (Exception)
		{
			return false;
		}
	}

	public void BSplineQuadraticUniform(List<Pnt3D> ControlPoints, double dt, bool Closed, ref List<Pnt3D> CalculatedPoints)
	{
		try
		{
			List<Pnt3D> list = new List<Pnt3D>();
			List<Pnt3D> CalculatedPoints2 = new List<Pnt3D>();
			List<Pnt3D> list2 = new List<Pnt3D>();
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			int num = 0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 1.0;
			double num6 = 1.0;
			double num7 = -2.0;
			double num8 = 1.0;
			double num9 = -2.0;
			double num10 = 2.0;
			double num11 = 0.0;
			double num12 = 1.0;
			double num13 = 1.0;
			double num14 = 0.0;
			double num15 = 0.0;
			double num16 = 0.0;
			double num17 = 0.0;
			double num18 = 0.0;
			double num19 = 0.0;
			double num20 = 0.0;
			double num21 = 0.0;
			double num22 = 0.0;
			double num23 = 0.0;
			if (dt <= 0.0)
			{
				dt = 0.1;
			}
			CalculatedPoints.Clear();
			num = Convert.ToInt32(1.0 / dt);
			if (!Closed)
			{
				for (int i = 0; i <= ControlPoints.Count - 1; i++)
				{
					list2.Add(new Pnt3D(ControlPoints[i]));
				}
				if (list2.Count <= 1)
				{
					return;
				}
				if (list2.Count == 2)
				{
					pnt3D = new Pnt3D();
					pnt3D = MiddlePointOfLine(list2[0], list2[1]);
					list2.Insert(1, new Pnt3D(pnt3D));
				}
			}
			else
			{
				pnt3D = new Pnt3D(ControlPoints[0]);
				pnt3D2 = new Pnt3D(ControlPoints[ControlPoints.Count - 1]);
				for (int j = 0; j <= ControlPoints.Count - 1; j++)
				{
					list2.Add(new Pnt3D(ControlPoints[j]));
				}
				list2.Insert(0, new Pnt3D(pnt3D2));
				list2.Add(new Pnt3D(pnt3D));
			}
			for (int k = 1; k <= list2.Count - 2; k++)
			{
				for (int l = 0; l <= num; l++)
				{
					pnt3D = new Pnt3D();
					num5 = (double)l * dt;
					num15 = 0.5 * (num6 * Math.Pow(num5, 2.0) + num9 * num5 + num12) * list2[k - 1].X;
					num16 = 0.5 * (num7 * Math.Pow(num5, 2.0) + num10 * num5 + num13) * list2[k].X;
					num17 = 0.5 * (num8 * Math.Pow(num5, 2.0) + num11 * num5 + num14) * list2[k + 1].X;
					num2 = num15 + num16 + num17;
					num15 = 0.5 * (num6 * Math.Pow(num5, 2.0) + num9 * num5 + num12) * list2[k - 1].Y;
					num16 = 0.5 * (num7 * Math.Pow(num5, 2.0) + num10 * num5 + num13) * list2[k].Y;
					num17 = 0.5 * (num8 * Math.Pow(num5, 2.0) + num11 * num5 + num14) * list2[k + 1].Y;
					num3 = num15 + num16 + num17;
					num15 = 0.5 * (num6 * Math.Pow(num5, 2.0) + num9 * num5 + num12) * list2[k - 1].Z;
					num16 = 0.5 * (num7 * Math.Pow(num5, 2.0) + num10 * num5 + num13) * list2[k].Z;
					num17 = 0.5 * (num8 * Math.Pow(num5, 2.0) + num11 * num5 + num14) * list2[k + 1].Z;
					num4 = num15 + num16 + num17;
					pnt3D.X = num2;
					pnt3D.Y = num3;
					pnt3D.Z = num4;
					CalculatedPoints.Add(pnt3D);
				}
			}
			if (!Closed && CalculatedPoints.Count > 0)
			{
				list.Add(new Pnt3D(ControlPoints[0]));
				list.Add(new Pnt3D(CalculatedPoints[0]));
				num18 = ControlPoints[1].X - ControlPoints[0].X;
				num19 = ControlPoints[1].Y - ControlPoints[0].Y;
				num20 = ControlPoints[1].Z - ControlPoints[0].Z;
				num21 = (CalculatedPoints[1].X - CalculatedPoints[0].X) * (1000.0 / (dt * 1000.0));
				num22 = (CalculatedPoints[1].Y - CalculatedPoints[0].Y) * (1000.0 / (dt * 1000.0));
				num23 = (CalculatedPoints[1].Z - CalculatedPoints[0].Z) * (1000.0 / (dt * 1000.0));
				HermiteCubicSplineWithStartEndVector(list, dt, 1.0, 0.0, new Vec3D(num18, num19, num20), new Vec3D(num21, num22, num23), ref CalculatedPoints2);
				for (int num24 = CalculatedPoints2.Count - 1; num24 >= 0; num24--)
				{
					CalculatedPoints.Insert(0, new Pnt3D(CalculatedPoints2[num24]));
				}
				list.Clear();
				CalculatedPoints2.Clear();
				list.Add(new Pnt3D(CalculatedPoints[CalculatedPoints.Count - 1]));
				list.Add(new Pnt3D(ControlPoints[ControlPoints.Count - 1]));
				num18 = (CalculatedPoints[CalculatedPoints.Count - 1].X - CalculatedPoints[CalculatedPoints.Count - 2].X) * (1000.0 / (dt * 1000.0));
				num19 = (CalculatedPoints[CalculatedPoints.Count - 1].Y - CalculatedPoints[CalculatedPoints.Count - 2].Y) * (1000.0 / (dt * 1000.0));
				num20 = (CalculatedPoints[CalculatedPoints.Count - 1].Z - CalculatedPoints[CalculatedPoints.Count - 2].Z) * (1000.0 / (dt * 1000.0));
				num21 = ControlPoints[ControlPoints.Count - 1].X - ControlPoints[ControlPoints.Count - 2].X;
				num22 = ControlPoints[ControlPoints.Count - 1].Y - ControlPoints[ControlPoints.Count - 2].Y;
				num23 = ControlPoints[ControlPoints.Count - 1].Z - ControlPoints[ControlPoints.Count - 2].Z;
				HermiteCubicSplineWithStartEndVector(list, dt, 1.0, 0.0, new Vec3D(num18, num19, num20), new Vec3D(num21, num22, num23), ref CalculatedPoints2);
				for (int m = 0; m <= CalculatedPoints2.Count - 1; m++)
				{
					CalculatedPoints.Add(new Pnt3D(CalculatedPoints2[m]));
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "ControlPoints: " + ControlPoints.Count + " - dt: " + dt + " - Closed: " + Closed;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
