	public void BsplineRationalKnotVector(List<Pnt3D> ControlPoints, int Order, double dt, List<double> Weigth, ref List<Pnt3D> CalculatedPoints)
	{
		try
		{
			List<int> list = new List<int>();
			List<double> list2 = new List<double>();
			Pnt3D pnt3D = new Pnt3D();
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			CalculatedPoints.Clear();
			int num4 = ControlPoints.Count + Order;
			for (int i = 0; i <= ControlPoints.Count - 1; i++)
			{
				list2.Add(0.0);
			}
			for (int j = 0; j <= num4 - 1; j++)
			{
				list.Add(0);
			}
			int num5 = Convert.ToInt32((double)ControlPoints.Count / dt);
			KnotBSpline(ControlPoints.Count, Order, list);
			double num6 = 0.0;
			double num7 = (double)list[num4 - 1] / (double)(num5 - 1);
			for (int k = 0; k <= num5 - 1; k++)
			{
				if ((double)list[num4 - 1] - num6 < 5E-06)
				{
					num6 = list[num4 - 1];
				}
				BasisRegionalBSpline(Order, num6, ControlPoints.Count, list, Weigth, list2);
				num = 0.0;
				num2 = 0.0;
				num3 = 0.0;
				for (int l = 0; l <= ControlPoints.Count - 1; l++)
				{
					num += list2[l] * ControlPoints[l].X;
					num2 += list2[l] * ControlPoints[l].Y;
					num3 += list2[l] * ControlPoints[l].Z;
				}
				pnt3D = new Pnt3D();
				pnt3D.X = num;
				pnt3D.Y = num2;
				pnt3D.Z = num3;
				CalculatedPoints.Add(pnt3D);
				num6 += num7;
			}
		}
		catch (Exception mSException)
		{
			string text = "ControlPoints: " + ControlPoints.Count + " - dt: " + dt + " - Order: " + Order + " - Weigth: " + Weigth.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void BsplineRationalKnotVectorKnott(List<Pnt3D> ControlPoints, int Order, double dt, List<double> Weigth, ref List<double> CalcKnot)
	{
		try
		{
			List<int> list = new List<int>();
			List<double> list2 = new List<double>();
			int num = ControlPoints.Count + Order;
			for (int i = 0; i <= ControlPoints.Count - 1; i++)
			{
				list2.Add(0.0);
			}
			for (int j = 0; j <= num - 1; j++)
			{
				list.Add(0);
			}
			Convert.ToInt32((double)ControlPoints.Count / dt);
			KnotBSpline(ControlPoints.Count, Order, list);
			CalcKnot.Clear();
			for (int k = 0; k <= list.Count - 1; k++)
			{
				CalcKnot.Add(list[k]);
			}
		}
		catch (Exception mSException)
		{
			string text = "ControlPoints: " + ControlPoints.Count + " - dt: " + dt + " - Order: " + Order + " - Weigth: " + Weigth.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void HermiteCubicSplineWithStartEndVector(List<Pnt3D> ControlPoints, double dt, double Multiply, double Offset, Vec3D StartVector, Vec3D EndVector, ref List<Pnt3D> CalculatedPoints)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			double num = 2.0;
			double num2 = -2.0;
			double num3 = 1.0;
			double num4 = 1.0;
			double num5 = -3.0;
			double num6 = 3.0;
			double num7 = -2.0;
			double num8 = -1.0;
			double num9 = 0.0;
			double num10 = 0.0;
			double num11 = 1.0;
			double num12 = 0.0;
			double num13 = 1.0;
			double num14 = 0.0;
			double num15 = 0.0;
			double num16 = 0.0;
			double num17 = 0.0;
			double num18 = 0.0;
			double num19 = 0.0;
			double num20 = 0.0;
			double num21 = 0.0;
			double num22 = 0.0;
			double num23 = 0.0;
			double num24 = 0.0;
			double num25 = 0.0;
			double num26 = 0.0;
			double num27 = 0.0;
			double num28 = 0.0;
			double num29 = 0.0;
			double num30 = 0.0;
			double num31 = 0.0;
			double num32 = 0.0;
			double num33 = 0.0;
			double num34 = 0.0;
			double num35 = 0.0;
			double num36 = 0.0;
			double num37 = 0.0;
			int num38 = 0;
			CalculatedPoints.Clear();
			num38 = Convert.ToInt32(1.0 / dt);
			for (int i = 0; i <= ControlPoints.Count - 2; i++)
			{
				if (ControlPoints.Count <= 2)
				{
					num21 = StartVector.X;
					num23 = StartVector.Y;
					num25 = StartVector.Z;
					num22 = EndVector.X;
					num24 = EndVector.Y;
					num26 = EndVector.Z;
				}
				else
				{
					if (i == 0)
					{
						num34 = AngleOfTwoLines(ControlPoints[i], ControlPoints[i + 1], ControlPoints[i + 1], ControlPoints[i + 2], new WorkPlane());
						num36 = (180.0 - num34) / 2.0;
						num34 = PointAngle(ControlPoints[i], ControlPoints[i + 1]);
						num35 = PointAngle(ControlPoints[i + 2], ControlPoints[i + 1]);
						num36 = (num34 + num35) / 2.0;
						num36 = ((num35 > num34) ? (num36 + 90.0) : (num36 - 90.0));
						num36 += Offset;
						num21 = StartVector.X;
						num23 = StartVector.Y;
						num27 = Math.Abs(DeltaX(ControlPoints[i + 1], ControlPoints[i])) * Multiply;
						num28 = Math.Abs(DeltaY(ControlPoints[i + 1], ControlPoints[i])) * Multiply;
						num29 = Math.Abs(DeltaZ(ControlPoints[i + 1], ControlPoints[i])) * Multiply;
						num22 = num27 * Math.Cos(buConversion.DegreeToRadian(num36));
						num24 = num28 * Math.Sin(buConversion.DegreeToRadian(num36));
						num26 = num29 * Math.Cos(buConversion.DegreeToRadian(num36));
					}
					if ((i > 0) & (i < ControlPoints.Count - 2))
					{
						num34 = AngleOfTwoLines(ControlPoints[i], ControlPoints[i + 1], ControlPoints[i + 1], ControlPoints[i + 2], new WorkPlane());
						num36 = (180.0 - num34) / 2.0;
						num34 = PointAngle(ControlPoints[i], ControlPoints[i + 1]);
						num35 = PointAngle(ControlPoints[i + 2], ControlPoints[i + 1]);
						num36 = (num34 + num35) / 2.0;
						num36 = ((num35 > num34) ? (num36 + 90.0) : (num36 - 90.0));
						num36 += Offset;
						num27 = Math.Abs(DeltaX(ControlPoints[i + 1], ControlPoints[i])) * Multiply;
						num28 = Math.Abs(DeltaY(ControlPoints[i + 1], ControlPoints[i])) * Multiply;
						num29 = Math.Abs(DeltaZ(ControlPoints[i + 1], ControlPoints[i])) * Multiply;
						num22 = num27 * Math.Cos(buConversion.DegreeToRadian(num36));
						num24 = num28 * Math.Sin(buConversion.DegreeToRadian(num36));
						num26 = num29 * Math.Cos(buConversion.DegreeToRadian(num36));
					}
					if (i == ControlPoints.Count - 2)
					{
						num22 = EndVector.X;
						num24 = EndVector.Y;
						num26 = EndVector.Z;
					}
				}
				for (int j = 0; j <= num38; j++)
				{
					pnt3D = new Pnt3D();
					num37 = (double)j * dt;
					num17 = ControlPoints[i].X;
					num18 = ControlPoints[i + 1].X;
					num19 = num21;
					num20 = num22;
					num30 = (Math.Pow(num37, 3.0) * num + Math.Pow(num37, 2.0) * num5 + num37 * num9 + num13) * num17;
					num31 = (Math.Pow(num37, 3.0) * num2 + Math.Pow(num37, 2.0) * num6 + num37 * num10 + num14) * num18;
					num32 = (Math.Pow(num37, 3.0) * num3 + Math.Pow(num37, 2.0) * num7 + num37 * num11 + num15) * num19;
					num33 = (Math.Pow(num37, 3.0) * num4 + Math.Pow(num37, 2.0) * num8 + num37 * num12 + num16) * num20;
					pnt3D.X = num30 + num31 + num32 + num33;
					num17 = ControlPoints[i].Y;
					num18 = ControlPoints[i + 1].Y;
					num19 = num23;
					num20 = num24;
					num30 = (Math.Pow(num37, 3.0) * num + Math.Pow(num37, 2.0) * num5 + num37 * num9 + num13) * num17;
					num31 = (Math.Pow(num37, 3.0) * num2 + Math.Pow(num37, 2.0) * num6 + num37 * num10 + num14) * num18;
					num32 = (Math.Pow(num37, 3.0) * num3 + Math.Pow(num37, 2.0) * num7 + num37 * num11 + num15) * num19;
					num33 = (Math.Pow(num37, 3.0) * num4 + Math.Pow(num37, 2.0) * num8 + num37 * num12 + num16) * num20;
					pnt3D.Y = num30 + num31 + num32 + num33;
					num17 = ControlPoints[i].Z;
					num18 = ControlPoints[i + 1].Z;
					num19 = num25;
					num20 = num26;
					num30 = (Math.Pow(num37, 3.0) * num + Math.Pow(num37, 2.0) * num5 + num37 * num9 + num13) * num17;
					num31 = (Math.Pow(num37, 3.0) * num2 + Math.Pow(num37, 2.0) * num6 + num37 * num10 + num14) * num18;
					num32 = (Math.Pow(num37, 3.0) * num3 + Math.Pow(num37, 2.0) * num7 + num37 * num11 + num15) * num19;
					num33 = (Math.Pow(num37, 3.0) * num4 + Math.Pow(num37, 2.0) * num8 + num37 * num12 + num16) * num20;
					pnt3D.Z = num30 + num31 + num32 + num33;
					CalculatedPoints.Add(pnt3D);
				}
				num21 = num22;
				num23 = num24;
				num25 = num26;
			}
		}
		catch (Exception mSException)
		{
			string text = "ControlPoints: " + ControlPoints.Count + " - dt: " + dt + " - Multiply: " + Multiply + " - Offset: " + Offset + " - StartVector: " + StartVector.ToString() + " - EndVector: " + EndVector.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void BezeirCurve(List<Pnt3D> ControlPoints, double dt, ref List<Pnt3D> CalculatedPoints)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			int num = 0;
			int num2 = 0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			double num6 = 0.0;
			if (ControlPoints.Count <= 1)
			{
				return;
			}
			if (dt <= 0.0)
			{
				dt = 0.1;
			}
			dt /= (double)ControlPoints.Count;
			CalculatedPoints.Clear();
			num = Convert.ToInt32(1.0 / dt);
			num2 = ControlPoints.Count - 1;
			for (int i = 0; i <= num; i++)
			{
				pnt3D = new Pnt3D();
				num6 = (double)i * dt;
				num3 = 0.0;
				num4 = 0.0;
				num5 = 0.0;
				for (int j = 0; j <= ControlPoints.Count - 1; j++)
				{
					BezeirBlend(num2, j, num6);
					num3 += ControlPoints[j].X * BezeirBlend(num2, j, num6);
					num4 += ControlPoints[j].Y * BezeirBlend(num2, j, num6);
					num5 += ControlPoints[j].Z * BezeirBlend(num2, j, num6);
				}
				pnt3D.X = num3;
				pnt3D.Y = num4;
				pnt3D.Z = num5;
				CalculatedPoints.Add(pnt3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "ControlPoints: " + ControlPoints.Count + " - dt: " + dt;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void SplineCubicUniform(List<Pnt3D> ControlPoints, double dt, ref List<Pnt3D> CalculatedPoints)
	{
		try
		{
			if (dt <= 0.0)
			{
				dt = 0.1;
			}
			CalculatedPoints.Clear();
			double[] array = new double[ControlPoints.Count];
			double[] array2 = new double[ControlPoints.Count];
			double[] array3 = new double[ControlPoints.Count];
			int nOutputPoints = Convert.ToInt32(1.0 / dt * (double)ControlPoints.Count);
			for (int i = 0; i <= ControlPoints.Count - 1; i++)
			{
				array[i] = ControlPoints[i].X;
				array2[i] = ControlPoints[i].Y;
				array3[i] = ControlPoints[i].Z;
			}
			CubicSpline.FitGeometric(array, array2, array3, nOutputPoints, out var xs, out var ys, out var zs);
			for (int j = 0; j <= xs.Length - 1; j++)
			{
				CalculatedPoints.Add(new Pnt3D(xs[j], ys[j], zs[j]));
			}
		}
		catch (Exception mSException)
		{
			string text = "ControlPoints: " + ControlPoints.Count + " - dt: " + dt;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public static double BezeirBlend(int n, int i, double t)
	{
		try
		{
			double num = 0.0;
			Math.Pow(t, i);
			Math.Pow(1.0 - t, n - i);
			return Factorial(n) / (Factorial(i) * Factorial(n - i)) * Math.Pow(t, i) * Math.Pow(1.0 - t, n - i);
		}
		catch (Exception mSException)
		{
			string text = "n: " + n + " - i: " + i + " - t: " + t;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public static void KnotBSpline(int PointNumber, int Order, List<int> KnotVector)
	{
		try
		{
			int num = PointNumber + Order;
			int num2 = PointNumber + 1;
			KnotVector.Clear();
			KnotVector.Add(0);
			for (int i = 1; i <= num - 1; i++)
			{
				if (i <= Order - 1 || i >= num2)
				{
					KnotVector.Add(KnotVector[i - 1]);
				}
				else
				{
					KnotVector.Add(KnotVector[i - 1] + 1);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "PointNumber: " + PointNumber + " - Order: " + Order + " - KnotVector: " + KnotVector.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public static void BasisBSpline(int Order, double Parameter, int PointNumber, List<int> KnotVector, List<double> BasisFunctions)
	{
		List<double> list = new List<double>();
		BasisFunctions.Clear();
		int num = PointNumber + Order;
		for (int i = 0; i <= num - 2; i++)
		{
			if (Parameter < (double)KnotVector[i] || !(Parameter < (double)KnotVector[i + 1]))
			{
				list.Add(0.0);
			}
			else
			{
				list.Add(1.0);
			}
		}
		for (int j = 2; j <= Order; j++)
		{
			for (int i = 0; i <= num - j - 1; i++)
			{
				double num2 = ((list[i] != 0.0) ? ((Parameter - (double)KnotVector[i]) * list[i] / (double)(KnotVector[i + j - 1] - KnotVector[i])) : 0.0);
				double num3 = ((list[i + 1] != 0.0) ? (((double)KnotVector[i + j] - Parameter) * list[i + 1] / (double)(KnotVector[i + j] - KnotVector[i + 1])) : 0.0);
				list[i] = num2 + num3;
			}
		}
		if (Parameter == (double)KnotVector[num - 1])
		{
			list[PointNumber - 1] = 1.0;
		}
		for (int i = 0; i <= PointNumber - 1; i++)
		{
			BasisFunctions.Add(list[i]);
		}
	}

	public static void BasisRegionalBSpline(int Order, double Parameter, int PointNumber, List<int> KnotVector, List<double> Weigth, List<double> BasisFunctions)
	{
		try
		{
			List<double> list = new List<double>();
			int num = PointNumber + Order;
			for (int i = 0; i <= num - 2; i++)
			{
				if (Parameter < (double)KnotVector[i] || !(Parameter < (double)KnotVector[i + 1]))
				{
					list.Add(0.0);
				}
				else
				{
					list.Add(1.0);
				}
			}
			for (int j = 2; j <= Order; j++)
			{
				for (int i = 0; i <= num - j - 1; i++)
				{
					double num2 = ((list[i] != 0.0) ? ((Parameter - (double)KnotVector[i]) * list[i] / (double)(KnotVector[i + j - 1] - KnotVector[i])) : 0.0);
					double num3 = ((list[i + 1] != 0.0) ? (((double)KnotVector[i + j] - Parameter) * list[i + 1] / (double)(KnotVector[i + j] - KnotVector[i + 1])) : 0.0);
					list[i] = num2 + num3;
				}
			}
			if (Parameter == (double)KnotVector[num - 1])
			{
				list[PointNumber - 1] = 1.0;
			}
			double num4 = 0.0;
			for (int i = 0; i <= PointNumber - 1; i++)
			{
				num4 += list[i] * Weigth[i];
			}
			for (int i = 0; i <= PointNumber - 1; i++)
			{
				if (num4 == 0.0)
				{
					BasisFunctions[i] = 0.0;
				}
				else
				{
					BasisFunctions[i] = list[i] * Weigth[i] / num4;
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Order: " + Order + " - Parameter: " + Parameter + " - PointNumber: " + PointNumber;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public static double SumRegionalBasic(int UCount, int WCount, List<double> NBasis, List<double> MBasis, List<double> Weigth)
	{
		double num = 0.0;
		for (int i = 0; i <= UCount - 1; i++)
		{
			if (NBasis[i] == 0.0)
			{
				continue;
			}
			for (int j = 0; j <= WCount - 1; j++)
			{
				if (MBasis[j] != 0.0)
				{
					num += Weigth[j] * NBasis[i] * MBasis[j];
				}
			}
		}
		return num;
	}

	public static double Factorial(int Value)
	{
		try
		{
			int num = 1;
			for (int i = 1; i <= Value; i++)
			{
				num *= i;
			}
			return num;
		}
		catch (Exception mSException)
		{
			string text = "Value: " + Value;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

	public void EntityToTriangleIndex(eEntities refEnt, ref List<Pnt3D> Vertices, ref List<TriangleIndex> TriIndex)
	{
		if (!(refEnt.GetType() == typeof(eSurface)))
		{
			return;
		}
		Vertices.Clear();
		TriIndex.Clear();
		if (((eSurface)refEnt).Triangles != null)
		{
			int num = 0;
			for (int i = 0; i <= ((eSurface)refEnt).Triangles.Count - 1; i++)
			{
				TriangleIndex triangleIndex = new TriangleIndex();
				Vertices.Add(new Pnt3D(((eSurface)refEnt).Triangles[i].FirstPoint));
				triangleIndex.V1 = num;
				num++;
				Vertices.Add(new Pnt3D(((eSurface)refEnt).Triangles[i].FirstPoint));
				triangleIndex.V2 = num;
				num++;
				Vertices.Add(new Pnt3D(((eSurface)refEnt).Triangles[i].FirstPoint));
				triangleIndex.V3 = num;
				TriIndex.Add(triangleIndex);
			}
		}
	}

	public void TriangleAtPointByLineRef(Pnt3D BasePoint, Pnt3D RefPoint, double TrianglePointAngle, double TriangleLength, WorkPlane Plane, bool Reverse, bool FromBaseLine, ref List<Pnt3D> TriangleVertice)
	{
		try
		{
			Pnt3D FirstPoint = new Pnt3D();
			Pnt3D SecondPoint = new Pnt3D();
			Pnt3D ThirdPoint = new Pnt3D();
			TriangleAtPointByLineRef(BasePoint, RefPoint, TrianglePointAngle, TriangleLength, Plane, Reverse, FromBaseLine, ref FirstPoint, ref SecondPoint, ref ThirdPoint);
			TriangleVertice.Clear();
			TriangleVertice.Add(FirstPoint);
			TriangleVertice.Add(SecondPoint);
			TriangleVertice.Add(ThirdPoint);
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - RefPoint: " + RefPoint.ToString() + " - TrianglePointAngle: " + TrianglePointAngle + " - TriangleLength: " + TriangleLength + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void TriangleAtPointByLineRef(Pnt3D BasePoint, Pnt3D RefPoint, double TrianglePointAngle, double TriangleLength, WorkPlane Plane, bool Reverse, bool FromBaseLine, ref Pnt3D FirstPoint, ref Pnt3D SecondPoint, ref Pnt3D ThirdPoint)
	{
		try
		{
			Pnt3D BasePnt = new Pnt3D();
			Pnt3D EndPnt = new Pnt3D();
			double num = 0.0;
			double num2 = 0.0;
			Pnt3D pnt3D = new Pnt3D(BasePoint);
			if (Reverse)
			{
				num2 = 180.0;
			}
			num = PointAngle(RefPoint, BasePoint);
			if (FromBaseLine)
			{
				num = PointAngle(BasePoint, RefPoint);
				pnt3D = new Pnt3D(RefPoint);
			}
			LineWithLengthAndAngle(pnt3D, TriangleLength, num + TrianglePointAngle + num2, Plane, ref BasePnt, ref EndPnt);
			FirstPoint = new Pnt3D(pnt3D);
			SecondPoint = new Pnt3D(EndPnt);
			BasePnt = new Pnt3D();
			EndPnt = new Pnt3D();
			LineWithLengthAndAngle(pnt3D, TriangleLength, num - TrianglePointAngle + num2, Plane, ref BasePnt, ref EndPnt);
			ThirdPoint = new Pnt3D(EndPnt);
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - RefPoint: " + RefPoint.ToString() + " - TrianglePointAngle: " + TrianglePointAngle + " - TriangleLength: " + TriangleLength + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void QuadToTriangle(Quad3D Quad, ref Triangle3D FirstTriangle, ref Triangle3D SecondTriangle)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			num = Length3D(Quad.FirstPoint, Quad.ThirdPoint);
			num2 = Length3D(Quad.SecondPoint, Quad.FourthPoint);
			if (!(num > num2))
			{
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.SecondPoint);
				FirstTriangle.FirstPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.ThirdPoint);
				FirstTriangle.SecondPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FourthPoint);
				FirstTriangle.ThirdPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.SecondPoint);
				SecondTriangle.FirstPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FourthPoint);
				SecondTriangle.SecondPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FirstPoint);
				SecondTriangle.ThirdPoint = new Pnt3D(pnt3D);
			}
			else
			{
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FirstPoint);
				FirstTriangle.FirstPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.SecondPoint);
				FirstTriangle.SecondPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.ThirdPoint);
				FirstTriangle.ThirdPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FirstPoint);
				SecondTriangle.FirstPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.ThirdPoint);
				SecondTriangle.SecondPoint = new Pnt3D(pnt3D);
				pnt3D = new Pnt3D();
				pnt3D = new Pnt3D(Quad.FourthPoint);
				SecondTriangle.ThirdPoint = new Pnt3D(pnt3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "Quad: " + Quad.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
