	public double TriangleArea(Triangle3D Triangle)
	{
		try
		{
			double num = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			Pnt3D pnt3D3 = new Pnt3D();
			pnt3D.X = Triangle.SecondPoint.X - Triangle.FirstPoint.X;
			pnt3D.Y = Triangle.SecondPoint.Y - Triangle.FirstPoint.Y;
			pnt3D.Z = Triangle.SecondPoint.Z - Triangle.FirstPoint.Z;
			pnt3D2.X = Triangle.ThirdPoint.X - Triangle.FirstPoint.X;
			pnt3D2.Y = Triangle.ThirdPoint.Y - Triangle.FirstPoint.Y;
			pnt3D2.Z = Triangle.ThirdPoint.Z - Triangle.FirstPoint.Z;
			pnt3D3.X = pnt3D.Y * pnt3D2.Z - pnt3D.Z * pnt3D2.Y;
			pnt3D3.Y = pnt3D.Z * pnt3D2.X - pnt3D.X * pnt3D2.Z;
			pnt3D3.Z = pnt3D.X * pnt3D2.Y - pnt3D.Y * pnt3D2.X;
			return 0.5 * Math.Sqrt(pnt3D3.X * pnt3D3.X + pnt3D3.Y * pnt3D3.Y + pnt3D3.Z * pnt3D3.Z);
		}
		catch (Exception mSException)
		{
			string text = "Triangle: " + Triangle.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

