	public void DirectionArrowToVertices(DirectionArrow arrow, WorkPlane Plane, double ArrowAngle, ref List<Pnt3D> Vertices)
	{
		try
		{
			Pnt3D EndPnt = new Pnt3D();
			Pnt3D EndPnt2 = new Pnt3D();
			double num = 0.0;
			if (arrow.Reverse)
			{
				num = 180.0;
			}
			Vertices.Clear();
			LineWithLengthAndAngle(arrow.Point, arrow.Length, arrow.Angle + 180.0 + num - ArrowAngle, Plane, ref EndPnt);
			LineWithLengthAndAngle(arrow.Point, arrow.Length, arrow.Angle + 180.0 + num + ArrowAngle, Plane, ref EndPnt2);
			Vertices.Add(EndPnt);
			Vertices.Add(arrow.Point);
			Vertices.Add(EndPnt2);
		}
		catch (Exception mSException)
		{
			string text = "arrow: " + arrow.ToString() + " | arrow: " + arrow.ToString();
