	public Pnt3D TriangleNormal(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D ThirdPoint)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			double num = SecondPoint.X - FirstPoint.X;
			double num2 = SecondPoint.Y - FirstPoint.Y;
			double num3 = SecondPoint.Z - FirstPoint.Z;
			double num4 = ThirdPoint.X - SecondPoint.X;
			double num5 = ThirdPoint.Y - SecondPoint.Y;
			double num6 = ThirdPoint.Z - SecondPoint.Z;
			double x = num2 * num6 - num3 * num5;
			double y = num3 * num4 - num * num6;
			double z = num * num5 - num2 * num4;
			pnt3D.X = x;
			pnt3D.Y = y;
			pnt3D.Z = z;
			return pnt3D;
		}
		catch (Exception mSException)
		{
			string text = "FirstPoint: " + FirstPoint.ToString() + " - SecondPoint: " + SecondPoint.ToString() + " - ThirdPoint: " + ThirdPoint.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return new Pnt3D();
		}
	}

