	public double ZInTriangle(Pnt3D Point1, Pnt3D Point2, Pnt3D Point3, ref Pnt3D RefPoint)
	{
		try
		{
			double num = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			double num2 = 0.0;
			pnt3D = TriangleNormal(Point1, Point2, Point3);
			if (pnt3D.Z != 0.0)
			{
				num2 = -1.0 * (pnt3D.X * Point1.X + pnt3D.Y * Point1.Y + pnt3D.Z * Point1.Z);
				num = (num2 + pnt3D.X * RefPoint.X + pnt3D.Y * RefPoint.Y) * -1.0 / pnt3D.Z;
				RefPoint.Z = num;
				return num;
			}
			RefPoint.Z = (Point1.Z + Point2.Z + Point3.Z) / 2.0;
			return RefPoint.Z;
		}
		catch (Exception mSException)
		{
			string text = "Point1: " + Point1.ToString() + " - Point2: " + Point2.ToString() + " - Point3: " + Point3.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0.0;
		}
	}

