	public void Helix(Pnt3D CenterPoint, double SpiralCount, double BottomRadius, double TopRadius, double Height, EntityResolution EntResolution, WorkPlane Plane, ref List<Pnt3D> CalcPoints)
	{
		double num = 0.0;
		double num2 = 0.0;
		Pnt3D pnt3D = new Pnt3D();
		int num3 = 0;
		CalcPoints.Clear();
		if (EntResolution.dt <= 0.0 || TopRadius <= 0.0 || BottomRadius <= 0.0 || SpiralCount <= 0.0)
		{
			return;
		}
		num = (TopRadius - BottomRadius) / Convert.ToDouble(SpiralCount);
		num2 = Height / (Math.PI * 2.0 * SpiralCount / EntResolution.dt);
		for (double num4 = 0.0; num4 <= Math.PI * 2.0 * SpiralCount; num4 += EntResolution.dt)
		{
			pnt3D = new Pnt3D();
			if (WorkPlane.isPlaneXY(Plane))
			{
				pnt3D.X = CenterPoint.X + (BottomRadius + num * num4 / (Math.PI * 2.0)) * Math.Cos(num4);
				pnt3D.Y = CenterPoint.Y + (BottomRadius + num * num4 / (Math.PI * 2.0)) * Math.Sin(num4);
				pnt3D.Z = CenterPoint.Z + (double)num3 * num2;
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				pnt3D.X = CenterPoint.X + (BottomRadius + num * num4 / (Math.PI * 2.0)) * Math.Cos(num4);
				pnt3D.Y = CenterPoint.Y + (double)num3 * num2;
				pnt3D.Z = CenterPoint.Z + (BottomRadius + num * num4 / (Math.PI * 2.0)) * Math.Sin(num4);
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				pnt3D.X = CenterPoint.X + (double)num3 * num2;
				pnt3D.Y = CenterPoint.Y + (BottomRadius + num * num4 / (Math.PI * 2.0)) * Math.Cos(num4);
				pnt3D.Z = CenterPoint.Z + (BottomRadius + num * num4 / (Math.PI * 2.0)) * Math.Sin(num4);
			}
			CalcPoints.Add(pnt3D);
			num3++;
		}
	}

