	public void DimensionAlignedWith2Point(Pnt3D BasePoint, Pnt3D RefPoint, double TrianglePointAngle, double TriangleLength, WorkPlane Plane, bool ReverseAngle, ref geoTriangle BasePointArrow, ref geoTriangle RefPointArrow, ref List<Pnt3D> FirstArrorVertices, ref List<Pnt3D> SecondArrorVertices)
	{
		try
		{
			double num = 0.0;
			if (ReverseAngle)
			{
				num = 180.0;
			}
			TriangleAtPointByLineRef(BasePoint, RefPoint, TrianglePointAngle + num, TriangleLength, Plane, Reverse: false, FromBaseLine: false, ref BasePointArrow.FirstPoint, ref BasePointArrow.SecondPoint, ref BasePointArrow.ThirdPoint);
			TriangleAtPointByLineRef(RefPoint, BasePoint, TrianglePointAngle + num, TriangleLength, Plane, Reverse: false, FromBaseLine: false, ref RefPointArrow.FirstPoint, ref RefPointArrow.SecondPoint, ref RefPointArrow.ThirdPoint);
			FirstArrorVertices.Clear();
			FirstArrorVertices.Add(new Pnt3D(BasePointArrow.SecondPoint));
			FirstArrorVertices.Add(new Pnt3D(BasePointArrow.FirstPoint));
			FirstArrorVertices.Add(new Pnt3D(BasePointArrow.ThirdPoint));
			SecondArrorVertices.Clear();
			SecondArrorVertices.Add(new Pnt3D(RefPointArrow.SecondPoint));
			SecondArrorVertices.Add(new Pnt3D(RefPointArrow.FirstPoint));
			SecondArrorVertices.Add(new Pnt3D(RefPointArrow.ThirdPoint));
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - RefPoint: " + RefPoint.ToString() + " - TrianglePointAngle: " + TrianglePointAngle + " - TriangleLength: " + TriangleLength + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void UShape3D(Pnt3D CenterPoint, double Width, double Height, double Depth, OrientationAngle Rotation, WorkPlane Plane, ref List<List<Pnt3D>> Vertices, ref List<Triangle3D> Triangles)
	{
		string text = "- Method = UShape3D";
		try
		{
			if (WorkPlane.isPlaneXY(Plane))
			{
				Pnt3D EndPnt = new Pnt3D();
				Pnt3D EndPnt2 = new Pnt3D();
				Pnt3D pnt3D = new Pnt3D();
				Pnt3D pnt3D2 = new Pnt3D();
