				List<Pnt3D> CopiedPnt = new List<Pnt3D>();
				Vertices = new List<List<Pnt3D>>();
				Triangles = new List<Triangle3D>();
				LineWithLengthAndAngle(CenterPoint, Width / 2.0, 0.0, Plane, ref EndPnt2);
				LineWithLengthAndAngle(CenterPoint, Width / 2.0, 180.0, Plane, ref EndPnt);
				pnt3D = new Pnt3D(EndPnt);
				pnt3D.Y += Height;
				pnt3D2 = new Pnt3D(EndPnt2);
				pnt3D2.Y += Height;
				list.Add(new Pnt3D(pnt3D));
				list.Add(new Pnt3D(EndPnt));
				list.Add(new Pnt3D(EndPnt2));
				list.Add(new Pnt3D(pnt3D2));
				Vertices.Add(list);
				Pnt3D.Copy(list, ref CopiedPnt);
				Move(new Pnt3D(), new Pnt3D(0.0, 0.0, Depth), ref CopiedPnt);
				Vertices.Add(CopiedPnt);
				for (int i = 1; i <= list.Count - 1; i++)
				{
					List<Pnt3D> list2 = new List<Pnt3D>();
					list2.Add(new Pnt3D(list[i - 1]));
					list2.Add(new Pnt3D(list[i]));
					list2.Add(new Pnt3D(CopiedPnt[i]));
					list2.Add(new Pnt3D(CopiedPnt[i - 1]));
					list2.Add(new Pnt3D(list[i - 1]));
					Vertices.Add(list2);
					Quad3D quad = new Quad3D(new Pnt3D(list[i - 1]), new Pnt3D(list[i]), new Pnt3D(CopiedPnt[i]), new Pnt3D(CopiedPnt[i - 1]));
					Triangle3D FirstTriangle = new Triangle3D();
					Triangle3D SecondTriangle = new Triangle3D();
					QuadToTriangle(quad, ref FirstTriangle, ref SecondTriangle);
					Triangles.Add(FirstTriangle);
					Triangles.Add(SecondTriangle);
				}
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				Pnt3D EndPnt3 = new Pnt3D();
				Pnt3D EndPnt4 = new Pnt3D();
				Pnt3D pnt3D3 = new Pnt3D();
				Pnt3D pnt3D4 = new Pnt3D();
