				Triangles = new List<Triangle3D>();
				LineWithLengthAndAngle(CenterPoint, Width / 2.0, 0.0, Plane, ref EndPnt4);
				LineWithLengthAndAngle(CenterPoint, Width / 2.0, 180.0, Plane, ref EndPnt3);
				pnt3D3 = new Pnt3D(EndPnt3);
				pnt3D3.Z += Height;
				pnt3D4 = new Pnt3D(EndPnt4);
				pnt3D4.Z += Height;
				list3.Add(new Pnt3D(pnt3D3));
				list3.Add(new Pnt3D(EndPnt3));
				list3.Add(new Pnt3D(EndPnt4));
				list3.Add(new Pnt3D(pnt3D4));
				Vertices.Add(list3);
				Pnt3D.Copy(list3, ref CopiedPnt2);
				Move(new Pnt3D(), new Pnt3D(0.0, Depth, 0.0), ref CopiedPnt2);
				Vertices.Add(CopiedPnt2);
				for (int j = 1; j <= list3.Count - 1; j++)
				{
					List<Pnt3D> list4 = new List<Pnt3D>();
					list4.Add(new Pnt3D(list3[j - 1]));
					list4.Add(new Pnt3D(list3[j]));
					list4.Add(new Pnt3D(CopiedPnt2[j]));
					list4.Add(new Pnt3D(CopiedPnt2[j - 1]));
					list4.Add(new Pnt3D(list3[j - 1]));
					Vertices.Add(list4);
					Quad3D quad2 = new Quad3D(new Pnt3D(list3[j - 1]), new Pnt3D(list3[j]), new Pnt3D(CopiedPnt2[j]), new Pnt3D(CopiedPnt2[j - 1]));
					Triangle3D FirstTriangle2 = new Triangle3D();
					Triangle3D SecondTriangle2 = new Triangle3D();
					QuadToTriangle(quad2, ref FirstTriangle2, ref SecondTriangle2);
					Triangles.Add(FirstTriangle2);
					Triangles.Add(SecondTriangle2);
				}
			}
			RotateByOrientationAngle(CenterPoint, Rotation, ref Vertices);
		}
		catch (Exception mSException)
		{
			string text2 = "CenterPoint: " + CenterPoint.ToString() + " - Width: " + Width + " - Height: " + Height + " - Depth: " + Depth + " - Rotation: " + Rotation.ToString();
			buLog.addLog(text2, "Not Ok", MethodBase.GetCurrentMethod().Name + text);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text2);
