	public void Polyline3D(List<Pnt3D> Vertice, double Length, double VectorAngle, Vec3D Vec, EntityResolution EntResolution, ref List<List<Pnt3D>> Vertices, ref List<Triangle3D> Triangles, ref List<eEntities> Entities)
	{
		try
		{
			Pnt3D pnt = new Pnt3D();
			Pnt3D pnt2 = new Pnt3D();
			List<Pnt3D> Points = new List<Pnt3D>();
			List<Pnt3D> Points2 = new List<Pnt3D>();
			Quad3D quad3D = new Quad3D();
			Triangle3D triangle3D = new Triangle3D();
			Triangle3D triangle3D2 = new Triangle3D();
			Pnt3D MinPoint = new Pnt3D();
			Pnt3D MaxPoint = new Pnt3D();
			BoxSizeCalculate(Vertice, ref MinPoint, ref MaxPoint);
			Triangles.Clear();
			Vertices.Clear();
			Entities.Clear();
			if (Vec3D.isVectorXAxis(Vec))
			{
				WorkPlane plane = new WorkPlane(planeType.YZ, 1);
				for (int i = 0; i <= Vertice.Count - 1; i++)
				{
					Points.Add(new Pnt3D(Vertice[i]));
					Points2.Add(new Pnt3D(Vertice[i].X + Length, Vertice[i].Y, Vertice[i].Z));
				}
				Rotate(MinPoint, VectorAngle, plane, ref Points);
				Rotate(MinPoint, VectorAngle, plane, ref Points2);
				Vertices.Add(Points);
				Vertices.Add(Points2);
				Entities.Add(new ePolyline(Points));
				Entities.Add(new ePolyline(Points2));
				for (int j = 0; j <= Points.Count - 1; j++)
				{
					List<Pnt3D> list = new List<Pnt3D>();
					list.Add(new Pnt3D(Points[j]));
					list.Add(new Pnt3D(Points2[j]));
					Vertices.Add(list);
					eLine item = new eLine(new Pnt3D(Points[j]), new Pnt3D(Points2[j]));
					Entities.Add(item);
					if (j > 0)
					{
						triangle3D = new Triangle3D();
						triangle3D2 = new Triangle3D();
						quad3D = new Quad3D(Points[j - 1], Points2[j - 1], Points2[j], Points[j]);
						QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
						Triangles.Add(triangle3D);
						Triangles.Add(triangle3D2);
					}
				}
			}
			if (Vec3D.isVectorYAxis(Vec))
			{
				WorkPlane plane2 = new WorkPlane(planeType.XZ, 1);
				for (int k = 0; k <= Vertice.Count - 1; k++)
				{
					Points.Add(new Pnt3D(Vertice[k]));
					Points2.Add(new Pnt3D(Vertice[k].X, Vertice[k].Y + Length, Vertice[k].Z));
				}
				Rotate(MinPoint, VectorAngle, plane2, ref Points);
				Rotate(MinPoint, VectorAngle, plane2, ref Points2);
				Vertices.Add(Points);
				Vertices.Add(Points2);
				Entities.Add(new ePolyline(Points));
				Entities.Add(new ePolyline(Points2));
				for (int l = 0; l <= Points.Count - 1; l++)
				{
					List<Pnt3D> list2 = new List<Pnt3D>();
					list2.Add(new Pnt3D(Points[l]));
					list2.Add(new Pnt3D(Points2[l]));
					Vertices.Add(list2);
					eLine item2 = new eLine(new Pnt3D(Points[l]), new Pnt3D(Points2[l]));
					Entities.Add(item2);
					if (l > 0)
					{
						triangle3D = new Triangle3D();
						triangle3D2 = new Triangle3D();
						quad3D = new Quad3D(Points[l - 1], Points2[l - 1], Points2[l], Points[l]);
						QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
						Triangles.Add(triangle3D);
						Triangles.Add(triangle3D2);
					}
				}
			}
			if (Vec3D.isVectorZAxis(Vec))
			{
				WorkPlane plane3 = new WorkPlane(planeType.XY, 1);
				for (int m = 0; m <= Vertice.Count - 1; m++)
				{
					Points.Add(new Pnt3D(Vertice[m]));
					Points2.Add(new Pnt3D(Vertice[m].X, Vertice[m].Y, Vertice[m].Z + Length));
				}
				Rotate(MinPoint, VectorAngle, plane3, ref Points);
				Rotate(MinPoint, VectorAngle, plane3, ref Points2);
				Vertices.Add(Points);
				Vertices.Add(Points2);
				Entities.Add(new ePolyline(Points));
				Entities.Add(new ePolyline(Points2));
				for (int n = 0; n <= Points.Count - 1; n++)
				{
					List<Pnt3D> list3 = new List<Pnt3D>();
					list3.Add(new Pnt3D(Points[n]));
					list3.Add(new Pnt3D(Points2[n]));
					Vertices.Add(list3);
					eLine item3 = new eLine(new Pnt3D(Points[n]), new Pnt3D(Points2[n]));
					Entities.Add(item3);
					if (n > 0)
					{
						triangle3D = new Triangle3D();
						triangle3D2 = new Triangle3D();
						quad3D = new Quad3D(Points[n - 1], Points2[n - 1], Points2[n], Points[n]);
						QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
						Triangles.Add(triangle3D);
						Triangles.Add(triangle3D2);
					}
				}
			}
			for (int num = 1; num <= Points.Count - 1; num++)
			{
				triangle3D = new Triangle3D();
				triangle3D.FirstPoint = new Pnt3D(pnt);
				triangle3D.SecondPoint = new Pnt3D(Points[num - 1]);
				triangle3D.ThirdPoint = new Pnt3D(Points[num]);
				Triangles.Add(triangle3D);
			}
			for (int num2 = 1; num2 <= Points2.Count - 1; num2++)
			{
				triangle3D = new Triangle3D();
				triangle3D.FirstPoint = new Pnt3D(pnt2);
				triangle3D.SecondPoint = new Pnt3D(Points2[num2 - 1]);
				triangle3D.ThirdPoint = new Pnt3D(Points2[num2]);
				Triangles.Add(triangle3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "Length: " + Length + " - VectorAngle: " + VectorAngle + " - Vec: " + Vec.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

