	public void Cylinder3D(Pnt3D BasePoint, double Length, double Radius, double Angle, Vec3D Vec, EntityResolution EntResolution, ref List<List<Pnt3D>> Vertices, ref List<Triangle3D> Triangles, ref List<Quad3D> Quads, ref List<eEntities> Entities)
	{
