	public void Cone3D(Pnt3D BasePoint, double Length, double BottomRadius, double TopRadius, double Angle, Vec3D Vec, EntityResolution EntResolution, ref List<List<Pnt3D>> Vertices, ref List<Triangle3D> Triangles, ref List<Quad3D> Quads, ref List<eEntities> Entities)
	{
		try
		{
			Pnt3D Points = new Pnt3D();
			Pnt3D Points2 = new Pnt3D();
			List<Pnt3D> Vertices2 = new List<Pnt3D>();
			List<Pnt3D> Vertices3 = new List<Pnt3D>();
			Quad3D quad3D = new Quad3D();
			Triangle3D triangle3D = new Triangle3D();
			Triangle3D triangle3D2 = new Triangle3D();
			Triangles.Clear();
			Quads.Clear();
			Vertices.Clear();
			Entities.Clear();
			EntResolution.ResolutionTypes = EntityResolutionType.ByNumber;
			if (Vec3D.isVectorXAxis(Vec))
			{
				WorkPlane plane = new WorkPlane(planeType.YZ, 1);
				CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z), BottomRadius, plane, EntResolution, ref Vertices2);
				CircleWithCenter(new Pnt3D(BasePoint.X + Length, BasePoint.Y, BasePoint.Z), TopRadius, plane, EntResolution, ref Vertices3);
				Points = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z);
				Points2 = new Pnt3D(BasePoint.X + Length, BasePoint.Y, BasePoint.Z);
				Rotate(BasePoint, Angle, plane, ref Vertices2);
				Rotate(BasePoint, Angle, plane, ref Vertices3);
				Rotate(BasePoint, Angle, plane, ref Points);
				Rotate(BasePoint, Angle, plane, ref Points2);
				Vertices.Add(Vertices2);
				Vertices.Add(Vertices3);
				Entities.Add(new eCircle(new Pnt3D(BasePoint.X - Length / 2.0, BasePoint.Y, BasePoint.Z), BottomRadius, plane));
				Entities.Add(new eCircle(new Pnt3D(BasePoint.X + Length / 2.0, BasePoint.Y, BasePoint.Z), TopRadius, plane));
				for (int i = 0; i <= Vertices2.Count - 1; i++)
				{
					List<Pnt3D> list = new List<Pnt3D>();
					list.Add(new Pnt3D(Vertices2[i]));
					list.Add(new Pnt3D(Vertices3[i]));
					Vertices.Add(list);
					eLine item = new eLine(new Pnt3D(Vertices2[i]), new Pnt3D(Vertices3[i]));
					Entities.Add(item);
					if (i > 0)
					{
						triangle3D = new Triangle3D();
						triangle3D2 = new Triangle3D();
						quad3D = new Quad3D(Vertices2[i - 1], Vertices3[i - 1], Vertices3[i], Vertices2[i]);
						Quads.Add(quad3D);
						QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
						Triangles.Add(triangle3D);
						Triangles.Add(triangle3D2);
					}
				}
			}
			if (Vec3D.isVectorYAxis(Vec))
			{
				WorkPlane plane2 = new WorkPlane(planeType.XZ, 1);
				CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z), BottomRadius, plane2, EntResolution, ref Vertices2);
				CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y + Length, BasePoint.Z), TopRadius, plane2, EntResolution, ref Vertices3);
				Points = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z);
				Points2 = new Pnt3D(BasePoint.X, BasePoint.Y + Length, BasePoint.Z);
