				Rotate(BasePoint, Angle, plane2, ref Vertices3);
				Rotate(BasePoint, Angle, plane2, ref Points);
				Rotate(BasePoint, Angle, plane2, ref Points2);
				Vertices.Add(Vertices2);
				Vertices.Add(Vertices3);
				Entities.Add(new eCircle(new Pnt3D(BasePoint.X - Length / 2.0, BasePoint.Y, BasePoint.Z), BottomRadius, plane2));
				Entities.Add(new eCircle(new Pnt3D(BasePoint.X + Length / 2.0, BasePoint.Y, BasePoint.Z), TopRadius, plane2));
				for (int j = 0; j <= Vertices2.Count - 1; j++)
				{
					List<Pnt3D> list2 = new List<Pnt3D>();
					list2.Add(new Pnt3D(Vertices2[j]));
					list2.Add(new Pnt3D(Vertices3[j]));
					Vertices.Add(list2);
					eLine item2 = new eLine(new Pnt3D(Vertices2[j]), new Pnt3D(Vertices3[j]));
