						Quads.Add(quad3D);
						QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
						Triangles.Add(triangle3D);
						Triangles.Add(triangle3D2);
					}
				}
			}
			if (Vec3D.isVectorZAxis(Vec))
			{
				WorkPlane plane3 = new WorkPlane(planeType.XY, 1);
				CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z), BottomRadius, plane3, EntResolution, ref Vertices2);
				CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Length), TopRadius, plane3, EntResolution, ref Vertices3);
				Points = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z);
				Points2 = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Length);
				Rotate(BasePoint, Angle, plane3, ref Vertices2);
				Rotate(BasePoint, Angle, plane3, ref Vertices3);
				Rotate(BasePoint, Angle, plane3, ref Points);
				Rotate(BasePoint, Angle, plane3, ref Points2);
				Vertices.Add(Vertices2);
				Vertices.Add(Vertices3);
				Entities.Add(new eCircle(new Pnt3D(BasePoint.X - Length / 2.0, BasePoint.Y, BasePoint.Z), BottomRadius, plane3));
				Entities.Add(new eCircle(new Pnt3D(BasePoint.X + Length / 2.0, BasePoint.Y, BasePoint.Z), TopRadius, plane3));
				for (int k = 0; k <= Vertices2.Count - 1; k++)
				{
					List<Pnt3D> list3 = new List<Pnt3D>();
					list3.Add(new Pnt3D(Vertices2[k]));
					list3.Add(new Pnt3D(Vertices3[k]));
					Vertices.Add(list3);
					eLine item3 = new eLine(new Pnt3D(Vertices2[k]), new Pnt3D(Vertices3[k]));
					Entities.Add(item3);
					if (k > 0)
					{
