						triangle3D2 = new Triangle3D();
						quad3D = new Quad3D(Vertices2[k - 1], Vertices3[k - 1], Vertices3[k], Vertices2[k]);
						Quads.Add(quad3D);
						QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
						Triangles.Add(triangle3D);
						Triangles.Add(triangle3D2);
					}
				}
			}
			for (int l = 1; l <= Vertices2.Count - 1; l++)
			{
				triangle3D = new Triangle3D();
				triangle3D.FirstPoint = new Pnt3D(Points);
				triangle3D.SecondPoint = new Pnt3D(Vertices2[l - 1]);
				triangle3D.ThirdPoint = new Pnt3D(Vertices2[l]);
				Triangles.Add(triangle3D);
			}
			for (int m = 1; m <= Vertices3.Count - 1; m++)
			{
