				triangle3D.SecondPoint = new Pnt3D(Vertices3[m - 1]);
				triangle3D.ThirdPoint = new Pnt3D(Vertices3[m]);
				Triangles.Add(triangle3D);
			}
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - Length: " + Length + " - Radius: " + BottomRadius + " - Angle: " + Angle + " - Vec: " + Vec.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
