	public void CylinderWithAngle3D(Pnt3D BasePoint, double Length, double Radius, double StartAngle, double EndAngle, double Angle, Vec3D Vec, EntityResolution EntResolution, ref List<Triangle3D> Triangles)
	{
		try
		{
			Pnt3D Points = new Pnt3D();
			Pnt3D Points2 = new Pnt3D();
			List<Pnt3D> Vertices = new List<Pnt3D>();
			List<Pnt3D> Vertices2 = new List<Pnt3D>();
			Quad3D quad3D = new Quad3D();
			Triangle3D triangle3D = new Triangle3D();
			Triangle3D triangle3D2 = new Triangle3D();
			if (Vec3D.isVectorXAxis(Vec))
			{
				WorkPlane plane = new WorkPlane(planeType.YZ, 1);
				ArcWithCenter(new Pnt3D(BasePoint.X - Length / 2.0, BasePoint.Y, BasePoint.Z), Radius, StartAngle, EndAngle, plane, EntResolution, ref Vertices);
				ArcWithCenter(new Pnt3D(BasePoint.X + Length / 2.0, BasePoint.Y, BasePoint.Z), Radius, StartAngle, EndAngle, plane, EntResolution, ref Vertices2);
				Points = new Pnt3D(BasePoint.X - Length / 2.0, BasePoint.Y, BasePoint.Z);
				Points2 = new Pnt3D(BasePoint.X + Length / 2.0, BasePoint.Y, BasePoint.Z);
				Rotate(BasePoint, Angle, plane, ref Vertices);
				Rotate(BasePoint, Angle, plane, ref Vertices2);
				Rotate(BasePoint, Angle, plane, ref Points);
				Rotate(BasePoint, Angle, plane, ref Points2);
				Triangles.Clear();
				for (int i = 1; i <= Vertices.Count - 1; i++)
				{
					triangle3D = new Triangle3D();
					triangle3D2 = new Triangle3D();
					quad3D = new Quad3D(Vertices[i - 1], Vertices2[i - 1], Vertices2[i], Vertices[i]);
					QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
					Triangles.Add(triangle3D);
					Triangles.Add(triangle3D2);
				}
			}
			if (Vec3D.isVectorYAxis(Vec))
			{
				WorkPlane plane2 = new WorkPlane(planeType.XZ, 1);
				CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y - Length / 2.0, BasePoint.Z), Radius, plane2, EntResolution, ref Vertices);
				CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y + Length / 2.0, BasePoint.Z), Radius, plane2, EntResolution, ref Vertices2);
				Points = new Pnt3D(BasePoint.X, BasePoint.Y - Length / 2.0, BasePoint.Z);
				Points2 = new Pnt3D(BasePoint.X, BasePoint.Y + Length / 2.0, BasePoint.Z);
				Rotate(BasePoint, Angle, plane2, ref Vertices);
				Rotate(BasePoint, Angle, plane2, ref Vertices2);
				Rotate(BasePoint, Angle, plane2, ref Points);
				Rotate(BasePoint, Angle, plane2, ref Points2);
				Triangles.Clear();
				for (int j = 1; j <= Vertices.Count - 1; j++)
				{
					triangle3D = new Triangle3D();
					triangle3D2 = new Triangle3D();
					quad3D = new Quad3D(Vertices[j - 1], Vertices2[j - 1], Vertices2[j], Vertices[j]);
					QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
					Triangles.Add(triangle3D);
					Triangles.Add(triangle3D2);
				}
			}
			if (Vec3D.isVectorZAxis(Vec))
			{
				WorkPlane plane3 = new WorkPlane(planeType.XY, 1);
				CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z), Radius, plane3, EntResolution, ref Vertices);
				CircleWithCenter(new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Length), Radius, plane3, EntResolution, ref Vertices2);
				Points = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z);
				Points2 = new Pnt3D(BasePoint.X, BasePoint.Y, BasePoint.Z + Length);
				Rotate(BasePoint, Angle, plane3, ref Vertices);
				Rotate(BasePoint, Angle, plane3, ref Vertices2);
				Rotate(BasePoint, Angle, plane3, ref Points);
				Rotate(BasePoint, Angle, plane3, ref Points2);
				Triangles.Clear();
				for (int k = 1; k <= Vertices.Count - 1; k++)
				{
					triangle3D = new Triangle3D();
					triangle3D2 = new Triangle3D();
					quad3D = new Quad3D(Vertices[k - 1], Vertices2[k - 1], Vertices2[k], Vertices[k]);
					QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
					Triangles.Add(triangle3D);
					Triangles.Add(triangle3D2);
				}
			}
			for (int l = 1; l <= Vertices.Count - 1; l++)
			{
				triangle3D = new Triangle3D();
				triangle3D.FirstPoint = new Pnt3D(Points);
				triangle3D.SecondPoint = new Pnt3D(Vertices[l - 1]);
				triangle3D.ThirdPoint = new Pnt3D(Vertices[l]);
				Triangles.Add(triangle3D);
			}
			for (int m = 1; m <= Vertices2.Count - 1; m++)
			{
				triangle3D = new Triangle3D();
				triangle3D.FirstPoint = new Pnt3D(Points2);
				triangle3D.SecondPoint = new Pnt3D(Vertices2[m - 1]);
				triangle3D.ThirdPoint = new Pnt3D(Vertices2[m]);
				Triangles.Add(triangle3D);
			}
			triangle3D = new Triangle3D();
			triangle3D.FirstPoint = new Pnt3D(Vertices[0]);
			triangle3D.SecondPoint = new Pnt3D(Vertices2[0]);
			triangle3D.ThirdPoint = new Pnt3D(Vertices2[Vertices2.Count - 1]);
			Triangles.Add(triangle3D);
			triangle3D = new Triangle3D();
			triangle3D.FirstPoint = new Pnt3D(Vertices2[Vertices2.Count - 1]);
			triangle3D.SecondPoint = new Pnt3D(Vertices[Vertices.Count - 1]);
			triangle3D.ThirdPoint = new Pnt3D(Vertices[0]);
			Triangles.Add(triangle3D);
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - Length: " + Length + " - Radius: " + Radius + " - StartAngle: " + StartAngle + " - EndAngle: " + EndAngle + " - Angle: " + Angle + " - Vec: " + Vec.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

