	public void ConeOpen3D(Pnt3D BasePoint, double Length, double BottomRadius, double TopRadius, double Angle, WorkPlane Plane, EntityResolution EntResolution, ref List<Triangle3D> Triangles)
	{
		try
		{
			double num = 1.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			Pnt3D BasePnt = new Pnt3D();
			Pnt3D EndPnt = new Pnt3D();
			List<Pnt3D> Vertices = new List<Pnt3D>();
			List<Pnt3D> CalcPoint = new List<Pnt3D>();
			Quad3D quad3D = new Quad3D();
			Triangle3D triangle3D = new Triangle3D();
			Triangle3D triangle3D2 = new Triangle3D();
			if (Plane.PlaneType == planeType.XY)
			{
				CircleWithCenter(BasePoint, BottomRadius, Plane, EntResolution, ref Vertices);
				num = TopRadius / BottomRadius;
				if (num <= 0.0)
				{
					num = 1.0;
				}
				Scale(BasePoint, 1.0, num, num, ScaleX: false, ScaleY: true, ScaleZ: true, Vertices, ref CalcPoint);
				Rotate(BasePoint, Angle, Plane, ref Vertices);
				Rotate(BasePoint, Angle, Plane, ref CalcPoint);
				LineWithLengthAndAngle(BasePoint, Length, Angle, Plane, ref BasePnt, ref EndPnt);
				num2 = EndPnt.X - BasePnt.X;
				num3 = EndPnt.Y - BasePnt.Y;
				num4 = EndPnt.Z - BasePnt.Z;
				for (int i = 0; i <= CalcPoint.Count - 1; i++)
				{
					BasePnt = new Pnt3D();
					BasePnt = AddOffsetToPoint(CalcPoint[i], num2, num3, num4);
					CalcPoint[i] = new Pnt3D(BasePnt);
				}
				Triangles.Clear();
				for (int j = 1; j <= Vertices.Count - 1; j++)
				{
					triangle3D = new Triangle3D();
					triangle3D2 = new Triangle3D();
					quad3D = new Quad3D(Vertices[j - 1], CalcPoint[j - 1], CalcPoint[j], Vertices[j]);
					QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
					Triangles.Add(triangle3D);
					Triangles.Add(triangle3D2);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - BottomRadius: " + BottomRadius + " - TopRadius: " + TopRadius + " - Length: " + Length + " - Angle: " + Angle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void ConeHollow3D(Pnt3D CenterPoint, double TopRadius, double BottomRadius, double Heigth, double Thickness, WorkPlane Plane, EntityResolution EntResolution, ref List<List<Pnt3D>> Vertices, ref List<Triangle3D> TriangleList)
	{
		try
		{
			List<Pnt3D> Vertices2 = new List<Pnt3D>();
			List<Pnt3D> Vertices3 = new List<Pnt3D>();
			List<Pnt3D> Vertices4 = new List<Pnt3D>();
			List<Pnt3D> Vertices5 = new List<Pnt3D>();
			List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
			Pnt3D center = new Pnt3D();
			TriangleList.Clear();
			if (Plane.PlaneType == planeType.XY)
			{
				center = AddOffsetToPoint(CenterPoint, 0.0, 0.0, Heigth);
			}
			if (Plane.PlaneType == planeType.XZ)
			{
				center = AddOffsetToPoint(CenterPoint, 0.0, Heigth, 0.0);
			}
			if (Plane.PlaneType == planeType.YZ)
			{
				center = AddOffsetToPoint(CenterPoint, Heigth, 0.0, 0.0);
			}
			if (!(TopRadius > BottomRadius))
			{
				CircleWithCenter(CenterPoint, BottomRadius, Plane, EntResolution, ref Vertices3);
				CircleWithCenter(center, TopRadius, Vertices3.Count - 1, Plane, ref Vertices2);
				CircleWithCenter(CenterPoint, BottomRadius - Thickness, Vertices3.Count - 1, Plane, ref Vertices5);
				CircleWithCenter(center, TopRadius - Thickness, Vertices3.Count - 1, Plane, ref Vertices4);
			}
			else
			{
				CircleWithCenter(center, TopRadius, Plane, EntResolution, ref Vertices2);
				CircleWithCenter(CenterPoint, BottomRadius, Vertices2.Count - 1, Plane, ref Vertices3);
				CircleWithCenter(center, TopRadius - Thickness, Vertices2.Count - 1, Plane, ref Vertices4);
				CircleWithCenter(CenterPoint, BottomRadius - Thickness, Vertices2.Count - 1, Plane, ref Vertices5);
			}
			SurfaceTriangles.Clear();
			SurfaceWithTwoVerticeList(Vertices2, Vertices4, ref SurfaceTriangles);
			for (int i = 0; i <= SurfaceTriangles.Count - 1; i++)
			{
				TriangleList.Add(new Triangle3D(SurfaceTriangles[i]));
			}
			SurfaceTriangles.Clear();
			SurfaceWithTwoVerticeList(Vertices3, Vertices5, ref SurfaceTriangles);
			for (int j = 0; j <= SurfaceTriangles.Count - 1; j++)
			{
				TriangleList.Add(new Triangle3D(SurfaceTriangles[j]));
			}
			SurfaceTriangles.Clear();
			SurfaceWithTwoVerticeList(Vertices2, Vertices3, ref SurfaceTriangles);
			for (int k = 0; k <= SurfaceTriangles.Count - 1; k++)
			{
				TriangleList.Add(new Triangle3D(SurfaceTriangles[k]));
			}
			SurfaceTriangles.Clear();
			SurfaceWithTwoVerticeList(Vertices4, Vertices5, ref SurfaceTriangles);
			for (int l = 0; l <= SurfaceTriangles.Count - 1; l++)
			{
				TriangleList.Add(new Triangle3D(SurfaceTriangles[l]));
			}
		}
		catch (Exception mSException)
		{
			string text = "CenterPoint: " + CenterPoint.ToString() + " - BottomRadius: " + BottomRadius + " - TopRadius: " + TopRadius + " - Heigth: " + Heigth + " - Thickness: " + Thickness + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

