	}

	public void Sphere3D(Pnt3D CenterPoint, double Radius, EntityResolution EntResolution, ref List<List<Pnt3D>> Vertices)
	{
		List<Triangle3D> TriangleList = new List<Triangle3D>();
		Sphere3D(CenterPoint, Radius, EntResolution, ref Vertices, ref TriangleList);
	}

	public void Sphere3D(Pnt3D CenterPoint, double Radius, EntityResolution EntResolution, ref List<List<Pnt3D>> Vertices, ref List<Triangle3D> TriangleList)
	{
		try
		{
			List<Pnt3D> Vertices2 = new List<Pnt3D>();
			List<Pnt3D> list = new List<Pnt3D>();
			List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
			List<Pnt3D>[] array = null;
			int num = 0;
			int num2 = 0;
			double num3 = 0.0;
			TriangleList.Clear();
			ArcWithCenter(CenterPoint, Radius, 0.0, 360.0, new WorkPlane(), EntResolution, ref Vertices2);
			for (int i = 0; i <= Vertices2.Count - 1; i++)
			{
				list.Add(new Pnt3D(Vertices2[i]));
			}
			num = CircleVerticeCountByResolution(Radius, EntResolution);
			if (num < 30)
			{
				num = 30;
			}
			num3 = 360f / (float)num;
			array = new List<Pnt3D>[num + 1];
			for (int j = 0; j <= num; j++)
			{
				Rotate(CenterPoint, (double)j * num3, new WorkPlane(planeType.XZ, 1), ref Vertices2);
				array[num2] = new List<Pnt3D>();
				for (int k = 0; k <= Vertices2.Count - 1; k++)
				{
					array[num2].Add(new Pnt3D(Vertices2[k]));
				}
				Vertices2.Clear();
				for (int l = 0; l <= list.Count - 1; l++)
				{
					Vertices2.Add(new Pnt3D(list[l]));
				}
				num2++;
			}
			for (int m = 1; m <= array.Length - 1; m++)
			{
				List<Pnt3D> list2 = new List<Pnt3D>();
				for (int n = 0; n <= array[m].Count - 1; n++)
				{
					list2.Add(new Pnt3D(array[m][n]));
				}
				Vertices.Add(list2);
				SurfaceTriangles.Clear();
				SurfaceWithTwoConnectedVertice(array[m - 1], array[m], ref SurfaceTriangles);
				for (int num4 = 0; num4 <= SurfaceTriangles.Count - 1; num4++)
				{
					TriangleList.Add(new Triangle3D(SurfaceTriangles[num4]));
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "CenterPoint: " + CenterPoint.ToString() + " - Radius: " + Radius;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void SphereHalf3D(Pnt3D CenterPoint, double Radius, double StartAngle, double EndAngle, EntityResolution EntResolution, WorkPlane Plane, ref List<Triangle3D> TriangleList)
	{
		try
		{
			List<Pnt3D> Vertices = new List<Pnt3D>();
			List<Pnt3D> list = new List<Pnt3D>();
			List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
			List<Pnt3D>[] array = null;
			int num = 0;
			int num2 = 0;
			double num3 = 0.0;
			TriangleList.Clear();
			if (Plane.PlaneType == planeType.XY)
			{
				ArcWithCenter(CenterPoint, Radius, 0.0, 180.0, Plane, EntResolution, ref Vertices);
			}
			if (Plane.PlaneType == planeType.XZ)
			{
				ArcWithCenter(CenterPoint, Radius, 0.0, 180.0, Plane, EntResolution, ref Vertices);
			}
			if (Plane.PlaneType == planeType.YZ)
			{
				ArcWithCenter(CenterPoint, Radius, 0.0, 180.0, Plane, EntResolution, ref Vertices);
			}
			for (int i = 0; i <= Vertices.Count - 1; i++)
			{
				list.Add(new Pnt3D(Vertices[i]));
			}
			num = CircleVerticeCountByResolution(Radius, EntResolution);
			if (num < 30)
			{
				num = 30;
			}
			num3 = (EndAngle - StartAngle) / (double)num;
			array = new List<Pnt3D>[num + 1];
			for (int j = 0; j <= num; j++)
			{
				if (Plane.PlaneType == planeType.XY)
				{
					Rotate(CenterPoint, StartAngle + (double)j * num3, Plane, ref Vertices);
				}
				if (Plane.PlaneType == planeType.XZ)
				{
					Rotate(CenterPoint, StartAngle - 90.0 + (double)j * num3, Plane, ref Vertices);
				}
				if (Plane.PlaneType == planeType.YZ)
				{
					Rotate(CenterPoint, StartAngle + 180.0 + (double)j * num3, Plane, ref Vertices);
				}
				array[num2] = new List<Pnt3D>();
				for (int k = 0; k <= Vertices.Count - 1; k++)
				{
					array[num2].Add(new Pnt3D(Vertices[k]));
				}
				Vertices.Clear();
				for (int l = 0; l <= list.Count - 1; l++)
				{
					Vertices.Add(new Pnt3D(list[l]));
				}
				num2++;
			}
			for (int m = 1; m <= array.Length - 1; m++)
			{
				SurfaceTriangles.Clear();
				SurfaceWithTwoConnectedVertice(array[m - 1], array[m], ref SurfaceTriangles);
				for (int n = 0; n <= SurfaceTriangles.Count - 1; n++)
				{
					TriangleList.Add(new Triangle3D(SurfaceTriangles[n]));
				}
			}
			SurfaceTriangles.Clear();
			SurfaceWithVerticeToPoint(array[0], CenterPoint, ref SurfaceTriangles);
			for (int num4 = 0; num4 <= SurfaceTriangles.Count - 1; num4++)
			{
				TriangleList.Add(new Triangle3D(SurfaceTriangles[num4]));
			}
			SurfaceTriangles.Clear();
			SurfaceWithVerticeToPoint(array[array.Length - 1], CenterPoint, ref SurfaceTriangles);
			for (int num5 = 0; num5 <= SurfaceTriangles.Count - 1; num5++)
			{
				TriangleList.Add(new Triangle3D(SurfaceTriangles[num5]));
			}
		}
		catch (Exception mSException)
		{
			string text = "CenterPoint: " + CenterPoint.ToString() + " - Radius: " + Radius + " - StartAngle: " + StartAngle + " - EndAngle: " + EndAngle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Trapezoid3D(Pnt3D TopLeftPoint, double TrapezTopWidth, double TrapezHeight, double TrapezTopLeftAngle, double TrapezTopRightAngle, Vec3D LengthDirection, double DirectionLength, double Rotation, ref eEntities SurfaceEntity)
	{
		List<Pnt3D> Vertice2D = new List<Pnt3D>();
		List<List<Pnt3D>> Vertice3D = new List<List<Pnt3D>>();
		List<Triangle3D> Triangles3D = new List<Triangle3D>();
		List<Quad3D> Quads3D = new List<Quad3D>();
		List<eEntities> Entities3D = new List<eEntities>();
		Trapezoid3D(TopLeftPoint, TrapezTopWidth, TrapezHeight, TrapezTopLeftAngle, TrapezTopRightAngle, LengthDirection, DirectionLength, Rotation, ref Vertice2D, ref Vertice3D, ref Quads3D, ref Triangles3D, ref Entities3D, ref SurfaceEntity);
	}

	public void Trapezoid3D(Pnt3D TopLeftPoint, double TrapezTopWidth, double TrapezHeight, double TrapezTopLeftAngle, double TrapezTopRightAngle, Vec3D LengthDirection, double DirectionLength, double Rotation, ref List<Quad3D> Quads, ref eEntities SurfaceEntity)
	{
		List<Pnt3D> Vertice2D = new List<Pnt3D>();
		List<List<Pnt3D>> Vertice3D = new List<List<Pnt3D>>();
		List<Triangle3D> Triangles3D = new List<Triangle3D>();
		List<eEntities> Entities3D = new List<eEntities>();
		Trapezoid3D(TopLeftPoint, TrapezTopWidth, TrapezHeight, TrapezTopLeftAngle, TrapezTopRightAngle, LengthDirection, DirectionLength, Rotation, ref Vertice2D, ref Vertice3D, ref Quads, ref Triangles3D, ref Entities3D, ref SurfaceEntity);
	}

	public void Trapezoid3D(Pnt3D TopLeftPoint, double TrapezTopWidth, double TrapezHeight, double TrapezTopLeftAngle, double TrapezTopRightAngle, Vec3D LengthDirection, double DirectionLength, double Rotation, ref List<Pnt3D> Vertice2D, ref List<List<Pnt3D>> Vertice3D, ref List<Quad3D> Quads3D, ref List<Triangle3D> Triangles3D, ref List<eEntities> Entities3D, ref eEntities SurfaceEntity)
	{
		Pnt3D pnt3D = new Pnt3D();
		Pnt3D pnt3D2 = new Pnt3D();
		Pnt3D CalcPoint = new Pnt3D();
		Pnt3D CalcPoint2 = new Pnt3D();
		ContentAlignmentPoints AlignPoints = new ContentAlignmentPoints();
		List<Pnt3D> CopiedPnt = new List<Pnt3D>();
		List<Pnt3D> Points = new List<Pnt3D>();
		List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
		Quad3D quad3D = new Quad3D();
		Triangle3D triangle3D = new Triangle3D();
		Triangle3D triangle3D2 = new Triangle3D();
		Vertice2D.Clear();
		Vertice3D.Clear();
		Quads3D.Clear();
		Triangles3D.Clear();
		Entities3D.Clear();
		if (Vec3D.isVectorZAxis(LengthDirection))
		{
			pnt3D = new Pnt3D(0.0, TrapezHeight, 0.0);
			pnt3D2 = new Pnt3D(TrapezTopWidth, TrapezHeight, 0.0);
			DiagonalLengthByAnglePerpendicularDistance(pnt3D, 90.0 - TrapezTopLeftAngle, 0.0 - TrapezHeight, new WorkPlane(), ref CalcPoint);
			DiagonalLengthByAnglePerpendicularDistance(pnt3D2, TrapezTopRightAngle - 90.0, 0.0 - TrapezHeight, new WorkPlane(), ref CalcPoint2);
			Points.Add(pnt3D);
			Points.Add(pnt3D2);
			Points.Add(CalcPoint2);
			Points.Add(CalcPoint);
			Points.Add(pnt3D);
			BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
			Move(AlignPoints.TopLeftPoint, TopLeftPoint, ref Points);
			Pnt3D.Copy(Points, ref CopiedPnt);
			Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref Points);
			Pnt3D.Copy(Points, ref Vertice2D);
			Vertice3D.Add(Points);
			ePolyline item = new ePolyline(Points);
			Entities3D.Add(item);
			quad3D = new Quad3D();
			PointsToQuad(Points, ref quad3D);
			Quads3D.Add(quad3D);
			triangle3D = new Triangle3D();
			triangle3D2 = new Triangle3D();
			QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
			Triangles3D.Add(triangle3D);
			Triangles3D.Add(triangle3D2);
			Pnt3D.Copy(Points, ref CopiedPnt2);
			Pnt3D.Offset(ref CopiedPnt2, 0.0, 0.0, DirectionLength);
			Vertice3D.Add(CopiedPnt2);
			item = new ePolyline(CopiedPnt2);
			Entities3D.Add(item);
			quad3D = new Quad3D();
			PointsToQuad(CopiedPnt2, ref quad3D);
			Quads3D.Add(quad3D);
			triangle3D = new Triangle3D();
			triangle3D2 = new Triangle3D();
			QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
			Triangles3D.Add(triangle3D);
			Triangles3D.Add(triangle3D2);
			for (int i = 0; i <= 3; i++)
			{
				List<Pnt3D> list = new List<Pnt3D>();
				list.Add(new Pnt3D(Points[i]));
				list.Add(new Pnt3D(Points[i + 1]));
				list.Add(new Pnt3D(CopiedPnt2[i + 1]));
				list.Add(new Pnt3D(CopiedPnt2[i]));
				list.Add(new Pnt3D(Points[i]));
				Vertice3D.Add(list);
				item = new ePolyline(list);
				Entities3D.Add(item);
				quad3D = new Quad3D();
				PointsToQuad(list, ref quad3D);
				Quads3D.Add(quad3D);
				triangle3D = new Triangle3D();
				triangle3D2 = new Triangle3D();
				QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
				Triangles3D.Add(triangle3D);
				Triangles3D.Add(triangle3D2);
			}
		}
		if (Vec3D.isVectorYAxis(LengthDirection))
		{
			pnt3D = new Pnt3D(0.0, 0.0, TrapezHeight);
			pnt3D2 = new Pnt3D(TrapezTopWidth, 0.0, TrapezHeight);
			DiagonalLengthByAnglePerpendicularDistance(pnt3D, 90.0 - TrapezTopLeftAngle, 0.0 - TrapezHeight, new WorkPlane(planeType.XZ, 1), ref CalcPoint);
			DiagonalLengthByAnglePerpendicularDistance(pnt3D2, TrapezTopRightAngle - 90.0, 0.0 - TrapezHeight, new WorkPlane(planeType.XZ, 1), ref CalcPoint2);
			Points.Add(pnt3D);
			Points.Add(pnt3D2);
			Points.Add(CalcPoint2);
			Points.Add(CalcPoint);
			Points.Add(pnt3D);
			BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
			Move(AlignPoints.TopLeftPoint, TopLeftPoint, ref Points);
			Pnt3D.Copy(Points, ref CopiedPnt);
			Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref Points);
			Pnt3D.Copy(Points, ref Vertice2D);
			Vertice3D.Add(Points);
			ePolyline item2 = new ePolyline(Points);
			Entities3D.Add(item2);
			quad3D = new Quad3D();
			PointsToQuad(Points, ref quad3D);
			Quads3D.Add(quad3D);
			triangle3D = new Triangle3D();
			triangle3D2 = new Triangle3D();
			QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
			Triangles3D.Add(triangle3D);
			Triangles3D.Add(triangle3D2);
			Pnt3D.Copy(CopiedPnt, ref CopiedPnt2);
			Pnt3D.Offset(ref CopiedPnt2, 0.0, DirectionLength, 0.0);
			Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref CopiedPnt2);
			Vertice3D.Add(CopiedPnt2);
			item2 = new ePolyline(CopiedPnt2);
			Entities3D.Add(item2);
			quad3D = new Quad3D();
			PointsToQuad(CopiedPnt2, ref quad3D);
			Quads3D.Add(quad3D);
			triangle3D = new Triangle3D();
			triangle3D2 = new Triangle3D();
			QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
			Triangles3D.Add(triangle3D);
			Triangles3D.Add(triangle3D2);
			for (int j = 0; j <= 3; j++)
			{
				List<Pnt3D> list2 = new List<Pnt3D>();
				list2.Add(new Pnt3D(Points[j]));
				list2.Add(new Pnt3D(Points[j + 1]));
				list2.Add(new Pnt3D(CopiedPnt2[j + 1]));
				list2.Add(new Pnt3D(CopiedPnt2[j]));
				list2.Add(new Pnt3D(Points[j]));
				Vertice3D.Add(list2);
				item2 = new ePolyline(list2);
				Entities3D.Add(item2);
				quad3D = new Quad3D();
				PointsToQuad(list2, ref quad3D);
				Quads3D.Add(quad3D);
				triangle3D = new Triangle3D();
				triangle3D2 = new Triangle3D();
				QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
				Triangles3D.Add(triangle3D);
				Triangles3D.Add(triangle3D2);
			}
		}
		if (Vec3D.isVectorXAxis(LengthDirection))
		{
			pnt3D = new Pnt3D(0.0, 0.0, TrapezHeight);
			pnt3D2 = new Pnt3D(0.0, TrapezTopWidth, TrapezHeight);
			DiagonalLengthByAnglePerpendicularDistance(pnt3D, 90.0 - TrapezTopLeftAngle, 0.0 - TrapezHeight, new WorkPlane(planeType.YZ, 1), ref CalcPoint);
			DiagonalLengthByAnglePerpendicularDistance(pnt3D2, TrapezTopRightAngle - 90.0, 0.0 - TrapezHeight, new WorkPlane(planeType.YZ, 1), ref CalcPoint2);
			Points.Add(pnt3D);
			Points.Add(pnt3D2);
			Points.Add(CalcPoint2);
			Points.Add(CalcPoint);
			Points.Add(pnt3D);
			BoxSizeWithContentAlignment(Points, new WorkPlane(LengthDirection), ref AlignPoints);
			Move(AlignPoints.TopLeftPoint, TopLeftPoint, ref Points);
			Pnt3D.Copy(Points, ref CopiedPnt);
			Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref Points);
			Pnt3D.Copy(Points, ref Vertice2D);
			Vertice3D.Add(Points);
			ePolyline item3 = new ePolyline(Points);
			Entities3D.Add(item3);
			quad3D = new Quad3D();
			PointsToQuad(Points, ref quad3D);
			Quads3D.Add(quad3D);
			triangle3D = new Triangle3D();
			triangle3D2 = new Triangle3D();
			QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
			Triangles3D.Add(triangle3D);
			Triangles3D.Add(triangle3D2);
			Pnt3D.Copy(CopiedPnt, ref CopiedPnt2);
			Pnt3D.Offset(ref CopiedPnt2, DirectionLength, 0.0, 0.0);
			Rotate(TopLeftPoint, Rotation, new WorkPlane(), ref CopiedPnt2);
			Vertice3D.Add(CopiedPnt2);
			item3 = new ePolyline(CopiedPnt2);
			Entities3D.Add(item3);
			quad3D = new Quad3D();
			PointsToQuad(CopiedPnt2, ref quad3D);
			Quads3D.Add(quad3D);
			triangle3D = new Triangle3D();
			triangle3D2 = new Triangle3D();
			QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
			Triangles3D.Add(triangle3D);
			Triangles3D.Add(triangle3D2);
			for (int k = 0; k <= 3; k++)
			{
				List<Pnt3D> list3 = new List<Pnt3D>();
				list3.Add(new Pnt3D(Points[k]));
				list3.Add(new Pnt3D(Points[k + 1]));
				list3.Add(new Pnt3D(CopiedPnt2[k + 1]));
				list3.Add(new Pnt3D(CopiedPnt2[k]));
				list3.Add(new Pnt3D(Points[k]));
				Vertice3D.Add(list3);
				item3 = new ePolyline(list3);
				Entities3D.Add(item3);
				quad3D = new Quad3D();
				PointsToQuad(list3, ref quad3D);
				Quads3D.Add(quad3D);
				triangle3D = new Triangle3D();
				triangle3D2 = new Triangle3D();
				QuadToTriangle(quad3D, ref triangle3D, ref triangle3D2);
				Triangles3D.Add(triangle3D);
				Triangles3D.Add(triangle3D2);
			}
		}
		if (Triangles3D.Count > 0)
		{
			SurfaceEntity = new eSurface(Triangles3D, Color.Gray);
		}
	}

	public void Plane3D(Pnt3D CornerPoint, Vec3D Vector, OrientationAngle Rotations, double Width, double Height, ref List<Pnt3D> Vertices)
	{
		Vertices.Clear();
		if (Vec3D.isVectorXAxis(Vector))
		{
			RectangleCorner(CornerPoint, Width, Height, new WorkPlane(), ref Vertices);
			RotateBySequanceOrientationAngle(CornerPoint, Rotations, RotationSequance.AC, ref Vertices);
		}
		if (Vec3D.isVectorYAxis(Vector))
		{
			MessageBox.Show("Not Developted");
		}
		if (Vec3D.isVectorZAxis(Vector))
		{
			MessageBox.Show("Not Developted");
		}
	}

	public void Clamper3D(double XPosition, int Type, double ProfileWidth, double ProfileHeight, ClamperData3D Data, ref List<Triangle3D> Triangles)
	{
		List<Triangle3D> Triangles2 = new List<Triangle3D>();
		List<Triangle3D> Triangles3 = new List<Triangle3D>();
		List<Triangle3D> Triangles4 = new List<Triangle3D>();
		Triangles.Clear();
		Triangles = new List<Triangle3D>();
		if (Type == 0)
		{
			BoxCorner3D(new Pnt3D(XPosition - Data.Width / 2.0, 0.0 - Data.ConstantPointThickness, 0.0 - Data.BottomThickness), Data.Width, ProfileWidth + Data.TipPointThickness + Data.ConstantPointThickness, Data.BottomThickness, new WorkPlane(), ref Triangles2);
			BoxCenter3D(new Pnt3D(XPosition, (0.0 - Data.ConstantPointThickness) / 2.0, 0.0), Data.Width, Data.ConstantPointThickness, Data.ConstantPointHeight, 0.0, new WorkPlane(), ref Triangles3);
			BoxCenter3D(new Pnt3D(XPosition, ProfileWidth + Data.TipPointThickness / 2.0, 0.0), Data.Width, Data.TipPointThickness, Data.TipPointHeight, 0.0, new WorkPlane(), ref Triangles4);
			Triangles.AddRange(Triangles2);
			Triangles.AddRange(Triangles3);
			Triangles.AddRange(Triangles4);
		}
		if (Type == 1)
		{
			BoxCorner3D(new Pnt3D(XPosition - Data.Width / 2.0, 0.0 - ProfileWidth - Data.ConstantPointThickness, 0.0 - Data.BottomThickness), Data.Width, ProfileWidth + Data.TipPointThickness + Data.ConstantPointThickness, Data.BottomThickness, new WorkPlane(), ref Triangles2);
			BoxCenter3D(new Pnt3D(XPosition, 0.0 - ProfileWidth - Data.ConstantPointThickness / 2.0, 0.0), Data.Width, Data.ConstantPointThickness, Data.ConstantPointHeight, 0.0, new WorkPlane(), ref Triangles3);
			BoxCenter3D(new Pnt3D(XPosition, Data.TipPointThickness / 2.0, 0.0), Data.Width, Data.TipPointThickness, Data.TipPointHeight, 0.0, new WorkPlane(), ref Triangles4);
			Triangles.AddRange(Triangles2);
			Triangles.AddRange(Triangles3);
			Triangles.AddRange(Triangles4);
		}
	}

	public void ToolDraw(ToolBase tool, Pnt3D ToolPoint, ToolDrawOptions DrawOptions, ref List<Triangle3D> Triangles)
	{
		new List<List<Pnt3D>>();
		new List<eEntities>();
	}

	public void ToolDraw(ToolBase tool, Pnt3D ToolPoint, ToolDrawOptions DrawOptions, ref ToolDrawVertices Drawings)
	{
		Drawings.TrianglesHolder.Clear();
		Drawings.TrianglesCutter.Clear();
		Drawings.TrianglesArbor.Clear();
		Drawings.TrianglesLength.Clear();
		Drawings.TrianglesSphere.Clear();
		Drawings.Vertices.Clear();
		if (tool.Geometry.GeometryType == ToolType.Flat)
		{
			double num = 1.0;
			if (tool.Geometry.LengthReverseDirection)
			{
				num = -1.0;
			}
			Cylinder3D(ToolPoint, tool.Geometry.CutLength * num, tool.Geometry.Diameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesCutter);
			Pnt3D pnt3D = new Pnt3D();
			pnt3D = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.CutLength * num));
			Cylinder3D(pnt3D, (tool.Geometry.Length - tool.Geometry.CutLength) * num, tool.Geometry.Diameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesLength);
			if ((tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.Length * num));
				Cone3D(pnt3D, tool.Geometry.ArborLength * num, tool.Geometry.ArborBottomDiameter / 2.0, tool.Geometry.ArborTopDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesArbor);
			}
			if ((tool.Geometry.HolderDiameter > 0.0) & (tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, (tool.Geometry.Length + tool.Geometry.ArborLength) * num));
				Cylinder3D(pnt3D, tool.Geometry.HolderLength * num, tool.Geometry.HolderDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesHolder);
			}
		}
		if (tool.Geometry.GeometryType == ToolType.Sphere)
		{
			double num2 = 1.0;
			if (tool.Geometry.LengthReverseDirection)
			{
				num2 = -1.0;
			}
			Pnt3D pnt3D2 = new Pnt3D();
			List<Pnt3D> Vertices = new List<Pnt3D>();
			ArcWithCenter(new Pnt3D(0.0, tool.Geometry.Diameter / 2.0, 0.0), tool.Geometry.Diameter / 2.0, 180.0, 270.0, new WorkPlane(), new EntityResolution(), ref Vertices);
			Vertices.Reverse();
			Vertices.Add(new Pnt3D((0.0 - tool.Geometry.Diameter) / 2.0, tool.Geometry.CutLength, 0.0));
			SurfaceRevolve(Vertices, new Pnt3D(), 0.0, 360.0, 2.0, new Vec3D(0.0, 0.0, 1.0), new EntityResolution(), ref Drawings.TrianglesCutter);
			pnt3D2 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.CutLength * num2));
			Cylinder3D(pnt3D2, (tool.Geometry.Length - tool.Geometry.CutLength) * num2, tool.Geometry.Diameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(0.1, 20, 20.0, EntityResolutionType.ByLength), ref Drawings.TrianglesLength);
			if ((tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D2 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.Length * num2));
				Cone3D(pnt3D2, tool.Geometry.ArborLength * num2, tool.Geometry.ArborBottomDiameter / 2.0, tool.Geometry.ArborTopDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesArbor);
			}
			if ((tool.Geometry.HolderDiameter > 0.0) & (tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D2 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, (tool.Geometry.Length + tool.Geometry.ArborLength) * num2));
				Cylinder3D(pnt3D2, tool.Geometry.HolderLength * num2, tool.Geometry.HolderDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesHolder);
			}
		}
		if (tool.Geometry.GeometryType == ToolType.Bullnose)
		{
			double num3 = 1.0;
			if (tool.Geometry.LengthReverseDirection)
			{
				num3 = -1.0;
			}
			Pnt3D pnt3D3 = new Pnt3D();
			Pnt3D ArcCenter = new Pnt3D();
			List<Pnt3D> Vertices2 = new List<Pnt3D>();
			double ArcSA = 0.0;
			double ArcEA = 0.0;
			List<Pnt3D> Points = new List<Pnt3D>();
			Points.Add(new Pnt3D());
			Points.Add(new Pnt3D(tool.Geometry.Diameter / 2.0 - tool.Geometry.RoundRadius, 0.0, 0.0));
			ArcWithTwoPointAndRadius(Points[Points.Count - 1], new Pnt3D(tool.Geometry.Diameter / 2.0, tool.Geometry.RoundRadius), tool.Geometry.RoundRadius, CW: false, new WorkPlane(), ref ArcCenter, ref ArcSA, ref ArcEA);
			ArcWithCenter(ArcCenter, tool.Geometry.RoundRadius, ArcSA, ArcEA, new WorkPlane(), new EntityResolution(), ref Vertices2);
			Points.AddRange(Vertices2);
			Points.Add(new Pnt3D(tool.Geometry.Diameter / 2.0, tool.Geometry.CutLength, 0.0));
			CheckDuplicatedPointsWithPrevious(ref Points);
			SurfaceRevolve(Points, new Pnt3D(), 0.0, 360.0, 2.0, new Vec3D(0.0, 0.0, 1.0), new EntityResolution(), ref Drawings.TrianglesCutter);
			pnt3D3 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.CutLength * num3));
			Cylinder3D(pnt3D3, (tool.Geometry.Length - tool.Geometry.CutLength) * num3, tool.Geometry.Diameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(0.1, 20, 20.0, EntityResolutionType.ByLength), ref Drawings.TrianglesLength);
			if ((tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D3 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.Length * num3));
				Cone3D(pnt3D3, tool.Geometry.ArborLength * num3, tool.Geometry.ArborBottomDiameter / 2.0, tool.Geometry.ArborTopDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesArbor);
			}
			if ((tool.Geometry.HolderDiameter > 0.0) & (tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D3 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, (tool.Geometry.Length + tool.Geometry.ArborLength) * num3));
				Cylinder3D(pnt3D3, tool.Geometry.HolderLength * num3, tool.Geometry.HolderDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesHolder);
			}
		}
		if (tool.Geometry.GeometryType == ToolType.Taper)
		{
			double num4 = 1.0;
			if (tool.Geometry.LengthReverseDirection)
			{
				num4 = -1.0;
			}
			double num5 = tool.Geometry.BottomDiameter / 2.0 + tool.Geometry.CutLength * Math.Tan(buConversion.DegreeToRadian(tool.Geometry.TaperAngle));
			Cone3D(ToolPoint, tool.Geometry.CutLength * num4, tool.Geometry.BottomDiameter / 2.0, num5, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesCutter);
			Pnt3D pnt3D4 = new Pnt3D();
			pnt3D4 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.CutLength * num4));
			Cylinder3D(pnt3D4, (tool.Geometry.Length - tool.Geometry.CutLength) * num4, num5, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesLength);
			if ((tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D4 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.Length * num4));
				Cone3D(pnt3D4, tool.Geometry.ArborLength * num4, tool.Geometry.ArborBottomDiameter / 2.0, tool.Geometry.ArborTopDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesArbor);
			}
			if ((tool.Geometry.HolderDiameter > 0.0) & (tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D4 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, (tool.Geometry.Length + tool.Geometry.ArborLength) * num4));
				Cylinder3D(pnt3D4, tool.Geometry.HolderLength * num4, tool.Geometry.HolderDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesHolder);
			}
		}
		if (tool.Geometry.GeometryType == ToolType.Taper)
		{
			double num6 = 1.0;
			if (tool.Geometry.LengthReverseDirection)
			{
				num6 = -1.0;
			}
			double num7 = tool.Geometry.BottomDiameter / 2.0 + tool.Geometry.CutLength * Math.Tan(buConversion.DegreeToRadian(tool.Geometry.TaperAngle));
			Cone3D(ToolPoint, tool.Geometry.CutLength * num6, tool.Geometry.BottomDiameter / 2.0, num7, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesCutter);
			Pnt3D pnt3D5 = new Pnt3D();
			pnt3D5 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.CutLength * num6));
			Cylinder3D(pnt3D5, (tool.Geometry.Length - tool.Geometry.CutLength) * num6, num7, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesLength);
			if ((tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D5 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.Length * num6));
				Cone3D(pnt3D5, tool.Geometry.ArborLength * num6, tool.Geometry.ArborBottomDiameter / 2.0, tool.Geometry.ArborTopDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesArbor);
			}
			if ((tool.Geometry.HolderDiameter > 0.0) & (tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D5 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, (tool.Geometry.Length + tool.Geometry.ArborLength) * num6));
				Cylinder3D(pnt3D5, tool.Geometry.HolderLength * num6, tool.Geometry.HolderDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesHolder);
			}
		}
		if (tool.Geometry.GeometryType == ToolType.Saw)
		{
			double num8 = 1.0;
			if (tool.Geometry.LengthReverseDirection)
			{
				num8 = -1.0;
			}
			if (tool.Geometry.PlaneDirection.Y == 1.0)
			{
				ToolPoint.Y -= tool.Geometry.Thickness * num8 * 0.5;
			}
			Cylinder3D(ToolPoint, tool.Geometry.Thickness * num8, tool.Geometry.Diameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesCutter);
			Pnt3D pnt3D6 = new Pnt3D();
			pnt3D6 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.Thickness * num8));
			Cylinder3D(pnt3D6, (tool.Geometry.Length - tool.Geometry.Thickness) * num8, tool.Geometry.LengthDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesLength);
			if ((tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D6 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, tool.Geometry.Length * num8));
				Cone3D(pnt3D6, tool.Geometry.ArborLength * num8, tool.Geometry.ArborBottomDiameter / 2.0, tool.Geometry.ArborTopDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesArbor);
			}
			if ((tool.Geometry.HolderDiameter > 0.0) & (tool.Geometry.ArborBottomDiameter > 0.0) & (tool.Geometry.ArborTopDiameter > 0.0))
			{
				pnt3D6 = new Pnt3D(AddOffsetToPoint(ToolPoint, tool.Geometry.PlaneDirection, (tool.Geometry.Length + tool.Geometry.ArborLength) * num8));
				Cylinder3D(pnt3D6, tool.Geometry.HolderLength * num8, tool.Geometry.HolderDiameter / 2.0, 0.0, tool.Geometry.PlaneDirection, new EntityResolution(), ref Drawings.TrianglesHolder);
			}
		}
		if (!tool.Geometry.DrawArbor)
		{
			Drawings.TrianglesArbor.Clear();
		}
		if (!tool.Geometry.DrawHolder)
		{
			Drawings.TrianglesHolder.Clear();
		}
		if (!tool.Geometry.DrawLength)
		{
			Drawings.TrianglesLength.Clear();
		}
	}

	public void CreatMeshSurfaceFromGridPoins(List<List<Pnt3D>> GridPoints, ref List<Triangle3D> Triangles)
	{
		Triangles = new List<Triangle3D>();
		for (int i = 1; i <= GridPoints.Count - 1; i++)
		{
			if (GridPoints[i - 1].Count == GridPoints[i].Count)
			{
				for (int j = 1; j <= GridPoints[i].Count - 1; j++)
				{
					Triangle3D FirstTriangle = new Triangle3D();
					Triangle3D SecondTriangle = new Triangle3D();
					Quad3D quad = new Quad3D(GridPoints[i - 1][j - 1], GridPoints[i - 1][j], GridPoints[i][j], GridPoints[i][j - 1]);
					QuadToTriangle(quad, ref FirstTriangle, ref SecondTriangle);
					Triangles.Add(FirstTriangle);
					Triangles.Add(SecondTriangle);
				}
			}
		}
	}

	public void GetGridPointsFromXYZList(List<string> CoordinateList, FileOpenModes Properties, ref List<List<Pnt3D>> GridPoints)
	{
		GridPoints = new List<List<Pnt3D>>();
		List<Pnt3D> list = new List<Pnt3D>();
		int num = 3;
		if (!Properties.XYZMode)
		{
			num = 2;
		}
		for (int i = 0; i <= CoordinateList.Count - 1; i++)
		{
			string text = "";
