		Hatch(XYAreaPoints, new List<List<Pnt3D>>(), GridDistance.X, 0.0, 0.0, 0.0, UsePolyline: false, 0.0, HatchType.Horizontal, HatchSortType.ByClosestLength, VerticalDirectionType.DownToUp, HorizontalDirectionType.LeftToRight, new WorkPlane(), 0.0, 0.0, UseZValue: false, ref HatchLines, ref HatchEntities);
