		for (int n = 0; n <= YVectorSurfPoint.Count - 1; n++)
		{
			if ((YVectorSurfPoint[n][0].X > num) & (YVectorSurfPoint[n][0].X < num2) & (YVectorSurfPoint[n][0].Y < num3))
			{
				CopiedPnt3.Add(new Pnt3D(YVectorSurfPoint[n][0]));
			}
		}
		if (CopiedPnt3.Count > 0)
		{
			List<Pnt3D> CopiedPnt5 = new List<Pnt3D>();
			Pnt3D.Copy(XVectorSurfPoint[0], ref CopiedPnt5);
			CopiedPnt5.Reverse();
			Pnt3D.Add(CopiedPnt5, ref CopiedPnt3);
			TriangulationPoints triangulationPoints2 = new TriangulationPoints();
			TriangulationPoints CalculatedPoint2 = new TriangulationPoints();
