			SurfaceSlicesBorders.Add(Pnt3D.Copy(CopiedPnt3));
			Triangulation(triangulationPoints2, MoveToZeroPoint: false, ref CalculatedPoint2);
			Triangle3D.Add(CalculatedPoint2.Triangles, ref SurfTriangles);
		}
		num = XVectorSurfPoint[XVectorSurfPoint.Count - 1][0].X;
		num2 = XVectorSurfPoint[XVectorSurfPoint.Count - 1][XVectorSurfPoint[XVectorSurfPoint.Count - 1].Count - 1].X;
		num4 = XVectorSurfPoint[XVectorSurfPoint.Count - 1][0].Y;
		for (int num5 = 0; num5 <= YVectorSurfPoint.Count - 1; num5++)
		{
			if ((YVectorSurfPoint[num5][YVectorSurfPoint[num5].Count - 1].X > num) & (YVectorSurfPoint[num5][YVectorSurfPoint[num5].Count - 1].X < num2) & (YVectorSurfPoint[num5][YVectorSurfPoint[num5].Count - 1].Y > num4))
			{
				CopiedPnt4.Add(new Pnt3D(YVectorSurfPoint[num5][YVectorSurfPoint[num5].Count - 1]));
			}
		}
		if (CopiedPnt4.Count > 0)
		{
			List<Pnt3D> CopiedPnt6 = new List<Pnt3D>();
			Pnt3D.Copy(XVectorSurfPoint[XVectorSurfPoint.Count - 1], ref CopiedPnt6);
