			TriangulationPoints CalculatedPoint3 = new TriangulationPoints();
			Pnt3D.Copy(CopiedPnt4, ref triangulationPoints3.Points);
			SurfaceSlicesBorders.Add(Pnt3D.Copy(CopiedPnt4));
			Triangulation(triangulationPoints3, MoveToZeroPoint: false, ref CalculatedPoint3);
			Triangle3D.Add(CalculatedPoint3.Triangles, ref SurfTriangles);
		}
	}

	public void SurfaceFromGridProfiles(List<List<Pnt3D>> GridPoints, ref List<Triangle3D> SurfTriangles)
	{
		List<Quad3D> list = new List<Quad3D>();
		for (int i = 0; i <= GridPoints.Count - 1; i++)
		{
			bool flag = false;
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
			Pnt3D.Copy(GridPoints[i], ref CopiedPnt);
			if (i <= GridPoints.Count - 2)
			{
				Pnt3D.Copy(GridPoints[i + 1], ref CopiedPnt2);
			}
			for (int j = 0; j <= CopiedPnt.Count - 2; j++)
			{
				bool flag2 = false;
				bool flag3 = false;
				Pnt3D firstPoint = new Pnt3D();
				Pnt3D secondPoint = new Pnt3D();
				Pnt3D thirdPoint = new Pnt3D();
				Pnt3D fourthPoint = new Pnt3D();
				int index = 0;
				for (int k = 0; k <= CopiedPnt2.Count - 1; k++)
				{
					if (!flag2 && buCompare.EQ(CopiedPnt[j].X, CopiedPnt2[k].X))
					{
						index = k;
						flag2 = true;
						firstPoint = new Pnt3D(CopiedPnt[j]);
						fourthPoint = new Pnt3D(CopiedPnt2[k]);
					}
					if (!flag3 && buCompare.EQ(CopiedPnt[j + 1].X, CopiedPnt2[k].X))
					{
						flag3 = true;
						secondPoint = new Pnt3D(CopiedPnt[j + 1]);
						thirdPoint = new Pnt3D(CopiedPnt2[k]);
					}
				}
				if (!(flag2 && flag3))
				{
					if (flag)
					{
						Quad3D quad3D = new Quad3D();
						quad3D.FirstPoint = new Pnt3D(CopiedPnt[j]);
						quad3D.SecondPoint = new Pnt3D(CopiedPnt[CopiedPnt.Count - 1]);
						quad3D.ThirdPoint = new Pnt3D(CopiedPnt2[CopiedPnt2.Count - 1]);
						quad3D.FourthPoint = new Pnt3D(CopiedPnt[j].X, CopiedPnt2[0].Y);
						list.Add(quad3D);
						flag = false;
					}
					continue;
				}
				if (!flag && j > 0)
				{
					Quad3D quad3D2 = new Quad3D();
					quad3D2.FirstPoint = new Pnt3D(CopiedPnt[0]);
					quad3D2.SecondPoint = new Pnt3D(CopiedPnt[j]);
					quad3D2.ThirdPoint = new Pnt3D(CopiedPnt[j].X, CopiedPnt2[index].Y, CopiedPnt2[index].Z);
					quad3D2.FourthPoint = new Pnt3D(CopiedPnt2[0]);
					list.Add(quad3D2);
				}
				Triangle3D FirstTriangle = new Triangle3D();
				Triangle3D SecondTriangle = new Triangle3D();
				QuadToTriangle(new Quad3D(firstPoint, secondPoint, thirdPoint, fourthPoint), ref FirstTriangle, ref SecondTriangle);
				SurfTriangles.Add(FirstTriangle);
				SurfTriangles.Add(SecondTriangle);
				flag = true;
			}
		}
		for (int l = 0; l <= list.Count - 1; l++)
		{
			Triangle3D FirstTriangle2 = new Triangle3D();
			Triangle3D SecondTriangle2 = new Triangle3D();
			QuadToTriangle(list[l], ref FirstTriangle2, ref SecondTriangle2);
			SurfTriangles.Add(FirstTriangle2);
			SurfTriangles.Add(SecondTriangle2);
		}
	}

	public void SurfaceFromPolygonWithXZAndYZProfileEntities(List<Pnt3D> AreaPoints, List<Pnt3D> XZProfilePoints, List<Pnt3D> YZProfilePoints, Vec3D GridDistance, ref List<List<Pnt3D>> XVectorSurfPoint, ref List<List<Pnt3D>> YVectorSurfPoint, ref List<Triangle3D> SurfTriangles)
	{
		List<eEntities> HatchLines = new List<eEntities>();
		List<eEntities> HatchLines2 = new List<eEntities>();
		List<List<eEntities>> HatchEntities = new List<List<eEntities>>();
		List<List<eEntities>> HatchEntities2 = new List<List<eEntities>>();
		Pnt3D MinPoint = new Pnt3D();
		Pnt3D MaxPoint = new Pnt3D();
		Length3D length3D = new Length3D();
		Pnt3D MinPoint2 = new Pnt3D();
		Pnt3D MaxPoint2 = new Pnt3D();
		Length3D length3D2 = new Length3D();
		Pnt3D MinPoint3 = new Pnt3D();
		Pnt3D MaxPoint3 = new Pnt3D();
		Length3D length3D3 = new Length3D();
		BoxSizeCalculate(AreaPoints, ref MinPoint, ref MaxPoint);
		length3D.dX = MaxPoint.X - MinPoint.X;
		length3D.dY = MaxPoint.Y - MinPoint.Y;
		BoxSizeCalculate(XZProfilePoints, ref MinPoint2, ref MaxPoint2);
		length3D2.dX = MaxPoint2.X - MinPoint2.X;
		length3D2.dY = MaxPoint2.Y - MinPoint2.Y;
		BoxSizeCalculate(YZProfilePoints, ref MinPoint3, ref MaxPoint3);
		length3D3.dX = MaxPoint3.X - MinPoint3.X;
		length3D3.dY = MaxPoint3.Y - MinPoint3.Y;
		Hatch(AreaPoints, new List<List<Pnt3D>>(), GridDistance.X, 0.0, 0.0, 0.0, UsePolyline: false, 0.0, HatchType.Horizontal, HatchSortType.ByClosestLength, VerticalDirectionType.DownToUp, HorizontalDirectionType.LeftToRight, new WorkPlane(), 0.0, 0.0, UseZValue: false, ref HatchLines, ref HatchEntities);
		Hatch(AreaPoints, new List<List<Pnt3D>>(), GridDistance.Y, 0.0, 0.0, 0.0, UsePolyline: false, 0.0, HatchType.Vertical, HatchSortType.ByClosestLength, VerticalDirectionType.DownToUp, HorizontalDirectionType.LeftToRight, new WorkPlane(), 0.0, 0.0, UseZValue: false, ref HatchLines2, ref HatchEntities2);
		for (int i = 0; i <= HatchLines.Count - 1; i++)
		{
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			Pnt3D.Copy(HatchLines[i].Vertice, ref CopiedPnt);
			XVectorSurfPoint.Add(CopiedPnt);
		}
		for (int j = 0; j <= HatchLines2.Count - 1; j++)
		{
			List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
			Pnt3D.Copy(HatchLines2[j].Vertice, ref CopiedPnt2);
			YVectorSurfPoint.Add(CopiedPnt2);
		}
	}

	public void GridFromBoxsize(Pnt3D MinPoint, Pnt3D MaxPoint, Vec3D Distances, ref List<List<Pnt3D>> XVectorSurfPoint, ref List<List<Pnt3D>> YVectorSurfPoint)
