	public void GridFromBoxsize(Pnt3D MinPoint, Pnt3D MaxPoint, Vec3D Distances, double ZValue, bool XEnable, bool YEnable, bool DevideLines, ref List<List<Pnt3D>> XVectorSurfPoint, ref List<List<Pnt3D>> YVectorSurfPoint)
	{
		List<Pnt3D> Vertices = new List<Pnt3D>();
		List<eEntities> HatchLines = new List<eEntities>();
		List<eEntities> HatchLines2 = new List<eEntities>();
		List<List<eEntities>> HatchEntities = new List<List<eEntities>>();
		List<List<eEntities>> HatchEntities2 = new List<List<eEntities>>();
		RectangleCorner(MinPoint, MaxPoint, new WorkPlane(), ref Vertices);
		if (XEnable)
		{
			Hatch(Vertices, new List<List<Pnt3D>>(), Distances.X, 0.0, 0.0, 0.0, UsePolyline: false, 0.0, HatchType.Horizontal, HatchSortType.ByClosestLength, VerticalDirectionType.DownToUp, HorizontalDirectionType.LeftToRight, new WorkPlane(), 0.0, 0.0, UseZValue: false, ref HatchLines, ref HatchEntities);
		}
		if (YEnable)
		{
			Hatch(Vertices, new List<List<Pnt3D>>(), Distances.Y, 0.0, 0.0, 0.0, UsePolyline: false, 0.0, HatchType.Vertical, HatchSortType.ByClosestLength, VerticalDirectionType.DownToUp, HorizontalDirectionType.LeftToRight, new WorkPlane(), 0.0, 0.0, UseZValue: false, ref HatchLines2, ref HatchEntities2);
		}
		XVectorSurfPoint.Clear();
		XVectorSurfPoint = new List<List<Pnt3D>>();
		YVectorSurfPoint.Clear();
		YVectorSurfPoint = new List<List<Pnt3D>>();
		if (!YEnable)
		{
			for (int i = 0; i <= HatchLines.Count - 1; i++)
			{
				if (DevideLines)
				{
					List<Pnt3D> Points = new List<Pnt3D>();
					eLine refEntity = new eLine(new Pnt3D(HatchLines[i].Vertice[0]), new Pnt3D(HatchLines[i].Vertice[1]));
					EntitiesResolution entitiesResolution = new EntitiesResolution();
					entitiesResolution.LineResolution.ResolutionTypes = EntityResolutionType.ByLength;
					entitiesResolution.LineResolution.GeometricLength = Distances.Y;
					EntitiesToPoint(refEntity, entitiesResolution, ref Points);
					XVectorSurfPoint.Add(Points);
				}
				else
				{
					List<Pnt3D> list = new List<Pnt3D>();
					list.Add(new Pnt3D(HatchLines[i].Vertice[0]));
					list.Add(new Pnt3D(HatchLines[i].Vertice[1]));
					XVectorSurfPoint.Add(list);
				}
			}
		}
		else
		{
			for (int j = 0; j <= HatchLines.Count - 1; j++)
			{
				List<Pnt3D> Points2 = new List<Pnt3D>();
				Pnt3D pnt3D = new Pnt3D(HatchLines[j].Vertice[0]);
				Pnt3D pnt3D2 = new Pnt3D(HatchLines[j].Vertice[1]);
				new Pnt3D();
				new Pnt3D();
				if (j <= HatchLines.Count - 2)
				{
					new Pnt3D(HatchLines[j + 1].Vertice[0]);
					new Pnt3D(HatchLines[j + 1].Vertice[1]);
				}
				Points2.Add(new Pnt3D(pnt3D));
				for (int k = 0; k <= HatchLines2.Count - 1; k++)
				{
					bool IsLineIntersect = false;
					bool IsIntersecPointInsideLines = false;
					Pnt3D IntersectionPoint = new Pnt3D();
					Pnt3D firstLineStartPoint = new Pnt3D(HatchLines2[k].Vertice[0]);
					Pnt3D firstLineEndPoint = new Pnt3D(HatchLines2[k].Vertice[1]);
					LineLineIntersection(firstLineStartPoint, firstLineEndPoint, pnt3D, pnt3D2, new WorkPlane(), ref IntersectionPoint, ref IsLineIntersect, ref IsIntersecPointInsideLines);
					if (IsLineIntersect && IsIntersecPointInsideLines)
					{
						Points2.Add(new Pnt3D(IntersectionPoint.X, IntersectionPoint.Y));
					}
				}
				Points2.Add(new Pnt3D(pnt3D2));
				CheckDuplicatedPointsWithPrevious(ref Points2);
				XVectorSurfPoint.Add(Points2);
			}
		}
		if (!XEnable)
		{
			for (int l = 0; l <= HatchLines2.Count - 1; l++)
			{
				if (DevideLines)
				{
					List<Pnt3D> Points3 = new List<Pnt3D>();
					eLine refEntity2 = new eLine(new Pnt3D(HatchLines2[l].Vertice[0]), new Pnt3D(HatchLines2[l].Vertice[1]));
					EntitiesResolution entitiesResolution2 = new EntitiesResolution();
					entitiesResolution2.LineResolution.ResolutionTypes = EntityResolutionType.ByLength;
					entitiesResolution2.LineResolution.GeometricLength = Distances.Y;
					EntitiesToPoint(refEntity2, entitiesResolution2, ref Points3);
					YVectorSurfPoint.Add(Points3);
				}
				else
				{
					List<Pnt3D> list2 = new List<Pnt3D>();
					list2.Add(new Pnt3D(HatchLines2[l].Vertice[0]));
					list2.Add(new Pnt3D(HatchLines2[l].Vertice[1]));
					YVectorSurfPoint.Add(list2);
				}
			}
		}
		else
		{
			for (int m = 0; m <= HatchLines2.Count - 1; m++)
			{
				List<Pnt3D> Points4 = new List<Pnt3D>();
				Pnt3D pnt3D3 = new Pnt3D(HatchLines2[m].Vertice[0]);
				Pnt3D pnt3D4 = new Pnt3D(HatchLines2[m].Vertice[1]);
				Points4.Add(new Pnt3D(pnt3D3));
				for (int n = 0; n <= HatchLines.Count - 1; n++)
				{
					bool IsLineIntersect2 = false;
					bool IsIntersecPointInsideLines2 = false;
					Pnt3D IntersectionPoint2 = new Pnt3D();
					Pnt3D firstLineStartPoint2 = new Pnt3D(HatchLines[n].Vertice[0]);
					Pnt3D firstLineEndPoint2 = new Pnt3D(HatchLines[n].Vertice[1]);
					LineLineIntersection(firstLineStartPoint2, firstLineEndPoint2, pnt3D3, pnt3D4, new WorkPlane(), ref IntersectionPoint2, ref IsLineIntersect2, ref IsIntersecPointInsideLines2);
					if (IsLineIntersect2 && IsIntersecPointInsideLines2)
					{
						Points4.Add(new Pnt3D(IntersectionPoint2.X, IntersectionPoint2.Y));
					}
				}
				Points4.Add(new Pnt3D(pnt3D4));
				CheckDuplicatedPointsWithPrevious(ref Points4);
				YVectorSurfPoint.Add(Points4);
			}
		}
		if (XVectorSurfPoint.Count > 0)
		{
			Move(new Pnt3D(), new Pnt3D(0.0, 0.0, ZValue), ref XVectorSurfPoint);
		}
		if (YVectorSurfPoint.Count > 0)
		{
			Move(new Pnt3D(), new Pnt3D(0.0, 0.0, ZValue), ref YVectorSurfPoint);
		}
	}

	public void SurfaceBsplineKnotVector(List<Pnt3D>[] ControlPoints, double du, double dw, ref List<Triangle3D> Triangles, ref List<Pnt3D>[] GridPoints)
	{
		List<int> knotVector = new List<int>();
		List<int> knotVector2 = new List<int>();
		List<double> list = new List<double>();
		List<double> list2 = new List<double>();
		List<Pnt3D> list3 = new List<Pnt3D>();
		Pnt3D pnt3D = new Pnt3D();
		int num = 0;
		double num2 = 0.0;
		double num3 = 0.0;
		double num4 = 0.0;
		list3.Clear();
		int num5 = Convert.ToInt32(1.0 / du);
		int num6 = Convert.ToInt32(1.0 / dw);
		KnotBSpline(ControlPoints.Length, ControlPoints.Length, knotVector);
		GridPoints = new List<Pnt3D>[num5 + 1];
		for (int i = 0; i <= num5; i++)
		{
			GridPoints[i] = new List<Pnt3D>();
			double parameter = (double)i * du;
			for (int j = 0; j <= num6; j++)
			{
				double num7 = (double)j * dw;
				num7 = ((num % 2 == 0) ? ((double)j * dw) : (1.0 - (double)j * dw));
				BasisBSpline(ControlPoints.Length, parameter, ControlPoints.Length, knotVector, list);
				num2 = 0.0;
				num3 = 0.0;
				num4 = 0.0;
				for (int k = 0; k <= ControlPoints.Length - 1; k++)
				{
					if (list[k] == 0.0)
					{
						continue;
					}
					KnotBSpline(ControlPoints[k].Count, ControlPoints[k].Count, knotVector2);
					BasisBSpline(ControlPoints[k].Count, num7, ControlPoints[k].Count, knotVector2, list2);
					for (int l = 0; l <= ControlPoints[k].Count - 1; l++)
					{
						if (list2[l] != 0.0)
						{
							num2 += ControlPoints[k][l].X * list[k] * list2[l];
							num3 += ControlPoints[k][l].Y * list[k] * list2[l];
							num4 += ControlPoints[k][l].Z * list[k] * list2[l];
						}
					}
				}
				pnt3D.X = num2;
				pnt3D.Y = num3;
				pnt3D.Z = num4;
				list3.Add(pnt3D);
				GridPoints[i].Add(pnt3D);
			}
			if (num % 2 == 0)
			{
				GridPoints[i].Reverse();
			}
			if (i > 0)
			{
				for (int m = 1; m <= GridPoints[i].Count - 1; m++)
				{
					Quad3D quad3D = new Quad3D();
					Triangle3D FirstTriangle = new Triangle3D();
					Triangle3D SecondTriangle = new Triangle3D();
					quad3D.FirstPoint = GridPoints[i - 1][m - 1];
					quad3D.SecondPoint = GridPoints[i - 1][m];
					quad3D.ThirdPoint = GridPoints[i][m];
					quad3D.FourthPoint = GridPoints[i][m - 1];
					QuadToTriangle(quad3D, ref FirstTriangle, ref SecondTriangle);
					Triangles.Add(FirstTriangle);
					Triangles.Add(SecondTriangle);
				}
			}
			num++;
		}
	}

	public void SurfaceBsplineRationalKnotVector(List<Pnt3D>[] ControlPoints, List<double>[] Weigths, double du, double dw, ref List<Triangle3D> Triangles, ref List<Pnt3D>[] GridPoints)
