		list.Clear();
		int num6 = Convert.ToInt32(1.0 / du);
		int num7 = Convert.ToInt32(1.0 / dw);
		KnotBSpline(ControlPoints[0].Count, Order, knotVector);
		GridPoints = new List<Pnt3D>[num6 + 1];
		for (int i = 0; i <= num6; i++)
		{
			GridPoints[i] = new List<Pnt3D>();
			double parameter = (double)i * du;
			for (int j = 0; j <= num7; j++)
			{
				double num8 = (double)j * dw;
				num8 = ((num % 2 == 0) ? ((double)j * dw) : (1.0 - (double)j * dw));
				BasisBSpline(Order, parameter, ControlPoints[0].Count, knotVector, list2);
				num2 = 0.0;
				num3 = 0.0;
				num4 = 0.0;
				for (int k = 0; k <= ControlPoints.Length - 1; k++)
				{
					if (list2[k] == 0.0)
					{
						continue;
					}
					KnotBSpline(ControlPoints[k].Count, Order, knotVector2);
					BasisBSpline(Order, num8, ControlPoints[k].Count, knotVector2, list3);
					num5 = SumRegionalBasic(ControlPoints.Length, ControlPoints[k].Count, list2, list3, Weigths[k]);
					for (int l = 0; l <= ControlPoints[k].Count - 1; l++)
					{
						if (list3[l] != 0.0)
						{
							num2 += ControlPoints[k][l].X * list2[k] * list3[l] / num5;
							num3 += ControlPoints[k][l].Y * list2[k] * list3[l] / num5;
							num4 += ControlPoints[k][l].Z * list2[k] * list3[l] / num5;
						}
					}
				}
				pnt3D.X = num2;
				pnt3D.Y = num3;
				pnt3D.Z = num4;
				list.Add(pnt3D);
				GridPoints[i].Add(pnt3D);
			}
			if (num % 2 == 0)
			{
				GridPoints[i].Reverse();
			}
			if (i > 0)
			{
				for (int m = 1; m <= GridPoints[i].Count - 1; m++)
				{
					Quad3D quad3D = new Quad3D();
					Triangle3D FirstTriangle = new Triangle3D();
					Triangle3D SecondTriangle = new Triangle3D();
					quad3D.FirstPoint = GridPoints[i - 1][m - 1];
					quad3D.SecondPoint = GridPoints[i - 1][m];
					quad3D.ThirdPoint = GridPoints[i][m];
					quad3D.FourthPoint = GridPoints[i][m - 1];
					QuadToTriangle(quad3D, ref FirstTriangle, ref SecondTriangle);
					Triangles.Add(FirstTriangle);
					Triangles.Add(SecondTriangle);
				}
			}
			num++;
		}
	}

	public void SurfaceExtrudeByPoints(List<Pnt3D> Points, Vec3D Direction, double Length, bool CloseSides, ref List<Triangle3D> Triangles)
	{
		List<List<Pnt3D>> ProfilePoints = new List<List<Pnt3D>>();
