	}

	public void SurfaceExtrudeByPoints(List<Pnt3D> Points, Vec3D Direction, double Length, bool CloseSides, ref List<Triangle3D> Triangles, ref List<List<Pnt3D>> ProfilePoints)
	{
		bool flag = IsClosed(Points);
		double angle = PointAngle(new Pnt3D(Direction.X, Direction.Y, Direction.Z), new Pnt3D());
		new Vec3D();
		Vec3D.Normalise(Direction);
		new OrientationAngle();
		Vector3dToOrientationAngle(Direction);
		ProfilePoints.Clear();
		ProfilePoints = new List<List<Pnt3D>>();
		for (int i = 1; i <= Points.Count - 1; i++)
		{
			List<Pnt3D> list = new List<Pnt3D>();
			Triangle3D FirstTriangle = new Triangle3D();
			Triangle3D SecondTriangle = new Triangle3D();
			Pnt3D EndPnt = new Pnt3D();
			Pnt3D EndPnt2 = new Pnt3D();
			LineWithLengthAndAngle(Points[i - 1], Length, angle, new WorkPlane(), ref EndPnt);
			LineWithLengthAndAngle(Points[i], Length, angle, new WorkPlane(), ref EndPnt2);
			Quad3D quad = new Quad3D(Points[i - 1], Points[i], EndPnt2, EndPnt);
			if (i == 1)
			{
				list.Add(new Pnt3D(Points[i - 1]));
				list.Add(new Pnt3D(EndPnt));
				ProfilePoints.Add(list);
			}
			list = new List<Pnt3D>();
			list.Add(new Pnt3D(Points[i]));
			list.Add(new Pnt3D(EndPnt2));
			ProfilePoints.Add(list);
			QuadToTriangle(quad, ref FirstTriangle, ref SecondTriangle);
			Triangles.Add(FirstTriangle);
			Triangles.Add(SecondTriangle);
		}
		if (!(flag && CloseSides))
		{
			return;
		}
		TriangulationPoints calcData = new TriangulationPoints();
		SurfaceFromXYPlane surfaceFromXYPlane = new SurfaceFromXYPlane();
		surfaceFromXYPlane.Height = Length;
		SurfaceFromTriangulation(Points, new List<List<Pnt3D>>(), surfaceFromXYPlane, ref calcData);
		if (calcData.Triangles.Count > 0)
		{
			for (int j = 0; j <= calcData.Triangles.Count - 1; j++)
			{
				Triangle3D item = new Triangle3D(calcData.Triangles[j]);
				Triangles.Add(item);
			}
		}
	}

	public void SurfaceProfileFromContour(List<Pnt3D> Points, Pnt3D RefPoint, SurfaceByVector surfData, ref List<Triangle3D> Triangles, ref List<List<Pnt3D>> ProfilePoints)
	{
		WorkPlane PlaneFound = new WorkPlane();
		Triangles.Clear();
		Triangles = new List<Triangle3D>();
		GetPointsPlane(Points, ref PlaneFound);
		if (!IsClosed(Points))
		{
			if (!(surfData.BaseHeight <= 0.0))
			{
				Pnt3D pnt3D = new Pnt3D(Points[0]);
				Pnt3D pnt3D2 = new Pnt3D(Points[Points.Count - 1]);
				if (WorkPlane.isPlaneXY(PlaneFound))
				{
					pnt3D.Y -= surfData.BaseHeight;
					pnt3D2.Y -= surfData.BaseHeight;
				}
				if (WorkPlane.isPlaneXZ(PlaneFound) | WorkPlane.isPlaneYZ(PlaneFound))
				{
					pnt3D.Z -= surfData.BaseHeight;
					pnt3D2.Z -= surfData.BaseHeight;
				}
				Points.Insert(0, pnt3D);
				Points.Add(pnt3D2);
				Points.Add(new Pnt3D(pnt3D));
			}
			else
			{
				Pnt3D item = new Pnt3D(Points[0]);
				Points.Add(item);
			}
		}
		Pnt3D MinPoint = new Pnt3D();
		Pnt3D MaxPoint = new Pnt3D();
		Pnt3D MidPoint = new Pnt3D();
		BoxSizeCalculate(Points, ref MinPoint, ref MidPoint, ref MaxPoint);
		if (WorkPlane.isPlaneXY(PlaneFound) & (surfData.Direction == VectorType.YVector))
		{
			RotateByMatrix(MinPoint, 90.0, VectorType.XVector, ref Points);
		}
		if (WorkPlane.isPlaneXY(PlaneFound) & (surfData.Direction == VectorType.XVector))
		{
			RotateByMatrix(MinPoint, 90.0, VectorType.XVector, ref Points);
			RotateByMatrix(MinPoint, 90.0, VectorType.ZVector, ref Points);
		}
		if (WorkPlane.isPlaneXZ(PlaneFound) & (surfData.Direction == VectorType.ZVector))
		{
			RotateByMatrix(MinPoint, -90.0, VectorType.XVector, ref Points);
		}
		MinPoint = new Pnt3D();
		MaxPoint = new Pnt3D();
		MidPoint = new Pnt3D();
		BoxSizeCalculate(Points, ref MinPoint, ref MidPoint, ref MaxPoint);
		Move(MinPoint, RefPoint, ref Points);
		new TriangulationPoints();
		Vec3D direction = new Vec3D(1.0, 0.0, 0.0);
		if (surfData.Direction == VectorType.XVector)
		{
			direction = new Vec3D(1.0, 0.0, 0.0);
		}
		if (surfData.Direction == VectorType.YVector)
		{
			direction = new Vec3D(0.0, 1.0, 0.0);
		}
		if (surfData.Direction == VectorType.ZVector)
		{
			direction = new Vec3D(0.0, 0.0, 1.0);
		}
		SurfaceExtrudeByPoints(Points, direction, surfData.Length, CloseSides: true, ref Triangles, ref ProfilePoints);
	}

