	public void SurfaceFromTriangulation(List<Pnt3D> ContourPoints, List<List<Pnt3D>> InnerContour, SurfaceFromXYPlane SurfData, ref TriangulationPoints calcData)
	{
		TriangulationPoints triangulationPoints = new TriangulationPoints();
		new TriangulationPoints();
		Pnt3D pnt3D = new Pnt3D(ContourPoints[0]);
		WorkPlane PlaneFound = new WorkPlane();
		GetPointsPlane(ContourPoints, ref PlaneFound);
		if (WorkPlane.isPlaneXZ(PlaneFound))
		{
			for (int i = 0; i <= ContourPoints.Count - 1; i++)
			{
				Pnt3D CalcPoint = new Pnt3D();
				PointConversionByPlane(PlaneFound, new WorkPlane(planeType.XY, 1), ContourPoints[i], ref CalcPoint);
				ContourPoints[i] = new Pnt3D(CalcPoint);
			}
		}
		if (WorkPlane.isPlaneYZ(PlaneFound))
		{
			for (int j = 0; j <= ContourPoints.Count - 1; j++)
			{
				Pnt3D CalcPoint2 = new Pnt3D();
				PointConversionByPlane(PlaneFound, new WorkPlane(planeType.XY, 1), ContourPoints[j], ref CalcPoint2);
				ContourPoints[j] = new Pnt3D(CalcPoint2);
			}
		}
		calcData = new TriangulationPoints();
		Pnt3D.Copy(ContourPoints, ref triangulationPoints.Points);
		Pnt3D.Copy(InnerContour, ref triangulationPoints.Holes);
		Triangulation(triangulationPoints, MoveToZeroPoint: false, ref calcData);
		if (WorkPlane.isPlaneXZ(PlaneFound) | WorkPlane.isPlaneYZ(PlaneFound))
		{
			for (int k = 0; k <= calcData.Points.Count - 1; k++)
			{
				Pnt3D CalcPoint3 = new Pnt3D();
				PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Points[k], ref CalcPoint3);
				calcData.Points[k] = new Pnt3D(CalcPoint3);
			}
			for (int l = 0; l <= calcData.Holes.Count - 1; l++)
			{
				for (int m = 0; m <= calcData.Holes[l].Count - 1; m++)
				{
					Pnt3D CalcPoint4 = new Pnt3D();
					PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Holes[l][m], ref CalcPoint4);
					calcData.Holes[l][m] = new Pnt3D(CalcPoint4);
				}
			}
			for (int n = 0; n <= calcData.Triangles.Count - 1; n++)
			{
				Pnt3D CalcPoint5 = new Pnt3D();
				Pnt3D CalcPoint6 = new Pnt3D();
				Pnt3D CalcPoint7 = new Pnt3D();
				PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Triangles[n].FirstPoint, ref CalcPoint5);
				calcData.Triangles[n].FirstPoint = new Pnt3D(CalcPoint5);
				PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Triangles[n].SecondPoint, ref CalcPoint6);
				calcData.Triangles[n].SecondPoint = new Pnt3D(CalcPoint6);
				PointConversionByPlane(new WorkPlane(planeType.XY, 1), PlaneFound, calcData.Triangles[n].ThirdPoint, ref CalcPoint7);
				calcData.Triangles[n].ThirdPoint = new Pnt3D(CalcPoint7);
			}
			if (WorkPlane.isPlaneYZ(PlaneFound))
			{
				Pnt3D pnt3D2 = new Pnt3D(calcData.Points[0]);
				Move(new Pnt3D(pnt3D2.X, 0.0), new Pnt3D(pnt3D.X, 0.0), ref calcData.Points);
				Move(new Pnt3D(pnt3D2.X, 0.0), new Pnt3D(pnt3D.X, 0.0), ref calcData.Holes);
				Move(new Pnt3D(pnt3D2.X, 0.0), new Pnt3D(pnt3D.X, 0.0), ref calcData.Triangles);
			}
			if (WorkPlane.isPlaneXZ(PlaneFound))
			{
				Pnt3D pnt3D3 = new Pnt3D(calcData.Points[0]);
				Move(new Pnt3D(0.0, pnt3D3.Y, 0.0), new Pnt3D(0.0, pnt3D.Y, 0.0), ref calcData.Points);
				Move(new Pnt3D(0.0, pnt3D3.Y, 0.0), new Pnt3D(0.0, pnt3D.Y, 0.0), ref calcData.Holes);
				Move(new Pnt3D(0.0, pnt3D3.Y, 0.0), new Pnt3D(0.0, pnt3D.Y, 0.0), ref calcData.Triangles);
			}
		}
		List<Triangle3D> CopiedPnt = new List<Triangle3D>();
		Triangle3D.Copy(calcData.Triangles, ref CopiedPnt);
		if (SurfData.Height == 0.0)
		{
			return;
		}
		if (WorkPlane.isPlaneXY(PlaneFound))
		{
			for (int num = 0; num <= CopiedPnt.Count - 1; num++)
			{
				Triangle3D Triangle = new Triangle3D(CopiedPnt[num]);
				Move(new Pnt3D(), new Pnt3D(0.0, 0.0, SurfData.Height), ref Triangle);
				calcData.Triangles.Add(Triangle);
			}
			List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
			Pnt3D.Copy(calcData.Points, ref CopiedPnt2);
			Pnt3D.Offset(ref CopiedPnt2, 0.0, 0.0, SurfData.Height);
			List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
			SurfaceWithTwoVerticeList(calcData.Points, CopiedPnt2, ref SurfaceTriangles);
			Triangle3D.Add(SurfaceTriangles, ref calcData.Triangles);
		}
		if (WorkPlane.isPlaneXZ(PlaneFound))
		{
			for (int num2 = 0; num2 <= CopiedPnt.Count - 1; num2++)
			{
				Triangle3D Triangle2 = new Triangle3D(CopiedPnt[num2]);
				Move(new Pnt3D(), new Pnt3D(0.0, SurfData.Height, 0.0), ref Triangle2);
				calcData.Triangles.Add(Triangle2);
			}
			List<Pnt3D> CopiedPnt3 = new List<Pnt3D>();
			Pnt3D.Copy(calcData.Points, ref CopiedPnt3);
			Pnt3D.Offset(ref CopiedPnt3, 0.0, SurfData.Height, 0.0);
			List<Triangle3D> SurfaceTriangles2 = new List<Triangle3D>();
			SurfaceWithTwoVerticeList(calcData.Points, CopiedPnt3, ref SurfaceTriangles2);
			Triangle3D.Add(SurfaceTriangles2, ref calcData.Triangles);
		}
		if (WorkPlane.isPlaneYZ(PlaneFound))
		{
			for (int num3 = 0; num3 <= CopiedPnt.Count - 1; num3++)
			{
				Triangle3D Triangle3 = new Triangle3D(CopiedPnt[num3]);
				Move(new Pnt3D(), new Pnt3D(SurfData.Height, 0.0, 0.0), ref Triangle3);
				calcData.Triangles.Add(Triangle3);
			}
			List<Pnt3D> CopiedPnt4 = new List<Pnt3D>();
			Pnt3D.Copy(calcData.Points, ref CopiedPnt4);
			Pnt3D.Offset(ref CopiedPnt4, SurfData.Height, 0.0, 0.0);
			List<Triangle3D> SurfaceTriangles3 = new List<Triangle3D>();
			SurfaceWithTwoVerticeList(calcData.Points, CopiedPnt4, ref SurfaceTriangles3);
			Triangle3D.Add(SurfaceTriangles3, ref calcData.Triangles);
		}
	}

	public void TrimGridPointsFromContourPoints(List<Pnt3D> ContourPoints, ref List<List<Pnt3D>> XDirPoints, ref List<List<Pnt3D>> YDirPoints)
	{
		List<List<Pnt3D>> list = new List<List<Pnt3D>>();
		List<List<Pnt3D>> list2 = new List<List<Pnt3D>>();
		for (int i = 0; i <= XDirPoints.Count - 1; i++)
		{
			List<Pnt3D> Points = new List<Pnt3D>();
			for (int j = 0; j <= XDirPoints[i].Count - 1; j++)
			{
				Pnt3D pnt3D = new Pnt3D(XDirPoints[i][j]);
				if (IsPointInsidePolygon(ContourPoints, pnt3D, CheckOver: true))
				{
					Points.Add(pnt3D);
				}
			}
			if (Points.Count > 0)
			{
				for (int k = 1; k <= ContourPoints.Count - 1; k++)
				{
					Pnt3D IntersectionPoint = new Pnt3D();
					LineLineIntersection(ContourPoints[k - 1], ContourPoints[k], Points[0], Points[1], new WorkPlane(), ref IntersectionPoint);
					if (IsPointOverAndInsideLine(ContourPoints[k - 1], ContourPoints[k], IntersectionPoint, new WorkPlane(), 0.01) && IntersectionPoint.X < Points[0].X)
					{
						Points.Insert(0, IntersectionPoint);
					}
					IntersectionPoint = new Pnt3D();
					LineLineIntersection(ContourPoints[k - 1], ContourPoints[k], Points[Points.Count - 2], Points[Points.Count - 1], new WorkPlane(), ref IntersectionPoint);
					if (IsPointOverAndInsideLine(ContourPoints[k - 1], ContourPoints[k], IntersectionPoint, new WorkPlane(), 0.01) && IntersectionPoint.X > Points[Points.Count - 1].X)
					{
						Points.Add(IntersectionPoint);
					}
				}
			}
			CheckDuplicatedPointsWithPrevious(ref Points);
			if (Points.Count > 1)
			{
				list.Add(Points);
			}
		}
		for (int l = 0; l <= YDirPoints.Count - 1; l++)
		{
			List<Pnt3D> Points2 = new List<Pnt3D>();
			for (int m = 0; m <= YDirPoints[l].Count - 1; m++)
			{
				Pnt3D pnt3D2 = new Pnt3D(YDirPoints[l][m]);
				if (IsPointInsidePolygon(ContourPoints, pnt3D2))
				{
					Points2.Add(pnt3D2);
				}
			}
			if (Points2.Count > 0)
			{
				for (int n = 1; n <= ContourPoints.Count - 1; n++)
				{
					Pnt3D IntersectionPoint2 = new Pnt3D();
					LineLineIntersection(ContourPoints[n - 1], ContourPoints[n], Points2[0], Points2[1], new WorkPlane(), ref IntersectionPoint2);
					if (IsPointOverAndInsideLine(ContourPoints[n - 1], ContourPoints[n], IntersectionPoint2, new WorkPlane(), 0.01) && IntersectionPoint2.Y < Points2[0].Y)
					{
						Points2.Insert(0, IntersectionPoint2);
					}
					IntersectionPoint2 = new Pnt3D();
					LineLineIntersection(ContourPoints[n - 1], ContourPoints[n], Points2[Points2.Count - 2], Points2[Points2.Count - 1], new WorkPlane(), ref IntersectionPoint2);
					if (IsPointOverAndInsideLine(ContourPoints[n - 1], ContourPoints[n], IntersectionPoint2, new WorkPlane(), 0.01) && IntersectionPoint2.Y > Points2[Points2.Count - 1].Y)
					{
						Points2.Add(IntersectionPoint2);
					}
				}
			}
			CheckDuplicatedPointsWithPrevious(ref Points2);
			if (Points2.Count > 1)
			{
				list2.Add(Points2);
			}
		}
		XDirPoints.Clear();
		XDirPoints = new List<List<Pnt3D>>();
		YDirPoints.Clear();
		YDirPoints = new List<List<Pnt3D>>();
		Pnt3D.Copy(list, ref XDirPoints);
		Pnt3D.Copy(list2, ref YDirPoints);
	}

	public void SurfaceRevolve(List<Pnt3D> RefPoints, Pnt3D RotatePoint, double StartAngle, double EndAngle, double AngleResolution, Vec3D RevolveDir, EntityResolution EntityResolution, ref List<Triangle3D> calcTriangles)
	{
		List<List<Pnt3D>> calcRevolvePoints = new List<List<Pnt3D>>();
		SurfaceRevolve(RefPoints, RotatePoint, StartAngle, EndAngle, AngleResolution, RevolveDir, EntityResolution, ref calcRevolvePoints, ref calcTriangles);
	}

	public void SurfaceRevolve(List<Pnt3D> RefPoints, Pnt3D RotatePoint, double StartAngle, double EndAngle, double AngleResolution, Vec3D RevolveDir, EntityResolution EntityResolution, ref List<List<Pnt3D>> calcRevolvePoints, ref List<Triangle3D> calcTriangles)
	{
		WorkPlane PlaneFound = new WorkPlane();
		double num = 0.0;
		double num2 = AngleResolution;
		int num3 = 1;
		List<Pnt3D> CopiedPnt = new List<Pnt3D>();
		calcRevolvePoints.Clear();
		calcTriangles.Clear();
		if (StartAngle > EndAngle)
		{
			return;
		}
		num = EndAngle - StartAngle;
		num3 = Convert.ToInt32(buNumeric.RoundToUpper(num / AngleResolution));
		num2 = num / Convert.ToDouble(num3);
		Pnt3D.Copy(RefPoints, ref CopiedPnt);
		GetPointsPlane(RefPoints, ref PlaneFound);
		Pnt3D MinPoint = new Pnt3D();
		Pnt3D MaxPoint = new Pnt3D();
		Pnt3D MidPoint = new Pnt3D();
		if (Vec3D.isVectorZAxis(RevolveDir))
		{
			RotateByMatrix(MinPoint, 90.0, VectorType.YVector, ref CopiedPnt);
			RotateByMatrix(MinPoint, 90.0, VectorType.XVector, ref CopiedPnt);
		}
		BoxSizeCalculate(CopiedPnt, ref MinPoint, ref MidPoint, ref MaxPoint);
		Move(CopiedPnt[0], new Pnt3D(), ref CopiedPnt);
		for (int i = 0; i <= num3; i++)
		{
			List<Pnt3D> CalcPoints = new List<Pnt3D>();
			if (Vec3D.isVectorYAxis(RevolveDir))
			{
				Rotate(RotatePoint, (double)i * num2, new WorkPlane(planeType.XZ, 1), CopiedPnt, ref CalcPoints);
				calcRevolvePoints.Add(CalcPoints);
			}
			if (Vec3D.isVectorZAxis(RevolveDir))
			{
				Rotate(RotatePoint, (double)i * num2, new WorkPlane(planeType.XY, 1), CopiedPnt, ref CalcPoints);
				calcRevolvePoints.Add(CalcPoints);
			}
			if (i > 0)
			{
				List<Triangle3D> SurfaceTriangles = new List<Triangle3D>();
				SurfaceWithTwoVerticeList(calcRevolvePoints[calcRevolvePoints.Count - 2], calcRevolvePoints[calcRevolvePoints.Count - 1], ref SurfaceTriangles);
				calcTriangles.AddRange(SurfaceTriangles);
			}
		}
	}

	public void WrapPointToCircle(double Radius, Pnt3D CenterPoint, WrapShapeParameter Pars, List<Pnt3D> RefPoints, ref List<Pnt3D> WrapedPoints)
	{
		if (RefPoints == null || RefPoints.Count == 0)
		{
			return;
		}
		List<Pnt4D> Vertices = new List<Pnt4D>();
		new List<Pnt3D>();
		EntityResolution entResolution = new EntityResolution(0.05, 10, 10.0, EntityResolutionType.ByLength);
		CircleWithCenter(CenterPoint, Radius, new WorkPlane(planeType.XY, 1), entResolution, ref Vertices);
		WrapedPoints = new List<Pnt3D>();
		if (Pars.CenterVector == VectorType.YVector)
		{
			for (int i = 0; i <= RefPoints.Count - 1; i++)
			{
				double calcAngle = 0.0;
				double num = 0.0;
				double num2 = 0.0;
				double num3 = 0.0;
				CirclePointAngleByLenght(Radius, RefPoints[i].X, ref calcAngle);
				num2 = RefPoints[i].Y;
				num = Radius * Math.Cos(buConversion.DegreeToRadian(calcAngle));
				num3 = Radius * Math.Sin(buConversion.DegreeToRadian(calcAngle));
				Pnt3D item = new Pnt3D(num, num2, num3);
				WrapedPoints.Add(item);
			}
		}
	}

	public void WrapPointToEllipse(double MajorRadius, double MinorRadius, Pnt3D CenterPoint, WrapShapeParameter Pars, List<List<Pnt3D>> RefPoints, double Resolution, ref List<List<Pnt3D>> WrapedPoints)
	{
		if (RefPoints != null && RefPoints.Count != 0)
		{
			WrapedPoints = new List<List<Pnt3D>>();
			for (int i = 0; i <= RefPoints.Count - 1; i++)
			{
				List<Pnt3D> CopiedPnt = new List<Pnt3D>();
				List<Pnt3D> WrapedPoints2 = new List<Pnt3D>();
				Pnt3D.Copy(RefPoints[i], ref CopiedPnt);
				WrapPointToEllipse(MajorRadius, MinorRadius, CenterPoint, Pars, CopiedPnt, Resolution, ref WrapedPoints2);
				WrapedPoints.Add(WrapedPoints2);
			}
		}
	}

	public void WrapPointToEllipse(double MajorRadius, double MinorRadius, Pnt3D CenterPoint, WrapShapeParameter Pars, List<Pnt3D> RefPoints, double Resolution, ref List<Pnt3D> WrapedPoints)
	{
		if (RefPoints == null || RefPoints.Count == 0)
		{
			return;
		}
		new List<Pnt4D>();
		new List<Pnt3D>();
		new EntityResolution(0.05, 10, 10.0, EntityResolutionType.ByLength);
		WrapedPoints = new List<Pnt3D>();
		if (Pars.CenterVector == VectorType.YVector)
		{
			for (int i = 0; i <= RefPoints.Count - 1; i++)
			{
				double calcAngle = 0.0;
				double num = 0.0;
				double num2 = 0.0;
				double num3 = 0.0;
				double num4 = 0.0;
				double num5 = 0.0;
				double num6 = 0.0;
				double num7 = 0.0;
				EllipsePointAngleByLenght(MajorRadius, MinorRadius, 0.0, RefPoints[i].X, Resolution, ref calcAngle);
				num5 = Math.PI * 2.0;
				num6 = Math.Sin(num5);
				num7 = Math.Cos(num5);
				num4 = buConversion.DegreeToRadianGreat360(calcAngle);
				num = MajorRadius * Math.Cos(num4);
				num2 = RefPoints[i].Y;
				num3 = MinorRadius * Math.Sin(num4);
				Pnt3D pnt3D = new Pnt3D();
				pnt3D.X = CenterPoint.X + num * num7 + num3 * num6;
				pnt3D.Y = num2;
				pnt3D.Z = CenterPoint.Z - num * num6 + num3 * num7;
				WrapedPoints.Add(pnt3D);
			}
		}
	}

	public void CreatEntityFromShapeData(ShapeData Data, WorkPlane Plane, ref eEntities Entity)
	{
		if (Data.GetType() == typeof(PointData))
		{
			PointData pointData = new PointData();
			pointData = (PointData)Data;
			Entity = new ePoint(pointData.StartPoint);
			Entity.Shape = new ShapeData();
			ShapeData.Copy(Data, ref Entity.Shape);
		}
		if (Data.GetType() == typeof(LineData))
		{
			LineData lineData = new LineData();
			lineData = (LineData)Data;
			new List<Pnt3D>();
			Pnt3D EndPnt = new Pnt3D();
			LineWithLengthAndAngle(lineData.StartPoint, lineData.Length, lineData.Angle, Plane, ref EndPnt);
			lineData.EndPoint = new Pnt3D(EndPnt);
			Entity = new eLine(lineData.StartPoint, EndPnt);
			Entity.Shape = new ShapeData();
			ShapeData.Copy(Data, ref Entity.Shape);
