		if (Data.GetType() == typeof(RectangleCornerData))
		{
			RectangleCornerData rectangleCornerData = new RectangleCornerData();
			rectangleCornerData = (RectangleCornerData)Data;
			List<Pnt3D> Vertices = new List<Pnt3D>();
			RectangleCorner(rectangleCornerData.CornerPoint, rectangleCornerData.Width, rectangleCornerData.Height, Plane, ref Vertices);
			Rotate(rectangleCornerData.CornerPoint, rectangleCornerData.Rotation, Plane, ref Vertices);
			Entity = new ePolyline(Vertices);
