		if (Data.GetType() == typeof(CircleCenterData))
		{
			CircleCenterData circleCenterData = new CircleCenterData();
			circleCenterData = (CircleCenterData)Data;
			List<Pnt3D> Vertices3 = new List<Pnt3D>();
