			List<Pnt3D> CalculatedPoints = new List<Pnt3D>();
			Barrel(barrelData.HeadCenterPoint, barrelData.HeadRadius, barrelData.Height, barrelData.Width, barrelData.Rotation, Reverse: false, Plane, buSystem.EntitiesResolution, ref CalculatedPoints);
			Entity = new ePolyline(CalculatedPoints);
			Entity.Shape = new ShapeData();
			ShapeData.Copy(Data, ref Entity.Shape);
		}
		if (Data.GetType() == typeof(EllipseCenterData))
		{
			EllipseCenterData ellipseCenterData = new EllipseCenterData();
			ellipseCenterData = (EllipseCenterData)Data;
			List<Pnt3D> Vertices4 = new List<Pnt3D>();
			EllipseWithCenter(ellipseCenterData.CenterPoint, ellipseCenterData.MajorRadius, ellipseCenterData.MinorRadius, ellipseCenterData.Rotation, Plane, new EntityResolution(), ref Vertices4);
			Entity = new eEllipse(ellipseCenterData.CenterPoint, ellipseCenterData.MajorRadius, ellipseCenterData.MinorRadius, ellipseCenterData.Rotation, Plane);
			Entity.Shape = new ShapeData();
			ShapeData.Copy(Data, ref Entity.Shape);
