		if (Data.GetType() == typeof(PolygonCenterData))
		{
			PolygonCenterData polygonCenterData = new PolygonCenterData();
			polygonCenterData = (PolygonCenterData)Data;
			List<Pnt3D> Vertices5 = new List<Pnt3D>();
			PolygonCenter(polygonCenterData.CenterPoint, polygonCenterData.Radius, polygonCenterData.Sides, Plane, ref Vertices5);
			Rotate(polygonCenterData.CenterPoint, polygonCenterData.Rotation, Plane, ref Vertices5);
			Entity = new ePolyline(Vertices5);
			Entity.Shape = new ShapeData();
			ShapeData.Copy(Data, ref Entity.Shape);
		}
		if (Data.GetType() == typeof(TriangleTwinData))
		{
			TriangleTwinData triangleTwinData = new TriangleTwinData();
			triangleTwinData = (TriangleTwinData)Data;
			List<Pnt3D> Vertices6 = new List<Pnt3D>();
			PolygonTriangleTwin(triangleTwinData.CenterPoint, triangleTwinData.Width, triangleTwinData.Height, Plane, ref Vertices6);
			Rotate(triangleTwinData.CenterPoint, triangleTwinData.Rotation, Plane, ref Vertices6);
			Entity = new ePolyline(Vertices6);
			Entity.Shape = new ShapeData();
			ShapeData.Copy(Data, ref Entity.Shape);
		}
		if (Data.GetType() == typeof(SlotData))
		{
			SlotData slotData = new SlotData();
			slotData = (SlotData)Data;
			List<Pnt3D> Vertices7 = new List<Pnt3D>();
			Slot(slotData.BasePoint, slotData.Width, slotData.Height, slotData.Rotation, Plane, new EntityResolution(), ref Vertices7);
			Entity = new ePolyline(Vertices7);
			Entity.Shape = new ShapeData();
			ShapeData.Copy(Data, ref Entity.Shape);
		}
		if (Data.GetType() == typeof(TextVectorData))
		{
			TextVectorData textVectorData = new TextVectorData();
			textVectorData = (TextVectorData)Data;
			List<TriangulationPoints> CalculatedPoints2 = new List<TriangulationPoints>();
			FontToVectorConvert(textVectorData.CenterPoint, textVectorData.Font, textVectorData.Text, Plane, new Pnt3D(), ref CalculatedPoints2);
			Entity = new ePolylineGroup();
			for (int i = 0; i <= CalculatedPoints2.Count - 1; i++)
			{
				Pnt3D.Add(CalculatedPoints2[i].Points, ref ((ePolylineGroup)Entity).GroupVertices);
				Pnt3D.Add(CalculatedPoints2[i].Holes, ref ((ePolylineGroup)Entity).InternalVertices);
			}
			Entity.Shape = new ShapeData();
			ShapeData.Copy(Data, ref Entity.Shape);
		}
	}

