	public void GetECamEntitiesWithBaseEntityIndexList(List<int> SelectedIndex, List<eEntities> RefEntities, ref List<eEntities> FoundECamEntities)
	{
		try
		{
			for (int i = 0; i <= SelectedIndex.Count - 1; i++)
			{
				for (int num = RefEntities.Count - 1; num >= 0; num--)
				{
					if (RefEntities[num].GetType() == typeof(eCam) && ((eCam)RefEntities[num]).BaseEntityIndex == SelectedIndex[i])
					{
						eEntities copiedEnt = new eEntities();
						eEntities.CopyEntity(RefEntities[num], ref copiedEnt);
						FoundECamEntities.Add(copiedEnt);
					}
				}
			}
		}
		catch (Exception)
		{
		}
	}

	public void CreateSurfaceGridFromTeachFile(SurfaceReadGridData Data, List<Pnt3D> TeachData, ref List<List<Pnt3D>> GridData)
	{
		Pnt3D MinPoint = new Pnt3D();
		Pnt3D MaxPoint = new Pnt3D();
		BoxSizeCalculate(TeachData, ref MinPoint, ref MaxPoint);
		new List<List<Pnt3D>>();
		List<List<Pnt3D>> YVectorSurfPoint = new List<List<Pnt3D>>();
		GridFromBoxsize(MinPoint, MaxPoint, new Vec3D(Data.GridDistance.X, Data.GridDistance.Y), 0.0, XEnable: true, YEnable: false, DevideLines: true, ref GridData, ref YVectorSurfPoint);
		for (int i = 0; i <= TeachData.Count - 1; i++)
		{
			int num = Convert.ToInt32(TeachData[i].X);
			int num2 = Convert.ToInt32(TeachData[i].Y);
			if (num2 <= GridData.Count - 1 && num <= GridData[num2].Count - 1)
			{
				GridData[num2][num] = new Pnt3D(GridData[num2][num].X, GridData[num2][num].Y, TeachData[i].Z);
			}
		}
		for (int j = 0; j <= GridData.Count - 1; j++)
		{
			double num3 = 0.0;
			for (int k = 0; k <= GridData[j].Count - 1; k++)
			{
				if (!buCompare.EQ(GridData[j][k].Z, 0.0, 0.001))
				{
					num3 = GridData[j][k].Z;
					k = GridData[j].Count;
				}
			}
			List<int> list = new List<int>();
			for (int l = 0; l <= GridData[j].Count - 1; l++)
			{
				if (!buCompare.EQ(GridData[j][l].Z, 0.0, 0.001))
				{
					double z = GridData[j][l].Z;
					if (list.Count > 0)
					{
						double num4 = z - num3;
						double num5 = num4 / (double)(list.Count + 1);
						for (int m = 0; m <= list.Count - 1; m++)
						{
							int index = list[m];
							GridData[j][index] = new Pnt3D(GridData[j][index].X, GridData[j][index].Y, GridData[j][index].Z + (double)(m + 1) * num5);
						}
						list.Clear();
					}
					num3 = GridData[j][l].Z;
				}
				else
				{
					list.Add(l);
					GridData[j][l] = new Pnt3D(GridData[j][l].X, GridData[j][l].Y, num3);
				}
			}
		}
		if (GridData.Count <= 0)
		{
			return;
		}
		int count = GridData[0].Count;
		for (int n = 0; n <= count - 1; n++)
		{
			double num6 = 0.0;
