	public void GetTangentAngleOfEntity(eEntities RefEntity, WorkPlane Plane, ref double StartAngle, ref double EndAngle)
	{
		if (!(RefEntity.GetType() == typeof(eArc)))
		{
			if (!(RefEntity.GetType() == typeof(eLine)))
			{
				if (!(RefEntity.GetType() == typeof(ePolyline)))
				{
					StartAngle = PointAngle(RefEntity.Vertice[1], RefEntity.Vertice[0], Plane);
					EndAngle = PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[RefEntity.Vertice.Count - 2], Plane);
				}
				else
				{
					StartAngle = PointAngle(RefEntity.Vertice[1], RefEntity.Vertice[0], Plane);
					EndAngle = PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[RefEntity.Vertice.Count - 2], Plane);
				}
			}
			else
			{
				StartAngle = PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[RefEntity.Vertice.Count - 2], Plane);
				EndAngle = StartAngle;
			}
		}
		else
		{
			StartAngle = ((eArc)RefEntity).StartAngle + 90.0;
			EndAngle = ((eArc)RefEntity).EndAngle + 90.0;
		}
	}

