	public void EntitiesGuideOffsetCalculate(List<eEntities> RefEntities, double Offset, WorkPlane Plane, double PlaneOffset, ref List<List<Pnt3D>> GuidePoints)
	{
		GuidePoints.Clear();
		for (int i = 0; i <= RefEntities.Count - 1; i++)
		{
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			Pnt3D.Copy(RefEntities[i].Vertice, ref CopiedPnt);
			if (IsClosed(CopiedPnt))
			{
				continue;
			}
			List<List<Pnt3D>> OffsetedPoints = new List<List<Pnt3D>>();
			OffsetContour(CopiedPnt, Math.Abs(Offset), OffsetCornerType.Chamfer, CamOpenContourType2.ClosedNoTips, Plane, PlaneOffset, ref OffsetedPoints);
			for (int j = 0; j <= OffsetedPoints.Count - 1; j++)
			{
				if (OffsetedPoints[j].Count > 1)
				{
					List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
					Pnt3D.Copy(OffsetedPoints[j], ref CopiedPnt2);
					GuidePoints.Add(CopiedPnt2);
				}
			}
		}
	}

