	public void EntityUpdateByLength(eEntities BaseEntity, double NewLength, StartPointType PointType, ref eEntities CalcEntity)
	{
		try
		{
			WorkPlane plane = new WorkPlane();
			if (BaseEntity.Vertice.Count <= 0)
			{
				return;
			}
			if (BaseEntity.GetType() == typeof(eLine))
			{
				if (PointType == StartPointType.Start)
				{
					double angle = PointAngle(BaseEntity.Vertice[0], BaseEntity.Vertice[1], plane);
					Pnt3D EndPnt = new Pnt3D();
					LineWithLengthAndAngle(BaseEntity.Vertice[1], NewLength, angle, plane, ref EndPnt);
					CalcEntity = new eLine(EndPnt, BaseEntity.Vertice[1], BaseEntity.dispThickness, BaseEntity.dispColor);
					CalcEntity.camDirections = BaseEntity.camDirections;
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
				if (PointType == StartPointType.End)
				{
					double angle2 = PointAngle(BaseEntity.Vertice[1], BaseEntity.Vertice[0], plane);
					Pnt3D EndPnt2 = new Pnt3D();
					LineWithLengthAndAngle(BaseEntity.Vertice[0], NewLength, angle2, plane, ref EndPnt2);
					CalcEntity = new eLine(BaseEntity.Vertice[0], EndPnt2, BaseEntity.dispThickness, BaseEntity.dispColor);
					CalcEntity.camDirections = BaseEntity.camDirections;
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
				if (PointType == StartPointType.StartAndEnd)
				{
					double angle3 = PointAngle(BaseEntity.Vertice[0], BaseEntity.Vertice[1], plane);
					Pnt3D EndPnt3 = new Pnt3D();
					LineWithLengthAndAngle(BaseEntity.Vertice[1], NewLength, angle3, plane, ref EndPnt3);
					double angle4 = PointAngle(BaseEntity.Vertice[1], BaseEntity.Vertice[0], plane);
					Pnt3D EndPnt4 = new Pnt3D();
					LineWithLengthAndAngle(BaseEntity.Vertice[0], NewLength, angle4, plane, ref EndPnt4);
					CalcEntity = new eLine(EndPnt3, EndPnt4, BaseEntity.dispThickness, BaseEntity.dispColor);
					CalcEntity.camDirections = BaseEntity.camDirections;
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
				CalcEntity.Update();
			}
			if (BaseEntity.GetType() == typeof(eArc))
			{
				eArc eArc2 = new eArc();
				eArc2 = (eArc)BaseEntity;
				double num = ArcCircumference(eArc2.Radius, 0.0, 360.0);
				double num2 = (BaseEntity.geoLength - NewLength) * 360.0 / num;
				if (PointType == StartPointType.Start)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
				if (PointType == StartPointType.End)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle, eArc2.EndAngle - num2, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
				if (PointType == StartPointType.StartAndEnd)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle - num2, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
				CalcEntity.Update();
			}
		}
		catch (Exception mSException)
		{
			string text = "BaseEntity: " + BaseEntity.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

