			}
			eArc eArc2 = new eArc();
			eArc2 = (eArc)BaseEntity;
			double num = ArcCircumference(eArc2.Radius, 0.0, 360.0);
			double num2 = CutLength * 360.0 / num;
			if (BaseEntity.camDirections == camPathDirectionType.Normal)
			{
				if (PointType == StartPointType.Start)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
				}
				if (PointType == StartPointType.End)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle, eArc2.EndAngle - num2, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
				}
			}
			if (BaseEntity.camDirections == camPathDirectionType.Reverse)
			{
				if (PointType == StartPointType.End)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
				}
				if (PointType == StartPointType.Start)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle, eArc2.EndAngle - num2, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
				}
			}
			if (PointType == StartPointType.StartAndEnd)
			{
				CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle - num2, eArc2.Plane);
				eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
			}
			CalcEntity.Update();
		}
		catch (Exception mSException)
		{
			string text = "BaseEntity: " + BaseEntity.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void EntityUpdateByLengthUsingCamDirection(eEntities BaseEntity, double CutLength, StartPointType PointType, WorkPlane Plane, ref eEntities CalcEntity)
	{
		try
		{
			if (BaseEntity.Vertice.Count <= 0)
			{
				return;
			}
			if (BaseEntity.GetType() == typeof(eLine))
			{
				if (BaseEntity.camDirections == camPathDirectionType.Normal)
				{
					if (PointType == StartPointType.Start)
					{
						double angle = PointAngle(BaseEntity.Vertice[1], BaseEntity.Vertice[0], Plane);
						Pnt3D EndPnt = new Pnt3D();
						LineWithLengthAndAngle(BaseEntity.Vertice[0], CutLength, angle, Plane, ref EndPnt);
						CalcEntity = new eLine(EndPnt, BaseEntity.Vertice[1], BaseEntity.dispThickness, BaseEntity.dispColor);
						eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
					}
					if (PointType == StartPointType.End)
					{
						double angle2 = PointAngle(BaseEntity.Vertice[0], BaseEntity.Vertice[1], Plane);
						Pnt3D EndPnt2 = new Pnt3D();
						LineWithLengthAndAngle(BaseEntity.Vertice[1], CutLength, angle2, Plane, ref EndPnt2);
						CalcEntity = new eLine(BaseEntity.Vertice[0], EndPnt2, BaseEntity.dispThickness, BaseEntity.dispColor);
						eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
					}
				}
				if (BaseEntity.camDirections == camPathDirectionType.Reverse)
				{
					if (PointType == StartPointType.Start)
					{
						double angle3 = PointAngle(BaseEntity.Vertice[0], BaseEntity.Vertice[1], Plane);
						Pnt3D EndPnt3 = new Pnt3D();
						LineWithLengthAndAngle(BaseEntity.Vertice[1], CutLength, angle3, Plane, ref EndPnt3);
						CalcEntity = new eLine(BaseEntity.Vertice[0], EndPnt3, BaseEntity.dispThickness, BaseEntity.dispColor);
						eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
					}
					if (PointType == StartPointType.End)
					{
						double angle4 = PointAngle(BaseEntity.Vertice[1], BaseEntity.Vertice[0], Plane);
						Pnt3D EndPnt4 = new Pnt3D();
						LineWithLengthAndAngle(BaseEntity.Vertice[0], CutLength, angle4, Plane, ref EndPnt4);
						CalcEntity = new eLine(EndPnt4, BaseEntity.Vertice[1], BaseEntity.dispThickness, BaseEntity.dispColor);
						eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
					}
				}
				if (PointType == StartPointType.StartAndEnd)
				{
					double angle5 = PointAngle(BaseEntity.Vertice[1], BaseEntity.Vertice[0], Plane);
					Pnt3D EndPnt5 = new Pnt3D();
					LineWithLengthAndAngle(BaseEntity.Vertice[0], CutLength, angle5, Plane, ref EndPnt5);
					double angle6 = PointAngle(BaseEntity.Vertice[0], BaseEntity.Vertice[1], Plane);
					Pnt3D EndPnt6 = new Pnt3D();
					LineWithLengthAndAngle(BaseEntity.Vertice[1], CutLength, angle6, Plane, ref EndPnt6);
					CalcEntity = new eLine(EndPnt5, EndPnt6, BaseEntity.dispThickness, BaseEntity.dispColor);
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
				CalcEntity.Update();
			}
			if (!(BaseEntity.GetType() == typeof(eArc)))
			{
				return;
			}
			eArc eArc2 = new eArc();
			eArc2 = (eArc)BaseEntity;
			double num = ArcCircumference(eArc2.Radius, 0.0, 360.0);
			double num2 = CutLength * 360.0 / num;
			if (BaseEntity.camDirections == camPathDirectionType.Normal)
			{
				if (PointType == StartPointType.Start)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
				if (PointType == StartPointType.End)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle, eArc2.EndAngle - num2, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
			}
			if (BaseEntity.camDirections == camPathDirectionType.Reverse)
			{
				if (PointType == StartPointType.End)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
				if (PointType == StartPointType.Start)
				{
					CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle, eArc2.EndAngle - num2, eArc2.Plane);
					eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
				}
			}
			if (PointType == StartPointType.StartAndEnd)
			{
				CalcEntity = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle + num2, eArc2.EndAngle - num2, eArc2.Plane);
				eEntities.CopyCommonPorperties(BaseEntity, GeometryThings: false, DisplayThings: true, CamThings: true, ref CalcEntity);
			}
			CalcEntity.Update();
		}
		catch (Exception mSException)
		{
			string text = "BaseEntity: " + BaseEntity.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void EntityUpdateByNewPoint(eEntities BaseEntity, Pnt3D CatchPoint, Pnt3D NewPoint, ref eEntities CalcEntity, ref List<Pnt3D> Vertices)
	{
		if (BaseEntity.Vertice.Count <= 0)
		{
			return;
		}
		if (BaseEntity.GetType() == typeof(ePoint))
		{
			Move(BaseEntity.Vertice[0], NewPoint, BaseEntity, ref CalcEntity);
		}
		if (BaseEntity.GetType() == typeof(eLine))
		{
			if (BaseEntity.Vertice[0] == CatchPoint)
			{
				CalcEntity = new eLine(NewPoint, BaseEntity.Vertice[BaseEntity.Vertice.Count - 1]);
				eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
			}
			if (BaseEntity.Vertice[BaseEntity.Vertice.Count - 1] == CatchPoint)
			{
				CalcEntity = new eLine(BaseEntity.Vertice[0], NewPoint);
				eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(ePolyline))
		{
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			Pnt3D.Copy(BaseEntity.Vertice, ref CopiedPnt);
			for (int i = 0; i <= CopiedPnt.Count - 1; i++)
			{
				if (CopiedPnt[i] == CatchPoint)
				{
					CopiedPnt[i] = new Pnt3D(NewPoint);
				}
			}
			CalcEntity = new ePolyline(CopiedPnt);
			eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
		}
		if (BaseEntity.GetType() == typeof(eArc))
		{
			eArc eArc2 = new eArc((eArc)BaseEntity);
			if (eArc2.CenterPoint == CatchPoint)
			{
				Move(eArc2.CenterPoint, NewPoint, BaseEntity, ref CalcEntity);
			}
			if (eArc2.StartPoint == CatchPoint)
			{
				Pnt3D Center = new Pnt3D();
				double Radius = 0.0;
				double StartAngle = 0.0;
				double EndAngle = 0.0;
				Arc3Point(NewPoint, eArc2.MiddlePoint, eArc2.EndPoint, eArc2.Plane, ref Center, ref Radius, ref StartAngle, ref EndAngle);
				CalcEntity = new eArc(Center, Radius, StartAngle, EndAngle, eArc2.Plane);
				eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
			}
			if (eArc2.MiddlePoint == CatchPoint)
			{
				Pnt3D Center2 = new Pnt3D();
				double Radius2 = 0.0;
				double StartAngle2 = 0.0;
				double EndAngle2 = 0.0;
				Arc3Point(eArc2.StartPoint, NewPoint, eArc2.EndPoint, eArc2.Plane, ref Center2, ref Radius2, ref StartAngle2, ref EndAngle2);
				CalcEntity = new eArc(Center2, Radius2, StartAngle2, EndAngle2, eArc2.Plane);
				eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
			}
			if (eArc2.EndPoint == CatchPoint)
			{
				Pnt3D Center3 = new Pnt3D();
				double Radius3 = 0.0;
				double StartAngle3 = 0.0;
				double EndAngle3 = 0.0;
				Arc3Point(eArc2.StartPoint, eArc2.MiddlePoint, NewPoint, eArc2.Plane, ref Center3, ref Radius3, ref StartAngle3, ref EndAngle3);
				CalcEntity = new eArc(Center3, Radius3, StartAngle3, EndAngle3, eArc2.Plane);
				eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(eCircle))
		{
			eCircle eCircle2 = new eCircle((eCircle)BaseEntity);
			if (eCircle2.CenterPoint == CatchPoint)
			{
				Move(eCircle2.CenterPoint, NewPoint, BaseEntity, ref CalcEntity);
			}
			if (eCircle2.Vertice[0] == CatchPoint)
			{
				double radius = Length3D(NewPoint, eCircle2.CenterPoint);
				CalcEntity = new eCircle(eCircle2.CenterPoint, radius, eCircle2.Plane);
				eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(eEllipse))
		{
			eEllipse eEllipse2 = new eEllipse((eEllipse)BaseEntity);
			if (eEllipse2.CenterPoint == CatchPoint)
			{
				Move(eEllipse2.CenterPoint, NewPoint, BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(eEllipseArc))
		{
			eEllipseArc eEllipseArc2 = new eEllipseArc((eEllipseArc)BaseEntity);
			if (eEllipseArc2.CenterPoint == CatchPoint)
			{
				Move(eEllipseArc2.CenterPoint, NewPoint, BaseEntity, ref CalcEntity);
			}
		}
		if (BaseEntity.GetType() == typeof(eBezeir))
		{
			eBezeir eBezeir2 = new eBezeir((eBezeir)BaseEntity);
			List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
			Pnt3D.Copy(eBezeir2.ControlPoints, ref CopiedPnt2);
			for (int j = 0; j <= CopiedPnt2.Count - 1; j++)
			{
				if (CopiedPnt2[j] == CatchPoint)
				{
					CopiedPnt2[j] = new Pnt3D(NewPoint);
				}
			}
			CalcEntity = new eBezeir(CopiedPnt2);
			eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
		}
		if (BaseEntity.GetType() == typeof(eBSpline))
		{
			eBSpline eBSpline2 = new eBSpline((eBSpline)BaseEntity);
			List<Pnt3D> CopiedPnt3 = new List<Pnt3D>();
			Pnt3D.Copy(eBSpline2.ControlPoints, ref CopiedPnt3);
			for (int k = 0; k <= CopiedPnt3.Count - 1; k++)
			{
				if (CopiedPnt3[k] == CatchPoint)
				{
					CopiedPnt3[k] = new Pnt3D(NewPoint);
				}
			}
			CalcEntity = new eBSpline(CopiedPnt3, eBSpline2.bClosed, eBSpline2.BType);
			eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
		}
		if (BaseEntity.GetType() == typeof(ePicture))
		{
			ePicture ePicture2 = new ePicture((ePicture)BaseEntity);
			List<Pnt3D> CopiedPnt4 = new List<Pnt3D>();
			Pnt3D.Copy(BaseEntity.Vertice, ref CopiedPnt4);
			for (int l = 0; l <= CopiedPnt4.Count - 1; l++)
			{
				if (CopiedPnt4[l] == CatchPoint)
				{
					CopiedPnt4[l] = new Pnt3D(NewPoint);
				}
			}
			Pnt3D MinPoint = new Pnt3D();
			Pnt3D MaxPoint = new Pnt3D();
			BoxSizeCalculate(CopiedPnt4, ref MinPoint, ref MaxPoint);
			CalcEntity = new ePicture(MinPoint, MaxPoint, ePicture2.PicturePath);
			eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
		}
		if (BaseEntity.GetType() == typeof(eText))
		{
			new eText((eText)BaseEntity);
			Move(BaseEntity.Vertice[0], NewPoint, BaseEntity, ref CalcEntity);
			eEntities.CopyCommonPorperties(BaseEntity, ref CalcEntity);
		}
		Vertices = new List<Pnt3D>();
		Pnt3D.Copy(CalcEntity.Vertice, ref Vertices);
	}

	public void EntityUpdateByNewPoint(eEntities BaseEntity, Pnt3D CatchPoint, Pnt3D NewPoint, ref List<Pnt3D> Vertices)
	{
		eEntities CalcEntity = new eEntities();
		EntityUpdateByNewPoint(BaseEntity, CatchPoint, NewPoint, ref CalcEntity, ref Vertices);
	}

	public void EntityLengthModify(eEntities RefEntity, StartPointType ModifyDirType, double ModifyLength, ref eEntities ModifiedEntity)
	{
		ModifiedEntity = new eEntities();
		double cutLength = ModifyLength / Math.Cos(buConversion.DegreeToRadian(RefEntity.Orientation.A));
		if (ModifyDirType == StartPointType.Start)
		{
			if (RefEntity.camDirections != camPathDirectionType.Normal)
			{
				EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), cutLength, StartPointType.End, new WorkPlane(), ref ModifiedEntity);
			}
			else
			{
				EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), cutLength, StartPointType.Start, new WorkPlane(), ref ModifiedEntity);
			}
		}
		if (ModifyDirType == StartPointType.End)
		{
			if (RefEntity.camDirections != camPathDirectionType.Normal)
			{
				EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), cutLength, StartPointType.Start, new WorkPlane(), ref ModifiedEntity);
			}
			else
			{
				EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), cutLength, StartPointType.End, new WorkPlane(), ref ModifiedEntity);
			}
		}
		if (ModifyDirType == StartPointType.StartAndEnd)
		{
			EntityUpdateByLengthUsingCamDirection(eEntities.CopyEntity(RefEntity), cutLength, StartPointType.StartAndEnd, new WorkPlane(), ref ModifiedEntity);
		}
		ModifiedEntity.bCamSelected = false;
		ModifiedEntity.bSelected = false;
	}

	public void EntityCornerModifyByConvexConcave(eEntities FirstEntity, eEntities LastEntity, ClockDirectionType ClockDir, bool ReverseThetaCalculation, double ModifyLength, ref eEntities ModifiedFirstEntity, ref eEntities ModifiedLastEntity)
	{
		ModifiedFirstEntity = new eEntities();
		ModifiedLastEntity = new eEntities();
		bool isTouch = false;
		StartEndType FirstEntityTouchPoint = StartEndType.Start;
		StartEndType SecondEntityTouchPoint = StartEndType.Start;
		EntityEntityTouchPoint(FirstEntity, LastEntity, 0.01, ref isTouch, ref FirstEntityTouchPoint, ref SecondEntityTouchPoint);
		Pnt3D pnt3D = new Pnt3D();
		Pnt3D pnt3D2 = new Pnt3D();
		Pnt3D pnt3D3 = new Pnt3D();
		Pnt3D pnt3D4 = new Pnt3D();
		if (FirstEntityTouchPoint != StartEndType.End)
		{
			pnt3D = new Pnt3D(FirstEntity.Vertice[0]);
			pnt3D2 = new Pnt3D(FirstEntity.Vertice[1]);
		}
		else
		{
			pnt3D = new Pnt3D(FirstEntity.Vertice[FirstEntity.Vertice.Count - 1]);
			pnt3D2 = new Pnt3D(FirstEntity.Vertice[FirstEntity.Vertice.Count - 2]);
		}
		if (SecondEntityTouchPoint != StartEndType.End)
		{
			pnt3D3 = new Pnt3D(LastEntity.Vertice[0]);
			pnt3D4 = new Pnt3D(LastEntity.Vertice[1]);
		}
		else
		{
			pnt3D3 = new Pnt3D(LastEntity.Vertice[LastEntity.Vertice.Count - 1]);
			pnt3D4 = new Pnt3D(LastEntity.Vertice[LastEntity.Vertice.Count - 2]);
		}
		double value = AngleOfTwoLines(pnt3D, pnt3D2, pnt3D3, pnt3D4, new WorkPlane());
		if (!(180.0 - Math.Abs(value) <= 30.0))
		{
			double num = 0.0;
			double num2 = ModifyLength;
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			List<Pnt3D> Points = new List<Pnt3D>();
			if (FirstEntity.GetType() == typeof(eLine))
			{
				EntityToPoint(FirstEntity, ref Points);
			}
			if (FirstEntity.GetType() == typeof(eArc))
			{
				ArcTo3Point(FirstEntity, ref Points);
				Points.RemoveAt(0);
			}
			Pnt3D.Add(Points, ref CopiedPnt);
			Points = new List<Pnt3D>();
			if (LastEntity.GetType() == typeof(eLine))
			{
				EntityToPoint(LastEntity, ref Points);
			}
			if (LastEntity.GetType() == typeof(eArc))
			{
				ArcTo3Point(LastEntity, ref Points);
				Points.RemoveAt(Points.Count - 1);
			}
			Pnt3D.Add(Points, ref CopiedPnt);
			CheckDuplicatedPointsWithPrevious(ref CopiedPnt);
			if (CopiedPnt.Count == 3)
			{
				num = CrossProductLength(CopiedPnt[0], CopiedPnt[1], CopiedPnt[CopiedPnt.Count - 1]);
			}
			if (CopiedPnt.Count > 3)
			{
				num = CrossProductLength(CopiedPnt[0], CopiedPnt[1], CopiedPnt[2]);
			}
			if (ReverseThetaCalculation)
			{
				num *= -1.0;
			}
			if (ClockDir != ClockDirectionType.CCW)
			{
				if (!(num >= 0.0))
				{
					new eEntities();
					new eEntities();
					num2 /= Math.Cos(buConversion.DegreeToRadian(FirstEntity.Orientation.A));
					if (FirstEntityTouchPoint == StartEndType.Start)
					{
						EntityUpdateByLength(eEntities.CopyEntity(FirstEntity), FirstEntity.geoLength - num2, StartPointType.Start, ref ModifiedFirstEntity);
					}
					if (FirstEntityTouchPoint == StartEndType.End)
					{
						EntityUpdateByLength(eEntities.CopyEntity(FirstEntity), FirstEntity.geoLength - num2, StartPointType.End, ref ModifiedFirstEntity);
					}
					if (SecondEntityTouchPoint == StartEndType.Start)
					{
						EntityUpdateByLength(eEntities.CopyEntity(LastEntity), LastEntity.geoLength - num2, StartPointType.Start, ref ModifiedLastEntity);
					}
					if (SecondEntityTouchPoint == StartEndType.End)
					{
						EntityUpdateByLength(eEntities.CopyEntity(LastEntity), LastEntity.geoLength - num2, StartPointType.End, ref ModifiedLastEntity);
					}
					ModifiedFirstEntity.bCamSelected = false;
					ModifiedFirstEntity.bSelected = false;
				}
				else
				{
					eEntities.CopyEntity(FirstEntity, ref ModifiedFirstEntity);
					ModifiedFirstEntity.bCamSelected = false;
					ModifiedFirstEntity.bSelected = false;
					eEntities.CopyEntity(LastEntity, ref ModifiedLastEntity);
					ModifiedLastEntity.bCamSelected = false;
					ModifiedLastEntity.bSelected = false;
				}
			}
			else if (!(num <= 0.0))
			{
				num2 /= Math.Cos(buConversion.DegreeToRadian(FirstEntity.Orientation.A));
				if (FirstEntityTouchPoint == StartEndType.Start)
				{
					EntityUpdateByLength(eEntities.CopyEntity(FirstEntity), FirstEntity.geoLength - num2, StartPointType.Start, ref ModifiedFirstEntity);
				}
				if (FirstEntityTouchPoint == StartEndType.End)
				{
					EntityUpdateByLength(eEntities.CopyEntity(FirstEntity), FirstEntity.geoLength - num2, StartPointType.End, ref ModifiedFirstEntity);
				}
				if (SecondEntityTouchPoint == StartEndType.Start)
				{
					EntityUpdateByLength(eEntities.CopyEntity(LastEntity), LastEntity.geoLength - num2, StartPointType.Start, ref ModifiedLastEntity);
				}
				if (SecondEntityTouchPoint == StartEndType.End)
				{
					EntityUpdateByLength(eEntities.CopyEntity(LastEntity), LastEntity.geoLength - num2, StartPointType.End, ref ModifiedLastEntity);
				}
				ModifiedFirstEntity.bCamSelected = false;
				ModifiedFirstEntity.bSelected = false;
			}
			else
			{
				eEntities.CopyEntity(FirstEntity, ref ModifiedFirstEntity);
				ModifiedFirstEntity.bCamSelected = false;
				ModifiedFirstEntity.bSelected = false;
				eEntities.CopyEntity(LastEntity, ref ModifiedLastEntity);
				ModifiedLastEntity.bCamSelected = false;
				ModifiedLastEntity.bSelected = false;
			}
		}
		else
		{
			eEntities.CopyEntity(FirstEntity, ref ModifiedFirstEntity);
			ModifiedFirstEntity.bCamSelected = false;
			ModifiedFirstEntity.bSelected = false;
			eEntities.CopyEntity(LastEntity, ref ModifiedLastEntity);
			ModifiedLastEntity.bCamSelected = false;
			ModifiedLastEntity.bSelected = false;
		}
	}

	public void EntityCornerModifyByConvexConcave1(eEntities FirstEntity, eEntities LastEntity, ClockDirectionType ClockDir, bool ReverseThetaCalculation, double ModifyLength, ref eEntities ModifiedFirstEntity, ref eEntities ModifiedLastEntity)
	{
		ModifiedFirstEntity = new eEntities();
		ModifiedLastEntity = new eEntities();
		double num = 0.0;
		double num2 = ModifyLength;
