	public void EntitiesToPoint(eEntities RefEntity, EntitiesResolution Resolution, ref List<Pnt3D> Points)
	{
		try
		{
			if (RefEntity.GetType() == typeof(ePoint))
			{
				Points.Add(new Pnt3D(RefEntity.Vertice[0]));
			}
			if (RefEntity.GetType() == typeof(eLine))
			{
				if (Resolution.LineResolution.ResolutionTypes != EntityResolutionType.None)
				{
					if (Resolution.LineResolution.ResolutionTypes != EntityResolutionType.ByNumber)
					{
						double num = Length3D(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
						double num2 = buNumeric.RoundToUpper(num / Resolution.LineResolution.GeometricLength);
						if (num2 <= 1.0)
						{
							num2 = 2.0;
						}
						double length = num / num2;
						if (RefEntity.camDirections == camPathDirectionType.Normal)
						{
							LineerToLineer(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], length, ref Points);
						}
						if (RefEntity.camDirections == camPathDirectionType.Reverse)
						{
							LineerToLineer(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[0], length, ref Points);
						}
					}
					else
					{
						double num3 = Length3D(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
						double length2 = num3 / (double)Resolution.LineResolution.GeometricCount;
						if (RefEntity.camDirections == camPathDirectionType.Normal)
						{
							LineerToLineer(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], length2, ref Points);
						}
						if (RefEntity.camDirections == camPathDirectionType.Reverse)
						{
							LineerToLineer(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[0], length2, ref Points);
						}
					}
				}
				else
				{
					if (RefEntity.camDirections == camPathDirectionType.Normal)
					{
						Pnt3D.Copy(RefEntity.Vertice, ref Points);
					}
					if (RefEntity.camDirections == camPathDirectionType.Reverse)
					{
						Pnt3D.Copy(RefEntity.Vertice, ref Points);
						Points.Reverse();
					}
				}
			}
			if (RefEntity.GetType() == typeof(ePolyline))
			{
				if (Resolution.PolylineResolution.ResolutionTypes != EntityResolutionType.None)
				{
					List<Pnt3D> CopiedPnt = new List<Pnt3D>();
					Pnt3D.Copy(RefEntity.Vertice, ref CopiedPnt);
					if (RefEntity.camDirections == camPathDirectionType.Reverse)
					{
						CopiedPnt.Reverse();
					}
					if (Resolution.PolylineResolution.ResolutionTypes != EntityResolutionType.ByNumber)
					{
						for (int i = 1; i <= CopiedPnt.Count - 1; i++)
						{
							List<Pnt3D> Vertices = new List<Pnt3D>();
							double num4 = Length3D(CopiedPnt[i - 1], CopiedPnt[i]);
							double num5 = buNumeric.RoundToUpper(num4 / Resolution.PolylineResolution.GeometricLength);
							if (!(num5 <= 1.0))
							{
							}
							double length3 = num4 / num5;
							LineerToLineer(CopiedPnt[i - 1], CopiedPnt[i], length3, ref Vertices);
							Points.AddRange(Vertices);
						}
					}
					else
					{
						for (int j = 1; j <= CopiedPnt.Count - 1; j++)
						{
							List<Pnt3D> Vertices2 = new List<Pnt3D>();
							double num6 = Length3D(CopiedPnt[j - 1], CopiedPnt[j]);
							double length4 = num6 / (double)Resolution.PolylineResolution.GeometricCount;
							LineerToLineer(CopiedPnt[j - 1], CopiedPnt[j], length4, ref Vertices2);
							Points.AddRange(Vertices2);
						}
					}
					CheckDuplicatedPointsWithPrevious(ref Points);
				}
				else
				{
					if (RefEntity.camDirections == camPathDirectionType.Normal)
					{
						Pnt3D.Copy(RefEntity.Vertice, ref Points);
					}
					if (RefEntity.camDirections == camPathDirectionType.Reverse)
					{
						Pnt3D.Copy(RefEntity.Vertice, ref Points);
						Points.Reverse();
					}
				}
			}
			if (RefEntity.GetType() == typeof(eCam))
			{
				if (Resolution.PolylineResolution.ResolutionTypes != EntityResolutionType.None)
				{
					List<Pnt3D> CopiedPnt2 = new List<Pnt3D>();
					Pnt3D.Copy(RefEntity.Vertice, ref CopiedPnt2);
					if (RefEntity.camDirections == camPathDirectionType.Reverse)
					{
						CopiedPnt2.Reverse();
					}
					if (Resolution.PolylineResolution.ResolutionTypes != EntityResolutionType.ByNumber)
					{
						for (int k = 1; k <= CopiedPnt2.Count - 1; k++)
						{
							List<Pnt3D> Vertices3 = new List<Pnt3D>();
							double num7 = Length3D(CopiedPnt2[k - 1], CopiedPnt2[k]);
							double num8 = buNumeric.RoundToUpper(num7 / Resolution.PolylineResolution.GeometricLength);
							if (!(num8 <= 1.0))
							{
							}
							double length5 = num7 / num8;
							LineerToLineer(CopiedPnt2[k - 1], CopiedPnt2[k], length5, ref Vertices3);
							Points.AddRange(Vertices3);
						}
					}
					else
					{
						for (int l = 1; l <= CopiedPnt2.Count - 1; l++)
						{
							List<Pnt3D> Vertices4 = new List<Pnt3D>();
							double num9 = Length3D(CopiedPnt2[l - 1], CopiedPnt2[l]);
							double length6 = num9 / (double)Resolution.PolylineResolution.GeometricCount;
							LineerToLineer(CopiedPnt2[l - 1], CopiedPnt2[l], length6, ref Vertices4);
							Points.AddRange(Vertices4);
						}
					}
					CheckDuplicatedPointsWithPrevious(ref Points);
				}
				else
				{
					if (RefEntity.camDirections == camPathDirectionType.Normal)
					{
						Pnt3D.Copy(RefEntity.Vertice, ref Points);
					}
					if (RefEntity.camDirections == camPathDirectionType.Reverse)
					{
						Pnt3D.Copy(RefEntity.Vertice, ref Points);
						Points.Reverse();
					}
				}
			}
			if (RefEntity.GetType() == typeof(eArc))
			{
				List<Pnt3D> Vertices5 = new List<Pnt3D>();
				int num10 = ArcVerticeCountByResolution(((eArc)RefEntity).Radius, ((eArc)RefEntity).StartAngle, ((eArc)RefEntity).EndAngle, Resolution.ArcResolution);
				if (num10 < Resolution.ArcResolution.MinPointCount)
				{
					num10 = Resolution.ArcResolution.MinPointCount;
				}
				ArcToLineerByCount(((eArc)RefEntity).CenterPoint, ((eArc)RefEntity).Radius, ((eArc)RefEntity).StartAngle, ((eArc)RefEntity).EndAngle, num10, ((eArc)RefEntity).Plane, ref Vertices5);
				if (RefEntity.camDirections == camPathDirectionType.Normal)
				{
					Pnt3D.Copy(Vertices5, ref Points);
				}
				if (RefEntity.camDirections == camPathDirectionType.Reverse)
				{
					Pnt3D.Copy(Vertices5, ref Points);
					Points.Reverse();
				}
			}
			if (RefEntity.GetType() == typeof(eCircle))
			{
				List<Pnt3D> Vertices6 = new List<Pnt3D>();
				int num11 = ArcVerticeCountByResolution(((eCircle)RefEntity).Radius, 0.0, 360.0, Resolution.CircleResolution);
				if (num11 < Resolution.CircleResolution.MinPointCount)
				{
					num11 = Resolution.CircleResolution.MinPointCount;
				}
				ArcToLineerByCount(((eCircle)RefEntity).CenterPoint, ((eCircle)RefEntity).Radius, 0.0, 360.0, num11, ((eCircle)RefEntity).Plane, ref Vertices6);
				if (RefEntity.camDirections == camPathDirectionType.Normal)
				{
					Pnt3D.Copy(Vertices6, ref Points);
				}
				if (RefEntity.camDirections == camPathDirectionType.Reverse)
				{
					Pnt3D.Copy(Vertices6, ref Points);
					Points.Reverse();
				}
			}
			if (RefEntity.GetType() == typeof(eEllipse))
			{
				List<Pnt3D> Vertices7 = new List<Pnt3D>();
				int num12 = EllipseVerticeCountByResolution(((eEllipse)RefEntity).MajorRadius, ((eEllipse)RefEntity).MinorRadius, Resolution.EllipseResolution);
				if (num12 < Resolution.EllipseResolution.MinPointCount)
				{
					num12 = Resolution.EllipseResolution.MinPointCount;
				}
				EllipseToLineerByCount(((eEllipse)RefEntity).CenterPoint, ((eEllipse)RefEntity).MajorRadius, ((eEllipse)RefEntity).MinorRadius, ((eEllipse)RefEntity).Angle, num12, ((eEllipse)RefEntity).Plane, ref Vertices7);
				if (RefEntity.camDirections == camPathDirectionType.Normal)
				{
					Pnt3D.Copy(Vertices7, ref Points);
				}
				if (RefEntity.camDirections == camPathDirectionType.Reverse)
				{
					Pnt3D.Copy(Vertices7, ref Points);
					Points.Reverse();
				}
			}
			if ((RefEntity.GetType() == typeof(eBSpline)) | (RefEntity.GetType() == typeof(eBezeir)))
			{
				if (RefEntity.camDirections == camPathDirectionType.Normal)
				{
					Pnt3D.Copy(RefEntity.Vertice, ref Points);
				}
				if (RefEntity.camDirections == camPathDirectionType.Reverse)
				{
					Pnt3D.Copy(RefEntity.Vertice, ref Points);
					Points.Reverse();
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "RefEntity: " + RefEntity.ToString() + " - Resolution: " + Resolution.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

