	public void EntityToPoint(eEntities RefEntity, EntityResolution Resolution, bool CalculateCAngles, ref List<Pnt6D> Points)
	{
		try
		{
			if (RefEntity.GetType() == typeof(ePoint))
			{
				Points.Add(new Pnt6D(new Pnt3D(RefEntity.Vertice[0]), new OrientationAngle(RefEntity.Orientation)));
			}
			if ((RefEntity.GetType() == typeof(eLine)) | (RefEntity.GetType() == typeof(ePolyline)) | (RefEntity.GetType() == typeof(eEllipse)) | (RefEntity.GetType() == typeof(eBSpline)) | (RefEntity.GetType() == typeof(eBezeir)))
			{
				if (RefEntity.camDirections == camPathDirectionType.Normal)
				{
					for (int i = 0; i <= RefEntity.Vertice.Count - 1; i++)
					{
						double c = 0.0;
						if (i < RefEntity.Vertice.Count - 1)
						{
							c = PointAngle(RefEntity.Vertice[i + 1], RefEntity.Vertice[i]);
						}
						if (i == RefEntity.Vertice.Count - 1)
						{
							c = PointAngle(RefEntity.Vertice[i], RefEntity.Vertice[i - 1]);
						}
						if (!CalculateCAngles)
						{
							c = RefEntity.Orientation.C;
						}
						Points.Add(new Pnt6D(new Pnt3D(RefEntity.Vertice[i]), new OrientationAngle(RefEntity.Orientation.A, RefEntity.Orientation.B, c)));
					}
				}
				if (RefEntity.camDirections == camPathDirectionType.Reverse)
				{
					List<Pnt3D> CopiedPnt = new List<Pnt3D>();
					Pnt3D.Copy(RefEntity.Vertice, ref CopiedPnt);
					CopiedPnt.Reverse();
					for (int j = 0; j <= CopiedPnt.Count - 1; j++)
					{
						double c2 = 0.0;
						if (j < CopiedPnt.Count - 1)
						{
							c2 = PointAngle(CopiedPnt[j + 1], CopiedPnt[j]);
						}
						if (j == CopiedPnt.Count - 1)
						{
							c2 = PointAngle(CopiedPnt[j], CopiedPnt[j - 1]);
						}
						if (!CalculateCAngles)
						{
							c2 = RefEntity.Orientation.C;
						}
						Points.Add(new Pnt6D(new Pnt3D(CopiedPnt[j]), new OrientationAngle(RefEntity.Orientation.A, RefEntity.Orientation.B, c2)));
					}
				}
			}
			if (RefEntity.GetType() == typeof(eArc))
			{
				List<Pnt3D> Vertices = new List<Pnt3D>();
				int num = ArcVerticeCountByResolution(((eArc)RefEntity).Radius, ((eArc)RefEntity).StartAngle, ((eArc)RefEntity).EndAngle, Resolution);
				if (num < Resolution.MinPointCount)
				{
					num = Resolution.MinPointCount;
				}
				ArcToLineerByCount(((eArc)RefEntity).CenterPoint, ((eArc)RefEntity).Radius, ((eArc)RefEntity).StartAngle, ((eArc)RefEntity).EndAngle, num, ((eArc)RefEntity).Plane, ref Vertices);
				if (RefEntity.camDirections == camPathDirectionType.Normal)
				{
					for (int k = 0; k <= Vertices.Count - 1; k++)
					{
						double c3 = 0.0;
						if (k < Vertices.Count - 1)
						{
							c3 = PointAngle(Vertices[k + 1], Vertices[k]);
						}
						if (k == Vertices.Count - 1)
						{
							c3 = PointAngle(Vertices[k], Vertices[k - 1]);
						}
						if (!CalculateCAngles)
						{
							c3 = RefEntity.Orientation.C;
						}
						Points.Add(new Pnt6D(new Pnt3D(Vertices[k]), new OrientationAngle(RefEntity.Orientation.A, RefEntity.Orientation.B, c3)));
					}
				}
				if (RefEntity.camDirections == camPathDirectionType.Reverse)
				{
					Vertices.Reverse();
					for (int l = 0; l <= Vertices.Count - 1; l++)
					{
						double c4 = 0.0;
						if (l < Vertices.Count - 1)
						{
							c4 = PointAngle(Vertices[l + 1], Vertices[l]);
						}
						if (l == Vertices.Count - 1)
						{
							c4 = PointAngle(Vertices[l], Vertices[l - 1]);
						}
						if (!CalculateCAngles)
						{
							c4 = RefEntity.Orientation.C;
						}
						Points.Add(new Pnt6D(new Pnt3D(Vertices[l]), new OrientationAngle(RefEntity.Orientation.A, RefEntity.Orientation.B, c4)));
					}
				}
