			{
				for (int n = 1; n <= list.Count - 1; n++)
				{
					eLine2 = new eLine(list[n - 1], list[n]);
					CalcEntities.Add(eLine2);
				}
				if (!buCompare.EQ(list[list.Count - 1], RefPoint[RefPoint.Count - 1]))
				{
					eLine2 = new eLine(list[list.Count - 1], RefPoint[RefPoint.Count - 1]);
					CalcEntities.Add(eLine2);
				}
			}
			return;
		}
		bool flag9 = false;
		camPathDirectionType camDirections = camPathDirectionType.Normal;
		if (buCompare.EQ(pnt3D, eArc2.Vertice[eArc2.Vertice.Count - 1], 0.01))
		{
			camDirections = camPathDirectionType.Reverse;
			eArc2.camDirections = camPathDirectionType.Reverse;
		}
		if (eArc2.EndAngle - eArc2.StartAngle > 180.0)
		{
			eArc2 = new eArc(list[0], list[Convert.ToInt32((double)list.Count / 4.0)], list[Convert.ToInt32((double)list.Count / 2.0)], Plane);
			eArc2.camDirections = camDirections;
