			eArc2.camDirections = camDirections;
			CalcEntities.Add(eArc2);
		}
	}

	public double Slope(Pnt3D StartPoint, Pnt3D EndPoint, WorkPlane Plane)
	{
		try
		{
			if (!WorkPlane.isPlaneXY(Plane))
			{
				if (!WorkPlane.isPlaneXZ(Plane))
				{
					if (!WorkPlane.isPlaneYZ(Plane))
					{
						return -1000000000.0;
					}
					if (buCompare.EQ(StartPoint.Y, EndPoint.Y, 0.001))
					{
						return -1000000000.0;
					}
					return (EndPoint.Z - StartPoint.Z) / (EndPoint.Y - StartPoint.Y);
				}
				if (buCompare.EQ(StartPoint.X, EndPoint.X, 0.001))
				{
					return -1000000000.0;
				}
				return (EndPoint.Z - StartPoint.Z) / (EndPoint.X - StartPoint.X);
			}
			if (buCompare.EQ(StartPoint.X, EndPoint.X, 0.001))
			{
				return -1000000000.0;
			}
			return (EndPoint.Y - StartPoint.Y) / (EndPoint.X - StartPoint.X);
		}
		catch (Exception mSException)
		{
			string text = "StartPoint: " + StartPoint.ToString() + " - EndPoint: " + EndPoint.ToString() + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1000000000.0;
		}
	}

