	public void GetAvailableGroupIndex(List<eEntities> Entities, List<int> AlreadyUsedGroupIndex, ref int GroupIndex, ref List<int> UsedGroupList)
	{
		try
		{
			UsedGroupList = new List<int>();
			for (int i = 0; i <= AlreadyUsedGroupIndex.Count - 1; i++)
			{
				UsedGroupList.Add(AlreadyUsedGroupIndex[i]);
			}
			for (int j = 0; j <= Entities.Count - 1; j++)
			{
				if (Entities[j].GroupIndex <= 0)
				{
					continue;
				}
				if (UsedGroupList.Count != 0)
				{
					bool flag = false;
					for (int k = 0; k <= UsedGroupList.Count - 1; k++)
					{
						if (Entities[j].GroupIndex == UsedGroupList[k])
						{
							flag = true;
						}
					}
					if (!flag)
					{
						UsedGroupList.Add(Entities[j].GroupIndex);
					}
				}
				else
				{
					UsedGroupList.Add(Entities[j].GroupIndex);
				}
			}
			if (UsedGroupList.Count == 0)
			{
				GroupIndex = 1;
			}
			if (UsedGroupList.Count == 1)
			{
				GroupIndex = UsedGroupList[0] + 1;
			}
			if (UsedGroupList.Count <= 1)
			{
				return;
			}
			SortList(SortDirectionType.Lower, ref UsedGroupList);
			bool flag2 = false;
			for (int l = 1; l <= UsedGroupList.Count - 1; l++)
			{
				int num = UsedGroupList[l] - UsedGroupList[l - 1];
				if (num >= 2)
				{
					GroupIndex = UsedGroupList[l - 1] + 1;
					flag2 = true;
				}
			}
			if (!flag2)
			{
				GroupIndex = UsedGroupList[UsedGroupList.Count - 1] + 1;
			}
		}
		catch (Exception mSException)
		{
			string text = "Entities: " + Entities.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

