	public void SetShapeDataToEntity(ShapeData Shape, ref eEntities Entitiy)
	{
		if (Shape == null)
		{
			Entitiy.Shape = null;
			return;
		}
		ShapeData Copied = new ShapeData();
		ShapeData.Copy(Shape, ref Copied);
		Entitiy.Shape = new ShapeData();
		Entitiy.Shape = Copied;
	}

	public void SetShapeDataToLastEntity(ShapeData Shape, ref List<eEntities> Entities)
	{
		if (Entities.Count > 0)
		{
			if (Shape == null)
			{
				Entities[Entities.Count - 1].Shape = null;
				return;
			}
			ShapeData Copied = new ShapeData();
			ShapeData.Copy(Shape, ref Copied);
			Entities[Entities.Count - 1].Shape = new ShapeData();
			Entities[Entities.Count - 1].Shape = Copied;
		}
	}

	public void SetSelectedPropertiesToEntities(bool Selected, ref List<eEntities> Entities)
	{
		if (Entities.Count > 0)
		{
			for (int i = 0; i <= Entities.Count - 1; i++)
			{
				Entities[i].bSelected = Selected;
			}
		}
	}

	public void EntityTtoEntityE(geoEntity EntityFrom, ref List<eEntities> EntityTo)
	{
		if (EntityFrom.GetType() == typeof(geoLine))
		{
			geoLine geoLine2 = new geoLine((geoLine)EntityFrom);
			EntityTo.Add(new eLine(geoLine2.StartPoint, geoLine2.EndPoint));
			EntityTo[0].LayerIndex = EntityFrom.Layer;
			EntityTo[0].Mode = EntityFrom.Mode;
			EntityTo[0].camToolNo = EntityFrom.ToolNo;
			EntityTo[0].GroupIndex = EntityFrom.Index;
		}
		if (EntityFrom.GetType() == typeof(geoPolyline))
		{
			geoPolyline geoPolyline2 = new geoPolyline((geoPolyline)EntityFrom);
			List<Pnt3D> list = new List<Pnt3D>();
			for (int i = 0; i <= geoPolyline2.Vertice.Count - 1; i++)
			{
				list.Add(new Pnt3D(geoPolyline2.Vertice[i]));
			}
			EntityTo.Add(new ePolyline(list));
			EntityTo[0].LayerIndex = EntityFrom.Layer;
			EntityTo[0].Mode = EntityFrom.Mode;
			EntityTo[0].camToolNo = EntityFrom.ToolNo;
			EntityTo[0].GroupIndex = EntityFrom.Index;
		}
		if (EntityFrom.GetType() == typeof(geoArc))
		{
			geoArc geoArc2 = new geoArc((geoArc)EntityFrom);
			EntityTo.Add(new eArc(geoArc2.CenterPoint, geoArc2.Radius, geoArc2.StartAngle, geoArc2.EndAngle, geoArc2.Plane));
			EntityTo[0].LayerIndex = EntityFrom.Layer;
			EntityTo[0].Mode = EntityFrom.Mode;
			EntityTo[0].camToolNo = EntityFrom.ToolNo;
			EntityTo[0].GroupIndex = EntityFrom.Index;
		}
