	public void ChangeEntityByCamDirection(eEntities RefEntity, ref eEntities ChangedEntity)
	{
		try
		{
			if (!((RefEntity.GetType() == typeof(eLine)) & (RefEntity.camDirections == camPathDirectionType.Reverse)))
			{
				if (!((RefEntity.GetType() == typeof(ePolyline)) & (RefEntity.camDirections == camPathDirectionType.Reverse)))
				{
					ChangedEntity = new eEntities();
					eEntities.CopyEntity(RefEntity, ref ChangedEntity);
					return;
				}
				List<Pnt3D> CopiedPnt = new List<Pnt3D>();
				Pnt3D.Copy(RefEntity.Vertice, ref CopiedPnt);
				CopiedPnt.Reverse();
				ChangedEntity = new ePolyline(CopiedPnt);
				eEntities.CopyCommonPorperties(RefEntity, ref ChangedEntity);
				ChangedEntity.camDirections = camPathDirectionType.Normal;
			}
			else
			{
				ChangedEntity = new eLine(RefEntity.Vertice[1], RefEntity.Vertice[0]);
				eEntities.CopyCommonPorperties(RefEntity, ref ChangedEntity);
				ChangedEntity.camDirections = camPathDirectionType.Normal;
			}
		}
		catch (Exception mSException)
		{
			string text = "RefEntity: " + RefEntity.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

