	public bool isEntityDerivatedFromEntity(ref eEntities RefEntity, List<eEntities> EntitiyList, EntityDerivatedData Data, EntityDerivatedType Type)
	{
		try
		{
			for (int i = 0; i <= EntitiyList.Count - 1; i++)
			{
				if (!(EntitiyList[i].GetType() == RefEntity.GetType()) || !(RefEntity.GetType() == typeof(eLine)) || Type != EntityDerivatedType.Offset)
				{
					continue;
				}
				Pnt3D pnt3D = new Pnt3D();
				Pnt3D pnt3D2 = new Pnt3D();
				pnt3D = MiddlePointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[1]);
				pnt3D2 = MiddlePointOfLine(EntitiyList[i].Vertice[0], EntitiyList[i].Vertice[1]);
				double value = Length3D(pnt3D, pnt3D2);
				if (buCompare.EQ(Math.Abs(value), Math.Abs(Data.Offset)))
				{
					if (Data.ApplyAllEntityData)
					{
						eEntities.CopyCommonPorperties(EntitiyList[i], ref RefEntity);
					}
					return true;
				}
			}
			return false;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public void CreateEntitiesFromCustomText(string Text, double CharSpace, double SpaceValue, double CharHeight, List<CharLibrary> CharLib, ref List<eEntities> TextEntities)
	{
		try
		{
			TextEntities.Clear();
			TextEntities = new List<eEntities>();
			double num = 1.0;
			if (Text.Length <= 0)
			{
				return;
			}
			char[] array = Text.ToCharArray();
			double num2 = 0.0;
			if (array == null)
			{
				return;
			}
			for (int i = 0; i <= array.Length - 1; i++)
			{
				bool flag = false;
				List<eEntities> EEntities = new List<eEntities>();
				for (int j = 0; j <= CharLib.Count - 1; j++)
				{
					string text = array[i].ToString();
					if (text == CharLib[j].Char)
					{
						geoEntity.GeoEntitiyToEEntity(CharLib[j].CharEntities, ref EEntities);
						j = 2147483645;
					}
					if (text == " ")
					{
						flag = true;
					}
				}
				if (!flag)
				{
					if (EEntities.Count <= 0)
					{
						num2 += SpaceValue;
						continue;
					}
					Pnt3D MinPoint = new Pnt3D();
					Pnt3D MaxPoint = new Pnt3D();
					BoxSizeCalculate(EEntities, ref MinPoint, ref MaxPoint);
					double num3 = MaxPoint.Y - MinPoint.Y;
					if ((num3 > 0.0 && CharHeight > 0.0) & (TextEntities.Count == 0))
					{
						num = CharHeight / num3;
					}
					Scale(MinPoint, num, num, 1.0, ScaleX: true, ScaleY: true, ScaleZ: false, new WorkPlane(), ref EEntities);
					Move(MinPoint, new Pnt3D(num2, 0.0, 0.0), ref EEntities);
					BoxSizeCalculate(EEntities, ref MinPoint, ref MaxPoint);
					eEntities.AddEntities(EEntities, ref TextEntities);
					num2 = MaxPoint.X + CharSpace;
				}
				else
				{
					num2 += SpaceValue;
				}
			}
		}
		catch (Exception)
		{
		}
	}

