				pnt3D2 = new Pnt3D();
				pnt3D2 = ((ePicture)Ent).StartPoint + pnt3D;
				((ePicture)Ent).StartPoint = pnt3D2;
				pnt3D2 = new Pnt3D();
				pnt3D2 = ((ePicture)Ent).EndPoint + pnt3D;
				((ePicture)Ent).EndPoint = pnt3D2;
				((ePicture)Ent).Update();
			}
			if (Ent.GetType() == typeof(eText))
			{
				pnt3D2 = new Pnt3D();
				pnt3D2 = ((eText)Ent).StartPoint + pnt3D;
				((eText)Ent).StartPoint = pnt3D2;
				((eText)Ent).Update();
			}
			if (Ent.GetType() == typeof(eSurface))
			{
				for (int j = 0; j <= ((eSurface)Ent).Triangles.Count - 1; j++)
				{
					Triangle3D triangle3D = new Triangle3D(((eSurface)Ent).Triangles[j]);
					pnt3D2 = new Pnt3D();
					pnt3D2 = triangle3D.FirstPoint + pnt3D;
					((eSurface)Ent).Triangles[j].FirstPoint = new Pnt3D(pnt3D2);
					pnt3D2 = new Pnt3D();
					pnt3D2 = triangle3D.SecondPoint + pnt3D;
					((eSurface)Ent).Triangles[j].SecondPoint = new Pnt3D(pnt3D2);
					pnt3D2 = new Pnt3D();
					pnt3D2 = triangle3D.ThirdPoint + pnt3D;
					((eSurface)Ent).Triangles[j].ThirdPoint = new Pnt3D(pnt3D2);
				}
				((eSurface)Ent).Update();
			}
			if (Ent.GetType() == typeof(eBSpline))
			{
				for (int k = 0; k <= ((eBSpline)Ent).ControlPoints.Count - 1; k++)
				{
					pnt3D2 = new Pnt3D();
					pnt3D2 = ((eBSpline)Ent).ControlPoints[k] + pnt3D;
					((eBSpline)Ent).ControlPoints[k] = pnt3D2;
				}
				((eBSpline)Ent).Update();
			}
			if (Ent.GetType() == typeof(eBezeir))
			{
				for (int l = 0; l <= ((eBezeir)Ent).ControlPoints.Count - 1; l++)
				{
					pnt3D2 = new Pnt3D();
					pnt3D2 = ((eBezeir)Ent).ControlPoints[l] + pnt3D;
					((eBezeir)Ent).ControlPoints[l] = pnt3D2;
				}
				((eBezeir)Ent).Update();
			}
			if (Ent.GetType() == typeof(ePolylineGroup))
			{
				for (int m = 0; m <= ((ePolylineGroup)Ent).GroupVertices.Count - 1; m++)
				{
					for (int n = 0; n <= ((ePolylineGroup)Ent).GroupVertices[m].Count - 1; n++)
					{
						pnt3D2 = new Pnt3D();
						pnt3D2 = ((ePolylineGroup)Ent).GroupVertices[m][n] + pnt3D;
						((ePolylineGroup)Ent).GroupVertices[m][n] = pnt3D2;
					}
				}
				for (int num4 = 0; num4 <= ((ePolylineGroup)Ent).InternalVertices.Count - 1; num4++)
				{
					for (int num5 = 0; num5 <= ((ePolylineGroup)Ent).InternalVertices[num4].Count - 1; num5++)
					{
						pnt3D2 = new Pnt3D();
						pnt3D2 = ((ePolylineGroup)Ent).InternalVertices[num4][num5] + pnt3D;
						((ePolylineGroup)Ent).InternalVertices[num4][num5] = pnt3D2;
					}
				}
				((ePolylineGroup)Ent).Update();
			}
			Ent.Update();
		}
		catch (Exception mSException)
		{
			string text = "From: " + From.ToString() + " - To: " + To.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
