	public void Rotate(Pnt3D CenterPoint, double Angle, WorkPlane Plane, List<Pnt3D> RefPoints, ref List<Pnt3D> CalcPoints)
	{
		try
		{
			CalcPoints.Clear();
			Pnt3D.Copy(RefPoints, ref CalcPoints);
			Rotate(CenterPoint, Angle, Plane, ref CalcPoints);
		}
		catch (Exception mSException)
		{
			string text = "CenterPoint: " + CenterPoint.ToString() + " - Angle: " + Angle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Rotate(Pnt3D CenterPoint, double Angle, WorkPlane Plane, ref List<Pnt3D> Points)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			for (int i = 0; i <= Points.Count - 1; i++)
			{
				num = Length3D(Points[i], CenterPoint, Plane);
				num2 = PointAngle(Points[i], CenterPoint, Plane);
				num2 += Angle;
				pnt3D = new Pnt3D();
				if (WorkPlane.isPlaneXY(Plane))
				{
					pnt3D = new Pnt3D(Points[i]);
					pnt3D.X = CenterPoint.X + num * Math.Cos(buConversion.DegreeToRadian(num2));
					pnt3D.Y = CenterPoint.Y + num * Math.Sin(buConversion.DegreeToRadian(num2));
					Points[i] = new Pnt3D(pnt3D);
				}
				if (WorkPlane.isPlaneXZ(Plane))
				{
					pnt3D = new Pnt3D(Points[i]);
					pnt3D.X = CenterPoint.X + num * Math.Cos(buConversion.DegreeToRadian(num2));
					pnt3D.Z = CenterPoint.Z + num * Math.Sin(buConversion.DegreeToRadian(num2));
					Points[i] = new Pnt3D(pnt3D);
				}
				if (WorkPlane.isPlaneYZ(Plane))
				{
					pnt3D = new Pnt3D(Points[i]);
					pnt3D.Y = CenterPoint.Y + num * Math.Cos(buConversion.DegreeToRadian(num2));
					pnt3D.Z = CenterPoint.Z + num * Math.Sin(buConversion.DegreeToRadian(num2));
					Points[i] = new Pnt3D(pnt3D);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "CenterPoint: " + CenterPoint.ToString() + " - Angle: " + Angle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Rotate(Pnt3D CenterPoint, double Angle, WorkPlane Plane, ref List<List<Pnt3D>> Points)
	{
		try
		{
			for (int i = 0; i <= Points.Count - 1; i++)
			{
				List<Pnt3D> TargetList = new List<Pnt3D>();
				buGeneral.CopyLists(Points[i], ref TargetList);
				Rotate(CenterPoint, Angle, Plane, ref TargetList);
				Points[i].Clear();
				for (int j = 0; j <= TargetList.Count - 1; j++)
				{
					Points[i].Add(new Pnt3D(TargetList[j]));
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "CenterPoint: " + CenterPoint.ToString() + " - Angle: " + Angle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Rotate(Pnt3D CenterPoint, double Angle, WorkPlane Plane, ref Pnt3D Points)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			num = Length3D(Points, CenterPoint, Plane);
			num2 = PointAngle(Points, CenterPoint, Plane);
			num2 += Angle;
			if (WorkPlane.isPlaneXY(Plane))
			{
				pnt3D = new Pnt3D(Points);
				pnt3D.X = CenterPoint.X + num * Math.Cos(buConversion.DegreeToRadian(num2));
				pnt3D.Y = CenterPoint.Y + num * Math.Sin(buConversion.DegreeToRadian(num2));
