		}
	}

	public void Rotate(Pnt3D CenterPoint, double Angle, WorkPlane Plane, eEntities RefEntities, ref eEntities CalcEntities)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			WorkPlane CalcPlane = new WorkPlane();
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			List<Pnt3D> TargetList = new List<Pnt3D>();
			List<Pnt3D> TargetList2 = new List<Pnt3D>();
			new List<eEntities>();
			TargetList.Clear();
			TargetList2.Clear();
			buGeneral.CopyLists(RefEntities.Vertice, ref TargetList);
			if (RefEntities.GetType() == typeof(eBSpline))
			{
				buGeneral.CopyLists(((eBSpline)RefEntities).ControlPoints, ref TargetList2);
			}
			if (RefEntities.GetType() == typeof(eBezeir))
			{
				buGeneral.CopyLists(((eBezeir)RefEntities).ControlPoints, ref TargetList2);
			}
			Rotate(CenterPoint, Angle, Plane, ref TargetList);
			Rotate(CenterPoint, Angle, Plane, ref TargetList2);
			if (RefEntities.GetType() == typeof(ePoint))
			{
				pnt3D = new Pnt3D(((ePoint)RefEntities).StartPoint);
				Rotate(CenterPoint, Angle, Plane, ref pnt3D);
				CalcEntities = new ePoint(pnt3D, RefEntities.dispThickness, RefEntities.dispColor);
				eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
				CalcEntities.Update();
			}
			if (RefEntities.GetType() == typeof(eLine))
			{
				pnt3D = new Pnt3D(((eLine)RefEntities).StartPoint);
				pnt3D2 = new Pnt3D(((eLine)RefEntities).EndPoint);
				Rotate(CenterPoint, Angle, Plane, ref pnt3D);
				Rotate(CenterPoint, Angle, Plane, ref pnt3D2);
				CalcEntities = new eLine(pnt3D, pnt3D2, RefEntities.dispThickness, RefEntities.dispColor);
				eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
				CalcEntities.Update();
			}
			if (RefEntities.GetType() == typeof(eUpperLine))
			{
				pnt3D = new Pnt3D(((eUpperLine)RefEntities).StartPoint);
				pnt3D2 = new Pnt3D(((eUpperLine)RefEntities).EndPoint);
				Rotate(CenterPoint, Angle, Plane, ref pnt3D);
				Rotate(CenterPoint, Angle, Plane, ref pnt3D2);
				CalcEntities = new eUpperLine(pnt3D, pnt3D2);
				eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
				CalcEntities.Update();
			}
			if (RefEntities.GetType() == typeof(eCircle))
			{
				pnt3D = new Pnt3D(((eCircle)RefEntities).CenterPoint);
				Rotate(CenterPoint, Angle, Plane, ref pnt3D);
				num = ((eCircle)RefEntities).Radius;
				if (Plane.PlaneType != ((eCircle)RefEntities).Plane.PlaneType)
				{
					PlaneRotation(((eCircle)RefEntities).Plane, Plane, Angle, ref CalcPlane);
				}
				else
				{
					CalcPlane = ((eCircle)RefEntities).Plane;
				}
				CalcEntities = new eCircle(pnt3D, num, CalcPlane);
				eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
				CalcEntities.Update();
			}
			if (RefEntities.GetType() == typeof(eArc))
			{
				pnt3D = new Pnt3D(((eArc)RefEntities).CenterPoint);
				Rotate(CenterPoint, Angle, Plane, ref pnt3D);
				num = ((eArc)RefEntities).Radius;
				if (Plane.PlaneType != ((eArc)RefEntities).Plane.PlaneType)
				{
					num3 = ((eArc)RefEntities).StartAngle;
					num4 = ((eArc)RefEntities).EndAngle;
					PlaneRotation(((eArc)RefEntities).Plane, Plane, Angle, ref CalcPlane);
				}
				else
				{
					CalcPlane = ((eArc)RefEntities).Plane;
					num3 = ((eArc)RefEntities).StartAngle + Angle;
					num4 = ((eArc)RefEntities).EndAngle + Angle;
				}
				CalcEntities = new eArc(pnt3D, num, num3, num4, CalcPlane);
				eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
				CalcEntities.Update();
			}
			if (RefEntities.GetType() == typeof(eEllipse))
			{
				pnt3D = new Pnt3D(((eEllipse)RefEntities).CenterPoint);
				Rotate(CenterPoint, Angle, Plane, ref pnt3D);
				num = ((eEllipse)RefEntities).MajorRadius;
				num2 = ((eEllipse)RefEntities).MinorRadius;
				if (Plane.PlaneType != ((eEllipse)RefEntities).Plane.PlaneType)
				{
					num5 = ((eEllipse)RefEntities).Angle;
					PlaneRotation(((eEllipse)RefEntities).Plane, Plane, Angle, ref CalcPlane);
				}
				else
				{
					CalcPlane = ((eEllipse)RefEntities).Plane;
					num5 = ((eEllipse)RefEntities).Angle + Angle;
				}
				CalcEntities = new eEllipse(pnt3D, num, num2, num5, CalcPlane);
				eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
				CalcEntities.Update();
			}
			if (RefEntities.GetType() == typeof(eEllipseArc))
			{
				pnt3D = new Pnt3D(((eEllipseArc)RefEntities).CenterPoint);
				Rotate(CenterPoint, Angle, Plane, ref pnt3D);
				num = ((eEllipseArc)RefEntities).MajorRadius;
				num2 = ((eEllipseArc)RefEntities).MinorRadius;
				if (Plane.PlaneType != ((eEllipseArc)RefEntities).Plane.PlaneType)
				{
					num3 = ((eEllipseArc)RefEntities).StartAngle;
					num4 = ((eEllipseArc)RefEntities).EndAngle;
					num5 = ((eEllipseArc)RefEntities).Angle;
					PlaneRotation(((eEllipseArc)RefEntities).Plane, Plane, Angle, ref CalcPlane);
				}
				else
				{
					CalcPlane = ((eEllipseArc)RefEntities).Plane;
					num3 = ((eEllipseArc)RefEntities).StartAngle;
					num4 = ((eEllipseArc)RefEntities).EndAngle;
					num5 = ((eEllipseArc)RefEntities).Angle + Angle;
				}
				CalcEntities = new eEllipseArc(pnt3D, num, num2, num3, num4, num5, CalcPlane);
				eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
				CalcEntities.Update();
			}
			if ((RefEntities.GetType() == typeof(ePolyline)) | (RefEntities.GetType() == typeof(eBSpline)) | (RefEntities.GetType() == typeof(eBezeir)))
			{
				if (RefEntities.GetType() == typeof(ePolyline))
				{
					CalcEntities = new ePolyline(TargetList, RefEntities.dispThickness, RefEntities.dispColor);
					eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
					CalcEntities.Update();
				}
				if (RefEntities.GetType() == typeof(eBSpline))
				{
					CalcEntities = new eBSpline(TargetList2, RefEntities.dispThickness, RefEntities.dispColor, ((eBSpline)RefEntities).bClosed, ((eBSpline)RefEntities).BType);
					eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
					CalcEntities.Update();
				}
				if (RefEntities.GetType() == typeof(eBezeir))
				{
					CalcEntities = new eBezeir(TargetList2, RefEntities.dispThickness, RefEntities.dispColor);
					eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
					CalcEntities.Update();
				}
			}
			if (RefEntities.GetType() == typeof(eSurface))
			{
				List<Triangle3D> list = new List<Triangle3D>();
				for (int i = 0; i <= ((eSurface)RefEntities).Triangles.Count - 1; i++)
				{
					Triangle3D triangle3D = new Triangle3D(((eSurface)RefEntities).Triangles[i]);
					Rotate(CenterPoint, Angle, Plane, ref triangle3D.FirstPoint);
					Rotate(CenterPoint, Angle, Plane, ref triangle3D.SecondPoint);
					Rotate(CenterPoint, Angle, Plane, ref triangle3D.ThirdPoint);
					list.Add(triangle3D);
				}
				CalcEntities = new eSurface(list, RefEntities.dispColor);
				eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
				CalcEntities.Update();
			}
			if (RefEntities.GetType() == typeof(eMesh))
			{
				CalcEntities = new eMesh(((eMesh)RefEntities).TriIndex, TargetList);
				eEntities.CopyCommonPorperties(RefEntities, ref CalcEntities);
				CalcEntities.Update();
			}
		}
		catch (Exception mSException)
		{
			string text = "CenterPoint: " + CenterPoint.ToString() + " - Angle: " + Angle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Rotate(Pnt3D CenterPoint, double Angle, WorkPlane Plane, ref eEntities RefEntities)
