	public void PlaneRotation(WorkPlane EntityPlane, WorkPlane OperationPlane, double Angle, ref WorkPlane CalcPlane)
	{
		try
		{
			if (!(buCompare.EQ(Math.Abs(Angle), 90.0) | buCompare.EQ(Math.Abs(Angle), 270.0)))
			{
				CalcPlane = new WorkPlane(EntityPlane);
				return;
			}
			if (EntityPlane.PlaneType == planeType.XY)
			{
				if (OperationPlane.PlaneType == planeType.YZ)
				{
					CalcPlane = new WorkPlane(planeType.XZ, 1);
				}
				if (OperationPlane.PlaneType == planeType.XZ)
				{
					CalcPlane = new WorkPlane(planeType.YZ, 1);
				}
			}
			if (EntityPlane.PlaneType == planeType.XZ)
			{
				if (OperationPlane.PlaneType == planeType.YZ)
				{
					CalcPlane = new WorkPlane(planeType.XY, 1);
				}
				if (OperationPlane.PlaneType == planeType.XY)
				{
					CalcPlane = new WorkPlane(planeType.XZ, 1);
				}
			}
			if (EntityPlane.PlaneType == planeType.YZ)
			{
				if (OperationPlane.PlaneType == planeType.XZ)
				{
					CalcPlane = new WorkPlane(planeType.XY, 1);
				}
				if (OperationPlane.PlaneType == planeType.XY)
				{
					CalcPlane = new WorkPlane(planeType.XZ, 1);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "EntityPlane: " + EntityPlane.ToString() + " - OperationPlane: " + OperationPlane.ToString() + " - Angle: " + Angle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void LineerArray(Pnt3D BasePoint, Vec3D DistanceVector, int XCount, int YCount, int ZCount, bool AcceptFirstEntity, Vec3D OffsetVector, eEntities RefEntities, ref List<eEntities> CalcEntities)
	{
		try
		{
			int num = 0;
			int num2 = 0;
			int num3 = 0;
			Pnt3D pnt3D = new Pnt3D();
			Pnt3D pnt3D2 = new Pnt3D();
			eEntities CalcEnt = new eEntities();
			eEntities eEntities2 = new eEntities();
			CalcEntities = new List<eEntities>();
			if (!AcceptFirstEntity)
			{
				num = XCount + 1;
				num2 = YCount + 1;
				num3 = ZCount + 1;
			}
			else
			{
				num = XCount;
				num2 = YCount;
				num3 = ZCount;
			}
			eEntities2 = new eEntities();
			eEntities.CopyEntity(RefEntities, ref eEntities2);
			CalcEntities.Add(eEntities2);
			for (int i = 0; i <= num3 - 1; i++)
			{
				for (int j = 0; j <= num - 1; j++)
				{
					for (int k = 0; k <= num2 - 1; k++)
					{
						pnt3D2 = new Pnt3D();
						if (j != 0 || k != 0 || i != 0)
						{
							pnt3D.X = (double)j * DistanceVector.X + (double)j * OffsetVector.X;
							pnt3D.Y = (double)k * DistanceVector.Y + (double)k * OffsetVector.Y;
							pnt3D.Z = (double)i * DistanceVector.Z;
							pnt3D2 = BasePoint + pnt3D;
							Move(BasePoint, pnt3D2, RefEntities, ref CalcEnt);
							RefEntities = new eEntities();
							eEntities.CopyEntity(eEntities2, ref RefEntities);
							if (RefEntities.Shape != null)
							{
								CalcEnt.Shape = new ShapeData();
								ShapeData.Copy(RefEntities.Shape, ref CalcEnt.Shape);
								ShapeDataMove(BasePoint, pnt3D2, ref CalcEnt.Shape);
							}
							CalcEntities.Add(CalcEnt);
						}
					}
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - DistanceVector: " + DistanceVector.ToString() + " - X Count: " + XCount + " - Y Count: " + YCount + " - Z Count: " + ZCount + "- RefEntities" + RefEntities.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

