	public void PolarArray(Pnt3D Center, ClockDirectionType Direction, int Count, double PolarAngle, WorkPlane Plane, bool AcceptFirstEntity, List<Pnt3D>[] RefVertices, ref List<Pnt3D>[] Vertices)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			int num3 = 0;
			int num4 = 0;
			Pnt3D pnt3D = new Pnt3D();
			num3 = (AcceptFirstEntity ? Count : (Count + 1));
			Vertices = new List<Pnt3D>[RefVertices.Length * num3];
			num4 = 0;
			for (int i = 0; i <= num3 - 1; i++)
			{
				for (int j = 0; j <= RefVertices.Length - 1; j++)
				{
					Vertices[num4] = new List<Pnt3D>();
					for (int k = 0; k <= RefVertices[j].Count - 1; k++)
					{
						num = Length3D(RefVertices[j][k], Center);
						num2 = PointAngle(RefVertices[j][k], Center, Plane);
						num2 = ((Direction == ClockDirectionType.CW) ? (num2 + (double)i * PolarAngle) : (num2 - (double)i * PolarAngle));
						pnt3D = new Pnt3D();
						if (WorkPlane.isPlaneXY(Plane))
						{
							pnt3D.X = Center.X + num * Math.Cos(buConversion.DegreeToRadian(num2));
							pnt3D.Y = Center.Y + num * Math.Sin(buConversion.DegreeToRadian(num2));
							pnt3D.Z = RefVertices[j][k].Z;
						}
						if (WorkPlane.isPlaneXZ(Plane))
						{
							pnt3D.X = Center.X + num * Math.Cos(buConversion.DegreeToRadian(num2));
							pnt3D.Y = RefVertices[j][k].Y;
							pnt3D.Z = Center.Z + num * Math.Sin(buConversion.DegreeToRadian(num2));
						}
						if (WorkPlane.isPlaneYZ(Plane))
						{
							pnt3D.X = RefVertices[j][k].X;
							pnt3D.Y = Center.Y + num * Math.Cos(buConversion.DegreeToRadian(num2));
							pnt3D.Z = Center.Z + num * Math.Sin(buConversion.DegreeToRadian(num2));
						}
						Vertices[num4].Add(pnt3D);
					}
					num4++;
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Direction: " + Direction.ToString() + " - Count: " + Count + " - PolarAngle: " + PolarAngle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

