	public void Mirror(Pnt3D BasePoint, Pnt3D VectorPoint, Pnt3D RefPoint, WorkPlane Plane, double ExtraOffset, ref Pnt3D CalcPoint)
	{
		try
		{
			double Distance = 0.0;
			Pnt3D PerpendicularPoint = new Pnt3D();
			PerpendicularDistancePointToLine(BasePoint, VectorPoint, RefPoint, Plane, ref PerpendicularPoint, ref Distance);
			double angle = PointAngle(PerpendicularPoint, RefPoint, Plane);
			LineWithLengthAndAngle(RefPoint, 2.0 * Distance + ExtraOffset, angle, Plane, ref BasePoint, ref CalcPoint);
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - VectorPoint: " + VectorPoint.ToString() + " - ExtraOffset: " + ExtraOffset + " - RefPoint: " + RefPoint.ToString() + "Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

