			PerpendicularDistancePointToLine(BasePoint, VectorPoint, new Pnt3D(RefPoint), Plane, ref PerpendicularPoint, ref Distance);
			double angle = PointAngle(PerpendicularPoint, new Pnt3D(RefPoint), Plane);
