	public void Tangent(eEntities RefEntity, Pnt3D RefTangentPoint, ref eEntities MovedEntity, Pnt3D MovedTangentPoint, double Offset, bool ReverseAngle, WorkPlane Plane)
	{
		try
		{
			double num = 0.0;
			double num2 = 1.0;
			ClosestPointType ClosestPoint = ClosestPointType.Start;
			Pnt3D EndPnt = new Pnt3D();
			if (ReverseAngle)
			{
				num2 = -1.0;
			}
			if (RefEntity.GetType() == typeof(eLine))
			{
				FindClosestPointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefTangentPoint, ref ClosestPoint);
				if (ClosestPoint != ClosestPointType.Start)
				{
					num = PointAngle(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], Plane);
					EndPnt = new Pnt3D(RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
					if (!buCompare.EQ(Offset, 0.0))
					{
						Pnt3D BasePnt = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Offset, num, Plane, ref BasePnt, ref EndPnt);
					}
				}
				else
				{
					num = PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[0], Plane);
					EndPnt = new Pnt3D(RefEntity.Vertice[0]);
					if (!buCompare.EQ(Offset, 0.0))
					{
						Pnt3D BasePnt2 = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Offset, num, Plane, ref BasePnt2, ref EndPnt);
					}
				}
				num += 180.0;
			}
			if (RefEntity.GetType() == typeof(eArc))
			{
				FindClosestPointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefTangentPoint, ref ClosestPoint);
				if (ClosestPoint != ClosestPointType.Start)
				{
					num = ((eArc)RefEntity).EndAngle;
					num += 90.0 * num2;
					EndPnt = new Pnt3D(RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
					if (!buCompare.EQ(Offset, 0.0))
					{
						Pnt3D BasePnt3 = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Offset, num, Plane, ref BasePnt3, ref EndPnt);
					}
				}
				else
				{
					num = ((eArc)RefEntity).StartAngle;
					num = num + 90.0 * num2 - 180.0;
					EndPnt = new Pnt3D(RefEntity.Vertice[0]);
					if (!buCompare.EQ(Offset, 0.0))
					{
						Pnt3D BasePnt4 = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Offset, num, Plane, ref BasePnt4, ref EndPnt);
					}
				}
			}
			if (RefEntity.GetType() == typeof(eCircle))
			{
				num = PointAngle(RefTangentPoint, ((eCircle)RefEntity).CenterPoint, Plane);
				Pnt3D BasePnt5 = new Pnt3D();
				LineWithLengthAndAngle(((eCircle)RefEntity).CenterPoint, ((eCircle)RefEntity).Radius, num, Plane, ref BasePnt5, ref EndPnt);
				num += 90.0 * num2;
				if (!buCompare.EQ(Offset, 0.0))
				{
					Pnt3D BasePnt6 = new Pnt3D();
					LineWithLengthAndAngle(EndPnt, Offset, num, Plane, ref BasePnt6, ref EndPnt);
				}
			}
			if ((RefEntity.GetType() == typeof(eEllipse)) | (RefEntity.GetType() == typeof(eEllipseArc)) | (RefEntity.GetType() == typeof(eBSpline)) | (RefEntity.GetType() == typeof(eBezeir)))
			{
				Pnt3D CalculatedPoint = new Pnt3D();
				double Distance = 0.0;
				int VerticeIndex = 0;
				ePolyline ePolyline2 = new ePolyline(RefEntity.Vertice);
				if (IsPointOverEntity(ePolyline2, RefTangentPoint, Plane, buSystem.resolutionCompare, ref CalculatedPoint, ref Distance, ref VerticeIndex) && ((VerticeIndex >= 0) & (VerticeIndex < ePolyline2.Vertice.Count - 1)))
				{
					num = PointAngle(ePolyline2.Vertice[VerticeIndex + 1], ePolyline2.Vertice[VerticeIndex], Plane);
					if (ReverseAngle)
					{
						num += 180.0;
					}
					EndPnt = new Pnt3D(ePolyline2.Vertice[VerticeIndex]);
					if (!buCompare.EQ(Offset, 0.0))
					{
						CalculatedPoint = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Offset, num, Plane, ref CalculatedPoint, ref EndPnt);
					}
				}
			}
			if (num < 0.0)
			{
				num += 360.0;
			}
			double num3 = 0.0;
			Pnt3D EndPnt2 = new Pnt3D();
			bool flag = false;
			if (MovedEntity.GetType() == typeof(eLine))
			{
				FindClosestPointOfLine(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedTangentPoint, ref ClosestPoint);
				if (ClosestPoint != ClosestPointType.Start)
				{
					num3 = PointAngle(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], Plane);
					EndPnt2 = new Pnt3D(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1]);
				}
				else
				{
					num3 = PointAngle(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedEntity.Vertice[0], Plane);
					EndPnt2 = new Pnt3D(MovedEntity.Vertice[0]);
				}
				flag = true;
			}
			if (MovedEntity.GetType() == typeof(eArc))
			{
				FindClosestPointOfLine(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedTangentPoint, ref ClosestPoint);
				if (ClosestPoint != ClosestPointType.Start)
				{
					num3 = ((eArc)MovedEntity).EndAngle - 90.0;
					EndPnt2 = new Pnt3D(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1]);
				}
				else
				{
					num3 = ((eArc)MovedEntity).StartAngle + 90.0;
					EndPnt2 = new Pnt3D(MovedEntity.Vertice[0]);
				}
				flag = true;
			}
			if (MovedEntity.GetType() == typeof(eCircle))
			{
				num3 = PointAngle(MovedTangentPoint, ((eCircle)MovedEntity).CenterPoint, Plane);
				Pnt3D BasePnt7 = new Pnt3D();
				LineWithLengthAndAngle(((eCircle)MovedEntity).CenterPoint, ((eCircle)MovedEntity).Radius, num3, Plane, ref BasePnt7, ref EndPnt2);
				num3 += 90.0;
				flag = true;
			}
			if (flag)
			{
				eEntities eEntities2 = new eEntities();
				eEntities2 = eEntities.CopyEntity(MovedEntity);
				Rotate(EndPnt2, num - num3, ClockDirectionType.CW, Plane, ref eEntities2);
				Move(EndPnt2, EndPnt, ref eEntities2);
				MovedEntity = eEntities.CopyEntity(eEntities2);
			}
		}
		catch (Exception mSException)
		{
			string text = "RefEntity: " + RefEntity.ToString() + " - RefTangentPoint: " + RefTangentPoint.ToString() + " - MovedEntity: " + MovedEntity.ToString() + " - MovedTangentPoint: " + MovedTangentPoint.ToString() + " - Offset: " + Offset + " - ReverseAngle: " + ReverseAngle + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Paralel(eEntities RefEntity, Pnt3D RefTangentPoint, ref eEntities MovedEntity, Pnt3D MovedTangentPoint, double Distance, WorkPlane Plane)
	{
		try
		{
			Pnt3D EndPnt = new Pnt3D();
			double num = 0.0;
			ClosestPointType ClosestPoint = ClosestPointType.Start;
			double num2 = -90.0;
			if (Distance < 0.0)
			{
				num2 = 90.0;
			}
			if (RefEntity.GetType() == typeof(eLine))
			{
				FindClosestPointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefTangentPoint, ref ClosestPoint);
				if (ClosestPoint != ClosestPointType.Start)
				{
					num = PointAngle(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], Plane);
					EndPnt = new Pnt3D(RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
					if (!buCompare.EQ(Distance, 0.0))
					{
						Pnt3D BasePnt = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Math.Abs(Distance), num + num2, Plane, ref BasePnt, ref EndPnt);
					}
				}
				else
				{
					num = PointAngle(RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefEntity.Vertice[0], Plane);
					EndPnt = new Pnt3D(RefEntity.Vertice[0]);
					if (!buCompare.EQ(Distance, 0.0))
					{
						Pnt3D BasePnt2 = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Math.Abs(Distance), num + num2, Plane, ref BasePnt2, ref EndPnt);
					}
				}
			}
			if (RefEntity.GetType() == typeof(eArc))
			{
				FindClosestPointOfLine(RefEntity.Vertice[0], RefEntity.Vertice[RefEntity.Vertice.Count - 1], RefTangentPoint, ref ClosestPoint);
				if (ClosestPoint != ClosestPointType.Start)
				{
					num = ((eArc)RefEntity).EndAngle + 90.0;
					EndPnt = new Pnt3D(RefEntity.Vertice[RefEntity.Vertice.Count - 1]);
					if (!buCompare.EQ(Distance, 0.0))
					{
						Pnt3D BasePnt3 = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Distance, num + num2, Plane, ref BasePnt3, ref EndPnt);
					}
				}
				else
				{
					num = ((eArc)RefEntity).StartAngle + 90.0;
					EndPnt = new Pnt3D(RefEntity.Vertice[0]);
					if (!buCompare.EQ(Distance, 0.0))
					{
						Pnt3D BasePnt4 = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Distance, num + num2, Plane, ref BasePnt4, ref EndPnt);
					}
				}
			}
			if (RefEntity.GetType() == typeof(eCircle))
			{
				num = PointAngle(RefTangentPoint, ((eCircle)RefEntity).CenterPoint, Plane) + 90.0;
				Pnt3D BasePnt5 = new Pnt3D();
				LineWithLengthAndAngle(((eCircle)RefEntity).CenterPoint, ((eCircle)RefEntity).Radius, num, Plane, ref BasePnt5, ref EndPnt);
				if (!buCompare.EQ(Distance, 0.0))
				{
					Pnt3D BasePnt6 = new Pnt3D();
					LineWithLengthAndAngle(EndPnt, Distance, num + num2, Plane, ref BasePnt6, ref EndPnt);
				}
			}
			if ((RefEntity.GetType() == typeof(eEllipse)) | (RefEntity.GetType() == typeof(eEllipseArc)) | (RefEntity.GetType() == typeof(eBSpline)) | (RefEntity.GetType() == typeof(eBezeir)))
			{
				Pnt3D CalculatedPoint = new Pnt3D();
				double Distance2 = 0.0;
				int VerticeIndex = 0;
				ePolyline ePolyline2 = new ePolyline(RefEntity.Vertice);
				if (IsPointOverEntity(ePolyline2, RefTangentPoint, Plane, buSystem.resolutionCompare, ref CalculatedPoint, ref Distance2, ref VerticeIndex) && ((VerticeIndex >= 0) & (VerticeIndex < ePolyline2.Vertice.Count - 1)))
				{
					num = PointAngle(ePolyline2.Vertice[VerticeIndex + 1], ePolyline2.Vertice[VerticeIndex], Plane);
					EndPnt = new Pnt3D(ePolyline2.Vertice[VerticeIndex]);
					if (!buCompare.EQ(Distance, 0.0))
					{
						CalculatedPoint = new Pnt3D();
						LineWithLengthAndAngle(EndPnt, Distance, num + num2, Plane, ref CalculatedPoint, ref EndPnt);
					}
				}
			}
			if (num < 0.0)
			{
				num += 360.0;
			}
			double num3 = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			bool flag = false;
			if (MovedEntity.GetType() == typeof(eLine))
			{
				FindClosestPointOfLine(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedTangentPoint, ref ClosestPoint);
				if (ClosestPoint != ClosestPointType.Start)
				{
					num3 = PointAngle(MovedEntity.Vertice[0], MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], Plane);
					pnt3D = new Pnt3D(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1]);
				}
				else
				{
					num3 = PointAngle(MovedEntity.Vertice[MovedEntity.Vertice.Count - 1], MovedEntity.Vertice[0], Plane);
					pnt3D = new Pnt3D(MovedEntity.Vertice[0]);
				}
				flag = true;
			}
			if (flag)
			{
				eEntities eEntities2 = new eEntities();
				eEntities2 = eEntities.CopyEntity(MovedEntity);
				Rotate(pnt3D, num - num3, ClockDirectionType.CW, Plane, ref eEntities2);
				if (!buCompare.EQ(Distance, 0.0))
				{
					Move(pnt3D, EndPnt, ref eEntities2);
				}
				MovedEntity = eEntities.CopyEntity(eEntities2);
			}
		}
		catch (Exception mSException)
		{
			string text = "RefEntity: " + RefEntity.ToString() + " - RefTangentPoint: " + RefTangentPoint.ToString() + " - MovedEntity: " + MovedEntity.ToString() + " - MovedTangentPoint: " + MovedTangentPoint.ToString() + " - Distance: " + Distance + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Scale(Pnt3D Center, double RatioX, double RatioY, double RatioZ, bool ScaleX, bool ScaleY, bool ScaleZ, ref Pnt3D CalcPnt)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			pnt3D = new Pnt3D(CalcPnt);
			pnt3D -= Center;
			if (RatioX > 0.0 && ScaleX)
			{
				pnt3D.X *= RatioX;
			}
			if (RatioY > 0.0 && ScaleY)
			{
				pnt3D.Y *= RatioY;
			}
			if (RatioZ > 0.0 && ScaleZ)
			{
				pnt3D.Z *= RatioZ;
			}
			pnt3D += Center;
			CalcPnt = new Pnt3D(pnt3D);
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - RatioX: " + RatioX + " - RatioY: " + RatioY + " - RatioZ: " + RatioZ + " - ScaleX: " + ScaleX + " - ScaleY: " + ScaleY + " - ScaleZ: " + ScaleZ;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

