	public void Scale(Pnt3D Center, double RatioX, double RatioY, double RatioZ, bool ScaleX, bool ScaleY, bool ScaleZ, ref List<Pnt3D>[] CalcPnt)
	{
		try
		{
			Pnt3D CalcPoint = new Pnt3D();
			for (int i = 0; i <= CalcPnt.Length - 1; i++)
			{
				for (int j = 0; j <= CalcPnt[i].Count - 1; j++)
				{
					Scale(Center, RatioX, RatioY, RatioZ, ScaleX, ScaleY, ScaleZ, CalcPnt[i][j], ref CalcPoint);
					CalcPnt[i][j] = new Pnt3D(CalcPoint);
				}
			}
		}
		catch (Exception mSException)
		{
