	public void Scale(Pnt3D Center, double RatioX, double RatioY, double RatioZ, bool ScaleX, bool ScaleY, bool ScaleZ, WorkPlane Plane, eEntities RefEntities, ref eEntities CalcEntities)
	{
		try
		{
			Pnt3D CalcPoint = new Pnt3D();
