			if (RatioX <= 0.0)
			{
				RatioX = 1.0;
			}
			if (RatioY <= 0.0)
			{
				RatioY = 1.0;
			}
			if (RatioZ <= 0.0)
			{
				RatioZ = 1.0;
			}
			if (WorkPlane.isPlaneXY(Plane) && !buCompare.EQ(RatioX, RatioY))
