					{
						List<Pnt3D> TargetList = new List<Pnt3D>();
						buGeneral.CopyLists(RefEntities.Vertice, ref TargetList);
						TargetList.Reverse();
						ePolyline ePolyline3 = new ePolyline(TargetList, RefEntities.dispThickness, RefEntities.dispColor);
						RefEntities = ePolyline3;
					}
