	public void FitEntityToWidthHeight(Vec3D StartSpace, Vec3D EndSpace, Pnt3D MinPoint, Pnt3D MaxPoint, double SetWidth, double SetHeight, WorkPlane Plane, ref eEntities RefEntity)
	{
		try
		{
			if (RefEntity != null && RefEntity.Vertice.Count != 0)
			{
				double num = Math.Abs(MaxPoint.X - MinPoint.X);
				double num2 = Math.Abs(MaxPoint.Y - MinPoint.Y);
				double num3 = Math.Abs(SetWidth - StartSpace.X - EndSpace.X);
				double num4 = Math.Abs(SetHeight - StartSpace.Y - EndSpace.Y);
				double ratioX = 1.0;
				double ratioY = 1.0;
				if (num3 > 0.0 && num > 0.0)
				{
					ratioX = num3 / num;
				}
				if (num4 > 0.0 && num2 > 0.0)
				{
					ratioY = num4 / num2;
				}
				Move(MinPoint, new Pnt3D(MinPoint.X + StartSpace.X, MinPoint.Y + StartSpace.Y), ref RefEntity);
				Scale(new Pnt3D(MinPoint.X + StartSpace.X, MinPoint.Y + StartSpace.Y), ratioX, ratioY, 1.0, ScaleX: true, ScaleY: true, ScaleZ: false, Plane, ref RefEntity);
			}
		}
		catch (Exception mSException)
		{
			string text = "StartSpace: " + StartSpace.ToString() + " - EndSpace: " + EndSpace.ToString() + " - MinPoint: " + MinPoint.ToString() + " - MaxPoint: " + MaxPoint.ToString() + " - SetWidth: " + SetWidth + " - SetHeight: " + SetHeight + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void FitEntityToWidthHeight(Vec3D StartSpace, Vec3D EndSpace, Pnt3D MinPoint, Pnt3D MaxPoint, double SetWidth, double SetHeight, WorkPlane Plane, ref List<eEntities> RefEntities)
	{
		try
		{
			for (int i = 0; i <= RefEntities.Count - 1; i++)
			{
				eEntities copiedEnt = new eEntities();
				eEntities.CopyEntity(RefEntities[i], ref copiedEnt);
				FitEntityToWidthHeight(StartSpace, EndSpace, MinPoint, MaxPoint, SetWidth, SetHeight, Plane, ref copiedEnt);
				RefEntities[i] = copiedEnt;
			}
		}
		catch (Exception mSException)
		{
			string text = "StartSpace: " + StartSpace.ToString() + " - EndSpace: " + EndSpace.ToString() + " - MinPoint: " + MinPoint.ToString() + " - MaxPoint: " + MaxPoint.ToString() + " - SetWidth: " + SetWidth + " - SetHeight: " + SetHeight + " - Plane: " + Plane.ToString();
