	public void Chamfer(Pnt3D Coordinate, double Length, WorkPlane Plane, ref eEntities FirstEnt, ref eEntities SecondEnt, ref eLine LineResultByCoordinate, ref List<eLine> CalcLine)
	{
		try
		{
			Chamfer(ref FirstEnt, ref SecondEnt, Length, Plane, ref CalcLine);
			if (CalcLine.Count > 0)
