	public int Break(eEntities RefEntities, Pnt3D BreakPoint, WorkPlane Plane, double Resolution, ref List<eEntities> BrokenEntites, ref bool Done)
	{
		try
		{
			Pnt3D CalculatedPoint = new Pnt3D();
			double Distance = 0.0;
			int VerticeIndex = 0;
			Done = false;
			if (IsPointOverEntity(RefEntities, BreakPoint, Plane, buSystem.resolutionCompare, ref CalculatedPoint, ref Distance, ref VerticeIndex) && Distance <= Resolution)
			{
				if (RefEntities.GetType() == typeof(eLine))
				{
					eLine eLine2 = new eLine(RefEntities);
					eEntities copiedEnt = new eLine(eLine2.StartPoint, CalculatedPoint, eLine2.dispThickness, eLine2.dispColor);
					eEntities.CopyCommonPorperties(eLine2, ref copiedEnt);
					eEntities copiedEnt2 = new eLine(CalculatedPoint, eLine2.EndPoint, eLine2.dispThickness, eLine2.dispColor);
					eEntities.CopyCommonPorperties(eLine2, ref copiedEnt2);
					BrokenEntites.Add(copiedEnt);
					BrokenEntites.Add(copiedEnt2);
					Done = true;
				}
				if (RefEntities.GetType() == typeof(ePolyline))
				{
					List<Pnt3D> Points = new List<Pnt3D>();
					for (int i = 0; i <= VerticeIndex - 1; i++)
					{
						Points.Add(new Pnt3D(RefEntities.Vertice[i]));
					}
					Points.Add(new Pnt3D(CalculatedPoint));
					buCompare.CheckDuplicatedPointsWithPrevious(ref Points);
					if (Points.Count > 1)
					{
						eEntities copiedEnt3 = new ePolyline(Points, RefEntities.dispThickness, RefEntities.dispColor);
						eEntities.CopyCommonPorperties(RefEntities, ref copiedEnt3);
						BrokenEntites.Add(copiedEnt3);
					}
					Points = new List<Pnt3D>();
					Points.Add(new Pnt3D(CalculatedPoint));
					for (int j = VerticeIndex; j <= RefEntities.Vertice.Count - 1; j++)
					{
						Points.Add(new Pnt3D(RefEntities.Vertice[j]));
					}
					buCompare.CheckDuplicatedPointsWithPrevious(ref Points);
					if (Points.Count > 1)
					{
						eEntities copiedEnt4 = new ePolyline(Points, RefEntities.dispThickness, RefEntities.dispColor);
						eEntities.CopyCommonPorperties(RefEntities, ref copiedEnt4);
						BrokenEntites.Add(copiedEnt4);
					}
					Done = true;
				}
				if (RefEntities.GetType() == typeof(eArc))
				{
					eArc eArc2 = new eArc(RefEntities);
					double num = PointAngle(CalculatedPoint, eArc2.CenterPoint, Plane);
					eEntities copiedEnt5 = new eArc(eArc2.CenterPoint, eArc2.Radius, eArc2.StartAngle, num, eArc2.Plane, eArc2.dispThickness, eArc2.dispColor);
					if (((eArc)copiedEnt5).StartAngle > ((eArc)copiedEnt5).EndAngle)
					{
						((eArc)copiedEnt5).EndAngle += 360.0;
					}
					if (((eArc)copiedEnt5).EndAngle - ((eArc)copiedEnt5).StartAngle > 360.0 && ((eArc)copiedEnt5).EndAngle > ((eArc)copiedEnt5).StartAngle)
					{
						((eArc)copiedEnt5).EndAngle -= 360.0;
					}
					eEntities.CopyCommonPorperties(eArc2, ref copiedEnt5);
					eEntities copiedEnt6 = new eArc(eArc2.CenterPoint, eArc2.Radius, num, eArc2.EndAngle, eArc2.Plane, eArc2.dispThickness, eArc2.dispColor);
					if (((eArc)copiedEnt6).StartAngle > ((eArc)copiedEnt6).EndAngle)
					{
						((eArc)copiedEnt6).EndAngle += 360.0;
					}
					if (((eArc)copiedEnt6).EndAngle - ((eArc)copiedEnt6).StartAngle > 360.0 && ((eArc)copiedEnt6).EndAngle > ((eArc)copiedEnt6).StartAngle)
					{
						((eArc)copiedEnt6).EndAngle -= 360.0;
					}
					eEntities.CopyCommonPorperties(eArc2, ref copiedEnt6);
					BrokenEntites.Add(copiedEnt5);
					BrokenEntites.Add(copiedEnt6);
					Done = true;
				}
			}
			return 1;
		}
		catch (Exception mSException)
		{
			string text = "RefEntities: " + RefEntities.ToString() + " - BreakPoint: " + BreakPoint.ToString() + " - Resolution: " + Resolution + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return 0;
		}
	}

