	public void Stretch(StretchEventArg e, eEntities RefEntities, ref eEntities CalcEntitites)
	{
		try
		{
			eEntities copiedEnt = new eEntities();
			eEntities.CopyEntity(RefEntities, ref copiedEnt);
			Stretch(e, ref copiedEnt);
			CalcEntitites = copiedEnt;
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + e.BasePoint.ToString() + " - StretchDirection: " + e.StretchDirection.ToString() + " - StretchValue: " + e.StretchValue;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Stretch(StretchEventArg e, ref List<eEntities> CalcEntitites)
	{
		List<eEntities> list = new List<eEntities>();
		for (int i = 0; i <= CalcEntitites.Count - 1; i++)
		{
			eEntities copiedEnt = new eEntities();
			eEntities.CopyEntity(CalcEntitites[i], ref copiedEnt);
			Stretch(e, ref copiedEnt);
			list.Add(copiedEnt);
		}
		CalcEntitites.Clear();
		eEntities.CopyEntities(list, ref CalcEntitites);
		list.Clear();
	}

	public void Stretch(StretchEventArg e, ref eEntities CalcEntitites)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			if (e.StretchDirection == VectorType.XVector)
			{
				if (CalcEntitites.GetType() == typeof(ePoint))
				{
					pnt3D = new Pnt3D();
					pnt3D = ((ePoint)CalcEntitites).StartPoint;
					if (e.Sign == PlusMinus.Plus && pnt3D.X > e.BasePoint.X)
					{
						pnt3D.X += e.StretchValue;
					}
					if (e.Sign == PlusMinus.Minus && pnt3D.X < e.BasePoint.X)
					{
						pnt3D.X -= e.StretchValue;
					}
					((ePoint)CalcEntitites).StartPoint = pnt3D;
					((ePoint)CalcEntitites).Update();
				}
