	public void Stretch(Pnt3D BasePoint, VectorType StretchDirection, double StretchValue, PlusMinus Sign, ref List<Pnt3D> Points)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			if (StretchDirection == VectorType.XVector)
			{
				for (int i = 0; i <= Points.Count - 1; i++)
				{
					pnt3D = new Pnt3D();
					pnt3D = Points[i];
					if (Sign == PlusMinus.Plus && pnt3D.X > BasePoint.X)
					{
						pnt3D.X += StretchValue;
					}
					if (Sign == PlusMinus.Minus && pnt3D.X < BasePoint.X)
					{
						pnt3D.X -= StretchValue;
					}
					Points[i] = pnt3D;
				}
			}
			if (StretchDirection != VectorType.YVector)
			{
				return;
			}
			for (int j = 0; j <= Points.Count - 1; j++)
			{
				pnt3D = new Pnt3D();
				pnt3D = Points[j];
				if (Sign == PlusMinus.Plus && pnt3D.Y > BasePoint.Y)
				{
					pnt3D.Y += StretchValue;
				}
				if (Sign == PlusMinus.Minus && pnt3D.Y < BasePoint.Y)
				{
					pnt3D.Y -= StretchValue;
				}
				Points[j] = pnt3D;
			}
		}
		catch (Exception mSException)
		{
			string text = "BasePoint: " + BasePoint.ToString() + " - StretchDirection: " + StretchDirection.ToString() + " - StretchValue: " + StretchValue;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void Stretch(Pnt3D BasePoint, VectorType StretchDirection, double StretchValue, PlusMinus Sign, ref List<List<Pnt3D>> Points)
	{
		List<List<Pnt3D>> list = new List<List<Pnt3D>>();
		for (int i = 0; i <= Points.Count - 1; i++)
		{
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			Pnt3D.Copy(Points[i], ref CopiedPnt);
			Stretch(BasePoint, StretchDirection, StretchValue, Sign, ref CopiedPnt);
			list.Add(CopiedPnt);
		}
		Points.Clear();
		Points = new List<List<Pnt3D>>();
		Pnt3D.Copy(list, ref Points);
	}

	public void Extend(List<eEntities> RefEntities, eEntities ExtendEntity, Pnt3D ExtendPoint, double Length, WorkPlane Plane, double Resolution, ref eEntities ExtendedEntity, ref bool Done)
