	public void FindOTherGroupEntities(int GroupIndex, int ActualEntityIndex, List<eEntities> Entities, ref List<int> GroupIndexList)
	{
		try
		{
			for (int i = 0; i <= Entities.Count - 1; i++)
			{
				if ((GroupIndex == Entities[i].GroupIndex && ActualEntityIndex != i) & !Entities[i].bSelected)
				{
					GroupIndexList.Add(i);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "GroupIndex: " + GroupIndex + " - Entities: " + Entities.Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void SelectionCheckIfDoubleIndexNumber(ref List<Selection> SelectedList)
	{
		try
		{
			List<Selection> list = new List<Selection>();
			for (int i = 0; i <= SelectedList.Count - 1; i++)
			{
				bool flag = false;
				for (int j = 0; j <= list.Count - 1; j++)
				{
					if (SelectedList[i].Index == list[j].Index)
					{
						flag = true;
						j = list.Count;
					}
				}
				if (!flag)
				{
					list.Add(SelectedList[i]);
				}
			}
			SelectedList.Clear();
			for (int k = 0; k <= list.Count - 1; k++)
			{
				SelectedList.Add(new Selection(list[k]));
			}
			list.Clear();
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void SelectionEntitiesToListByIndexNumber(List<eEntities> SelectableEntities, ref SelectedEntities Selected, ref List<eEntities> Entities, ref eEntities MouseClickEntities, List<int> EntityIndexList, bool ControlKey, Pnt3D ClickPoint, SelectionFilter Filter, SelectionArg Arg)
