			}
			if ((Arg.SmartSelection & (EntityIndexList.Count == 1) & !Arg.OnlyECamEntities) && ((Entities[EntityIndexList[0]].GetType() != typeof(eCam)) & (Entities[EntityIndexList[0]].GetType() != typeof(eMesh)) & (Entities[EntityIndexList[0]].GetType() != typeof(eSurface)) & (Entities[EntityIndexList[0]].GetType() != typeof(eSolid3D))))
			{
				for (int k = 0; k <= EntityIndexList.Count - 1; k++)
				{
					int num3 = EntityIndexList[k];
					_ = Entities[num3].EntityIndex;
					ClosestPointType ClosestPoint = ClosestPointType.Start;
					FindClosestPointOfLine(Entities[num3].Vertice[0], Entities[num3].Vertice[Entities[num3].Vertice.Count - 1], ClickPoint, ref ClosestPoint);
