							for (int n = 0; n <= Selected.SelectedListArr.Count - 1; n++)
							{
								for (int num5 = 0; num5 <= Selected.SelectedListArr[n].Count - 1; num5++)
								{
									if (Selected.SelectedListArr[n][num5].Index == num4)
									{
										flag3 = false;
									}
								}
							}
							if (flag3)
							{
