					if (list.Count > 0)
					{
						Selected.SelectedListArr.Add(list);
					}
					if (Selected.SelectedListArr.Count <= 0)
					{
						continue;
					}
					Selected.SelectedList.Clear();
					for (int num6 = 0; num6 <= Selected.SelectedListArr.Count - 1; num6++)
					{
						for (int num7 = 0; num7 <= Selected.SelectedListArr[num6].Count - 1; num7++)
						{
