					}
					if (list2.Count > 0)
					{
						Selected.SelectedListArr.Add(list2);
					}
					if (Selected.SelectedListArr.Count <= 0)
					{
						continue;
					}
					Selected.SelectedList.Clear();
					for (int num12 = 0; num12 <= Selected.SelectedListArr.Count - 1; num12++)
					{
						for (int num13 = 0; num13 <= Selected.SelectedListArr[num12].Count - 1; num13++)
						{
							Selection item2 = new Selection(Selected.SelectedListArr[num12][num13]);
							Selected.SelectedList.Add(item2);
						}
					}
					return;
				}
			}
			for (int num14 = 0; num14 <= EntityIndexList.Count - 1; num14++)
			{
				new List<int>();
				int num15 = EntityIndexList[num14];
				int groupIndex = Entities[num15].GroupIndex;
				if (groupIndex > 0)
				{
					FindOTherGroupEntities(groupIndex, num15, Entities, ref GroupIndexList);
				}
			}
			if (GroupIndexList.Count > 0)
			{
				buGeneral.AddLists(GroupIndexList, ref EntityIndexList);
			}
			for (int num16 = 0; num16 <= EntityIndexList.Count - 1; num16++)
			{
				new List<int>();
				bool flag4 = false;
				bool flag5 = true;
				bool flag6 = false;
				int num17 = EntityIndexList[num16];
				if (!((num17 >= 0) & (num17 <= Entities.Count - 1)))
				{
					continue;
				}
				Selection selection3 = new Selection(num17);
				selection3.EntityIndex = Entities[num17].EntityIndex;
				selection3.ClickPoint = new Pnt3D(ClickPoint);
				selection3.ID = Entities[num17].EntityID;
