							flag5 = true;
						}
					}
				}
				eEntities.CopyEntity(Entities[num17], ref selection3.Entity);
				Pnt3D.Copy(selection3.Entity.Vertice, ref selection3.Vertices);
				if (Entities[num17].bSelectable && flag5)
				{
					if (ControlKey)
					{
						if (!Entities[num17].bSelected)
						{
							Entities[num17].bSelected = true;
							flag4 = true;
						}
						else
						{
							Entities[num17].bSelected = false;
							flag6 = true;
						}
					}
					else
					{
						Entities[num17].bSelected = true;
						flag4 = true;
					}
				}
				if (flag6)
				{
					for (int num19 = 0; num19 <= Selected.SelectedList.Count - 1; num19++)
					{
						if (Selected.SelectedList[num19].Index == num17)
						{
							Selected.SelectedList.RemoveAt(num19);
							num19 = Selected.SelectedList.Count;
						}
					}
				}
				if (!(flag4 && flag5))
				{
					continue;
				}
				bool flag7 = false;
				for (int num20 = 0; num20 <= Selected.SelectedList.Count - 1; num20++)
				{
					if (Selected.SelectedList[num20].Index == num17)
					{
						flag7 = true;
					}
				}
				if (!flag7)
				{
					Selected.SelectedList.Add(selection3);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "EntityIndexList: " + EntityIndexList.Count + " - ControlKey " + ControlKey;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
