				}
			}
			if (GroupIndexList.Count > 0)
			{
				buGeneral.AddLists(GroupIndexList, ref EntityIndexList);
			}
			for (int l = 0; l <= EntityIndexList.Count - 1; l++)
			{
				new List<int>();
				bool flag3 = false;
				bool flag4 = true;
				bool flag5 = false;
				int num4 = EntityIndexList[l];
				if (!((num4 >= 0) & (num4 <= Entities.Count - 1)))
				{
					continue;
				}
				Selection selection = new Selection(num4);
				selection.EntityIndex = Entities[num4].EntityIndex;
				selection.ClickPoint = new Pnt3D(ClickPoint);
				selection.ID = Entities[num4].EntityID;
				if (SelectableEntities != null && SelectableEntities.Count > 0)
				{
					flag4 = false;
					for (int m = 0; m <= SelectableEntities.Count - 1; m++)
					{
						if (Entities[num4].GetType() == SelectableEntities[m].GetType())
						{
							flag4 = true;
						}
					}
				}
				eEntities.CopyEntity(Entities[num4], ref selection.Entity);
				Pnt3D.Copy(selection.Entity.Vertice, ref selection.Vertices);
				if (Entities[num4].bSelectable && flag4)
				{
					if (ControlKey)
					{
						if (!Entities[num4].bSelected)
						{
							Entities[num4].bSelected = true;
							flag3 = true;
						}
						else
						{
							Entities[num4].bSelected = false;
							flag5 = true;
						}
					}
					else
					{
						Entities[num4].bSelected = true;
						flag3 = true;
					}
				}
				if (flag5)
				{
					for (int n = 0; n <= SelectedList.Count - 1; n++)
					{
						if (SelectedList[n].Index == num4)
						{
							SelectedList.RemoveAt(n);
							n = SelectedList.Count;
						}
					}
				}
				if (!(flag3 && flag4))
				{
					continue;
				}
				bool flag6 = false;
				for (int num5 = 0; num5 <= SelectedList.Count - 1; num5++)
				{
					if (SelectedList[num5].Index == num4)
					{
						flag6 = true;
					}
				}
				if (!flag6)
				{
					SelectedList.Add(selection);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "EntityIndexList: " + EntityIndexList.Count + " - ControlKey " + ControlKey;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

