	public void SelectionSplitByGroupIndex(List<Selection> SelectedList, ref List<List<Selection>> SelectionSplitedGroups)
	{
		try
		{
			for (int i = 0; i <= SelectedList.Count - 1; i++)
			{
				int index = SelectedList[i].Index;
				eEntities eEntities2 = new eEntities();
				eEntities2 = eEntities.CopyEntity(SelectedList[i].Entity);
				bool flag = false;
				for (int j = 0; j <= SelectionSplitedGroups.Count - 1; j++)
				{
					int num = 0;
					while (num <= SelectionSplitedGroups[j].Count - 1)
					{
						if (!((eEntities2.GroupIndex > 0) & (eEntities2.GroupIndex == SelectionSplitedGroups[j][num].GroupIndex)))
						{
							num++;
							continue;
						}
						goto IL_00a4;
					}
					continue;
					IL_00a4:
					Selection selection = new Selection();
					selection.Entity = eEntities.CopyEntity(eEntities2);
					selection.Index = index;
					selection.GroupIndex = eEntities2.GroupIndex;
					SelectionSplitedGroups[j].Add(selection);
					flag = true;
					break;
				}
				if (!flag)
				{
					List<Selection> list = new List<Selection>();
					Selection selection2 = new Selection();
					selection2.Entity = eEntities.CopyEntity(eEntities2);
					selection2.Index = index;
					selection2.GroupIndex = eEntities2.GroupIndex;
					list.Add(selection2);
					SelectionSplitedGroups.Add(list);
				}
			}
		}
		catch (Exception mSException)
