	public void SelectEntitiesByLayer(List<eEntities> RefEntities, int LayerIndex, ref List<Selection> SelectedList)
	{
		for (int i = 0; i <= RefEntities.Count - 1; i++)
		{
			if (!(RefEntities[i].bSelectable & (RefEntities[i].LayerIndex == LayerIndex)))
			{
				continue;
			}
			Selection selection = new Selection(i);
			eEntities.CopyEntity(RefEntities[i], ref selection.Entity);
			if (!((RefEntities[i].GetType() == typeof(eBSpline)) | (RefEntities[i].GetType() == typeof(eBezeir))))
			{
				Pnt3D.Copy(selection.Entity.Vertice, ref selection.Vertices);
				for (int j = 0; j <= RefEntities[i].Vertice.Count - 1; j++)
				{
					selection.VerticeIndex.Add(j);
				}
			}
			else
			{
				Pnt3D.Copy(((eCurveEntities)RefEntities[i]).ControlPoints, ref selection.ControlPoints);
				for (int k = 0; k <= ((eCurveEntities)RefEntities[i]).ControlPoints.Count - 1; k++)
				{
					selection.ControlPointsIndex.Add(k);
				}
			}
			SelectedList.Add(selection);
		}
	}

