	public int DevidePointList(List<Pnt6D> refPoints, double DevideLength, double StartLength, double EndLength, bool DevideMiddlePoints, DevideTipType DevidePoint, ref List<Pnt6D> calcPoints)
	{
		try
		{
			List<Pnt6D> calcStartPoints = new List<Pnt6D>();
			List<Pnt6D> calcMiddlePoints = new List<Pnt6D>();
			List<Pnt6D> calcEndPoints = new List<Pnt6D>();
			int result = DevidePointList(refPoints, DevideLength, StartLength, EndLength, DevideMiddlePoints, DevidePoint, ref calcStartPoints, ref calcMiddlePoints, ref calcEndPoints);
			calcPoints.Clear();
			calcPoints.AddRange(calcStartPoints);
			calcPoints.AddRange(calcMiddlePoints);
			calcPoints.AddRange(calcEndPoints);
			CheckDuplicatedPointsWithPrevious(ref calcPoints);
			return result;
		}
		catch (Exception mSException)
		{
			string text = "DevideLength: " + DevideLength + " - StartLength: " + StartLength + " - EndLength: " + EndLength + " - DevidePoint: " + DevidePoint;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

	public int DevidePointList(List<Pnt6D> refPoints, double DevideLength, double StartLength, double EndLength, bool DevideMiddlePoints, DevideTipType DevidePoint, ref List<Pnt6D> calcStartPoints, ref List<Pnt6D> calcMiddlePoints, ref List<Pnt6D> calcEndPoints)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			bool flag = false;
			bool flag2 = false;
			calcStartPoints.Clear();
			calcMiddlePoints.Clear();
			calcEndPoints.Clear();
			num = Length3D(refPoints);
			num5 = num;
			if (refPoints.Count > 1)
			{
				if (!(num < StartLength + EndLength))
				{
					calcStartPoints.Add(new Pnt6D(refPoints[0]));
					for (int i = 1; i <= refPoints.Count - 1; i++)
					{
						double num6 = Length3D(refPoints[i - 1], refPoints[i]);
						num2 += num6;
						num3 = num - num2;
						if (!(num4 < StartLength && num2 > StartLength))
						{
							if (!flag)
							{
								calcStartPoints.Add(new Pnt6D(refPoints[i]));
							}
						}
						else
						{
							double angle = PointAngle(refPoints[i], refPoints[i - 1]);
							double calcAngle = 0.0;
							Pnt3D EndPnt = new Pnt3D();
							LineWithLengthAndAngle(new Pnt3D(refPoints[i - 1]), StartLength - num4, angle, new WorkPlane(), ref EndPnt);
							Pnt6D CurrentPoint = new Pnt6D(EndPnt);
							GetAngleOfPointFromPreAndNextPoint(refPoints[i - 1], refPoints[i], ref CurrentPoint, ref calcAngle);
							calcStartPoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 0.0, 0.0, calcAngle));
							calcMiddlePoints.Add(new Pnt6D(EndPnt.X, EndPnt.Y, EndPnt.Z, 0.0, 0.0, calcAngle));
							flag = true;
						}
						if (!(num3 < EndLength && num5 > EndLength))
						{
							if (flag && !flag2)
							{
								calcMiddlePoints.Add(new Pnt6D(refPoints[i]));
							}
						}
						else
						{
							double angle2 = PointAngle(refPoints[i - 1], refPoints[i]);
							double calcAngle2 = 0.0;
							Pnt3D EndPnt2 = new Pnt3D();
							LineWithLengthAndAngle(new Pnt3D(refPoints[i]), EndLength - num3, angle2, new WorkPlane(), ref EndPnt2);
							Pnt6D CurrentPoint2 = new Pnt6D(EndPnt2);
							GetAngleOfPointFromPreAndNextPoint(refPoints[i - 1], refPoints[i], ref CurrentPoint2, ref calcAngle2);
							calcEndPoints.Add(new Pnt6D(EndPnt2.X, EndPnt2.Y, EndPnt2.Z, 0.0, 0.0, calcAngle2));
							if (!flag2)
							{
								calcMiddlePoints.Add(new Pnt6D(EndPnt2.X, EndPnt2.Y, EndPnt2.Z, 0.0, 0.0, calcAngle2));
							}
							flag2 = true;
						}
						if (calcEndPoints.Count > 0)
						{
							calcEndPoints.Add(new Pnt6D(refPoints[i]));
						}
						num4 = num2;
						num5 = num3;
					}
					DevidePointsByLength(ref calcStartPoints, DevideLength);
					DevidePointsByLength(ref calcEndPoints, DevideLength);
					if (DevideMiddlePoints)
					{
						DevidePointsByLength(ref calcMiddlePoints, DevideLength);
					}
					return 2;
				}
				Pnt6D.Copy(refPoints, ref calcMiddlePoints);
				return 1;
			}
			return 0;
		}
		catch (Exception mSException)
		{
			string text = "DevideLength: " + DevideLength + " - StartLength: " + StartLength + " - EndLength: " + EndLength + " - DevidePoint: " + DevidePoint;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

	public int GetAngleOfPointFromPreAndNextPoint(Pnt6D PrePoint, Pnt6D NextPoint, ref Pnt6D CurrentPoint, ref double calcAngle)
	{
		try
		{
			double num = Length3D(PrePoint, NextPoint);
			double num2 = Length3D(PrePoint, CurrentPoint);
			double num3 = Length3D(NextPoint, CurrentPoint);
			double num4 = PrePoint.C * (num2 / num) + NextPoint.C * (num3 / num);
			CurrentPoint = new Pnt6D(CurrentPoint.X, CurrentPoint.Y, CurrentPoint.Z, CurrentPoint.A, CurrentPoint.B, num4);
			calcAngle = num4;
			return 1;
		}
		catch (Exception mSException)
		{
			string text = "";
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

	public int DevidePointsByLength(ref List<Pnt6D> Points, double DevideLength)
	{
		try
		{
			List<Pnt6D> CopiedPnt = new List<Pnt6D>();
			if (!(DevideLength <= 0.0))
			{
				Pnt6D.Copy(Points, ref CopiedPnt);
				Points.Clear();
				PolylineToPolyline(CopiedPnt, DevideLength, ref Points);
				return 1;
			}
			return 0;
		}
		catch (Exception mSException)
		{
			string text = "DevideLength: " + DevideLength;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return -1;
		}
	}

	public void CircleDevide(Pnt3D Center, double Radius, DevideData DevideData, WorkPlane Plane, ref List<eEntities> DevidedEntities)
	{
		try
		{
			DevidedEntities.Clear();
			if (DevideData.Type == DevideType.NotDevide)
			{
				DevidedEntities.Add(new eCircle(Center, Radius, Plane));
			}
			if (DevideData.Type == DevideType.HalfArc)
			{
				eEntities FirstArc = new eEntities();
				eEntities SecondArc = new eEntities();
				CircleToArcByHalf(new eCircle(Center, Radius, Plane), ref FirstArc, ref SecondArc);
				DevidedEntities.Add(FirstArc);
				DevidedEntities.Add(SecondArc);
			}
			if (DevideData.Type == DevideType.QuadraticArc)
			{
				eEntities FirstArc2 = new eEntities();
				eEntities SecondArc2 = new eEntities();
				eEntities ThirdArc = new eEntities();
				eEntities FourthArc = new eEntities();
				CircleToArcByQuadratic(new eCircle(Center, Radius, Plane), ref FirstArc2, ref SecondArc2, ref ThirdArc, ref FourthArc);
				DevidedEntities.Add(FirstArc2);
				DevidedEntities.Add(SecondArc2);
				DevidedEntities.Add(ThirdArc);
				DevidedEntities.Add(FourthArc);
			}
			if (DevideData.Type == DevideType.LineByLength)
			{
				List<Pnt3D> Vertices = new List<Pnt3D>();
				CircleToLineer(Center, Radius, DevideData.Length, Plane, ref Vertices);
				eEntities item = new ePolyline(Vertices);
				DevidedEntities.Add(item);
			}
			if (DevideData.Type == DevideType.ArcByLength)
			{
				List<eArc> CalculatedArcs = new List<eArc>();
				ArcToArc(Center, Radius, 0.0, 360.0, DevideData.Length, Plane, ref CalculatedArcs);
				for (int i = 0; i <= CalculatedArcs.Count - 1; i++)
				{
					eEntities copiedEnt = new eEntities();
					eEntities.CopyEntity(CalculatedArcs[i], ref copiedEnt);
					DevidedEntities.Add(copiedEnt);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Radius: " + Radius + " - DevideData: " + DevideData.ToString() + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

