	public void LineerInterpolation(Pnt3D FirstPoint, Pnt3D SecondPoint, int Count, ref List<Pnt3D> CalculatedPoints)
	{
		try
		{
			if (Count > 1)
			{
				double dt = 1.0 / Convert.ToDouble(Count);
				LineerInterpolation(FirstPoint, SecondPoint, dt, ref CalculatedPoints);
			}
		}
		catch (Exception mSException)
		{
			string text = "FirstPoint: " + FirstPoint.ToString() + " - SecondPoint: " + SecondPoint.ToString() + " - Count: " + Count;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void LineerInterpolation(Pnt3D FirstPoint, Pnt3D SecondPoint, double dt, ref List<Pnt3D> CalculatedPoints)
	{
		try
		{
			int num = 0;
			double num2 = 0.0;
			Pnt3D pnt3D = new Pnt3D();
			num = Convert.ToInt32(1.0 / dt);
			CalculatedPoints.Clear();
			for (int i = 0; i <= num; i++)
			{
				pnt3D = new Pnt3D();
				num2 = (double)i * dt;
				pnt3D.X = FirstPoint.X * (1.0 - num2) + SecondPoint.X * num2;
				pnt3D.Y = FirstPoint.Y * (1.0 - num2) + SecondPoint.Y * num2;
				pnt3D.Z = FirstPoint.Z * (1.0 - num2) + SecondPoint.Z * num2;
