	public void ArcToArc(Pnt3D Center, double Radius, double SA, double EA, double Length, WorkPlane Plane, ref List<eArc> CalculatedArcs)
	{
		try
		{
			int num = Convert.ToInt32(ArcCircumference(Radius, SA, EA) / Length);
			double num2 = (EA - SA) / (double)num;
			CalculatedArcs.Clear();
			for (int i = 1; i <= num; i++)
			{
				eArc item = new eArc(new Pnt3D(Center), Radius, SA + (double)(i - 1) * num2, SA + (double)i * num2, Plane);
				CalculatedArcs.Add(item);
			}
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Rad: " + Radius + " - SA: " + SA + " - EA: " + EA + " - Len: " + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void LineerToLineer(Pnt3D StartPoint, Pnt3D EndPoint, double Length, ref List<Pnt3D> Vertices)
	{
		try
		{
			double num = Length3D(StartPoint, EndPoint);
			if (!(Length <= 0.0))
			{
				int num2 = Convert.ToInt32(num / Length);
				double num3 = 1.0;
				Vertices.Clear();
				if (num2 > 1)
				{
					num3 = 1.0 / (double)num2;
					LineerInterpolation(StartPoint, EndPoint, num3, ref Vertices);
				}
				else
				{
					Vertices.Add(new Pnt3D(StartPoint));
					Vertices.Add(new Pnt3D(EndPoint));
				}
			}
			else
			{
				Vertices.Add(new Pnt3D(StartPoint));
				Vertices.Add(new Pnt3D(EndPoint));
			}
		}
		catch (Exception mSException)
		{
			string text = "SP: " + StartPoint.ToString() + " - EP: " + EndPoint.ToString() + " - Len: " + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

