			{
				FirstArc = new eArc(((eCircle)RefCircle).CenterPoint, ((eCircle)RefCircle).Radius, 0.0, 90.0, ((eCircle)RefCircle).Plane);
				eEntities.CopyCommonPorperties(RefCircle, ref FirstArc);
				SecondArc = new eArc(((eCircle)RefCircle).CenterPoint, ((eCircle)RefCircle).Radius, 90.0, 180.0, ((eCircle)RefCircle).Plane);
				eEntities.CopyCommonPorperties(RefCircle, ref FirstArc);
