				eEntities.CopyCommonPorperties(RefCircle, ref FirstArc);
			}
		}
		catch (Exception mSException)
		{
			string text = "RefCircle: " + RefCircle.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
