	public void PolylineToPolyline(List<Pnt3D> Points, double Length, ref List<Pnt3D> Vertices)
	{
		try
		{
			Vertices.Clear();
			if (Length <= 0.0 || Points.Count <= 1)
			{
				return;
			}
			for (int i = 1; i <= Points.Count - 1; i++)
			{
				List<Pnt3D> Vertices2 = new List<Pnt3D>();
				LineerToLineer(Points[i - 1], Points[i], Length, ref Vertices2);
				if (Vertices2.Count > 1)
				{
					Pnt3D.Add(Vertices2, ref Vertices);
				}
				if (i < Points.Count - 1 && Vertices.Count > 0)
				{
					Vertices.RemoveAt(Vertices.Count - 1);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Len:" + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void PolylineToPolyline(List<Pnt6D> Points, double Length, ref List<Pnt6D> Vertices)
	{
		try
		{
			Vertices.Clear();
			if (Length <= 0.0 || Points.Count <= 1)
			{
				return;
			}
			for (int i = 1; i <= Points.Count - 1; i++)
			{
				List<Pnt6D> Vertices2 = new List<Pnt6D>();
