	public void EntitiesToLineer(List<eEntities> RefEntities, double Length, ref List<List<Pnt3D>> CalcPoints)
	{
		try
		{
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			for (int i = 0; i <= RefEntities.Count - 1; i++)
			{
				List<Pnt3D> CalcPoints2 = new List<Pnt3D>();
				EntitiesToLineer(RefEntities[i], Length, ref CalcPoints2);
				if (RefEntities[i].camDirections == camPathDirectionType.Reverse)
				{
					CalcPoints2.Reverse();
				}
				if (i == 0)
				{
					List<Pnt3D> CalcPoints3 = new List<Pnt3D>();
					if (RefEntities.Count > 1)
					{
						EntitiesToLineer(RefEntities[i + 1], Length, ref CalcPoints3);
					}
					if ((CalcPoints2.Count > 1) & (CalcPoints3.Count > 1))
					{
						bool flag = false;
						if (buCompare.EQ(CalcPoints2[CalcPoints2.Count - 1], CalcPoints3[0]) | buCompare.EQ(CalcPoints2[CalcPoints2.Count - 1], CalcPoints3[CalcPoints3.Count - 1]))
						{
							Pnt3D.Add(CalcPoints2, ref CopiedPnt);
							flag = true;
						}
						if (buCompare.EQ(CalcPoints2[0], CalcPoints3[0]) | buCompare.EQ(CalcPoints2[0], CalcPoints3[CalcPoints3.Count - 1]))
						{
							CalcPoints2.Reverse();
							Pnt3D.Add(CalcPoints2, ref CopiedPnt);
							flag = true;
						}
						if (!flag)
						{
							Pnt3D.Add(CalcPoints2, ref CopiedPnt);
						}
					}
				}
				if (i <= 0)
				{
					continue;
				}
				if ((CopiedPnt.Count > 0) & (CalcPoints2.Count > 0))
				{
					bool flag2 = false;
					if (buCompare.EQ(CalcPoints2[CalcPoints2.Count - 1], CopiedPnt[CopiedPnt.Count - 1]))
					{
						Pnt3D.Add(CalcPoints2, ref CopiedPnt);
						flag2 = true;
					}
					if (buCompare.EQ(CalcPoints2[0], CopiedPnt[CopiedPnt.Count - 1]))
					{
						CalcPoints2.Reverse();
						Pnt3D.Add(CalcPoints2, ref CopiedPnt);
						flag2 = true;
					}
					if (!flag2)
					{
						CalcPoints.Add(CopiedPnt);
						CopiedPnt = new List<Pnt3D>();
					}
				}
				if ((CopiedPnt.Count == 0) & (CalcPoints2.Count > 0))
				{
					Pnt3D.Add(CalcPoints2, ref CopiedPnt);
				}
			}
		}
		catch (Exception mSException)
		{
			string text = "Len: " + Length;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

