	public void SortPointByDistance(Pnt3D RefPoint, SortDirectionType Direction, ref List<Pnt3D> SortingPoints)
	{
		try
		{
			for (int i = 0; i < SortingPoints.Count - 1; i++)
			{
				for (int j = 1; j < SortingPoints.Count - i; j++)
				{
					double num = Length3D(RefPoint, SortingPoints[j]);
					double num2 = Length3D(RefPoint, SortingPoints[j - 1]);
					if (num < num2)
					{
						Pnt3D pnt = new Pnt3D(SortingPoints[j - 1]);
						SortingPoints[j - 1] = new Pnt3D(SortingPoints[j]);
						SortingPoints[j] = new Pnt3D(pnt);
					}
				}
			}
			if (Direction == SortDirectionType.Bigger)
			{
				SortingPoints.Reverse();
			}
		}
		catch (Exception mSException)
		{
			string text = "RefPoint: " + RefPoint.ToString() + " - Direction: " + Direction;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public void SortQuickDeltaX(Pnt3D RefPoint, int Lower, int Upper, ref List<Pnt3D> PntLst)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			int num = Lower;
			int num2 = Upper;
			if (PntLst.Count <= 0)
			{
				return;
			}
			double num3 = DeltaX(RefPoint, PntLst[Convert.ToInt32(Math.Floor((double)(Lower + Upper) / 2.0))]);
			while (true)
			{
				if (DeltaX(RefPoint, PntLst[num]) < num3)
				{
					num++;
					continue;
				}
				while (num3 < DeltaX(RefPoint, PntLst[num2]))
				{
					num2--;
				}
				if (num <= num2)
				{
					pnt3D = new Pnt3D(PntLst[num]);
					PntLst[num++] = new Pnt3D(PntLst[num2]);
					PntLst[num2--] = new Pnt3D(pnt3D);
				}
				if (num >= num2)
				{
					break;
				}
			}
			if (num2 > Lower)
			{
				SortQuickDeltaX(RefPoint, Lower, num2, ref PntLst);
			}
			if (num < Upper)
			{
				SortQuickDeltaX(RefPoint, num, Upper, ref PntLst);
			}
		}
		catch (Exception mSException)
		{
			string text = "RefPoint: " + RefPoint.ToString() + " - Lower: " + Lower + " - Upper: " + Upper;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

