			Pnt3D.Copy(ProfilePoints, ref CopiedPnt);
			BoxSizeCalculate(ProfilePoints, ref MinPoint, ref MaxPoint);
			CalculatedPoints.Clear();
			CalculatedPoints = new List<Pnt3D>();
			if (ZHeightData.ZType == ZHeightProfileType.Linear)
			{
				if (ZHeightData.Direction == VectorXYType.XVector)
				{
					SortDeltaX(new Pnt3D(0.0, MinPoint.X - 10.0, 0.0), SortDirectionType.Lower, ref CopiedPnt);
					SortedOriginalPoints.Clear();
					SortedOriginalPoints = new List<Pnt3D>();
					Pnt3D.Copy(CopiedPnt, ref SortedOriginalPoints);
					if (CopiedPnt.Count > 0)
					{
						double num = CopiedPnt[0].X;
						double num2 = CopiedPnt[CopiedPnt.Count - 1].X;
						if (ZHeightData.LevelMax != ZHeightData.LevelMin && ZHeightData.LevelMax > ZHeightData.LevelMin)
						{
							num = ZHeightData.LevelMin;
							num2 = ZHeightData.LevelMax;
						}
						double num3 = num2 - pntLevel.X;
						double num4 = pntLevel.X - num;
						for (int i = 0; i <= CopiedPnt.Count - 1; i++)
						{
							Pnt3D pnt3D = new Pnt3D(CopiedPnt[i]);
							double num5 = Math.Abs(DeltaX(pntLevel, CopiedPnt[i]));
							if (!(CopiedPnt[i].X >= pntLevel.X))
							{
								if ((num4 > 0.0) & (CopiedPnt[i].X >= num))
								{
									pnt3D.Z += (num4 - num5) / num4 * ZHeightData.ZHeightValue;
								}
							}
							else if ((num3 > 0.0) & (CopiedPnt[i].X <= num2))
							{
								pnt3D.Z += (num3 - num5) / num3 * ZHeightData.ZHeightValue;
							}
							CalculatedPoints.Add(new Pnt3D(pnt3D.X, pnt3D.Y, pnt3D.Z));
						}
					}
				}
				if (ZHeightData.Direction == VectorXYType.YVector)
				{
					SortDeltaY(new Pnt3D(0.0, MinPoint.Y - 10.0, 0.0), SortDirectionType.Lower, ref CopiedPnt);
					SortedOriginalPoints.Clear();
					SortedOriginalPoints = new List<Pnt3D>();
					Pnt3D.Copy(CopiedPnt, ref SortedOriginalPoints);
					if (CopiedPnt.Count > 0)
					{
						double num6 = CopiedPnt[0].Y;
						double num7 = CopiedPnt[CopiedPnt.Count - 1].Y;
						if (ZHeightData.LevelMax != ZHeightData.LevelMin && ZHeightData.LevelMax > ZHeightData.LevelMin)
						{
							num6 = ZHeightData.LevelMin;
							num7 = ZHeightData.LevelMax;
						}
						double num8 = num7 - pntLevel.Y;
						double num9 = pntLevel.Y - num6;
						for (int j = 0; j <= CopiedPnt.Count - 1; j++)
						{
							Pnt3D pnt3D2 = new Pnt3D(CopiedPnt[j]);
							double num10 = Math.Abs(DeltaY(pntLevel, CopiedPnt[j]));
							if (!(CopiedPnt[j].Y >= pntLevel.Y))
							{
								if ((num9 > 0.0) & (CopiedPnt[j].Y >= num6))
								{
									pnt3D2.Z += (num9 - num10) / num9 * ZHeightData.ZHeightValue;
								}
							}
							else if ((num8 > 0.0) & (CopiedPnt[j].Y <= num7))
							{
								pnt3D2.Z += (num8 - num10) / num8 * ZHeightData.ZHeightValue;
							}
							CalculatedPoints.Add(new Pnt3D(pnt3D2.X, pnt3D2.Y, pnt3D2.Z));
						}
					}
				}
			}
			if (ZHeightData.ZType == ZHeightProfileType.Circular)
			{
				if (ZHeightData.Direction == VectorXYType.XVector)
				{
					SortDeltaX(new Pnt3D(0.0, MinPoint.X - 10.0, 0.0), SortDirectionType.Lower, ref CopiedPnt);
					SortedOriginalPoints.Clear();
					SortedOriginalPoints = new List<Pnt3D>();
					Pnt3D.Copy(CopiedPnt, ref SortedOriginalPoints);
					if (CopiedPnt.Count > 0)
					{
						double num11 = CopiedPnt[0].X;
						double num12 = CopiedPnt[CopiedPnt.Count - 1].X;
						if (ZHeightData.LevelMax != ZHeightData.LevelMin && ZHeightData.LevelMax > ZHeightData.LevelMin)
						{
							num11 = ZHeightData.LevelMin;
							num12 = ZHeightData.LevelMax;
						}
						double num13 = num12 - pntLevel.X;
						double num14 = pntLevel.X - num11;
						for (int k = 0; k <= CopiedPnt.Count - 1; k++)
						{
							Pnt3D pnt3D3 = new Pnt3D(CopiedPnt[k]);
							double num15 = Math.Abs(DeltaX(pntLevel, CopiedPnt[k]));
							if (!(CopiedPnt[k].X >= pntLevel.X))
							{
								if ((num14 > 0.0) & (CopiedPnt[k].X >= num11))
								{
									pnt3D3.Z += Math.Sin((num14 - num15) / num14 * Math.PI * 0.5) * ZHeightData.ZHeightValue;
								}
							}
							else if ((num13 > 0.0) & (CopiedPnt[k].X <= num12))
							{
								pnt3D3.Z += Math.Sin((num13 - num15) / num13 * Math.PI * 0.5) * ZHeightData.ZHeightValue;
							}
							CalculatedPoints.Add(new Pnt3D(pnt3D3.X, pnt3D3.Y, pnt3D3.Z));
						}
					}
				}
				if (ZHeightData.Direction == VectorXYType.YVector)
				{
					SortDeltaY(new Pnt3D(0.0, MinPoint.Y - 10.0, 0.0), SortDirectionType.Lower, ref CopiedPnt);
					SortedOriginalPoints.Clear();
					SortedOriginalPoints = new List<Pnt3D>();
					Pnt3D.Copy(CopiedPnt, ref SortedOriginalPoints);
					if (CopiedPnt.Count > 0)
					{
						double num16 = CopiedPnt[0].Y;
						double num17 = CopiedPnt[CopiedPnt.Count - 1].Y;
						if (ZHeightData.LevelMax != ZHeightData.LevelMin && ZHeightData.LevelMax > ZHeightData.LevelMin)
						{
							num16 = ZHeightData.LevelMin;
							num17 = ZHeightData.LevelMax;
						}
						double num18 = num17 - pntLevel.Y;
						double num19 = pntLevel.Y - num16;
						for (int l = 0; l <= CopiedPnt.Count - 1; l++)
						{
							Pnt3D pnt3D4 = new Pnt3D(CopiedPnt[l]);
							double num20 = Math.Abs(DeltaY(pntLevel, CopiedPnt[l]));
							if (!(CopiedPnt[l].Y >= pntLevel.Y))
							{
								if ((num19 > 0.0) & (CopiedPnt[l].Y >= num16))
								{
									pnt3D4.Z += Math.Sin((num19 - num20) / num19 * Math.PI * 0.5) * ZHeightData.ZHeightValue;
								}
							}
							else if ((num18 > 0.0) & (CopiedPnt[l].Y <= num17))
							{
								pnt3D4.Z += Math.Sin((num18 - num20) / num18 * Math.PI * 0.5) * ZHeightData.ZHeightValue;
							}
							CalculatedPoints.Add(new Pnt3D(pnt3D4.X, pnt3D4.Y, pnt3D4.Z));
						}
					}
				}
			}
			if (ZHeightData.ZType != ZHeightProfileType.Constant)
			{
				return;
			}
			if (ZHeightData.Direction == VectorXYType.XVector)
			{
				SortDeltaX(new Pnt3D(0.0, MinPoint.X - 10.0, 0.0), SortDirectionType.Lower, ref CopiedPnt);
				SortedOriginalPoints.Clear();
				SortedOriginalPoints = new List<Pnt3D>();
				Pnt3D.Copy(CopiedPnt, ref SortedOriginalPoints);
				if (CopiedPnt.Count > 0)
				{
					double num21 = CopiedPnt[0].X;
					double num22 = CopiedPnt[CopiedPnt.Count - 1].X;
					if (ZHeightData.LevelMax != ZHeightData.LevelMin && ZHeightData.LevelMax > ZHeightData.LevelMin)
					{
						num21 = ZHeightData.LevelMin;
						num22 = ZHeightData.LevelMax;
					}
					double num23 = num22 - pntLevel.X;
					double num24 = pntLevel.X - num21;
					for (int m = 0; m <= CopiedPnt.Count - 1; m++)
					{
						Pnt3D pnt3D5 = new Pnt3D(CopiedPnt[m]);
						Math.Abs(DeltaX(pntLevel, CopiedPnt[m]));
						if (!(CopiedPnt[m].X >= pntLevel.X))
						{
							if ((num24 > 0.0) & (CopiedPnt[m].X >= num21))
							{
								pnt3D5.Z = ZHeightData.ZHeightValue;
							}
						}
						else if ((num23 > 0.0) & (CopiedPnt[m].X <= num22))
						{
							pnt3D5.Z = ZHeightData.ZHeightValue;
						}
						CalculatedPoints.Add(new Pnt3D(pnt3D5.X, pnt3D5.Y, pnt3D5.Z));
					}
				}
			}
			if (ZHeightData.Direction != VectorXYType.YVector)
			{
				return;
			}
			SortDeltaY(new Pnt3D(0.0, MinPoint.Y - 10.0, 0.0), SortDirectionType.Lower, ref CopiedPnt);
			SortedOriginalPoints.Clear();
			SortedOriginalPoints = new List<Pnt3D>();
			Pnt3D.Copy(CopiedPnt, ref SortedOriginalPoints);
			if (CopiedPnt.Count <= 0)
			{
				return;
			}
			double num25 = CopiedPnt[0].Y;
			double num26 = CopiedPnt[CopiedPnt.Count - 1].Y;
			if (ZHeightData.LevelMax != ZHeightData.LevelMin && ZHeightData.LevelMax > ZHeightData.LevelMin)
			{
				num25 = ZHeightData.LevelMin;
				num26 = ZHeightData.LevelMax;
			}
			double num27 = num26 - pntLevel.Y;
			double num28 = pntLevel.Y - num25;
			for (int n = 0; n <= CopiedPnt.Count - 1; n++)
			{
				Pnt3D pnt3D6 = new Pnt3D(CopiedPnt[n]);
				Math.Abs(DeltaY(pntLevel, CopiedPnt[n]));
				if (!(CopiedPnt[n].Y >= pntLevel.Y))
				{
					if ((num28 > 0.0) & (CopiedPnt[n].Y >= num25))
					{
						pnt3D6.Z = ZHeightData.ZHeightValue;
					}
				}
				else if ((num27 > 0.0) & (CopiedPnt[n].Y <= num26))
				{
					pnt3D6.Z = ZHeightData.ZHeightValue;
				}
				CalculatedPoints.Add(new Pnt3D(pnt3D6.X, pnt3D6.Y, pnt3D6.Z));
			}
		}
		catch (Exception mSException)
		{
			string text = "pntLevel: " + pntLevel.ToString();
			buLog.addLog(text, "Not Ok", callMethod);
			buException.throwException(mSException, callMethod, ShowMessageBox: false, text);
		}
	}

	public int ConvexCircularHeigth(VectorType Axis, Pnt3D MinPoint, Pnt3D MaxPoint, double Radius, double Resolution, double Offset, List<Pnt3D> RefPoint, ref List<Pnt3D> CalcPoints)
	{
