	}

	public int ConvexCircularHeigth(VectorType Axis, Pnt3D MinPoint, Pnt3D MaxPoint, double Radius, double Resolution, double Offset, List<Pnt3D> RefPoint, ref List<Pnt3D> CalcPoints, ref geoArc ArcData)
	{
		double Radius2 = 10.0;
		double num = 0.0;
		double x = 0.0;
		double y = 0.0;
		double x2 = 0.0;
		double y2 = 0.0;
		double x3 = 0.0;
		double y3 = 0.0;
		double num2 = 0.0;
		double num3 = 0.0;
		double num4 = 0.0;
		double num5 = 0.0;
		double StartAngle = 0.0;
		double EndAngle = 0.0;
		Pnt3D pnt3D = new Pnt3D();
		List<Pnt3D> CopiedPnt = new List<Pnt3D>();
		if (Axis == VectorType.XVector)
		{
			num3 = (MaxPoint.Y - MinPoint.Y) / 2.0;
			num2 = Math.Sqrt(Radius * Radius - num3 * num3);
			x = MinPoint.Y;
			x2 = MinPoint.Y + (MaxPoint.Y - MinPoint.Y) / 2.0;
			x3 = MaxPoint.Y;
			y = (Radius - num2) * -1.0;
			y2 = 0.0;
			y3 = (Radius - num2) * -1.0;
		}
		if (Axis == VectorType.YVector)
		{
			num3 = (MaxPoint.X - MinPoint.X) / 2.0;
			num2 = Math.Sqrt(Radius * Radius - num3 * num3);
			x = MinPoint.X;
			x2 = MinPoint.X + (MaxPoint.X - MinPoint.X) / 2.0;
			x3 = MaxPoint.X;
			y = (Radius - num2) * -1.0;
			y2 = 0.0;
			y3 = (Radius - num2) * -1.0;
		}
		if (!(num3 > Radius))
		{
			Pnt3D Center = new Pnt3D();
			List<Pnt3D> Vertices = new List<Pnt3D>();
			EntityResolution entResolution = new EntityResolution(Resolution, 10, 10.0, EntityResolutionType.ByLength);
			Arc3Point(new Pnt3D(x, y), new Pnt3D(x2, y2), new Pnt3D(x3, y3), new WorkPlane(), entResolution, ref Center, ref Radius2, ref StartAngle, ref EndAngle, ref Vertices);
			num4 = Center.X;
			num5 = Center.Y;
			ArcData.CenterPoint = new Pnt3D(num4, num5);
			ArcData.Radius = Radius2;
			ArcData.StartAngle = StartAngle;
			ArcData.EndAngle = EndAngle;
			CalcPoints.Clear();
			if (!(Radius < num3))
			{
				if (RefPoint.Count >= 1)
				{
					Pnt3D.Copy(RefPoint, ref CopiedPnt);
				}
				if (Axis == VectorType.XVector)
				{
					for (int i = 0; i <= CopiedPnt.Count - 1; i++)
					{
						pnt3D = new Pnt3D();
						num = num5 + Math.Sqrt(0.0 - Math.Pow(CopiedPnt[i].Y, 2.0) + 2.0 * CopiedPnt[i].Y * num4 - Math.Pow(num4, 2.0) + Math.Pow(Radius2, 2.0));
						pnt3D.X = CopiedPnt[i].X;
						pnt3D.Y = CopiedPnt[i].Y;
						pnt3D.Z = num + Offset;
						if (buNumeric.IsNumeric(num.ToString("f8")))
						{
							CalcPoints.Add(new Pnt3D(pnt3D));
							continue;
						}
						CalcPoints.Clear();
						return -1;
					}
				}
				if (Axis == VectorType.YVector)
				{
					for (int j = 0; j <= CopiedPnt.Count - 1; j++)
					{
						pnt3D = new Pnt3D();
						num = num5 + Math.Sqrt(0.0 - Math.Pow(CopiedPnt[j].X, 2.0) + 2.0 * CopiedPnt[j].X * num4 - Math.Pow(num4, 2.0) + Math.Pow(Radius2, 2.0));
						pnt3D.X = CopiedPnt[j].X;
						pnt3D.Y = CopiedPnt[j].Y;
						pnt3D.Z = num + Offset;
						if (buNumeric.IsNumeric(num.ToString("f8")))
						{
							CalcPoints.Add(pnt3D);
							continue;
						}
						CalcPoints.Clear();
						return -1;
					}
				}
				return 1;
			}
			return -1;
		}
		return -2;
	}

