	public int HeightFromFreeDrawing(VectorType Axis, Pnt3D MinPoint, Pnt3D MaxPoint, List<Pnt3D> ProfilePoints, double Resolution, double Offset, List<Pnt3D> RefPoint, ref List<Pnt3D> CalcPoints, ref List<double> AnglesVersusProfile)
	{
		new Pnt3D();
		List<Pnt3D> Vertices = new List<Pnt3D>();
		List<Pnt3D> Vertices2 = new List<Pnt3D>();
		if (!(Resolution > 0.0))
		{
			Pnt3D.Copy(ProfilePoints, ref Vertices2);
		}
		else
		{
			PolylineToPolyline(ProfilePoints, Resolution, ref Vertices2);
		}
		if (RefPoint.Count > 1)
		{
			if (!(Resolution > 0.0))
			{
				Pnt3D.Copy(RefPoint, ref Vertices);
			}
			else
			{
				PolylineToPolyline(RefPoint, Resolution, ref Vertices);
			}
		}
		if (RefPoint.Count == 1)
		{
			Pnt3D.Copy(RefPoint, ref Vertices);
		}
		CalcPoints = new List<Pnt3D>();
		if (Axis == VectorType.YVector)
		{
			for (int i = 0; i <= Vertices.Count - 1; i++)
			{
				Pnt3D pnt3D = new Pnt3D(Vertices[i]);
				for (int j = 0; j <= Vertices2.Count - 2; j++)
				{
					Pnt3D pnt3D2 = new Pnt3D(Vertices2[j]);
					Pnt3D pnt3D3 = new Pnt3D(Vertices2[j + 1]);
					if (((pnt3D2.X <= pnt3D.X) | buCompare.EQ(pnt3D.X, pnt3D2.X, buSystem.resolutionCompare)) & ((pnt3D.X <= pnt3D3.X) | buCompare.EQ(pnt3D.X, pnt3D3.X, buSystem.resolutionCompare)))
					{
						j = Vertices2.Count;
						double X = 0.0;
						buNumeric.EquationLineer(pnt3D2.Z, pnt3D3.Z, pnt3D2.X, pnt3D3.X, pnt3D.X, ref X);
						pnt3D.Z = X;
						double item = PointAngle(pnt3D3, pnt3D2, new WorkPlane(planeType.XZ, 1));
						AnglesVersusProfile.Add(item);
						CalcPoints.Add(pnt3D);
					}
				}
			}
		}
		return 1;
	}

	public Pnt3D SnapFunction(Pnt3D Base, Vec3D SnapDistances, WorkPlane Plane)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			if (WorkPlane.isPlaneXY(Plane))
			{
				pnt3D.X = Math.Round(Base.X / SnapDistances.X) * SnapDistances.X;
				pnt3D.Y = Math.Round(Base.Y / SnapDistances.Y) * SnapDistances.Y;
				pnt3D.Z = 0.0;
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				pnt3D.X = Math.Round(Base.X / SnapDistances.X) * SnapDistances.X;
				pnt3D.Y = 0.0;
				pnt3D.Z = Math.Round(Base.Z / SnapDistances.Z) * SnapDistances.Z;
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				pnt3D.X = 0.0;
				pnt3D.Y = Math.Round(Base.Y / SnapDistances.Y) * SnapDistances.Y;
				pnt3D.Z = Math.Round(Base.Z / SnapDistances.Z) * SnapDistances.Z;
			}
			return pnt3D;
		}
		catch (Exception mSException)
		{
			string text = "Base: " + Base.ToString() + " - SnapDistances: " + SnapDistances.ToString() + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return new Pnt3D();
		}
	}

	public void OrthoFunction(Pnt3D RefPnt, Pnt3D CenterPnt, WorkPlane Plane, ref Pnt3D OrthoPnt, ref int OrthoDir)
	{
		try
		{
			Pnt3D pnt3D = new Pnt3D();
			double num;
			if (WorkPlane.isPlaneXY(Plane))
			{
				pnt3D.X = CenterPnt.X;
				pnt3D.Y = CenterPnt.Y;
				if (RefPnt.X - pnt3D.X == 0.0)
				{
					OrthoPnt.X = RefPnt.X;
					OrthoPnt.Y = RefPnt.Y;
				}
				else
				{
					OrthoPnt.X = RefPnt.X;
					OrthoPnt.Y = RefPnt.Y;
					num = (RefPnt.Y - pnt3D.Y) / (RefPnt.X - pnt3D.X);
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Y > pnt3D.Y)) && num > 1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Y = RefPnt.Y;
						OrthoDir = 2;
					}
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Y > pnt3D.Y)) && num < 1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Y = pnt3D.Y;
						OrthoDir = 1;
					}
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Y < pnt3D.Y)) && num < -1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Y = RefPnt.Y;
						OrthoDir = 4;
					}
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Y < pnt3D.Y)) && num > -1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Y = pnt3D.Y;
						OrthoDir = 1;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Y < pnt3D.Y)) && num > 1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Y = RefPnt.Y;
						OrthoDir = 4;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Y < pnt3D.Y)) && num < 1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Y = pnt3D.Y;
						OrthoDir = 3;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Y > pnt3D.Y)) && num < -1.0)
					{
						OrthoPnt.X = pnt3D.X;
						OrthoPnt.Y = RefPnt.Y;
						OrthoDir = 2;
					}
					if (((RefPnt.X < pnt3D.X) & (RefPnt.Y > pnt3D.Y)) && num > -1.0)
					{
						OrthoPnt.X = RefPnt.X;
						OrthoPnt.Y = pnt3D.Y;
						OrthoDir = 3;
					}
				}
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				pnt3D.X = CenterPnt.X;
				pnt3D.Z = CenterPnt.Z;
				if (RefPnt.X - pnt3D.X == 0.0)
				{
					OrthoPnt.X = RefPnt.X;
					OrthoPnt.Z = RefPnt.Z;
				}
				else
				{
					OrthoPnt.X = RefPnt.X;
					OrthoPnt.Z = RefPnt.Z;
					num = (RefPnt.Z - pnt3D.Z) / (RefPnt.X - pnt3D.X);
					if (((RefPnt.X > pnt3D.X) & (RefPnt.Z > pnt3D.Z)) && num > 1.0)
					{
