		{
			for (int i = 1; i <= Contours.Outter.Count - 1; i++)
			{
				Pnt3D IntersectionPoint = new Pnt3D();
				bool IsLineIntersect = false;
				bool IsIntersecPointInsideLines = false;
				LineLineIntersection(StartPoint, EndPoint, Contours.Outter[i - 1], Contours.Outter[i], Plane, ref IntersectionPoint, ref IsLineIntersect, ref IsIntersecPointInsideLines);
				if (IsLineIntersect && IsPointOverAndInsideLine(StartPoint, EndPoint, IntersectionPoint, Plane, buSystem.resolutionCompare) && IsPointOverAndInsideLine(Contours.Outter[i - 1], Contours.Outter[i], IntersectionPoint, Plane, buSystem.resolutionCompare))
				{
