			}
			for (int j = 0; j <= Contours.Holes.Count - 1; j++)
			{
				for (int k = 1; k <= Contours.Holes[j].Count - 1; k++)
				{
					Pnt3D IntersectionPoint2 = new Pnt3D();
					bool IsLineIntersect2 = false;
					bool IsIntersecPointInsideLines2 = false;
					LineLineIntersection(StartPoint, EndPoint, Contours.Holes[j][k - 1], Contours.Holes[j][k], Plane, ref IntersectionPoint2, ref IsLineIntersect2, ref IsIntersecPointInsideLines2);
