	public bool IsTriangleAnyPointInZone(Pnt3D FirstPoint, Pnt3D SecondPoint, Pnt3D ThirdPoint, Pnt3D MinCorner, Pnt3D MaxCorner, ref bool IsYLower, ref bool IsXLower, ref bool IsYBigger, ref bool IsXBigger)
	{
		try
		{
			bool flag = false;
			bool flag2 = false;
			bool flag3 = false;
			IsYBigger = false;
			IsYLower = false;
			IsXBigger = false;
			IsXLower = false;
			if (((FirstPoint.X >= MinCorner.X) & (FirstPoint.X <= MaxCorner.X)) && ((FirstPoint.Y >= MinCorner.Y) & (FirstPoint.Y <= MaxCorner.Y)))
			{
				flag = true;
			}
			if (((SecondPoint.X >= MinCorner.X) & (SecondPoint.X <= MaxCorner.X)) && ((SecondPoint.Y >= MinCorner.Y) & (SecondPoint.Y <= MaxCorner.Y)))
			{
				flag2 = true;
