			if ((FirstPoint.Y < MinCorner.Y) & (SecondPoint.Y < MinCorner.Y) & (ThirdPoint.Y < MinCorner.Y))
			{
				IsYLower = true;
			}
			if ((FirstPoint.Y > MaxCorner.Y) & (SecondPoint.Y > MaxCorner.Y) & (ThirdPoint.Y > MaxCorner.Y))
			{
				IsYBigger = true;
			}
			if ((FirstPoint.X < MinCorner.X) & (SecondPoint.X < MinCorner.X) & (ThirdPoint.X < MinCorner.X))
			{
