	public bool IsAngleInsideArcAngles(ref double Angle, double ArcStartAngle, double ArcEndAngle)
	{
		try
		{
			if (!(buCompare.EQ(Angle, ArcStartAngle) | buCompare.EQ(Angle, ArcEndAngle)))
			{
				if (!((Angle >= ArcStartAngle) & (Angle <= ArcEndAngle)))
				{
					if ((ArcStartAngle < 0.0) & (Angle > 0.0))
					{
						double num = Angle - 360.0;
						if (num >= ArcStartAngle && num <= ArcEndAngle)
						{
							Angle = num;
							return true;
						}
					}
					Angle += 360.0;
					if (!((Angle >= ArcStartAngle) & (Angle <= ArcEndAngle)))
					{
						return false;
					}
					return true;
				}
				return true;
			}
			return true;
		}
		catch (Exception mSException)
		{
			string text = "Angle: " + Angle + " - ArcStartAngle: " + ArcStartAngle + " - ArcEndAngle: " + ArcEndAngle;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

