	public bool IsPointInsideTriangle3(Triangle3D Triangle, Pnt3D RefPoint)
	{
		double num = ((Triangle.SecondPoint.Y - Triangle.ThirdPoint.Y) * (RefPoint.X - Triangle.ThirdPoint.X) + (Triangle.ThirdPoint.X - Triangle.SecondPoint.X) * (RefPoint.Y - Triangle.ThirdPoint.Y)) / ((Triangle.SecondPoint.Y - Triangle.ThirdPoint.Y) * (Triangle.FirstPoint.X - Triangle.ThirdPoint.X) + (Triangle.ThirdPoint.X - Triangle.SecondPoint.X) * (Triangle.FirstPoint.Y - Triangle.ThirdPoint.Y));
		double num2 = ((Triangle.ThirdPoint.Y - Triangle.FirstPoint.Y) * (RefPoint.X - Triangle.ThirdPoint.X) + (Triangle.FirstPoint.X - Triangle.ThirdPoint.X) * (RefPoint.Y - Triangle.ThirdPoint.Y)) / ((Triangle.SecondPoint.Y - Triangle.ThirdPoint.Y) * (Triangle.FirstPoint.X - Triangle.ThirdPoint.X) + (Triangle.ThirdPoint.X - Triangle.SecondPoint.X) * (Triangle.FirstPoint.Y - Triangle.ThirdPoint.Y));
		double num3 = 1.0 - num - num2;
		if (num != 0.0 && num2 != 0.0 && num3 != 0.0)
		{
			if (num < 0.0 || !(num <= 1.0) || !(num2 >= 0.0) || !(num2 <= 1.0) || !(num3 >= 0.0) || !(num3 <= 1.0))
