	public bool IsPointInsidePolygon(List<Pnt3D> Vertices, Pnt3D RefPoint, WorkPlane Plane, bool CheckOver)
	{
		try
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			double num5 = 0.0;
			if (WorkPlane.isPlaneXY(Plane))
			{
				for (int i = 0; i < Vertices.Count; i++)
				{
					num2 = Vertices[i].X - RefPoint.X;
					num3 = Vertices[i].Y - RefPoint.Y;
					num4 = Vertices[(i + 1) % Vertices.Count].X - RefPoint.X;
					num5 = Vertices[(i + 1) % Vertices.Count].Y - RefPoint.Y;
					num += Class156.smethod_131(num5, num2, num4, this, num3);
					if (CheckOver && i > 0 && IsPointInsideLine(Vertices[i - 1], Vertices[i], RefPoint, Plane))
					{
						return true;
					}
				}
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				for (int j = 0; j < Vertices.Count; j++)
				{
					num2 = Vertices[j].X - RefPoint.X;
					num3 = Vertices[j].Z - RefPoint.Z;
					num4 = Vertices[(j + 1) % Vertices.Count].X - RefPoint.X;
					num5 = Vertices[(j + 1) % Vertices.Count].Z - RefPoint.Z;
					num += Class156.smethod_131(num5, num2, num4, this, num3);
				}
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				for (int k = 0; k < Vertices.Count; k++)
				{
					num2 = Vertices[k].Y - RefPoint.Y;
					num3 = Vertices[k].Z - RefPoint.Z;
					num4 = Vertices[(k + 1) % Vertices.Count].Y - RefPoint.Y;
					num5 = Vertices[(k + 1) % Vertices.Count].Z - RefPoint.Z;
					num += Class156.smethod_131(num5, num2, num4, this, num3);
				}
			}
			if (!((Math.Abs(num) < Math.PI) | buCompare.EQ(Math.Abs(num), Math.PI)))
			{
				return true;
			}
			return false;
		}
		catch (Exception mSException)
		{
			string text = "Vertices: " + Vertices.Count + " - RefPoint: " + RefPoint.ToString() + " - Plane: " + Plane.ToString() + " - CheckOver: " + CheckOver;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public void IsPointLeftOrRightOfOpenContour(List<Pnt3D> Vertices, Pnt3D RefPoint, WorkPlane Plane, ref CamOpenContourType2 Direction)
	{
		try
		{
			List<Pnt3D> CopiedPnt = new List<Pnt3D>();
			ClockDirectionType clockDirectionType = ClockDirectionType.CW;
			if (Vertices.Count > 2)
			{
				Pnt3D.Copy(Vertices, ref CopiedPnt);
				CopiedPnt.Add(new Pnt3D(CopiedPnt[0]));
				if (PolygonDirection(CopiedPnt, Plane) == ClockDirectionType.CCW)
				{
					Vertices.Reverse();
					CopiedPnt.Reverse();
				}
				if (CopiedPnt.Count > 2)
				{
					bool flag = IsPointInsidePolygon(CopiedPnt, RefPoint);
					Direction = CamOpenContourType2.Left;
					if (flag)
					{
						Direction = CamOpenContourType2.Right;
					}
				}
			}
			if (Vertices.Count != 2)
			{
				return;
			}
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			double num4 = 0.0;
			num = Length3D(RefPoint, Vertices[0]);
			num2 = Length3D(RefPoint, Vertices[1]);
			if (!(num < num2))
			{
				num3 = PointAngle(Vertices[1], Vertices[0], Plane);
				num4 = PointAngle(RefPoint, Vertices[0], Plane);
				double num5 = Math.Abs(num3 - num4);
				if (num5 > 180.0)
				{
					if (!(num3 < num4))
					{
						num4 += 360.0;
					}
					else
					{
						num3 += 360.0;
					}
				}
				if (!(num3 > num4))
				{
					Direction = CamOpenContourType2.Left;
				}
				else
				{
					Direction = CamOpenContourType2.Right;
				}
				return;
			}
			num3 = PointAngle(Vertices[0], Vertices[1], Plane);
			num4 = PointAngle(RefPoint, Vertices[1], Plane);
			double num6 = Math.Abs(num3 - num4);
			if (num6 > 180.0)
			{
				if (!(num3 < num4))
				{
					num4 += 360.0;
				}
				else
				{
					num3 += 360.0;
				}
			}
			if (!(num3 > num4))
			{
				Direction = CamOpenContourType2.Right;
			}
			else
			{
				Direction = CamOpenContourType2.Left;
			}
		}
		catch (Exception mSException)
		{
			string text = "Vertices: " + Vertices.Count + " - RefPoint: " + RefPoint.ToString() + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

	public bool IsPointInsideWindow(Pnt3D Base, Pnt3D ControledPoint, double WindowSize, WorkPlane Plane)
	{
		try
		{
			if (!WorkPlane.isPlaneXY(Plane))
			{
				if (!WorkPlane.isPlaneXZ(Plane))
				{
					if (!WorkPlane.isPlaneYZ(Plane))
					{
						if (((Base.X - WindowSize / 2.0 <= ControledPoint.X) & (ControledPoint.X <= Base.X + WindowSize / 2.0)) && ((Base.Y - WindowSize / 2.0 <= ControledPoint.Y) & (ControledPoint.Y <= Base.Y + WindowSize / 2.0)) && ((Base.Z - WindowSize / 2.0 <= ControledPoint.Z) & (ControledPoint.Z <= Base.Z + WindowSize / 2.0)))
						{
							return true;
						}
					}
					else if (((Base.Y - WindowSize / 2.0 <= ControledPoint.Y) & (ControledPoint.Y <= Base.Y + WindowSize / 2.0)) && ((Base.Z - WindowSize / 2.0 <= ControledPoint.Z) & (ControledPoint.Z <= Base.Z + WindowSize / 2.0)))
					{
						return true;
					}
				}
				else if (((Base.X - WindowSize / 2.0 <= ControledPoint.X) & (ControledPoint.X <= Base.X + WindowSize / 2.0)) && ((Base.Z - WindowSize / 2.0 <= ControledPoint.Z) & (ControledPoint.Z <= Base.Z + WindowSize / 2.0)))
				{
					return true;
				}
			}
			else if (((Base.X - WindowSize / 2.0 <= ControledPoint.X) & (ControledPoint.X <= Base.X + WindowSize / 2.0)) && ((Base.Y - WindowSize / 2.0 <= ControledPoint.Y) & (ControledPoint.Y <= Base.Y + WindowSize / 2.0)))
			{
				return true;
			}
			return false;
		}
		catch (Exception mSException)
		{
			string text = "Base: " + Base.ToString() + " - ControledPoint: " + ControledPoint.ToString() + " - Resolution: " + WindowSize + " - Plane: " + Plane.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

