	public bool IsPointInsideArc(Pnt3D Center, double Radius, double StartAngle, double EndAngle, Pnt3D RefPoint, WorkPlane Plane, double Resolution, ref int ClosestPoint)
	{
		try
		{
			double num = StartAngle;
			double num2 = EndAngle;
			double num3 = 0.0;
			bool result = false;
			if (num > 360.0 && num2 > 360.0)
			{
				num -= 360.0;
				num2 -= 360.0;
			}
			if (num > num2)
			{
				num2 += 360.0;
			}
			num3 = PointAngle(RefPoint, Center, Plane);
			ClosestPoint = -1;
			if (num < num2 && IsAngleInsideArcAngles(ref num3, num, num2))
			{
				result = true;
				double num4 = num3 - num;
				double num5 = num2 - num3;
				if (!(num4 < num5))
				{
					ClosestPoint = 1;
				}
				else
				{
					ClosestPoint = 0;
				}
			}
			return result;
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Radius: " + Radius + " - StartAngle: " + StartAngle + " - EndAngle: " + EndAngle + " - RefPoint: " + RefPoint.ToString() + " - Resolution: " + Resolution;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

	public bool IsPointOverArc(Pnt3D Center, double Radius, double StartAngle, double EndAngle, Pnt3D RefPoint, WorkPlane Plane, double Resolution, ref Pnt3D CalculatedPoint, ref double Distance)
	{
		try
		{
			bool flag = false;
			int ClosestPoint = 0;
			double num = PointAngle(RefPoint, Center, Plane);
			CalculatedPoint = new Pnt3D();
			if (WorkPlane.isPlaneXY(Plane))
			{
				CalculatedPoint.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(num));
				CalculatedPoint.Y = Center.Y + Radius * Math.Sin(buConversion.DegreeToRadian(num));
				CalculatedPoint.Z = Center.Z;
			}
			if (WorkPlane.isPlaneXZ(Plane))
			{
				CalculatedPoint.X = Center.X + Radius * Math.Cos(buConversion.DegreeToRadian(num));
				CalculatedPoint.Y = Center.Y;
				CalculatedPoint.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadian(num));
			}
			if (WorkPlane.isPlaneYZ(Plane))
			{
				CalculatedPoint.X = Center.X;
				CalculatedPoint.Y = Center.Y + Radius * Math.Cos(buConversion.DegreeToRadian(num));
				CalculatedPoint.Z = Center.Z + Radius * Math.Sin(buConversion.DegreeToRadian(num));
			}
			Distance = Length3D(Center, RefPoint, Plane) - Radius;
			if (!(flag = IsPointInsideArc(Center, Radius, StartAngle, EndAngle, RefPoint, Plane, Resolution, ref ClosestPoint)) && (StartAngle > 360.0 || EndAngle > 360.0))
			{
				num += 360.0;
				flag = IsPointInsideArc(Center, Radius, StartAngle, EndAngle, RefPoint, Plane, Resolution, ref ClosestPoint);
			}
			if (!buCompare.EQ(Distance, 0.0, Resolution))
			{
				flag = false;
			}
			return flag;
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Radius: " + Radius + " - StartAngle: " + StartAngle + " - EndAngle: " + EndAngle + " - RefPoint: " + RefPoint.ToString() + " - Resolution: " + Resolution;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
		}
	}

