	public bool IsPointInsideAndOverArc(Pnt3D Center, double Radius, double StartAngle, double EndAngle, Pnt3D RefPoint, WorkPlane Plane, double Resolution, ref int ClosestPoint)
	{
		try
		{
			Pnt3D CalculatedPoint = new Pnt3D();
			double Distance = 0.0;
			if (!IsPointInsideArc(Center, Radius, StartAngle, EndAngle, RefPoint, Plane, Resolution, ref ClosestPoint) || !IsPointOverArc(Center, Radius, StartAngle, EndAngle, RefPoint, Plane, Resolution, ref CalculatedPoint, ref Distance) || !(Distance <= Resolution))
			{
				return false;
			}
			return true;
		}
		catch (Exception mSException)
		{
			string text = "Center: " + Center.ToString() + " - Radius: " + Radius + " - StartAngle: " + StartAngle + " - EndAngle: " + EndAngle + " - RefPoint: " + RefPoint.ToString() + " - Resolution: " + Resolution;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
			return false;
