	public bool IsPointOverLine(Pnt3D StartPoint, Pnt3D EndPoint, Pnt3D RefPoint, WorkPlane Plane, double Resolution, ref Pnt3D CalculatedPoint, ref double Distance)
	{
		try
		{
			double X = 0.0;
			double Y = 0.0;
			double Z = 0.0;
			double X2 = 0.0;
			double Y2 = 0.0;
			double Z2 = 0.0;
			double num = 0.0;
			CalculatedPoint = new Pnt3D();
			PointToVariables(StartPoint, ref X, ref Y, ref Z);
			PointToVariables(EndPoint, ref X2, ref Y2, ref Z2);
			if (!WorkPlane.isPlaneXY(Plane))
			{
				goto IL_0075;
			}
			if (!buCompare.EQ(X, X2, Resolution))
