					if (!buCompare.EQ(X, X2, Resolution) & !buCompare.EQ(Y, Y2, Resolution))
					{
						num = (Y2 - Y) / (X2 - X);
						CalculatedPoint.X = (0.0 - (-1.0 * Math.Pow(num, 2.0) * X2 + Y2 * num - RefPoint.X - RefPoint.Y * num)) / (1.0 + Math.Pow(num, 2.0));
						CalculatedPoint.Y = (Y2 - num * X2 + RefPoint.X * num + RefPoint.Y * Math.Pow(num, 2.0)) / (1.0 + Math.Pow(num, 2.0));
					}
					CalculatedPoint.Z = ZFromXYZ(StartPoint, EndPoint, CalculatedPoint);
					goto IL_0075;
				}
				CalculatedPoint.X = RefPoint.X;
				CalculatedPoint.Y = Y;
				CalculatedPoint.Z = RefPoint.Z;
