			if (!buCompare.EQ(X, X2, Resolution))
			{
				if (!buCompare.EQ(Z, Z2, Resolution))
				{
					if (!buCompare.EQ(X, X2, Resolution) & !buCompare.EQ(Z, Z2, Resolution))
					{
						num = (Z2 - Z) / (X2 - X);
						CalculatedPoint.X = (0.0 - (-1.0 * Math.Pow(num, 2.0) * X2 + Z2 * num - RefPoint.X - RefPoint.Z * num)) / (1.0 + Math.Pow(num, 2.0));
						CalculatedPoint.Z = (Z2 - num * X2 + RefPoint.X * num + RefPoint.Z * Math.Pow(num, 2.0)) / (1.0 + Math.Pow(num, 2.0));
					}
					CalculatedPoint.Y = YFromXYZ(StartPoint, EndPoint, CalculatedPoint);
					goto IL_0081;
				}
				CalculatedPoint.X = RefPoint.X;
				CalculatedPoint.Y = RefPoint.Y;
				CalculatedPoint.Z = Z;
			}
			else
			{
				CalculatedPoint.X = X;
				CalculatedPoint.Y = RefPoint.Y;
				CalculatedPoint.Z = RefPoint.Z;
			}
			goto IL_0487;
			IL_0487:
			Distance = Length3D(RefPoint, CalculatedPoint);
			return IsPointInsideLine(StartPoint, EndPoint, CalculatedPoint, Plane);
			IL_0081:
			if (WorkPlane.isPlaneYZ(Plane))
			{
				if (!buCompare.EQ(Y, Y2, Resolution))
				{
					if (!buCompare.EQ(Z, Z2, Resolution))
					{
						if (!buCompare.EQ(Y, Y2, Resolution) & !buCompare.EQ(Z, Z2, Resolution))
						{
							num = (Z2 - Z) / (Y2 - Y);
							CalculatedPoint.Y = (0.0 - (-1.0 * Math.Pow(num, 2.0) * Y2 + Z2 * num - RefPoint.Y - RefPoint.Z * num)) / (1.0 + Math.Pow(num, 2.0));
							CalculatedPoint.Z = (Z2 - num * Y2 + RefPoint.Y * num + RefPoint.Z * Math.Pow(num, 2.0)) / (1.0 + Math.Pow(num, 2.0));
						}
						CalculatedPoint.X = XFromXYZ(StartPoint, EndPoint, CalculatedPoint);
					}
					else
					{
						CalculatedPoint.X = RefPoint.X;
						CalculatedPoint.Y = RefPoint.Y;
						CalculatedPoint.Z = Z;
					}
				}
				else
				{
					CalculatedPoint.X = RefPoint.X;
					CalculatedPoint.Y = Y;
					CalculatedPoint.Z = RefPoint.Z;
				}
			}
			goto IL_0487;
		}
		catch (Exception mSException)
		{
