				{
					if (IsPointOverLine(RefEntity.Vertice[i - 1], RefEntity.Vertice[i], RefPoint, Plane, ref CalculatedPoint2, ref Distance2))
					{
						result = true;
						if (Distance2 < num)
						{
							num = Distance2;
							CalculatedPoint = new Pnt3D(CalculatedPoint2);
							VerticeIndex = i;
						}
					}
				}
			}
			if (RefEntity.GetType() == typeof(eArc) && IsPointOverArc(((eArc)RefEntity).CenterPoint, ((eArc)RefEntity).Radius, ((eArc)RefEntity).StartAngle, ((eArc)RefEntity).EndAngle, RefPoint, Plane, Resolution, ref CalculatedPoint2, ref Distance2))
			{
				result = true;
				if (Distance2 < num)
				{
					num = Distance2;
					CalculatedPoint = new Pnt3D(CalculatedPoint2);
				}
			}
			if (RefEntity.GetType() == typeof(eCircle) && IsPointOverArc(((eCircle)RefEntity).CenterPoint, ((eCircle)RefEntity).Radius, 0.0, 360.0, RefPoint, Plane, Resolution, ref CalculatedPoint2, ref Distance2))
			{
