		if (TipPoint)
		{
			if ((RefEntities.GetType() == typeof(eLine)) | (RefEntities.GetType() == typeof(ePolyline)) | (RefEntities.GetType() == typeof(eBSpline)) | (RefEntities.GetType() == typeof(eBezeir)) | (RefEntities.GetType() == typeof(ePicture)) | (RefEntities.GetType() == typeof(eText)) | (RefEntities.GetType() == typeof(eDimLineer)))
