				ArcStartMiddleEndPoint(((eArc)RefEntities).CenterPoint, ((eArc)RefEntities).Radius, ((eArc)RefEntities).StartAngle, ((eArc)RefEntities).EndAngle, ((eArc)RefEntities).Plane, ref MiddlePoint);
				if (IsPointInsideWindow(RefPoint, MiddlePoint, Resolution, Plane))
