			{
				CatchPoint = new Pnt3D(((eCircle)RefEntities).CenterPoint);
				VerticeIndex = 2;
				OsnapTypes = osnapType.Center;
				return true;
			}
			if (RefEntities.GetType() == typeof(eArc) && IsPointInsideWindow(RefPoint, ((eArc)RefEntities).CenterPoint, Resolution, Plane))
			{
				CatchPoint = new Pnt3D(((eArc)RefEntities).CenterPoint);
