				VerticeIndex = 2;
				OsnapTypes = osnapType.Center;
				return true;
			}
		}
		if (Outter)
		{
			List<Pnt3D> OutsidePoints = new List<Pnt3D>();
			EntityOutsidePoints(RefEntities, ref OutsidePoints);
			for (int k = 0; k <= OutsidePoints.Count - 1; k++)
			{
				if (IsPointInsideWindow(new Pnt3D(RefPoint), new Pnt3D(OutsidePoints[k]), Resolution, Plane))
