					VerticeIndex = l;
					OsnapTypes = osnapType.ControlPoint;
					return true;
				}
			}
		}
		if (Over)
		{
			double Distance = 0.0;
			int ClosestVerticeIndex = 0;
			if (IsPointOverAndInsideEntity(RefEntities, RefPoint, Plane, Resolution, ref CatchPoint, ref Distance, ref VerticeIndex, ref ClosestVerticeIndex))
