	public bool IsPointOverAndInsideEntity(eEntities RefEntity, Pnt3D RefPoint, WorkPlane Plane, double Resolution, ref Pnt3D CalculatedPoint, ref double Distance, ref int VerticeIndex, ref int ClosestVerticeIndex)
	{
		try
		{
			bool result = false;
			Pnt3D CalculatedPoint2 = new Pnt3D();
			double Distance2 = 0.0;
			double num = double.MaxValue;
			ClosestVerticeIndex = 0;
			if ((RefEntity.GetType() == typeof(eLine)) | (RefEntity.GetType() == typeof(eEllipse)) | (RefEntity.GetType() == typeof(eEllipseArc)) | (RefEntity.GetType() == typeof(eBezeir)) | (RefEntity.GetType() == typeof(eBSpline)))
			{
				for (int i = 1; i <= RefEntity.Vertice.Count - 1; i++)
