					{
						VerticeIndex = i - 1;
						result = true;
						num = Distance2;
						CalculatedPoint = new Pnt3D(CalculatedPoint2);
					}
				}
			}
			if (RefEntity.GetType() == typeof(ePolyline))
			{
				for (int j = 1; j <= RefEntity.Vertice.Count - 1; j++)
				{
					if (!IsPointOverLine(RefEntity.Vertice[j - 1], RefEntity.Vertice[j], RefPoint, Plane, ref CalculatedPoint2, ref Distance2))
					{
						continue;
					}
					int ClosestPoint = -1;
					if (IsPointInsideLine(RefEntity.Vertice[j - 1], RefEntity.Vertice[j], RefPoint, Plane, Resolution, ref ClosestPoint) && Distance2 < num)
					{
						if (ClosestPoint != 0)
						{
							ClosestVerticeIndex = j;
						}
						else
						{
							ClosestVerticeIndex = j - 1;
						}
						result = true;
						VerticeIndex = j - 1;
						num = Distance2;
						CalculatedPoint = new Pnt3D(CalculatedPoint2);
					}
				}
			}
			if (RefEntity.GetType() == typeof(eArc) && IsPointOverArc(((eArc)RefEntity).CenterPoint, ((eArc)RefEntity).Radius, ((eArc)RefEntity).StartAngle, ((eArc)RefEntity).EndAngle, RefPoint, Plane, Resolution, ref CalculatedPoint2, ref Distance2) && Distance2 < num && IsPointInsideEntity(RefEntity, RefPoint, Plane, Resolution, ref ClosestVerticeIndex))
			{
				result = true;
				num = Distance2;
				VerticeIndex = 0;
				CalculatedPoint = new Pnt3D(CalculatedPoint2);
			}
			if (RefEntity.GetType() == typeof(eCircle) && IsPointOverArc(((eCircle)RefEntity).CenterPoint, ((eCircle)RefEntity).Radius, 0.0, 360.0, RefPoint, Plane, Resolution, ref CalculatedPoint2, ref Distance2) && IsPointInsideEntity(RefEntity, RefPoint, Plane, Resolution, ref ClosestVerticeIndex) && Distance2 < num)
			{
				result = true;
				num = Distance2;
				VerticeIndex = 0;
				CalculatedPoint = new Pnt3D(CalculatedPoint2);
			}
			Distance = num;
			return result;
		}
		catch (Exception mSException)
		{
			string text = "RefEntity: " + RefEntity.ToString() + " - RefPoint: " + RefPoint.ToString() + " - Plane: " + Plane.ToString() + " - Resolution: " + Resolution;
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
