	public void CreatMachine(KinematicBase Kinematic, ref List<eEntities> MachineEntities)
	{
		try
		{
			MachineEntities.Clear();
			if (Kinematic.Type == KinemeticType.CartezianXYZ_WristAC_5Axis)
			{
				Vec3D vec3D = new Vec3D(Kinematic.RotateCenterOffsetOfA.X - Kinematic.RotateCenterOffsetOfC.X, Kinematic.RotateCenterOffsetOfA.Y - Kinematic.RotateCenterOffsetOfC.Y, Kinematic.RotateCenterOffsetOfA.Z - Kinematic.RotateCenterOffsetOfC.Z);
				eLine eLine2 = null;
				Pnt3D startPoint = new Pnt3D(0.0, 0.0, 0.0);
				Pnt3D endPoint = new Pnt3D(vec3D.X, vec3D.Y, 0.0);
				if (vec3D.Y != 0.0)
				{
					eLine2 = new eLine(startPoint, endPoint);
					MachineEntities.Add(eLine2);
				}
				startPoint = new Pnt3D(vec3D.X, vec3D.Y, 0.0);
				endPoint = new Pnt3D(vec3D.X, vec3D.Y, 0.0 - Kinematic.RotateCenterOffsetOfC.Z);
				eLine2 = new eLine(startPoint, endPoint);
				MachineEntities.Add(eLine2);
				startPoint = new Pnt3D(vec3D.X, vec3D.Y, 0.0 - Kinematic.RotateCenterOffsetOfC.Z);
				endPoint = new Pnt3D(vec3D.X, vec3D.Y - Kinematic.RotateCenterOffsetOfA.Y, 0.0 - Kinematic.RotateCenterOffsetOfC.Z);
				eLine2 = new eLine(startPoint, endPoint);
				MachineEntities.Add(eLine2);
			}
		}
		catch (Exception mSException)
		{
			string text = "Kinematic: " + Kinematic.ToString();
			buLog.addLog(text, "Not Ok", MethodBase.GetCurrentMethod().Name);
			buException.throwException(mSException, MethodBase.GetCurrentMethod().Name, ShowMessageBox: false, text);
		}
	}

