	public int FontToVectorConvert(Pnt3D Location, Font fFont, string ConvertString, WorkPlane Plane, Pnt3D PlaneOffset, ref List<TriangulationPoints> CalculatedPoints)
	{
		Graphics fx = null;
		List<TriangulationPoints> CalculatedPoints2 = new List<TriangulationPoints>();
		int result = FontToVectorConvert(fx, fFont, ConvertString, ref CalculatedPoints2);
		for (int i = 0; i <= CalculatedPoints2.Count - 1; i++)
		{
			TriangulationPoints Triangulation = new TriangulationPoints();
			for (int j = 0; j <= CalculatedPoints2[i].Points.Count - 1; j++)
			{
				Pnt3D pnt3D = new Pnt3D(CalculatedPoints2[i].Points[j]);
				if (WorkPlane.isPlaneXY(Plane))
				{
					pnt3D.Z = PlaneOffset.Z;
				}
				if (WorkPlane.isPlaneXZ(Plane))
				{
					pnt3D.Z = pnt3D.Y;
					pnt3D.Y = PlaneOffset.Y;
				}
				if (WorkPlane.isPlaneYZ(Plane))
				{
					double y = pnt3D.Y;
					pnt3D.Y = pnt3D.X;
					pnt3D.Z = y;
					pnt3D.X = PlaneOffset.X;
				}
				Triangulation.Points.Add(pnt3D);
			}
			for (int k = 0; k <= CalculatedPoints2[i].Holes.Count - 1; k++)
			{
				List<Pnt3D> list = new List<Pnt3D>();
				for (int l = 0; l <= CalculatedPoints2[i].Holes[k].Count - 1; l++)
				{
					Pnt3D pnt3D2 = new Pnt3D(CalculatedPoints2[i].Holes[k][l]);
					if (WorkPlane.isPlaneXY(Plane))
					{
						pnt3D2.Z = PlaneOffset.Z;
					}
					if (WorkPlane.isPlaneXZ(Plane))
					{
						pnt3D2.Z = pnt3D2.Y;
						pnt3D2.Y = PlaneOffset.Y;
					}
					if (WorkPlane.isPlaneYZ(Plane))
					{
						double y2 = pnt3D2.Y;
						pnt3D2.Y = pnt3D2.X;
						pnt3D2.Z = y2;
						pnt3D2.X = PlaneOffset.X;
					}
					list.Add(pnt3D2);
				}
				Triangulation.Holes.Add(list);
			}
			for (int m = 0; m <= CalculatedPoints2[i].Triangles.Count - 1; m++)
			{
				Triangle3D triangle3D = new Triangle3D(CalculatedPoints2[i].Triangles[m]);
				if (WorkPlane.isPlaneXY(Plane))
				{
					triangle3D.FirstPoint.Z = PlaneOffset.Z;
					triangle3D.SecondPoint.Z = PlaneOffset.Z;
					triangle3D.ThirdPoint.Z = PlaneOffset.Z;
				}
				if (WorkPlane.isPlaneXZ(Plane))
				{
					triangle3D.FirstPoint.Z = triangle3D.FirstPoint.Y;
					triangle3D.SecondPoint.Z = triangle3D.SecondPoint.Y;
					triangle3D.ThirdPoint.Z = triangle3D.ThirdPoint.Y;
					triangle3D.FirstPoint.Y = PlaneOffset.Y;
					triangle3D.SecondPoint.Y = PlaneOffset.Y;
					triangle3D.ThirdPoint.Y = PlaneOffset.Y;
				}
				if (WorkPlane.isPlaneYZ(Plane))
				{
					double y3 = triangle3D.FirstPoint.Y;
					triangle3D.FirstPoint.Y = triangle3D.FirstPoint.X;
					triangle3D.FirstPoint.Z = y3;
					triangle3D.FirstPoint.X = PlaneOffset.X;
					y3 = triangle3D.SecondPoint.Y;
					triangle3D.SecondPoint.Y = triangle3D.SecondPoint.X;
					triangle3D.SecondPoint.Z = y3;
					triangle3D.SecondPoint.X = PlaneOffset.X;
					y3 = triangle3D.ThirdPoint.Y;
					triangle3D.ThirdPoint.Y = triangle3D.ThirdPoint.X;
					triangle3D.ThirdPoint.Z = y3;
					triangle3D.ThirdPoint.X = PlaneOffset.X;
				}
				Triangulation.Triangles.Add(triangle3D);
			}
			Move(new Pnt3D(), Location, ref Triangulation);
			CalculatedPoints.Add(Triangulation);
		}
		return result;
	}

	public int FontToVectorConvert(Graphics fx, Font fFont, string ConvertString, ref List<TriangulationPoints> CalculatedPoints)
